const ARENA_QUESTIONS = {"10":{"1":[{"q":"Đối tượng nghiên cứu chính của Vật lí là:","opts":["Các dạng vận động của vật chất và năng lượng.","Sự biến đổi của các chất hoá học tạo thành chất mới.","Cấu tạo và hoạt động của các cơ thể sinh vật sống.","Lịch sử hình thành và phát triển của vỏ Trái Đất."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Đối tượng nghiên cứu của Vật lí gồm các dạng vận động của vật chất (cơ, nhiệt, điện, từ, quang, hạt nhân,...) và năng lượng.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Circle of Physics branches -->\n      <circle cx=\"250\" cy=\"120\" r=\"45\" fill=\"#1e1b4b\" stroke=\"#6366f1\" stroke-width=\"2.5\"/>\n      <text x=\"225\" y=\"125\" fill=\"#a5b4fc\" font-size=\"14\" font-weight=\"bold\">VẬT LÍ</text>\n      <!-- Branch 1: Mechanics -->\n      <circle cx=\"120\" cy=\"70\" r=\"30\" fill=\"#0c4a6e\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"100\" y=\"75\" fill=\"#7dd3fc\" font-size=\"12\" font-weight=\"bold\">Cơ học</text>\n      <line x1=\"210\" y1=\"100\" x2=\"145\" y2=\"80\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <!-- Branch 2: Thermodynamics -->\n      <circle cx=\"380\" cy=\"70\" r=\"30\" fill=\"#7f1d1d\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n      <text x=\"355\" y=\"75\" fill=\"#fca5a5\" font-size=\"12\" font-weight=\"bold\">Nhiệt học</text>\n      <line x1=\"290\" y1=\"100\" x2=\"355\" y2=\"80\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <!-- Branch 3: Electromagnetism -->\n      <circle cx=\"120\" cy=\"170\" r=\"30\" fill=\"#78350f\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <text x=\"95\" y=\"175\" fill=\"#fde68a\" font-size=\"12\" font-weight=\"bold\">Điện - Từ</text>\n      <line x1=\"210\" y1=\"140\" x2=\"145\" y2=\"160\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <!-- Branch 4: Optics & Quantum -->\n      <circle cx=\"380\" cy=\"170\" r=\"30\" fill=\"#064e3b\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <text x=\"350\" y=\"175\" fill=\"#a7f3d0\" font-size=\"12\" font-weight=\"bold\">Quang học</text>\n      <line x1=\"290\" y1=\"140\" x2=\"355\" y2=\"160\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Các nhánh nghiên cứu cốt lõi của khoa học Vật lí</text>\n    </svg>"},{"q":"Phương pháp nghiên cứu đặc thù và phổ biến nhất của Vật lí là sự kết hợp chặt chẽ giữa:","opts":["Phương pháp thực nghiệm và phương pháp mô hình (lí thuyết).","Phương pháp phỏng vấn xã hội học và thống kê dân số.","Phương pháp suy diễn thuần tuý không cần kiểm chứng thực tế.","Phương pháp mô tả cảm tính và kinh nghiệm dân gian."],"ans":0,"exp":"• Tiến trình nghiên cứu vật lí luôn kết hợp giữa xây dựng giả thuyết lí thuyết (mô hình hoá) và tiến hành thí nghiệm thực nghiệm để kiểm chứng tính đúng đắn của giả thuyết.","svgGraph":null},{"q":"Thành tựu nào sau đây gắn liền trực tiếp với cuộc Cách mạng công nghiệp lần thứ nhất xuất phát từ các nghiên cứu về nhiệt học?","opts":["Động cơ hơi nước của James Watt.","Máy tính điện tử bán dẫn và Internet.","Trí tuệ nhân tạo (AI) và robot tự hành.","Đèn chiếu sáng sợi đốt và mạng lưới điện xoay chiều."],"ans":0,"exp":"• Các phát minh về nhiệt học và sự hoàn thiện động cơ hơi nước của James Watt đã mở đầu cuộc Cách mạng công nghiệp lần thứ nhất, thay thế lao động thủ công bằng cơ giới hoá.","svgGraph":null},{"q":"Ứng dụng nào sau đây trong y học hiện đại dựa trên thành tựu của Vật lí hạt nhân và sóng điện từ?","opts":["Chụp cắt lớp vi tính (CT) và cộng hưởng từ (MRI).","Kĩ thuật cấy ghép mô nhân tạo từ tế bào gốc.","Kĩ thuật nuôi cấy vi khuẩn tạo kháng sinh.","Phương pháp xoa bóp bấm huyệt cổ truyền."],"ans":0,"exp":"• CT dùng tia X và MRI dùng từ trường mạnh kết hợp sóng radio (hiện tượng cộng hưởng từ hạt nhân) là ứng dụng trực tiếp của vật lí trong y học.","svgGraph":null},{"q":"Thí nghiệm nổi tiếng thả rơi các vật có khối lượng khác nhau từ tháp nghiêng Pisa của nhà bác học nào đã chứng minh mọi vật rơi tự do như nhau nếu không có sức cản không khí?","opts":["Galileo Galilei.","Isaac Newton.","Albert Einstein.","Archimedes."],"ans":0,"exp":"• Galileo Galilei là cha đẻ của phương pháp thực nghiệm trong vật lí; ông đã bác bỏ quan niệm sai lầm cổ xưa của Aristotle cho rằng vật nặng rơi nhanh hơn vật nhẹ.","svgGraph":null},{"q":"Quy tắc nào sau đây là quan trọng nhất để trở thành người học Vật lí có tư duy khoa học?","opts":["Luôn tìm kiếm bằng chứng thực nghiệm và lập luận logic trước khi chấp nhận một kết luận.","Ghi nhớ máy móc các công thức toán học mà không cần hiểu ý nghĩa vật lí của các đại lượng.","Tin tưởng tuyệt đối vào cảm giác trực quan của bản thân mà không cần đo đạc.","Bỏ qua các kết quả thí nghiệm không trùng khớp với suy đoán chủ quan ban đầu."],"ans":0,"exp":"• Tư duy vật lí dựa trên bằng chứng đo đạc thực nghiệm khách quan, phản biện khoa học và suy luận logic có căn cứ.","svgGraph":null}],"2":[{"q":"Biển cảnh báo hình tam giác viền vàng, bên trong có hình tia sét màu đen mang ý nghĩa cảnh báo gì?","opts":["Nguy hiểm về điện giật, điện áp cao.","Khu vực có hoá chất ăn mòn da tay.","Nơi có nguồn bức xạ hạt nhân nguy hiểm.","Khu vực có nhiệt độ cao gây bỏng nhiệt."],"ans":0,"exp":"• Kí hiệu tia sét trong tam giác vàng là biển cảnh báo nguy cơ điện giật, điện áp nguy hiểm trong phòng thí nghiệm.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Warning Triangle -->\n      <polygon points=\"250,30 370,200 130,200\" fill=\"#fbbf24\" stroke=\"#d97706\" stroke-width=\"4\"/>\n      <polygon points=\"250,50 350,190 150,190\" fill=\"#fef08a\"/>\n      <!-- Lightning bolt symbol -->\n      <polygon points=\"255,65 220,125 250,125 235,180 280,115 250,115\" fill=\"#0f172a\"/>\n      <text x=\"175\" y=\"225\" fill=\"#fef08a\" font-size=\"13\" font-weight=\"bold\">NGUY CƠ ĐIỆN CAO ÁP NGUY HIỂM</text>\n    </svg>"},{"q":"Khi tiến hành thí nghiệm với các thiết bị sử dụng nguồn điện lưới xoay chiều 220 V trong phòng thực hành, hành vi nào sau đây là KHÔNG AN TOÀN?","opts":["Cắm phích điện khi tay còn ướt hoặc đứng trên sàn nhà có nước ẩm ướt.","Kiểm tra dây dẫn điện trước khi đóng cầu dao.","Sử dụng bút thử điện để kiểm tra vỏ kim loại của thiết bị.","Ngắt nguồn điện ngay lập tức khi phát hiện mùi khét lạ."],"ans":0,"exp":"• Nước là chất dẫn điện tốt (chứa các ion khoáng); khi tay ướt điện trở cơ thể giảm mạnh, nếu chạm vào nguồn điện sẽ dẫn đến dòng điện lớn chạy qua người gây giật điện tử vong.","svgGraph":null},{"q":"Khi xảy ra sự cố chập điện làm bùng phát đám cháy trong phòng thí nghiệm, thao tác đầu tiên và quan trọng nhất cần làm là:","opts":["Nhanh chóng ngắt cầu dao tổng của phòng thí nghiệm.","Dùng nước lạnh dội thật nhiều vào đám cháy nơi có thiết bị điện.","Hô hoán và chạy thật nhanh ra khỏi phòng mà không ngắt điện.","Dùng chăn len ướt đắp trực tiếp lên ổ cắm đang có điện."],"ans":0,"exp":"• Bước tiên quyết khi chữa cháy điện là phải cắt nguồn điện ngay lập tức để ngăn dòng điện tiếp tục sinh nhiệt và tránh nguy cơ bị điện giật cho người chữa cháy.","svgGraph":null},{"q":"Bình chữa cháy khí CO₂ (cacbonic) thường được ưu tiên sử dụng để chữa các đám cháy thiết bị điện tử trong phòng thí nghiệm vì lý do nào sau đây?","opts":["Khí CO₂ không dẫn điện và không làm đọng cặn làm hỏng các linh kiện vi mạch điện tử.","Khí CO₂ có thể cung cấp thêm khí oxy giúp dập tắt lửa nhanh hơn.","Khí CO₂ có trọng lượng nhẹ hơn không khí nên bốc hơi ngay lập tức.","Khí CO₂ có tính ăn mòn kim loại cực kì cao."],"ans":0,"exp":"• Bình CO₂ dập lửa bằng cách làm lạnh đột ngột và cách ly oxy mà không để lại cặn bột hoá chất, đồng thời cách điện an toàn cho thiết bị điện tử.","svgGraph":null},{"q":"Dòng điện xoay chiều có giá trị bao nhiêu chạy qua cơ thể người bắt đầu gây co giật cơ bắp mạnh và nguy hiểm tới tính mạng?","opts":["Khoảng từ 10 mA đến 25 mA trở lên.","Khoảng từ 0,1 mA đến 0,5 mA.","Khoảng trên 100 A.","Dòng điện xoay chiều ở bất kì giá trị nào cũng không gây nguy hiểm."],"ans":0,"exp":"• Dòng điện xoay chiều tần số 50 Hz từ 10 mA bắt đầu gây co giật cơ không buông tay được, từ 25 mA gây khó thở và trên 50 mA có thể gây rung thất tim tử vong.","svgGraph":null},{"q":"Vị trí đặt các thiết bị an toàn như bình cứu hoả, hộp sơ cứu y tế trong phòng thực hành Vật lí phải đảm bảo tiêu chuẩn nào?","opts":["Ở vị trí thông thoáng, dễ nhìn thấy, dễ tiếp cận và không có vật cản lối đi.","Khoá kĩ bên trong tủ bảo mật của phòng giáo viên để tránh học sinh nghịch.","Để ở góc khuất phía sau các dãy bàn thí nghiệm nặng.","Cất gọn gàng trên trần nhà hoặc gác xép."],"ans":0,"exp":"• Thiết bị ứng phó khẩn cấp phải luôn đặt ở nơi dễ quan sát và tiếp cận tức thời khi có sự cố hoả hoạn hay tai nạn.","svgGraph":null}],"3":[{"q":"Phép đo trực tiếp một đại lượng vật lí là:","opts":["Phép so sánh trực tiếp đại lượng cần đo với đại lượng cùng loại bằng dụng cụ đo.","Phép xác định đại lượng thông qua một công thức toán học từ các phép đo khác.","Phép ước lượng độ lớn của vật bằng mắt thường không dùng thang chia.","Phép tính tích phân hoặc đạo hàm trên máy tính bỏ túi."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Phép đo trực tiếp là phép so sánh trực tiếp đại lượng cần đo với đại lượng chuẩn cùng loại thông qua thang đo của dụng cụ (ví dụ: đo chiều dài bằng thước kẻ, đo thời gian bằng đồng hồ).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr3\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Ruler with mm divisions -->\n      <rect x=\"50\" y=\"80\" width=\"400\" height=\"60\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <!-- Marks on ruler -->\n      <line x1=\"100\" y1=\"80\" x2=\"100\" y2=\"110\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n      <text x=\"96\" y=\"125\" fill=\"#f8fafc\" font-size=\"12\">0</text>\n      <line x1=\"150\" y1=\"80\" x2=\"150\" y2=\"105\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n      <line x1=\"200\" y1=\"80\" x2=\"200\" y2=\"110\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n      <text x=\"196\" y=\"125\" fill=\"#f8fafc\" font-size=\"12\">1</text>\n      <line x1=\"250\" y1=\"80\" x2=\"250\" y2=\"105\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n      <line x1=\"300\" y1=\"80\" x2=\"300\" y2=\"110\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n      <text x=\"296\" y=\"125\" fill=\"#f8fafc\" font-size=\"12\">2</text>\n      <line x1=\"350\" y1=\"80\" x2=\"350\" y2=\"105\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n      <line x1=\"400\" y1=\"80\" x2=\"400\" y2=\"110\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n      <text x=\"396\" y=\"125\" fill=\"#f8fafc\" font-size=\"12\">3</text>\n      <text x=\"415\" y=\"105\" fill=\"#38bdf8\" font-size=\"12\">cm</text>\n      <!-- Measured Object -->\n      <rect x=\"100\" y=\"45\" width=\"185\" height=\"25\" fill=\"#fbbf24\" stroke=\"#d97706\" stroke-width=\"1.5\" rx=\"3\"/>\n      <text x=\"160\" y=\"62\" fill=\"#0f172a\" font-size=\"12\" font-weight=\"bold\">Vật cần đo (L)</text>\n      <!-- Annotation on measured length -->\n      <line x1=\"285\" y1=\"35\" x2=\"285\" y2=\"78\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n      <text x=\"260\" y=\"25\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">L ≈ 1,85 cm ± 0,05 cm</text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Minh hoạ phép đo trực tiếp và giới hạn sai số dụng cụ</text>\n    </svg>"},{"q":"Biểu thức viết chuẩn mực kết quả đo của một đại lượng vật lí A là:","opts":["A = Ā ± ΔA.","A = Ā · ΔA.","A = Ā / ΔA.","A = Ā + (ΔA)²."],"ans":0,"exp":"• Kết quả đo được ghi dưới dạng khoảng tin cậy: A = Ā ± ΔA, trong đó Ā là giá trị trung bình của các lần đo, ΔA là sai số tuyệt đối của phép đo.","svgGraph":null},{"q":"Đo chiều dài của một cuốn sách bằng thước có độ chia nhỏ nhất (ĐCNN) là 1 mm. Sai số dụng cụ thông thường được quy ước lấy bằng:","opts":["Một nửa ĐCNN (0,5 mm) hoặc bằng một ĐCNN (1 mm).","Gấp 10 lần độ chia nhỏ nhất (10 mm).","Bằng không vì thước chế tạo rất chính xác.","Một phần mười độ chia nhỏ nhất (0,1 mm)."],"ans":0,"exp":"• Quy ước SGK: Sai số dụng cụ thông thường được lấy bằng một nửa độ chia nhỏ nhất hoặc bằng một độ chia nhỏ nhất trên thang đo.","svgGraph":null},{"q":"Đo 5 lần đường kính d của một viên bi thép thu được các giá trị lần lượt là: 6,32 mm; 6,34 mm; 6,33 mm; 6,35 mm; 6,31 mm. Giá trị trung bình d<sub>tb</sub> của đường kính viên bi là:","opts":["6,33 mm.","6,32 mm.","6,34 mm.","6,35 mm."],"ans":0,"exp":"• <b>Giá trị trung bình:</b><br>d<sub>tb</sub> = <span class=\"fraction\"><span class=\"numerator\">6,32 + 6,34 + 6,33 + 6,35 + 6,31</span><span class=\"denominator\">5</span></span> = <span class=\"fraction\"><span class=\"numerator\">31,65</span><span class=\"denominator\">5</span></span> = 6,33 mm.","svgGraph":null},{"q":"Một học sinh đo khối lượng m và thể tích V của một khối đồng thu được: m = (890 ± 5) g và V = (100 ± 2) cm³. Khối lượng riêng của đồng tính được từ công thức ρ = m/V có sai số tỉ đối δρ là:","opts":["2,56%.","0,56%.","2,00%.","1,44%."],"ans":0,"exp":"• <b>Bước 1: Tính sai số tỉ đối của m:</b> δm = <span class=\"fraction\"><span class=\"numerator\">5</span><span class=\"denominator\">890</span></span> · 100% ≈ 0,56%.<br>• <b>Bước 2: Tính sai số tỉ đối của V:</b> δV = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">100</span></span> · 100% = 2,00%.<br>• <b>Bước 3: Sai số tỉ đối của thương ρ = m/V:</b><br>δρ = δm + δV = 0,56% + 2,00% = 2,56%.","svgGraph":null},{"q":"Thời gian rơi tự do của một vật đo được là t = (0,405 ± 0,008) s. Sai số tỉ đối của phép đo thời gian này xấp xỉ bằng:","opts":["1,98%.","0,80%.","3,96%.","0,02%."],"ans":0,"exp":"• <b>Công thức sai số tỉ đối:</b> δt = <span class=\"fraction\"><span class=\"numerator\">Δt</span><span class=\"denominator\">t<sub>tb</sub></span></span> · 100%<br>• <b>Thay số:</b> δt = <span class=\"fraction\"><span class=\"numerator\">0,008</span><span class=\"denominator\">0,405</span></span> · 100% ≈ 1,98%.","svgGraph":null}],"4":[{"q":"Độ dịch chuyển là một đại lượng vectơ nối từ:","opts":["Vị trí đầu đến vị trí cuối của chuyển động.","Gốc toạ độ đến vị trí ban đầu của vật.","Vị trí cuối cùng quay ngược trở lại gốc toạ độ.","Tâm Trái Đất đến trọng tâm của vật."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Độ dịch chuyển là một đại lượng vectơ có gốc tại vị trí ban đầu, ngọn tại vị trí kết thúc của chuyển động, đặc trưng cho độ biến thiên vị trí của vật.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr4\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Start point A and End point B -->\n      <circle cx=\"100\" cy=\"150\" r=\"7\" fill=\"#ef4444\"/>\n      <text x=\"85\" y=\"175\" fill=\"#ef4444\" font-size=\"14\" font-weight=\"bold\">Điểm A</text>\n      <circle cx=\"400\" cy=\"80\" r=\"7\" fill=\"#34d399\"/>\n      <text x=\"405\" y=\"105\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">Điểm B</text>\n      <!-- Displacement vector d (straight arrow) -->\n      <line x1=\"100\" y1=\"150\" x2=\"395\" y2=\"82\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr4)\"/>\n      <text x=\"235\" y=\"105\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">Vectơ độ dịch chuyển d</text>\n      <!-- Distance path s (curved yellow line) -->\n      <path d=\"M 100,150 Q 180,40 280,180 T 400,80\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2.5\" stroke-dasharray=\"4,3\"/>\n      <text x=\"210\" y=\"55\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Quãng đường s (quỹ đạo thực)</text>\n      <text x=\"145\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Phân biệt độ dịch chuyển d và quãng đường s</text>\n    </svg>"},{"q":"Khi nào độ lớn của độ dịch chuyển d bằng với quãng đường đi được s của vật?","opts":["Khi vật chuyển động thẳng và không đổi chiều chuyển động.","Khi vật chuyển động tròn đều trọn vẹn một vòng.","Khi vật chuyển động thẳng đi rồi quay lại điểm xuất phát.","Trong mọi trường hợp chuyển động bất kì."],"ans":0,"exp":"• Độ lớn của độ dịch chuyển chỉ bằng quãng đường đi được khi vật chuyển động trên đường thẳng và không đổi chiều (d = s). Nếu đổi chiều hoặc đi đường cong thì d < s.","svgGraph":null},{"q":"Một người đi bộ từ điểm A đến điểm B cách nhau 400 m về phía Đông, sau đó rẽ sang hướng Bắc đi tiếp 300 m đến điểm C. Độ lớn của độ dịch chuyển tổng hợp của người đó từ A đến C là:","opts":["500 m.","700 m.","100 m.","1200 m."],"ans":0,"exp":"• Hai hướng Đông và Bắc vuông góc với nhau (tam giác vuông ABC tại B).<br>• <b>Độ lớn độ dịch chuyển AC:</b> d = √(AB² + BC²) = √(400² + 300²) = √(160000 + 90000) = 500 m.","svgGraph":null},{"q":"Một ô tô chạy trên đường tròn bán kính R = 100 m. Sau khi đi được nửa vòng tròn, quãng đường s và độ lớn độ dịch chuyển d của ô tô lần lượt là (lấy π ≈ 3,14):","opts":["s = 314 m; d = 200 m.","s = 628 m; d = 0 m.","s = 200 m; d = 314 m.","s = 314 m; d = 0 m."],"ans":0,"exp":"• <b>Quãng đường nửa đường tròn:</b> s = π·R = 3,14 · 100 = 314 m.<br>• <b>Độ dịch chuyển:</b> Nối hai đầu đường kính: d = 2·R = 2 · 100 = 200 m.","svgGraph":null},{"q":"Trên trục toạ độ Ox, một chất điểm ban đầu ở vị trí x₁ = -5 m chuyển động đến vị trí x₂ = +15 m. Độ dịch chuyển Δx của chất điểm trên trục Ox là:","opts":["+20 m.","+10 m.","-20 m.","-10 m."],"ans":0,"exp":"• <b>Công thức độ dịch chuyển toạ độ:</b> Δx = x₂ - x₁ = 15 - (-5) = +20 m (hướng theo chiều dương trục toạ độ).","svgGraph":null},{"q":"Một flycam bay từ điểm A lên thẳng đứng 40 m, sau đó bay ngang theo phương nằm ngang 30 m đến điểm B. Khoảng cách không gian giữa điểm xuất phát A và vị trí hiện tại B là:","opts":["50 m.","70 m.","10 m.","1200 m."],"ans":0,"exp":"• Khoảng cách không gian chính là độ lớn độ dịch chuyển nối điểm đầu A và điểm cuối B: d = √(40² + 30²) = 50 m.","svgGraph":null}],"5":[{"q":"Tốc độ trung bình v<sub>tb</sub> của một vật được xác định bằng:","opts":["Thương số giữa quãng đường đi được và khoảng thời gian để đi hết quãng đường đó (v<sub>tb</sub> = s/t).","Thương số giữa độ dịch chuyển và khoảng thời gian thực hiện độ dịch chuyển đó (v = d/t).","Tích của quãng đường đi được với khoảng thời gian chuyển động.","Đạo hàm của vận tốc tức thời theo thời gian."],"ans":0,"exp":"• <b>Định nghĩa tốc độ trung bình:</b> v<sub>tb</sub> = <span class=\"fraction\"><span class=\"numerator\">s</span><span class=\"denominator\">t</span></span>, là đại lượng vô hướng đặc trưng cho mức độ chuyển động nhanh hay chậm của vật trên suốt quãng đường s.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr5\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Speedometer Circle -->\n      <circle cx=\"250\" cy=\"130\" r=\"85\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <!-- Dial ticks -->\n      <path d=\"M 190,130 A 60 60 0 0 1 310,130\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"4\" stroke-dasharray=\"3,6\"/>\n      <!-- Needle indicating speed -->\n      <line x1=\"250\" y1=\"130\" x2=\"285\" y2=\"80\" stroke=\"#f43f5e\" stroke-width=\"3.5\" marker-end=\"url(#arr5)\"/>\n      <circle cx=\"250\" cy=\"130\" r=\"6\" fill=\"#f8fafc\"/>\n      <!-- Speed digital value -->\n      <text x=\"235\" y=\"165\" fill=\"#38bdf8\" font-size=\"18\" font-weight=\"bold\">60</text>\n      <text x=\"232\" y=\"182\" fill=\"#94a3b8\" font-size=\"11\">km/h</text>\n      <!-- Label -->\n      <text x=\"135\" y=\"35\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">Tốc kế đo tốc độ tức thời của phương tiện</text>\n      <text x=\"130\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Tốc kế hiển thị giá trị độ lớn vận tốc tại thời điểm quan sát</text>\n    </svg>"},{"q":"Vận tốc trung bình là đại lượng vectơ được tính bằng công thức:","opts":["v = d / Δt (với d là vectơ độ dịch chuyển trong khoảng thời gian Δt).","v = s / Δt (với s là quãng đường đi được).","v = a · t.","v = d · Δt."],"ans":0,"exp":"• <b>Định nghĩa vận tốc trung bình:</b> v = <span class=\"fraction\"><span class=\"numerator\">d</span><span class=\"denominator\">Δt</span></span>, là đại lượng vectơ có cùng hướng với vectơ độ dịch chuyển d, đặc trưng cho cả tốc độ và hướng chuyển động của vật.","svgGraph":null},{"q":"Một xe máy đi từ A đến B dài 60 km hết thời gian 1,5 giờ, sau đó từ B quay trở về A hết thời gian 2,5 giờ. Tốc độ trung bình của xe máy trong toàn bộ chuyến đi cả đi lẫn về là:","opts":["30 km/h.","0 km/h.","40 km/h.","24 km/h."],"ans":0,"exp":"• <b>Tổng quãng đường cả đi lẫn về:</b> s = 60 + 60 = 120 km.<br>• <b>Tổng thời gian:</b> t = 1,5 + 2,5 = 4,0 h.<br>• <b>Tốc độ trung bình:</b> v<sub>tb</sub> = <span class=\"fraction\"><span class=\"numerator\">s</span><span class=\"denominator\">t</span></span> = <span class=\"fraction\"><span class=\"numerator\">120</span><span class=\"denominator\">4</span></span> = 30 km/h. (Lưu ý: vận tốc trung bình bằng 0 vì d = 0).","svgGraph":null},{"q":"Một canô đi xuôi dòng nước từ bến A đến bến B với vận tốc 24 km/h đối với bờ. Biết vận tốc của dòng nước chảy là 4 km/h. Vận tốc của canô đối với dòng nước là:","opts":["20 km/h.","28 km/h.","16 km/h.","6 km/h."],"ans":0,"exp":"• Khi xuôi dòng: v<sub>xuôi</sub>ôi = v<sub>thuyền</sub>ền/nước + v<sub>nước</sub>ước/bờ.<br>• Thay số: 24 = v<sub>thuyền</sub>ền/nước + 4 ⇒ v<sub>thuyền</sub>ền/nước = 24 - 4 = 20 km/h.","svgGraph":null},{"q":"Một chiếc ca nô chạy ngược dòng trên đoạn sông AB mất 3 giờ. Biết khoảng cách AB = 45 km và vận tốc của canô trong nước yên lặng là 18 km/h. Vận tốc chảy của dòng nước là:","opts":["3 km/h.","15 km/h.","5 km/h.","2 km/h."],"ans":0,"exp":"• <b>Vận tốc của canô đối với bờ khi ngược dòng:</b> v<sub>ngược</sub>ược = <span class=\"fraction\"><span class=\"numerator\">45</span><span class=\"denominator\">3</span></span> = 15 km/h.<br>• <b>Công thức ngược dòng:</b> v<sub>ngược</sub>ược = v<sub>thuyền</sub>ền/nước - v<sub>nước</sub>ước/bờ ⇒ 15 = 18 - v<sub>nước</sub>ước ⇒ v<sub>nước</sub>ước = 3 km/h.","svgGraph":null},{"q":"Quy đổi vận tốc v = 72 km/h sang đơn vị m/s trong hệ SI thu được kết quả là:","opts":["20 m/s.","25 m/s.","15 m/s.","30 m/s."],"ans":0,"exp":"• <b>Quy tắc quy đổi:</b> v(m/s) = <span class=\"fraction\"><span class=\"numerator\">v(km/h)</span><span class=\"denominator\">3,6</span></span> = <span class=\"fraction\"><span class=\"numerator\">72</span><span class=\"denominator\">3,6</span></span> = 20 m/s.","svgGraph":null}],"6":[{"q":"Trong thí nghiệm đo tốc độ của xe đồ chơi chuyển động trên máng đỡ bằng đồng hồ bấm giây, tốc độ được xác định theo nguyên tắc nào?","opts":["Đo quãng đường s bằng thước đo và đo thời gian chuyển động t bằng đồng hồ bấm giây, rồi tính v = s/t.","Đọc trực tiếp giá trị vận tốc hiển thị trên màn hình của thước đo điện tử.","Dùng lực kế đo lực đẩy tác dụng lên xe rồi nhân với gia tốc trọng trường.","Đo thể tích và khối lượng của xe rồi tra bảng số liệu tiêu chuẩn."],"ans":0,"exp":"• Nguyên tắc đo gián tiếp tốc độ chuyển động: Đo trực tiếp quãng đường s bằng thước và thời gian t bằng đồng hồ, sau đó tính v qua công thức v = s/t.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr6\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Inclined track -->\n      <line x1=\"60\" y1=\"90\" x2=\"440\" y2=\"160\" stroke=\"#38bdf8\" stroke-width=\"4\"/>\n      <!-- Photogate 1 at A -->\n      <rect x=\"140\" y=\"80\" width=\"16\" height=\"35\" fill=\"#f43f5e\" rx=\"2\"/>\n      <text x=\"130\" y=\"70\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">Cổng quang 1</text>\n      <!-- Photogate 2 at B -->\n      <rect x=\"340\" y=\"115\" width=\"16\" height=\"35\" fill=\"#f43f5e\" rx=\"2\"/>\n      <text x=\"330\" y=\"105\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">Cổng quang 2</text>\n      <!-- Toy car on track -->\n      <rect x=\"180\" y=\"90\" width=\"45\" height=\"22\" fill=\"#fbbf24\" stroke=\"#d97706\" rx=\"4\"/>\n      <circle cx=\"192\" cy=\"115\" r=\"5\" fill=\"#475569\"/>\n      <circle cx=\"213\" cy=\"120\" r=\"5\" fill=\"#475569\"/>\n      <line x1=\"225\" y1=\"100\" x2=\"260\" y2=\"106\" stroke=\"#34d399\" stroke-width=\"2\" marker-end=\"url(#arr6)\"/>\n      <!-- Digital timer connection lines -->\n      <rect x=\"200\" y=\"175\" width=\"100\" height=\"40\" fill=\"#1e293b\" stroke=\"#64748b\" rx=\"5\"/>\n      <text x=\"215\" y=\"200\" fill=\"#34d399\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">0.428 s</text>\n      <line x1=\"148\" y1=\"115\" x2=\"220\" y2=\"175\" stroke=\"#f43f5e\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\"/>\n      <line x1=\"348\" y1=\"150\" x2=\"280\" y2=\"175\" stroke=\"#f43f5e\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\"/>\n      <text x=\"130\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Bộ thí nghiệm đo tốc độ bằng cổng quang điện và đồng hồ hiện số</text>\n    </svg>"},{"q":"Ưu điểm vượt trội của việc sử dụng cổng quang điện kết hợp với đồng hồ đo thời gian hiện số so với đồng hồ bấm giây thủ công bằng tay là:","opts":["Loại bỏ hoàn toàn sai số do phản xạ bấm tay của con người, đo thời gian chính xác tới phần nghìn giây.","Không cần đo quãng đường di chuyển mà đồng hồ tự tính ra vận tốc.","Thiết bị tự động khử được ma sát giữa bánh xe và mặt đường ray.","Giúp xe chuyển động nhanh hơn với gia tốc lớn hơn."],"ans":0,"exp":"• Cổng quang điện sử dụng chùm tia hồng ngoại bị ngắt mở tự động kích hoạt mạch đếm điện tử, loại bỏ thời gian trễ do phản xạ tay người (khoảng 0,1s - 0,2s).","svgGraph":null},{"q":"Khi đo tốc độ tức thời của một xe có gắn tấm chắn sáng rộng d = 2 cm đi qua một cổng quang điện duy nhất, đồng hồ hiện số đo được thời gian chắn sáng là Δt = 0,05 s. Tốc độ tức thời của xe khi qua cổng là:","opts":["0,4 m/s.","0,1 m/s.","2,5 m/s.","0,001 m/s."],"ans":0,"exp":"• <b>Đổi đơn vị:</b> d = 2 cm = 0,02 m.<br>• <b>Tốc độ tức thời:</b> v = <span class=\"fraction\"><span class=\"numerator\">d</span><span class=\"denominator\">Δt</span></span> = <span class=\"fraction\"><span class=\"numerator\">0,02</span><span class=\"denominator\">0,05</span></span> = 0,4 m/s.","svgGraph":null},{"q":"Kết quả đo quãng đường và thời gian của một chuyển động là: s = (0,600 ± 0,002) m và t = (1,50 ± 0,03) s. Sai số tỉ đối của phép đo tốc độ v = s/t là:","opts":["2,33%.","0,33%.","2,00%.","1,67%."],"ans":0,"exp":"• <b>Sai số tỉ đối của s:</b> δs = <span class=\"fraction\"><span class=\"numerator\">0,002</span><span class=\"denominator\">0,600</span></span> · 100% ≈ 0,33%.<br>• <b>Sai số tỉ đối của t:</b> δt = <span class=\"fraction\"><span class=\"numerator\">0,03</span><span class=\"denominator\">1,50</span></span> · 100% = 2,00%.<br>• <b>Sai số tỉ đối của v = s/t:</b> δv = δs + δt = 0,33% + 2,00% = 2,33%.","svgGraph":null},{"q":"Để hạn chế ảnh hưởng của lực ma sát giữa xe và máng dẫn trong bài thực hành đo tốc độ, giải pháp kĩ thuật nào sau đây là phù hợp nhất?","opts":["Sử dụng đệm khí (Air track) nâng xe lơ lửng trên luồng không khí nén mỏng.","Tăng thêm thật nhiều tải trọng nặng đè lên xe.","Bôi keo dính vào các bánh xe của xe chuyển động.","Chế tạo máng trượt có bề mặt thật gồ ghề nhám ráp."],"ans":0,"exp":"• Máng đệm không khí (Air track) phun các tia khí nén nâng xe trôi lơ lửng không tiếp xúc trực tiếp bề mặt máng, giúp triệt tiêu ma sát gần như hoàn toàn.","svgGraph":null},{"q":"Thiết bị 'súng bắn tốc độ' dùng trong kiểm tra an toàn giao thông của cảnh sát giao thông ứng dụng hiện tượng vật lí nào để đo tốc độ phương tiện?","opts":["Hiệu ứng Doppler của sóng vô tuyến hoặc chùm tia laser phản xạ từ xe đang chạy.","Cảm biến áp suất ngầm dưới lòng đường đo tải trọng xe.","Đo nhiệt lượng toả ra từ ống xả khí của động cơ xe.","Sóng siêu âm tạo cộng hưởng làm rung kính chắn gió của xe."],"ans":0,"exp":"• Súng bắn tốc độ phát sóng điện từ tới xe chuyển động; sóng phản xạ bị thay đổi tần số do hiệu ứng Doppler (hoặc đo thời gian truyền của chùm laser Lidar) từ đó máy tính tính tức thời tốc độ của xe.","svgGraph":null}],"7":[{"q":"Hệ số góc (độ dốc) của đường biểu diễn trên đồ thị độ dịch chuyển – thời gian (d – t) của một vật chuyển động thẳng đặc trưng cho:","opts":["Vận tốc chuyển động của vật.","Gia tốc chuyển động của vật.","Lực kéo tác dụng vào vật.","Công cơ học mà vật sinh ra."],"ans":0,"exp":"• <b>Ý nghĩa hệ số góc:</b> Độ dốc = <span class=\"fraction\"><span class=\"numerator\">Δd</span><span class=\"denominator\">Δt</span></span> = v. Độ dốc của đường d - t cho biết vận tốc của chuyển động. Độ dốc dương nghĩa là vật chuyển động theo chiều dương, độ dốc âm là theo chiều âm, nằm ngang là đứng yên.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr7\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Axes d and t -->\n      <line x1=\"60\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr7)\"/>\n      <line x1=\"80\" y1=\"220\" x2=\"80\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr7)\"/>\n      <text x=\"445\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">t (s)</text>\n      <text x=\"85\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">d (m)</text>\n      <!-- Line 1: Positive slope (moving forward) -->\n      <line x1=\"80\" y1=\"200\" x2=\"220\" y2=\"80\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <text x=\"140\" y=\"125\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">v₁ > 0 (đi tới)</text>\n      <!-- Line 2: Horizontal (stationary) -->\n      <line x1=\"220\" y1=\"80\" x2=\"320\" y2=\"80\" stroke=\"#fbbf24\" stroke-width=\"3\"/>\n      <text x=\"240\" y=\"70\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">v₂ = 0 (đứng yên)</text>\n      <!-- Line 3: Negative slope (moving back) -->\n      <line x1=\"320\" y1=\"80\" x2=\"420\" y2=\"170\" stroke=\"#f43f5e\" stroke-width=\"3\"/>\n      <text x=\"360\" y=\"115\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">v₃ &lt; 0 (lùi lại)</text>\n      <!-- Points -->\n      <circle cx=\"220\" cy=\"80\" r=\"4\" fill=\"#34d399\"/>\n      <circle cx=\"320\" cy=\"80\" r=\"4\" fill=\"#34d399\"/>\n      <text x=\"130\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Các dạng đường biểu diễn trên đồ thị d - t</text>\n    </svg>"},{"q":"Nếu đồ thị độ dịch chuyển – thời gian (d – t) là một đoạn thẳng nằm ngang song song với trục thời gian Ot thì vật đang:","opts":["Đứng yên tại một vị trí cố định.","Chuyển động thẳng đều với vận tốc rất lớn.","Chuyển động nhanh dần đều.","Chuyển động chậm dần đều rồi dừng lại."],"ans":0,"exp":"• Đường d - t nằm ngang tức là toạ độ/độ dịch chuyển không đổi theo thời gian (Δd = 0) ⇒ vận tốc v = Δd/Δt = 0 ⇒ vật đang đứng yên.","svgGraph":null},{"q":"Từ đồ thị d – t của một vật chuyển động thẳng, người ta thấy sau khoảng thời gian Δt = 4 s vật thực hiện độ dịch chuyển Δd = 20 m. Vận tốc của vật là:","opts":["5 m/s.","80 m/s.","0,2 m/s.","10 m/s."],"ans":0,"exp":"• <b>Công thức vận tốc từ đồ thị:</b> v = <span class=\"fraction\"><span class=\"numerator\">Δd</span><span class=\"denominator\">Δt</span></span> = <span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">4</span></span> = 5 m/s.","svgGraph":null},{"q":"Một xe ô tô chuyển động thẳng có đồ thị d – t gồm 2 giai đoạn: trong 2 giờ đầu đi được độ dịch chuyển 80 km; trong 1 giờ tiếp theo xe đứng yên nghỉ ngơi. Vận tốc trung bình của ô tô trong toàn bộ 3 giờ là:","opts":["26,7 km/h.","40 km/h.","80 km/h.","0 km/h."],"ans":0,"exp":"• <b>Tổng độ dịch chuyển:</b> d = 80 + 0 = 80 km.<br>• <b>Tổng thời gian:</b> t = 2 + 1 = 3 h.<br>• <b>Vận tốc trung bình:</b> v<sub>tb</sub> = <span class=\"fraction\"><span class=\"numerator\">80</span><span class=\"denominator\">3</span></span> ≈ 26,67 km/h.","svgGraph":null},{"q":"Đồ thị toạ độ – thời gian (x – t) của hai chuyển động thẳng đều (1) và (2) là hai đường thẳng cắt nhau tại điểm (t = 10 s, x = 50 m). Ý nghĩa vật lí của điểm giao nhau này là:","opts":["Tại thời điểm 10 s kể từ lúc bắt đầu chuyển động, hai vật gặp nhau ở toạ độ cách gốc 50 m.","Sau 10 s hai vật dừng lại hoàn toàn tại cùng một chỗ.","Hai vật có cùng vận tốc tức thời bằng 5 m/s.","Hai vật bắt đầu đổi chiều chuyển động ngược lại."],"ans":0,"exp":"• Giao điểm của hai đường x - t là nghiệm chung x₁ = x₂ và t₁ = t₂, biểu thị thời điểm và toạ độ gặp nhau của hai vật.","svgGraph":null},{"q":"Trong đồ thị d – t, đoạn thẳng đi xuống từ điểm (t = 0 s, d = 40 m) đến điểm (t = 5 s, d = 0 m). Vận tốc của vật trong khoảng thời gian này là:","opts":["-8 m/s.","+8 m/s.","-5 m/s.","+40 m/s."],"ans":0,"exp":"• <b>Công thức vận tốc:</b> v = <span class=\"fraction\"><span class=\"numerator\">d₂ - d₁</span><span class=\"denominator\">t₂ - t₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">0 - 40</span><span class=\"denominator\">5 - 0</span></span> = <span class=\"fraction\"><span class=\"numerator\">-40</span><span class=\"denominator\">5</span></span> = -8 m/s. Dấu trừ cho biết vật chuyển động ngược chiều dương.","svgGraph":null}],"8":[{"q":"Gia tốc là đại lượng vật lí đặc trưng cho:","opts":["Sự thay đổi nhanh hay chậm của vận tốc theo thời gian.","Mức độ nhanh hay chậm của toạ độ vị trí vật thể.","Độ dài quãng đường mà vật đi được trong một đơn vị thời gian.","Độ bền vững của trạng thái cân bằng lực."],"ans":0,"exp":"• <b>Định nghĩa gia tốc:</b> a = <span class=\"fraction\"><span class=\"numerator\">Δv</span><span class=\"denominator\">Δt</span></span>, là đại lượng vectơ đặc trưng cho tốc độ biến thiên của vận tốc cả về độ lớn lẫn hướng theo thời gian. Đơn vị trong hệ SI là m/s².","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr8\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Case 1: Nhanh dan deu (a and v same direction) -->\n      <g transform=\"translate(40, 40)\">\n        <rect x=\"0\" y=\"0\" width=\"190\" height=\"120\" fill=\"#1e293b\" rx=\"8\"/>\n        <text x=\"20\" y=\"25\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Nhanh dần đều: a · v > 0</text>\n        <circle cx=\"40\" cy=\"70\" r=\"14\" fill=\"#38bdf8\"/>\n        <!-- Vector v -->\n        <line x1=\"54\" y1=\"65\" x2=\"110\" y2=\"65\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr8)\"/>\n        <text x=\"75\" y=\"58\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"bold\">v</text>\n        <!-- Vector a -->\n        <line x1=\"54\" y1=\"85\" x2=\"130\" y2=\"85\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr8)\"/>\n        <text x=\"85\" y=\"102\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">a (cùng chiều v)</text>\n      </g>\n      <!-- Case 2: Cham dan deu (a and v opposite direction) -->\n      <g transform=\"translate(270, 40)\">\n        <rect x=\"0\" y=\"0\" width=\"190\" height=\"120\" fill=\"#1e293b\" rx=\"8\"/>\n        <text x=\"20\" y=\"25\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">Chậm dần đều: a · v &lt; 0</text>\n        <circle cx=\"150\" cy=\"70\" r=\"14\" fill=\"#38bdf8\"/>\n        <!-- Vector v -->\n        <line x1=\"150\" y1=\"65\" x2=\"195\" y2=\"65\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr8)\"/>\n        <text x=\"165\" y=\"58\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"bold\">v</text>\n        <!-- Vector a -->\n        <line x1=\"136\" y1=\"85\" x2=\"70\" y2=\"85\" stroke=\"#f43f5e\" stroke-width=\"3\" marker-end=\"url(#arr8)\"/>\n        <text x=\"80\" y=\"102\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">a (ngược chiều v)</text>\n      </g>\n      <text x=\"140\" y=\"210\" fill=\"#94a3b8\" font-size=\"12\">Mối quan hệ hướng giữa vectơ gia tốc a và vectơ vận tốc v</text>\n    </svg>"},{"q":"Trong chuyển động thẳng nhanh dần đều, vectơ gia tốc a luôn có hướng:","opts":["Cùng hướng với vectơ vận tốc v (tích a·v > 0).","Ngược hướng với vectơ vận tốc v (tích a·v < 0).","Vuông góc với phương chuyển động.","Tuỳ ý thay đổi không phụ thuộc vào hướng chuyển động."],"ans":0,"exp":"• Khi chuyển động nhanh dần, độ lớn vận tốc tăng lên nên vectơ gia tốc a cùng chiều với vectơ vận tốc v (a·v > 0). Ngược lại, chậm dần thì a ngược chiều v (a·v < 0).","svgGraph":null},{"q":"Một ô tô đang chuyển động với vận tốc 10 m/s thì tăng tốc đều, sau 5 giây vận tốc của xe đạt 25 m/s. Gia tốc của ô tô là:","opts":["3 m/s².","5 m/s².","7 m/s².","15 m/s²."],"ans":0,"exp":"• <b>Công thức tính gia tốc:</b> a = <span class=\"fraction\"><span class=\"numerator\">v₂ - v₁</span><span class=\"denominator\">t</span></span> = <span class=\"fraction\"><span class=\"numerator\">25 - 10</span><span class=\"denominator\">5</span></span> = <span class=\"fraction\"><span class=\"numerator\">15</span><span class=\"denominator\">5</span></span> = 3 m/s².","svgGraph":null},{"q":"Một đoàn tàu hoả đang chạy với vận tốc 72 km/h (20 m/s) thì người lái tàu hãm phanh để tàu chạy chậm dần đều. Sau 20 giây thì tàu dừng hẳn. Gia tốc của đoàn tàu là:","opts":["-1 m/s².","+1 m/s².","-2 m/s².","-3,6 m/s²."],"ans":0,"exp":"• <b>Dừng hẳn:</b> v₂ = 0.<br>• <b>Gia tốc hãm phanh:</b> a = <span class=\"fraction\"><span class=\"numerator\">v₂ - v₁</span><span class=\"denominator\">t</span></span> = <span class=\"fraction\"><span class=\"numerator\">0 - 20</span><span class=\"denominator\">20</span></span> = -1 m/s² (gia tốc ngược hướng vận tốc).","svgGraph":null},{"q":"Một vận động viên chạy nước rút bắt đầu xuất phát từ trạng thái nghỉ với gia tốc không đổi a = 4 m/s². Sau thời gian t = 2,5 giây kể từ lúc xuất phát, vận tốc của vận động viên đạt:","opts":["10 m/s.","12,5 m/s.","8 m/s.","16 m/s."],"ans":0,"exp":"• <b>Công thức vận tốc:</b> v = v₀ + at = 0 + 4 · 2,5 = 10 m/s (tương đương 36 km/h).","svgGraph":null},{"q":"Đồ thị vận tốc – thời gian (v – t) của một vật chuyển động có dạng một đường thẳng song song với trục hoành Ot. Gia tốc của vật bằng:","opts":["0 m/s².","1 m/s².","Một hằng số dương khác 0.","Vô cùng lớn."],"ans":0,"exp":"• Đường v - t song song với trục hoành tức vận tốc không thay đổi theo thời gian (v = const) ⇒ chuyển động thẳng đều ⇒ gia tốc a = 0.","svgGraph":null}],"9":[{"q":"Chuyển động thẳng biến đổi đều là chuyển động thẳng trong đó:","opts":["Gia tốc có phương, chiều và độ lớn không đổi theo thời gian (a = const).","Vận tốc tức thời có giá trị không đổi theo thời gian.","Quãng đường đi được tỉ lệ bậc nhất với thời gian chuyển động.","Độ dốc của đồ thị vận tốc – thời gian thay đổi liên tục."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Chuyển động thẳng biến đổi đều là chuyển động có quỹ đạo là đường thẳng và có gia tốc không đổi theo thời gian (a = const).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr9\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Axes v and t -->\n      <line x1=\"60\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr9)\"/>\n      <line x1=\"80\" y1=\"220\" x2=\"80\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr9)\"/>\n      <text x=\"445\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">t (s)</text>\n      <text x=\"85\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">v (m/s)</text>\n      <!-- Line: v = v0 + at -->\n      <line x1=\"80\" y1=\"150\" x2=\"380\" y2=\"60\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <!-- Intercept v0 -->\n      <circle cx=\"80\" cy=\"150\" r=\"4\" fill=\"#ef4444\"/>\n      <text x=\"55\" y=\"155\" fill=\"#ef4444\" font-size=\"13\" font-weight=\"bold\">v₀</text>\n      <!-- Shaded area for displacement d -->\n      <polygon points=\"80,150 340,72 340,200 80,200\" fill=\"#38bdf8\" opacity=\"0.15\"/>\n      <text x=\"180\" y=\"175\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">Diện tích hình thang = Độ dịch chuyển d</text>\n      <line x1=\"340\" y1=\"72\" x2=\"340\" y2=\"200\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <text x=\"335\" y=\"215\" fill=\"#fbbf24\" font-size=\"12\">t</text>\n      <text x=\"140\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Đồ thị v - t của chuyển động thẳng biến đổi đều</text>\n    </svg>"},{"q":"Hệ thức độc lập thời gian liên hệ giữa vận tốc v, vận tốc ban đầu v₀, gia tốc a và độ dịch chuyển d trong chuyển động thẳng biến đổi đều là:","opts":["v² - v₀² = 2·a·d.","v² + v₀² = 2·a·d.","v - v₀ = 2·a·d.","v² - v₀² = a·d."],"ans":0,"exp":"• <b>Hệ thức liên hệ không phụ thuộc thời gian:</b> v² - v₀² = 2ad. Nếu vật chuyển động thẳng không đổi chiều thì d = s ⇒ v² - v₀² = 2as.","svgGraph":null},{"q":"Một đoàn tàu bắt đầu rời ga (v₀ = 0) chuyển động thẳng nhanh dần đều với gia tốc a = 0,2 m/s². Quãng đường tàu đi được sau thời gian 30 giây là:","opts":["90 m.","180 m.","6 m.","45 m."],"ans":0,"exp":"• <b>Công thức tính độ dịch chuyển:</b> d = v₀t + <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>at²<br>• <b>Thay số:</b> d = 0 + <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 0,2 · (30)² = 0,1 · 900 = 90 m.","svgGraph":null},{"q":"Một xe máy đang chạy với vận tốc 36 km/h (10 m/s) thì tăng ga chuyển động nhanh dần đều với gia tốc a = 2 m/s² trên quãng đường dài 24 m. Vận tốc của xe ở cuối quãng đường này là:","opts":["14 m/s.","12 m/s.","16 m/s.","20 m/s."],"ans":0,"exp":"• <b>Sử dụng hệ thức độc lập thời gian:</b> v² - v₀² = 2as<br>• Thay số: v² - 10² = 2 · 2 · 24 = 96 ⇒ v² = 100 + 96 = 196 ⇒ v = √196 = 14 m/s.","svgGraph":null},{"q":"Một ô tô chuyển động nhanh dần đều không vận tốc ban đầu (v₀ = 0). Trong giây thứ nhất xe đi được quãng đường s₁ = 2 m. Quãng đường xe đi được trong giây thứ hai là:","opts":["6 m.","4 m.","8 m.","2 m."],"ans":0,"exp":"• <b>Bước 1: Tìm gia tốc a:</b> s₁ = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>a·(1)² = 2 m ⇒ a = 4 m/s².<br>• <b>Bước 2: Quãng đường sau 2 giây:</b> s(2) = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 4 · 2² = 8 m.<br>• <b>Quãng đường trong giây thứ hai:</b> Δs₂ = s(2) - s(1) = 8 - 2 = 6 m.","svgGraph":null},{"q":"Khoảng cách an toàn tối thiểu giữa hai ô tô đang lưu thông trên đường cao tốc với tốc độ cao dựa chủ yếu vào yếu tố vật lí nào?","opts":["Quãng đường phản xạ của tài xế cộng với quãng đường hãm phanh dừng xe.","Khối lượng xe càng nhẹ thì khoảng cách an toàn cần giữ càng xa.","Màu sơn phản quang của đuôi xe phía trước.","Công suất cực đại của hệ thống điều hoà trên xe."],"ans":0,"exp":"• Khoảng cách an toàn = Quãng đường đi trong thời gian tài xế phản xạ (khoảng 0,7s - 1s: s₁ = v·t<sub>px</sub>) + Quãng đường phanh chậm dần đều (s₂ = v² / 2a<sub>hãm</sub>).","svgGraph":null}],"10":[{"q":"Sự rơi tự do là sự rơi của một vật:","opts":["Chỉ dưới tác dụng của trọng lực trong điều kiện không có lực cản không khí.","Từ trên cao xuống dưới với vận tốc ban đầu rất lớn.","Trong đó lực cản không khí cân bằng hoàn toàn với trọng lực.","Chuyển động thẳng đều từ trên xuống dưới với vận tốc không đổi."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Sự rơi tự do là sự rơi của các vật chỉ chịu tác dụng của trọng lực. Trong thực tế, nếu sức cản của không khí rất nhỏ so với trọng lực thì có thể coi chuyển động rơi của vật là rơi tự do.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr10\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Height scale vertical line -->\n      <line x1=\"120\" y1=\"30\" x2=\"120\" y2=\"210\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <!-- Falling ball at different times -->\n      <!-- t = 0 -->\n      <circle cx=\"120\" cy=\"40\" r=\"10\" fill=\"#ef4444\"/>\n      <text x=\"145\" y=\"45\" fill=\"#fca5a5\" font-size=\"12\">t = 0 (v₀ = 0)</text>\n      <!-- t = 1s (h = 5m) -->\n      <circle cx=\"120\" cy=\"75\" r=\"10\" fill=\"#f59e0b\"/>\n      <text x=\"145\" y=\"80\" fill=\"#fde68a\" font-size=\"12\">t = 1s (h₁ = 1/2 g)</text>\n      <!-- t = 2s (h = 20m) -->\n      <circle cx=\"120\" cy=\"130\" r=\"10\" fill=\"#38bdf8\"/>\n      <text x=\"145\" y=\"135\" fill=\"#7dd3fc\" font-size=\"12\">t = 2s (h₂ = 4h₁)</text>\n      <!-- t = 3s (h = 45m) -->\n      <circle cx=\"120\" cy=\"195\" r=\"10\" fill=\"#34d399\"/>\n      <text x=\"145\" y=\"200\" fill=\"#a7f3d0\" font-size=\"12\">t = 3s (h₃ = 9h₁)</text>\n      <!-- Gravity arrow g -->\n      <line x1=\"320\" y1=\"70\" x2=\"320\" y2=\"150\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr10)\"/>\n      <text x=\"335\" y=\"115\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">g (thẳng đứng hướng xuống)</text>\n      <text x=\"120\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Ảnh chụp hoạt nghiệm chuyển động rơi tự do (khoảng cách tăng theo t²)</text>\n    </svg>"},{"q":"Chuyển động rơi tự do của một vật có tính chất là chuyển động:","opts":["Thẳng nhanh dần đều theo phương thẳng đứng từ trên xuống dưới.","Thẳng chậm dần đều theo phương nằm ngang.","Thẳng đều với vận tốc không đổi bằng 9,8 m/s.","Biến đổi phức tạp phụ thuộc vào hình dạng và khối lượng của vật."],"ans":0,"exp":"• Rơi tự do có phương thẳng đứng, chiều từ trên xuống dưới và là chuyển động thẳng nhanh dần đều với gia tốc rơi tự do g.","svgGraph":null},{"q":"Một vật được thả rơi tự do từ độ cao h = 45 m xuống đất. Lấy gia tốc trọng trường g = 10 m/s². Thời gian rơi của vật đến khi chạm đất là:","opts":["3 s.","4,5 s.","9 s.","2 s."],"ans":0,"exp":"• <b>Công thức thời gian rơi tự do:</b> t = √(<span class=\"fraction\"><span class=\"numerator\">2h</span><span class=\"denominator\">g</span></span>)<br>• <b>Thay số:</b> t = √(<span class=\"fraction\"><span class=\"numerator\">2 · 45</span><span class=\"denominator\">10</span></span>) = √9 = 3 s.","svgGraph":null},{"q":"Thả một hòn đá rơi tự do từ miệng một giếng sâu. Sau 2 giây kể từ khi thả thì nghe thấy tiếng hòn đá chạm đáy giếng. Bỏ qua thời gian truyền âm trong không khí, lấy g = 10 m/s². Độ sâu của giếng là:","opts":["20 m.","40 m.","10 m.","30 m."],"ans":0,"exp":"• <b>Công thức độ sâu rơi tự do:</b> h = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>g·t² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 10 · 2² = 5 · 4 = 20 m.","svgGraph":null},{"q":"Một vật rơi tự do chạm đất với vận tốc v = 30 m/s. Lấy g = 10 m/s². Độ cao ban đầu khi thả vật là:","opts":["45 m.","90 m.","30 m.","15 m."],"ans":0,"exp":"• <b>Công thức liên hệ:</b> v² = 2gh ⇒ h = <span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">2g</span></span> = <span class=\"fraction\"><span class=\"numerator\">30²</span><span class=\"denominator\">2 · 10</span></span> = <span class=\"fraction\"><span class=\"numerator\">900</span><span class=\"denominator\">20</span></span> = 45 m.","svgGraph":null},{"q":"Tại sao khi một chiếc lá cây và một hòn sỏi rơi trong không khí ngoài trời, hòn sỏi rơi xuống đất nhanh hơn chiếc lá?","opts":["Vì lực cản của không khí tác dụng lên chiếc lá là đáng kể so với trọng lượng rất nhỏ của nó.","Vì Trái Đất hút hòn sỏi mạnh hơn chiếc lá với gia tốc trọng trường lớn hơn.","Vì chiếc lá có khối lượng âm trong không khí quyển.","Vì lực hấp dẫn chỉ tác dụng lên các vật có dạng hình khối đặc."],"ans":0,"exp":"• Chiếc lá có diện tích bề mặt lớn và trọng lượng nhỏ nên tỉ số lực cản/trọng lực rất lớn làm giảm mạnh gia tốc rơi so với hòn sỏi đặc có lực cản không đáng kể.","svgGraph":null}],"11":[{"q":"Trong bài thực hành đo gia tốc rơi tự do bằng cổng quang điện và đồng hồ hiện số, gia tốc g được tính từ công thức:","opts":["g = 2·s / t².","g = s / (2t²).","g = 2·s · t².","g = s / t."],"ans":0,"exp":"• Từ công thức rơi tự do không vận tốc đầu: s = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>gt² ⇒ g = <span class=\"fraction\"><span class=\"numerator\">2s</span><span class=\"denominator\">t²</span></span>.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Vertical stand -->\n      <line x1=\"120\" y1=\"20\" x2=\"120\" y2=\"210\" stroke=\"#64748b\" stroke-width=\"4\"/>\n      <!-- Electromagnet at top -->\n      <rect x=\"105\" y=\"25\" width=\"30\" height=\"20\" fill=\"#dc2626\" rx=\"3\"/>\n      <text x=\"145\" y=\"40\" fill=\"#fca5a5\" font-size=\"11\">Nam châm điện</text>\n      <!-- Steel ball dropped -->\n      <circle cx=\"120\" cy=\"55\" r=\"7\" fill=\"#f8fafc\"/>\n      <!-- Photogate A -->\n      <rect x=\"100\" y=\"80\" width=\"40\" height=\"15\" fill=\"#0284c7\" rx=\"2\"/>\n      <text x=\"145\" y=\"92\" fill=\"#7dd3fc\" font-size=\"11\">Cổng quang A</text>\n      <!-- Photogate B -->\n      <rect x=\"100\" y=\"170\" width=\"40\" height=\"15\" fill=\"#0284c7\" rx=\"2\"/>\n      <text x=\"145\" y=\"182\" fill=\"#7dd3fc\" font-size=\"11\">Cổng quang B</text>\n      <!-- Height distance s -->\n      <line x1=\"85\" y1=\"80\" x2=\"85\" y2=\"170\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"85\" cy=\"80\" r=\"3\" fill=\"#fbbf24\"/>\n      <circle cx=\"85\" cy=\"170\" r=\"3\" fill=\"#fbbf24\"/>\n      <text x=\"60\" y=\"130\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">s</text>\n      <!-- Digital Timer Screen -->\n      <rect x=\"250\" y=\"80\" width=\"160\" height=\"70\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"8\"/>\n      <text x=\"270\" y=\"110\" fill=\"#94a3b8\" font-size=\"11\">ĐỒNG HỒ HIỆN SỐ</text>\n      <text x=\"275\" y=\"135\" fill=\"#34d399\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">0.285 s</text>\n      <text x=\"140\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Mô hình bố trí thí nghiệm đo gia tốc rơi tự do</text>\n    </svg>"},{"q":"Vai trò của nam châm điện đặt ở đỉnh giá đỡ trong thí nghiệm đo gia tốc rơi tự do là:","opts":["Giữ viên bi đứng yên và thả rơi viên bi với vận tốc ban đầu triệt tiêu hoàn toàn (v₀ = 0).","Khuếch đại gia tốc rơi của viên bi lên mức lớn hơn bình thường.","Đẩy viên bi rơi xuống với lực điện từ cực mạnh.","Đo trực tiếp khối lượng của viên bi kim loại."],"ans":0,"exp":"• Nam châm điện giữ viên bi cố định; khi ngắt công tắc điện, từ trường mất tức thì viên bi bắt đầu rơi tự do với vận tốc đầu v₀ = 0 hoàn toàn không có lực đẩy cơ học bằng tay.","svgGraph":null},{"q":"Trong một lần thí nghiệm, đo được quãng đường rơi tự do s = (0,784 ± 0,002) m và thời gian rơi t = (0,400 ± 0,004) s. Giá trị trung bình của gia tốc rơi tự do g<sub>tb</sub> là:","opts":["9,80 m/s².","9,75 m/s².","9,85 m/s².","10,0 m/s²."],"ans":0,"exp":"• <b>Giá trị trung bình của g:</b><br>g<sub>tb</sub> = <span class=\"fraction\"><span class=\"numerator\">2·s<sub>tb</sub></span><span class=\"denominator\">t<sub>tb</sub>²</span></span> = <span class=\"fraction\"><span class=\"numerator\">2 · 0,784</span><span class=\"denominator\">(0,400)²</span></span> = <span class=\"fraction\"><span class=\"numerator\">1,568</span><span class=\"denominator\">0,16</span></span> = 9,80 m/s².","svgGraph":null},{"q":"Biết sai số tỉ đối của phép đo quãng đường là δs = 0,4% và sai số tỉ đối của phép đo thời gian là δt = 0,8%. Sai số tỉ đối của phép đo gia tốc rơi tự do g là:","opts":["2,0%.","1,2%.","1,6%.","0,4%."],"ans":0,"exp":"• <b>Công thức sai số tỉ đối của g = 2s/t²:</b><br>δg = δs + 2·δt = 0,4% + 2 · 0,8% = 0,4% + 1,6% = 2,0%.","svgGraph":null},{"q":"Kết quả đo gia tốc rơi tự do tại phòng thí nghiệm của trường thu được là g = (9,78 ± 0,12) m/s². Khoảng giá trị tin cậy của gia tốc rơi tự do đo được là:","opts":["Từ 9,66 m/s² đến 9,90 m/s².","Từ 9,78 m/s² đến 9,90 m/s².","Từ 9,66 m/s² đến 9,78 m/s².","Từ 9,80 m/s² đến 10,0 m/s²."],"ans":0,"exp":"• Khoảng tin cậy: [g<sub>tb</sub> - Δg ; g<sub>tb</sub> + Δg] = [9,78 - 0,12 ; 9,78 + 0,12] = [9,66 ; 9,90] m/s².","svgGraph":null},{"q":"Nếu không có đồng hồ hiện số và cổng quang điện, có thể đo sơ bộ gia tốc rơi tự do bằng phương pháp truyền thống nào sau đây?","opts":["Sử dụng đồng hồ bấm giây thủ công đo chu kì dao động của con lắc đơn chiều dài L rồi tính g = 4π²L / T².","Dùng nhiệt kế đo nhiệt độ nóng chảy của nước đá.","Dùng lực kế đo thể tích của một khối chì nhúng trong nước.","Dùng kính hiển vi quan sát tế bào thực vật."],"ans":0,"exp":"• Con lắc đơn T = 2π√(L/g) ⇒ g = 4π²L/T² là phương pháp đo gia tốc trọng trường kinh điển rất chính xác với dụng cụ đơn giản.","svgGraph":null}],"12":[{"q":"Chuyển động ném ngang là chuyển động có thể phân tích thành hai chuyển động thành phần độc lập:","opts":["Chuyển động thẳng đều theo phương ngang (Ox) và chuyển động rơi tự do theo phương thẳng đứng (Oy).","Chuyển động thẳng biến đổi đều theo phương ngang và đứng yên theo phương thẳng đứng.","Hai chuyển động thẳng đều theo cả phương ngang và phương thẳng đứng.","Hai chuyển động rơi tự do theo cả hai phương vuông góc nhau."],"ans":0,"exp":"• <b>Nguyên tắc độc lập chuyển động:</b> Theo phương ngang Ox không có lực tác dụng (F<sub>x</sub> = 0) nên chuyển động thẳng đều với v<sub>x</sub> = v₀. Theo phương thẳng đứng Oy chỉ chịu trọng lực P nên rơi tự do với gia tốc a<sub>y</sub> = g.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr12\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Height cliff at Left -->\n      <rect x=\"50\" y=\"40\" width=\"40\" height=\"160\" fill=\"#1e293b\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <line x1=\"50\" y1=\"200\" x2=\"450\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <!-- Launch point O -->\n      <circle cx=\"90\" cy=\"40\" r=\"6\" fill=\"#ef4444\"/>\n      <text x=\"75\" y=\"32\" fill=\"#ef4444\" font-size=\"13\" font-weight=\"bold\">O</text>\n      <!-- Initial horizontal velocity v0 -->\n      <line x1=\"90\" y1=\"40\" x2=\"160\" y2=\"40\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr12)\"/>\n      <text x=\"120\" y=\"30\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">v₀</text>\n      <!-- Parabolic trajectory -->\n      <path d=\"M 90,40 Q 230,40 370,200\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"3\"/>\n      <!-- Impact point on ground -->\n      <circle cx=\"370\" cy=\"200\" r=\"5\" fill=\"#34d399\"/>\n      <!-- Height h and Range L -->\n      <line x1=\"35\" y1=\"40\" x2=\"35\" y2=\"200\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n      <text x=\"15\" y=\"125\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">h</text>\n      <line x1=\"90\" y1=\"215\" x2=\"370\" y2=\"215\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <text x=\"210\" y=\"230\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Tầm xa L = v₀·√(2h/g)</text>\n    </svg>"},{"q":"Quỹ đạo chuyển động của một vật ném ngang có dạng là:","opts":["Một nhánh của đường parabol có đỉnh tại vị trí ném.","Một đường thẳng dốc nghiêng nối từ điểm ném xuống đất.","Một cung tròn bán kính bằng độ cao thả vật.","Một đường xoắn ốc quanh trục thẳng đứng."],"ans":0,"exp":"• <b>Phương trình quỹ đạo:</b> Khử thời gian t từ x = v₀t và y = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>gt² ta được: y = (<span class=\"fraction\"><span class=\"numerator\">g</span><span class=\"denominator\">2v₀²</span></span>)·x². Đây là phương trình của một nhánh parabol đỉnh O.","svgGraph":null},{"q":"Một vật được ném ngang từ độ cao h = 20 m với vận tốc ban đầu v₀ = 15 m/s. Lấy g = 10 m/s². Tầm ném xa L của vật khi chạm đất là:","opts":["30 m.","15 m.","45 m.","60 m."],"ans":0,"exp":"• <b>Bước 1: Tính thời gian bay t:</b> t = √(<span class=\"fraction\"><span class=\"numerator\">2h</span><span class=\"denominator\">g</span></span>) = √(<span class=\"fraction\"><span class=\"numerator\">2 · 20</span><span class=\"denominator\">10</span></span>) = √4 = 2 s.<br>• <b>Bước 2: Tính tầm ném xa L:</b> L = v₀ · t = 15 · 2 = 30 m.","svgGraph":null},{"q":"Một máy bay cứu trợ đang bay theo phương ngang ở độ cao h = 500 m với tốc độ 180 km/h (50 m/s) muốn thả một gói hàng rơi trúng vị trí người gặp nạn trên mặt đất. Lấy g = 10 m/s². Máy bay phải thả gói hàng khi còn cách vị trí người gặp nạn theo phương ngang một khoảng cách là:","opts":["500 m.","1000 m.","250 m.","750 m."],"ans":0,"exp":"• <b>Bước 1: Tính thời gian rơi của gói hàng:</b><br>t = √(<span class=\"fraction\"><span class=\"numerator\">2h</span><span class=\"denominator\">g</span></span>) = √(<span class=\"fraction\"><span class=\"numerator\">2 · 500</span><span class=\"denominator\">10</span></span>) = √100 = 10 s.<br>• <b>Bước 2: Tầm bay ngang của gói hàng:</b><br>L = v₀ · t = 50 · 10 = 500 m. Vậy phải thả trước 500 m.","svgGraph":null},{"q":"Một vật được ném ngang từ độ cao h với vận tốc v₀ = 10 m/s. Lấy g = 10 m/s². Sau 1 giây kể từ lúc ném, góc hợp bởi vectơ vận tốc tức thời của vật với phương ngang là:","opts":["45°.","30°.","60°.","90°."],"ans":0,"exp":"• <b>Thành phần vận tốc:</b> v<sub>x</sub> = v₀ = 10 m/s; v<sub>y</sub> = g·t = 10 · 1 = 10 m/s.<br>• <b>Góc hợp với phương ngang:</b> tan(β) = <span class=\"fraction\"><span class=\"numerator\">v<sub>y</sub></span><span class=\"denominator\">v<sub>x</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">10</span><span class=\"denominator\">10</span></span> = 1 ⇒ β = 45°.","svgGraph":null},{"q":"Trong các môn thể thao như ném lao, đẩy tạ, ném đĩa, yếu tố nào sau đây đóng vai trò quyết định nhiều nhất đến thành tích tầm xa của vận động viên?","opts":["Tốc độ giải phóng vật ném (v₀) và góc ném tối ưu (khoảng 38° - 44° tuỳ độ cao người ném).","Màu sắc của dụng cụ thi đấu phản xạ ánh sáng mặt trời.","Thời gian vận động viên khởi động trước trận đấu.","Nhiệt độ môi trường phòng thay đồ."],"ans":0,"exp":"• Tầm xa L tỉ lệ với bình phương vận tốc đầu v₀² (yếu tố quan trọng hàng đầu) kết hợp với việc lựa chọn góc ném tối ưu phù hợp với độ cao tay người ném.","svgGraph":null}],"13":[{"q":"Tổng hợp lực là phép thay thế hai hay nhiều lực tác dụng đồng thời vào một vật bằng một lực duy nhất có tác dụng:","opts":["Giống hệt như tác dụng của tất cả các lực thành phần đó.","Gấp đôi tác dụng của các lực thành phần ban đầu.","Làm triệt tiêu hoàn toàn chuyển động của vật.","Làm vật đổi hướng chuyển động sang phương vuông góc."],"ans":0,"exp":"• <b>Định nghĩa tổng hợp lực:</b> Tổng hợp lực là thay thế các lực tác dụng đồng thời vào cùng một vật bằng một lực có tác dụng giống hệt như các lực ấy. Lực thay thế gọi là hợp lực: F = F₁ + F₂.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr13\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Origin point O -->\n      <circle cx=\"120\" cy=\"170\" r=\"6\" fill=\"#f8fafc\"/>\n      <text x=\"100\" y=\"180\" fill=\"#f8fafc\" font-size=\"13\" font-weight=\"bold\">O</text>\n      <!-- Force F1 (horizontal) -->\n      <line x1=\"120\" y1=\"170\" x2=\"280\" y2=\"170\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr13)\"/>\n      <text x=\"210\" y=\"190\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">F₁</text>\n      <!-- Force F2 (angled 45 deg) -->\n      <line x1=\"120\" y1=\"170\" x2=\"220\" y2=\"70\" stroke=\"#fbbf24\" stroke-width=\"3\" marker-end=\"url(#arr13)\"/>\n      <text x=\"155\" y=\"105\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">F₂</text>\n      <!-- Parallelogram dotted lines -->\n      <line x1=\"280\" y1=\"170\" x2=\"380\" y2=\"70\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n      <line x1=\"220\" y1=\"70\" x2=\"380\" y2=\"70\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n      <!-- Resultant Force F (diagonal) -->\n      <line x1=\"120\" y1=\"170\" x2=\"375\" y2=\"73\" stroke=\"#34d399\" stroke-width=\"3.5\" marker-end=\"url(#arr13)\"/>\n      <text x=\"260\" y=\"105\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">F (Hợp lực)</text>\n      <text x=\"135\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Quy tắc hình bình hành tổng hợp hai lực đồng quy</text>\n    </svg>"},{"q":"Hai lực đồng quy F₁ và F₂ có độ lớn lần lượt là 6 N và 8 N, hợp với nhau một góc 90° (vuông góc nhau). Độ lớn hợp lực F của hai lực này là:","opts":["10 N.","14 N.","2 N.","48 N."],"ans":0,"exp":"• <b>Công thức góc vuông:</b> F = √(F₁² + F₂²)<br>• <b>Thay số:</b> F = √(6² + 8²) = √(36 + 64) = √100 = 10 N.","svgGraph":null},{"q":"Điều kiện cân bằng của một chất điểm chịu tác dụng của nhiều lực là:","opts":["Hợp lực của tất cả các lực tác dụng lên vật phải triệt tiêu bằng 0 (F = ∑F<sub>i</sub> = 0).","Tổng độ lớn của các lực tác dụng phải là một số dương cực đại.","Các lực tác dụng phải có cùng phương và cùng chiều.","Vật phải chuyển động với gia tốc lớn nhất có thể."],"ans":0,"exp":"• <b>Điều kiện cân bằng:</b> Một chất điểm ở trạng thái cân bằng khi và chỉ khi hợp lực của tất cả các lực tác dụng lên nó bằng 0: F = F₁ + F₂ + ... = 0.","svgGraph":null},{"q":"Một vật có trọng lượng P = 20 N được giữ yên trên một mặt phẳng nghiêng góc α = 30° so với phương ngang bởi một sợi dây song song với mặt nghiêng. Bỏ qua ma sát. Lực căng T của sợi dây có độ lớn là:","opts":["10 N.","17,3 N.","20 N.","5 N."],"ans":0,"exp":"• <b>Phân tích trọng lực:</b> Thành phần trọng lực kéo vật trượt dọc theo mặt phẳng nghiêng là: P₁ = P·sin(α).<br>• Vì vật cân bằng nên lực căng dây: T = P₁ = P·sin(30°) = 20 · 0,5 = 10 N.","svgGraph":null},{"q":"Hai người cùng kéo một chiếc thuyền nhỏ bằng hai sợi dây tạo với phương chuyển động của thuyền các góc bằng nhau α = 30°. Lực kéo của mỗi người có độ lớn bằng nhau F₁ = F₂ = 100 N. Hợp lực kéo tác dụng lên thuyền theo phương chuyển động xấp xỉ bằng:","opts":["173 N.","200 N.","100 N.","141 N."],"ans":0,"exp":"• <b>Góc giữa hai lực:</b> θ = 2α = 60°.<br>• <b>Công thức hợp lực khi F₁ = F₂:</b> F = 2·F₁·cos(<span class=\"fraction\"><span class=\"numerator\">θ</span><span class=\"denominator\">2</span></span>) = 2 · 100 · cos(30°) = 200 · <span class=\"fraction\"><span class=\"numerator\">√3</span><span class=\"denominator\">2</span></span> = 100√3 ≈ 173,2 N.","svgGraph":null},{"q":"Một chất điểm cân bằng dưới tác dụng của ba lực đồng quy F₁, F₂, F₃. Nếu giữ nguyên độ lớn và phương chiều của F₁ và F₂ nhưng bỏ đi lực F₃ thì hợp lực của hai lực còn lại là:","opts":["Một lực có cùng phương, cùng độ lớn nhưng ngược chiều với lực F₃.","Một lực có độ lớn bằng 0.","Một lực có cùng chiều hoàn toàn với lực F₃.","Một lực có độ lớn bằng tổng độ lớn (F₁ + F₂ + F₃)."],"ans":0,"exp":"• Vì F₁ + F₂ + F₃ = 0 ⇒ F₁₂ = F₁ + F₂ = -F₃. Hợp lực F₁₂ là vectơ trực đối với F₃.","svgGraph":null}],"14":[{"q":"Nội dung định luật 1 Newton phát biểu rằng:","opts":["Nếu một vật không chịu tác dụng của lực nào hoặc chịu tác dụng của các lực có hợp lực bằng không, thì vật đang đứng yên sẽ tiếp tục đứng yên, đang chuyển động sẽ tiếp tục chuyển động thẳng đều.","Gia tốc của một vật luôn tỉ lệ thuận với lực tác dụng và tỉ lệ nghịch với khối lượng của vật.","Trong mọi trường hợp tương tác, lực tác dụng luôn bằng phản lực nhưng ngược chiều.","Mọi vật trong tự nhiên đều có xu hướng dừng lại nếu không có lực duy trì chuyển động."],"ans":0,"exp":"• <b>Định luật 1 Newton:</b> Nếu hợp lực tác dụng lên vật bằng 0 (F = 0) thì gia tốc của vật a = 0; vật giữ nguyên trạng thái đứng yên hoặc chuyển động thẳng đều ban đầu.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr14\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Bus outline braking -->\n      <rect x=\"100\" y=\"70\" width=\"280\" height=\"100\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2.5\" rx=\"10\"/>\n      <!-- Bus wheels -->\n      <circle cx=\"160\" cy=\"170\" r=\"18\" fill=\"#475569\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <circle cx=\"320\" cy=\"170\" r=\"18\" fill=\"#475569\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <!-- Passenger leaning forward due to inertia -->\n      <circle cx=\"250\" cy=\"95\" r=\"9\" fill=\"#ef4444\"/>\n      <line x1=\"250\" y1=\"104\" x2=\"265\" y2=\"135\" stroke=\"#ef4444\" stroke-width=\"4\"/>\n      <line x1=\"265\" y1=\"135\" x2=\"260\" y2=\"160\" stroke=\"#ef4444\" stroke-width=\"3\"/>\n      <!-- Motion and Braking Arrow -->\n      <line x1=\"200\" y1=\"45\" x2=\"280\" y2=\"45\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr14)\"/>\n      <text x=\"210\" y=\"38\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">v (xe chạy tới)</text>\n      <text x=\"280\" y=\"105\" fill=\"#fca5a5\" font-size=\"11\" font-weight=\"bold\">Hành khách chúi về phía trước</text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Hiện tượng quán tính: hành khách chúi người khi xe phanh gấp</text>\n    </svg>"},{"q":"Quán tính là tính chất của mọi vật có xu hướng:","opts":["Bảo toàn vận tốc của nó cả về hướng và độ lớn.","Tự động tăng vận tốc khi không có ngoại lực tác dụng.","Biến đổi hình dạng liên tục trong không gian.","Dừng lại ngay lập tức khi thôi tác dụng lực."],"ans":0,"exp":"• <b>Định nghĩa quán tính:</b> Quán tính là tính chất bảo toàn trạng thái đứng yên hoặc chuyển động thẳng đều (bảo toàn vectơ vận tốc) của vật.","svgGraph":null},{"q":"Đại lượng vật lí nào sau đây là thước đo mức quán tính của một vật?","opts":["Khối lượng của vật.","Trọng lượng của vật.","Vận tốc chuyển động của vật.","Thể tích của vật."],"ans":0,"exp":"• Khối lượng là đại lượng đặc trưng cho mức quán tính của vật: vật có khối lượng càng lớn thì mức quán tính càng lớn (càng khó làm thay đổi vận tốc của nó).","svgGraph":null},{"q":"Một tàu vũ trụ đang bay trong không gian sâu thẳm giữa các vì sao, rất xa mọi thiên thể lớn nên lực hấp dẫn coi như triệt tiêu hoàn toàn. Nếu động cơ tên lửa tắt hẳn thì con tàu sẽ:","opts":["Tiếp tục chuyển động thẳng đều mãi mãi với vận tốc không đổi.","Dừng lại ngay lập tức tại vị trí động cơ tắt.","Chuyển động chậm dần đều rồi dừng lại sau vài ngày.","Quay tròn tại chỗ vô hạn định."],"ans":0,"exp":"• Theo định luật 1 Newton: Trong không gian chân không không có lực cản và không có lực hấp dẫn (∑F = 0), con tàu bảo toàn vận tốc và bay thẳng đều vĩnh viễn.","svgGraph":null},{"q":"Một cuốn sách nằm yên trên mặt bàn nằm ngang. Cặp lực nào sau đây là hai lực cân bằng tác dụng lên cuốn sách?","opts":["Trọng lực của Trái Đất hút cuốn sách và phản lực của mặt bàn nâng cuốn sách.","Trọng lực của Trái Đất hút cuốn sách và lực hút của cuốn sách tác dụng lên Trái Đất.","Áp lực của cuốn sách đè lên bàn và phản lực của bàn nâng cuốn sách.","Trọng lực của cuốn sách và lực ma sát nghỉ giữa sách với bàn."],"ans":0,"exp":"• Cuốn sách cân bằng nên hai lực tác dụng trực tiếp lên cuốn sách là trọng lực P (hướng xuống) và phản lực N của mặt bàn (hướng lên) là hai lực cân bằng: P + N = 0.","svgGraph":null},{"q":"Tại sao các xe tải chở hàng siêu trường, siêu trọng lại bị hạn chế tốc độ tối đa thấp hơn so với xe ô tô con du lịch trên các tuyến đường?","opts":["Vì xe tải có khối lượng rất lớn dẫn đến mức quán tính cực kì lớn, quãng đường phanh dừng xe sẽ rất dài nếu chạy nhanh.","Vì xe tải tiêu thụ nhiều nhiên liệu hơn khi chạy ở tốc độ cao.","Vì kích thước xe tải quá lớn làm cản trở tầm nhìn của camera phạt nguội.","Vì động cơ xe tải không thể đạt được tốc độ của xe con."],"ans":0,"exp":"• Khối lượng m lớn dẫn tới mức quán tính lớn, làm việc hãm dừng xe rất khó khăn; gia tốc hãm nhỏ khiến quãng đường phanh dài gây nguy cơ tai nạn nghiêm trọng.","svgGraph":null}],"15":[{"q":"Định luật 2 Newton phát biểu rằng gia tốc a của một vật có cùng hướng với lực tác dụng F và:","opts":["Tỉ lệ thuận với độ lớn của lực tác dụng và tỉ lệ nghịch với khối lượng của vật (a = F / m).","Tỉ lệ thuận với khối lượng của vật và tỉ lệ nghịch với độ lớn của lực.","Tỉ lệ thuận với bình phương của lực tác dụng lên vật.","Không phụ thuộc vào khối lượng mà chỉ phụ thuộc vào vận tốc ban đầu."],"ans":0,"exp":"• <b>Định luật 2 Newton:</b> a = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">m</span></span> hay F = m·a. Vectơ gia tốc luôn cùng hướng với vectơ hợp lực tác dụng lên vật.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr15\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Block on horizontal ground -->\n      <line x1=\"60\" y1=\"170\" x2=\"440\" y2=\"170\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <rect x=\"180\" y=\"110\" width=\"90\" height=\"60\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2.5\" rx=\"5\"/>\n      <text x=\"215\" y=\"145\" fill=\"#f8fafc\" font-size=\"16\" font-weight=\"bold\">m</text>\n      <!-- Force vector F -->\n      <line x1=\"270\" y1=\"140\" x2=\"380\" y2=\"140\" stroke=\"#fbbf24\" stroke-width=\"3.5\" marker-end=\"url(#arr15)\"/>\n      <text x=\"315\" y=\"130\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">Lực F</text>\n      <!-- Acceleration vector a -->\n      <line x1=\"225\" y1=\"85\" x2=\"310\" y2=\"85\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr15)\"/>\n      <text x=\"245\" y=\"75\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Gia tốc a = F/m</text>\n      <!-- Vertical forces P and N -->\n      <line x1=\"225\" y1=\"140\" x2=\"225\" y2=\"205\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr15)\"/>\n      <text x=\"235\" y=\"200\" fill=\"#94a3b8\" font-size=\"11\">P</text>\n      <line x1=\"225\" y1=\"140\" x2=\"225\" y2=\"40\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr15)\"/>\n      <text x=\"235\" y=\"50\" fill=\"#94a3b8\" font-size=\"11\">N</text>\n      <text x=\"145\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Mô hình định luật 2 Newton: F = m·a</text>\n    </svg>"},{"q":"Một lực không đổi F = 20 N tác dụng lên một vật có khối lượng m = 4 kg đang đứng yên trên mặt sàn trơn nhẵn nằm ngang. Gia tốc mà vật thu được là:","opts":["5 m/s².","80 m/s².","0,2 m/s².","10 m/s²."],"ans":0,"exp":"• <b>Công thức định luật 2 Newton:</b> a = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">m</span></span><br>• <b>Thay số:</b> a = <span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">4</span></span> = 5 m/s².","svgGraph":null},{"q":"Trong hệ đơn vị SI, đơn vị lực Newton (N) được định nghĩa theo các đơn vị cơ bản là:","opts":["1 N = 1 kg·m/s².","1 N = 1 kg·m²/s².","1 N = 1 kg·m/s.","1 N = 1 g·cm/s²."],"ans":0,"exp":"• Từ F = m·a: đơn vị khối lượng là kg, gia tốc là m/s² ⇒ 1 N = 1 kg · 1 m/s² = 1 kg·m/s².","svgGraph":null},{"q":"Một quả bóng khối lượng m = 500 g đang bay với vận tốc 10 m/s thì bị một cầu thủ sút trả ngược lại theo đúng phương cũ với vận tốc 15 m/s. Thời gian bóng tiếp xúc với chân cầu thủ là 0,05 s. Lực trung bình của cú sút tác dụng lên bóng là:","opts":["250 N.","50 N.","100 N.","150 N."],"ans":0,"exp":"• Chọn chiều dương là chiều bật lại của bóng: v₁ = -10 m/s; v₂ = +15 m/s.<br>• <b>Độ biến thiên vận tốc:</b> Δv = v₂ - v₁ = 15 - (-10) = 25 m/s.<br>• <b>Lực tác dụng:</b> F = m·<span class=\"fraction\"><span class=\"numerator\">Δv</span><span class=\"denominator\">Δt</span></span> = 0,5 · <span class=\"fraction\"><span class=\"numerator\">25</span><span class=\"denominator\">0,05</span></span> = 0,5 · 500 = 250 N.","svgGraph":null},{"q":"Một ô tô có khối lượng 1,2 tấn đang chạy với tốc độ 72 km/h (20 m/s) thì hãm phanh chuyển động chậm dần đều và dừng lại sau khi đi thêm được 50 m. Lực hãm phanh tác dụng lên xe là:","opts":["4800 N.","2400 N.","9600 N.","1200 N."],"ans":0,"exp":"• <b>Bước 1: Tính gia tốc hãm:</b><br>v² - v₀² = 2as ⇒ 0² - 20² = 2 · a · 50 ⇒ 100a = -400 ⇒ a = -4 m/s².<br>• <b>Bước 2: Tính độ lớn lực hãm phanh:</b><br>F<sub>h</sub>ãm = m·|a| = 1200 · 4 = 4800 N.","svgGraph":null},{"q":"Hệ túi khí (Airbag) trên ô tô bung ra trong các vụ va chạm giao thông nhằm mục đích vật lí cơ bản nào?","opts":["Kéo dài thời gian va chạm Δt của người với vô lăng, từ đó làm giảm lực va đập F = Δp / Δt tác dụng lên cơ thể.","Làm tăng khối lượng của người lái xe để tăng mức quán tính.","Triệt tiêu hoàn toàn động lượng của xe ô tô trong 0,001 giây.","Làm mát nhiệt độ cabin xe sau khi va chạm."],"ans":0,"exp":"• Theo định luật 2 Newton: F = Δp / Δt. Với cùng một độ biến thiên động lượng Δp, túi khí làm tăng thời gian hãm dừng Δt lên hàng chục lần giúp lực cản tác dụng lên đầu và ngực người giảm đi rất nhiều, hạn chế chấn thương tử vong.","svgGraph":null}],"16":[{"q":"Theo định luật 3 Newton, trong mọi trường hợp khi vật A tác dụng lên vật B một lực, thì vật B cũng tác dụng lại vật A một lực. Hai lực này là hai lực:","opts":["Trực đối: cùng phương, cùng độ lớn nhưng ngược chiều và đặt vào hai vật khác nhau.","Cân bằng: cùng đặt vào một vật và triệt tiêu lẫn nhau.","Cùng phương, cùng chiều và cùng độ lớn.","Có độ lớn tỉ lệ nghịch với khối lượng của hai vật tương tác."],"ans":0,"exp":"• <b>Định luật 3 Newton:</b> F<sub>AB</sub> = -F<sub>BA</sub>. Lực và phản lực luôn xuất hiện và mất đi đồng thời thành từng cặp; chúng có cùng bản chất, cùng giá, ngược chiều, cùng độ lớn nhưng đặt vào hai vật khác nhau nên không bao giờ triệt tiêu lẫn nhau.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr16\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Body A -->\n      <circle cx=\"160\" cy=\"120\" r=\"35\" fill=\"#1e293b\" stroke=\"#ef4444\" stroke-width=\"2.5\"/>\n      <text x=\"140\" y=\"125\" fill=\"#fca5a5\" font-size=\"16\" font-weight=\"bold\">Vật A</text>\n      <!-- Body B -->\n      <circle cx=\"340\" cy=\"120\" r=\"35\" fill=\"#1e293b\" stroke=\"#3b82f6\" stroke-width=\"2.5\"/>\n      <text x=\"320\" y=\"125\" fill=\"#93c5fd\" font-size=\"16\" font-weight=\"bold\">Vật B</text>\n      <!-- Force F₂₁ (B acts on A, points to left) -->\n      <line x1=\"160\" y1=\"120\" x2=\"60\" y2=\"120\" stroke=\"#ef4444\" stroke-width=\"3.5\" marker-end=\"url(#arr16)\"/>\n      <text x=\"70\" y=\"105\" fill=\"#ef4444\" font-size=\"13\" font-weight=\"bold\">F₂₁</text>\n      <!-- Force F₁₂ (A acts on B, points to right) -->\n      <line x1=\"340\" y1=\"120\" x2=\"440\" y2=\"120\" stroke=\"#3b82f6\" stroke-width=\"3.5\" marker-end=\"url(#arr16)\"/>\n      <text x=\"380\" y=\"105\" fill=\"#3b82f6\" font-size=\"13\" font-weight=\"bold\">F₁₂</text>\n      <text x=\"180\" y=\"80\" fill=\"#fbbf24\" font-size=\"15\" font-weight=\"bold\">F₁₂ = -F₂₁</text>\n      <text x=\"135\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Cặp lực và phản lực tương tác trực đối theo Định luật 3 Newton</text>\n    </svg>"},{"q":"Tại sao lực và phản lực trong định luật 3 Newton KHÔNG THỂ cân bằng và triệt tiêu lẫn nhau?","opts":["Vì chúng tác dụng lên hai vật hoàn toàn khác nhau.","Vì độ lớn của chúng luôn khác nhau.","Vì phương tác dụng của chúng vuông góc với nhau.","Vì chúng không xuất hiện cùng một thời điểm."],"ans":0,"exp":"• Hai lực cân bằng phải cùng đặt lên một vật thể duy nhất. Cặp lực và phản lực đặt lên hai vật tương tác riêng biệt nên chúng không thể tự triệt tiêu nhau.","svgGraph":null},{"q":"Một con ngựa kéo một cỗ xe chuyển động về phía trước trên đường. Theo định luật 3 Newton, lực mà cỗ xe tác dụng lên con ngựa có độ lớn:","opts":["Luôn luôn bằng độ lớn lực mà con ngựa tác dụng lên cỗ xe.","Nhỏ hơn lực mà con ngựa tác dụng lên cỗ xe nên xe mới chạy tới được.","Lớn hơn lực con ngựa tác dụng lên cỗ xe.","Bằng không vì xe bị kéo đi một cách thụ động."],"ans":0,"exp":"• Theo định luật 3 Newton, trong mọi trạng thái (đứng yên, tăng tốc, chuyển động đều), lực ngựa kéo xe luôn có độ lớn bằng lực xe kéo lại ngựa. Xe chạy tới được là nhờ hợp lực tác dụng lên xe dương (lực kéo > ma sát) và hợp lực lên ngựa dương (lực ma sát đất đẩy chân ngựa > lực xe kéo lại).","svgGraph":null},{"q":"Một người có khối lượng m = 60 kg đứng trên một tấm ván trượt trên mặt băng trơn trượt ném một quả tạ khối lượng M = 3 kg về phía trước với vận tốc v = 8 m/s. Bỏ qua ma sát với mặt băng. Vận tốc giật lùi của người và ván trượt ngay sau khi ném là:","opts":["-0,4 m/s.","-0,8 m/s.","-1,2 m/s.","-2,4 m/s."],"ans":0,"exp":"• <b>Bảo toàn động lượng:</b> m·V + M·v = 0<br>• <b>Vận tốc giật lùi:</b> V = -<span class=\"fraction\"><span class=\"numerator\">M·v</span><span class=\"denominator\">m</span></span> = -<span class=\"fraction\"><span class=\"numerator\">3 · 8</span><span class=\"denominator\">60</span></span> = -<span class=\"fraction\"><span class=\"numerator\">24</span><span class=\"denominator\">60</span></span> = -0,4 m/s.","svgGraph":null},{"q":"Một quả bóng tennis va đập vào bức tường bê tông với lực tác dụng lên tường là F = 400 N trong thời gian 0,02 s. Lực mà bức tường tác dụng ngược lại quả bóng có độ lớn là:","opts":["400 N.","200 N.","800 N.","0 N."],"ans":0,"exp":"• Theo định luật 3 Newton, lực tường tác dụng lên bóng luôn có độ lớn bằng đúng lực bóng tác dụng lên tường: |F<sub>tb</sub>| = |F<sub>bt</sub>| = 400 N.","svgGraph":null},{"q":"Khi bước từ một chiếc thuyền nhỏ không cột dây lên cầu cảng, người ta thấy chiếc thuyền bị đẩy lùi ra xa bờ. Hiện tượng này là do:","opts":["Chân người khi đạp về phía sau để tiến lên đã tác dụng một lực đẩy ngược lại lên thuyền theo định luật 3 Newton.","Gió thổi từ trên bờ đẩy chiếc thuyền trôi ra xa.","Dòng nước dưới đáy thuyền tự động sinh ra lực xoáy hút thuyền.","Chiếc thuyền có khối lượng âm so với cơ thể người."],"ans":0,"exp":"• Muốn tiến về trước, chân người tác dụng lực đẩy ra phía sau lên sàn thuyền. Phản lực của thuyền đẩy người tới bờ, đồng thời lực của chân đẩy thuyền dạt lùi ra xa.","svgGraph":null}],"17":[{"q":"Trọng lực tác dụng lên một vật là lực hấp dẫn giữa Trái Đất và vật đó, có đặc điểm:","opts":["Phương thẳng đứng, chiều từ trên xuống dưới và đặt tại trọng tâm của vật.","Phương nằm ngang, chiều theo chiều chuyển động của vật.","Phương tiếp tuyến với quỹ đạo và đặt tại điểm tiếp xúc.","Phương xiên 45° hướng về phía tâm của xích đạo."],"ans":0,"exp":"• <b>Đặc điểm của trọng lực:</b> Trọng lực P là lực hút của Trái Đất tác dụng lên vật; có phương thẳng đứng, chiều từ trên xuống dưới, điểm đặt tại trọng tâm của vật và độ lớn gọi là trọng lượng: P = m·g.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr17\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Ceiling horizontal line -->\n      <line x1=\"160\" y1=\"30\" x2=\"340\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"4\"/>\n      <!-- Rope vertical line -->\n      <line x1=\"250\" y1=\"30\" x2=\"250\" y2=\"120\" stroke=\"#fbbf24\" stroke-width=\"2.5\"/>\n      <!-- Suspended Block -->\n      <rect x=\"220\" y=\"120\" width=\"60\" height=\"50\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <!-- Center of gravity dot G -->\n      <circle cx=\"250\" cy=\"145\" r=\"4\" fill=\"#f8fafc\"/>\n      <text x=\"260\" y=\"148\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">G</text>\n      <!-- Tension vector T (upward) -->\n      <line x1=\"250\" y1=\"120\" x2=\"250\" y2=\"60\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr17)\"/>\n      <text x=\"260\" y=\"80\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Lực căng T</text>\n      <!-- Gravity vector P (downward) -->\n      <line x1=\"250\" y1=\"145\" x2=\"250\" y2=\"215\" stroke=\"#ef4444\" stroke-width=\"3\" marker-end=\"url(#arr17)\"/>\n      <text x=\"260\" y=\"200\" fill=\"#ef4444\" font-size=\"13\" font-weight=\"bold\">Trọng lực P</text>\n      <text x=\"140\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Vật treo cân bằng dưới tác dụng của Trọng lực P và Lực căng T</text>\n    </svg>"},{"q":"Khối lượng m và trọng lượng P của một vật liên hệ với nhau qua công thức:","opts":["P = m · g.","P = m / g.","m = P · g.","P = m · g²."],"ans":0,"exp":"• Trọng lượng P là độ lớn của trọng lực tác dụng lên vật: P = m·g, trong đó m đo bằng kg, g đo bằng m/s² và P đo bằng Newton (N).","svgGraph":null},{"q":"Lực căng dây xuất hiện tại các điểm trên sợi dây mềm đàn hồi khi bị kéo căng có đặc điểm:","opts":["Có phương trùng với phương của sợi dây, chiều hướng từ hai đầu dây vào phần giữa của sợi dây.","Có phương vuông góc với sợi dây hướng ra ngoài không gian.","Luôn có chiều hướng thẳng đứng lên trên bất kể dây đặt theo phương nào.","Có độ lớn thay đổi liên tục dọc theo chiều dài của một sợi dây nhẹ lý tưởng."],"ans":0,"exp":"• Lực căng dây xuất hiện chống lại sự dãn; phương trùng với sợi dây, chiều hướng từ điểm liên kết vào trong lòng sợi dây để kéo giữ các vật nối.","svgGraph":null},{"q":"Một vật có khối lượng m = 5 kg được treo bằng một sợi dây chịu được lực căng tối đa T<sub>max</sub> = 70 N. Lấy g = 10 m/s². Gia tốc kéo lên lớn nhất mà sợi dây có thể chịu được mà không bị đứt là:","opts":["4 m/s².","14 m/s².","2 m/s².","10 m/s²."],"ans":0,"exp":"• <b>Phương trình định luật 2 khi kéo lên:</b> T - mg = ma ⇒ a = <span class=\"fraction\"><span class=\"numerator\">T - mg</span><span class=\"denominator\">m</span></span><br>• <b>Thay giá trị cực đại:</b> a<sub>max</sub> = <span class=\"fraction\"><span class=\"numerator\">70 - 5 · 10</span><span class=\"denominator\">5</span></span> = <span class=\"fraction\"><span class=\"numerator\">70 - 50</span><span class=\"denominator\">5</span></span> = <span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">5</span></span> = 4 m/s².","svgGraph":null},{"q":"Một người có khối lượng m = 60 kg đứng trên một bàn cân lò xo đặt trong buồng thang máy. Lấy g = 10 m/s². Khi thang máy chuyển động nhanh dần đều đi xuống với gia tốc a = 2 m/s², số chỉ của bàn cân là:","opts":["480 N (tương đương 48 kg).","720 N (tương đương 72 kg).","600 N (tương đương 60 kg).","120 N."],"ans":0,"exp":"• <b>Đi xuống nhanh dần đều:</b> Trọng lực thắng phản lực sàn: P - N = ma ⇒ N = m(g - a).<br>• <b>Thay số:</b> N = 60 · (10 - 2) = 60 · 8 = 480 N (số chỉ cân giảm).","svgGraph":null},{"q":"Một sợi dây dù có độ bền giới hạn chịu được lực căng cực đại là 1500 N. Một người leo núi có khối lượng cả người và ba lô là 75 kg. Lấy g = 10 m/s². Hệ số an toàn n (tỉ số giữa lực căng cực đại chịu được và trọng lượng của người) là:","opts":["2,0 lần.","1,5 lần.","3,0 lần.","0,5 lần."],"ans":0,"exp":"• <b>Trọng lượng người và đồ:</b> P = mg = 75 · 10 = 750 N.<br>• <b>Hệ số an toàn:</b> n = <span class=\"fraction\"><span class=\"numerator\">T<sub>max</sub></span><span class=\"denominator\">P</span></span> = <span class=\"fraction\"><span class=\"numerator\">1500</span><span class=\"denominator\">750</span></span> = 2,0 lần.","svgGraph":null}],"18":[{"q":"Lực ma sát trượt xuất hiện ở mặt tiếp xúc giữa hai vật khi:","opts":["Vật này trượt trên bề mặt của vật kia, có hướng ngược hướng vận tốc tương đối.","Vật này lăn trên bề mặt của vật kia không có trượt.","Một vật có xu hướng chuyển động nhưng chưa chuyển động được.","Hai vật đặt cách xa nhau trong không gian chân không."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Lực ma sát trượt xuất hiện ở bề mặt tiếp xúc khi một vật trượt trên bề mặt của một vật khác; nó có phương tiếp tuyến với mặt tiếp xúc và có chiều ngược chiều chuyển động tương đối của vật.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr18\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Ground line with hatch -->\n      <line x1=\"60\" y1=\"160\" x2=\"440\" y2=\"160\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <!-- Block sliding right -->\n      <rect x=\"180\" y=\"100\" width=\"100\" height=\"60\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <text x=\"220\" y=\"135\" fill=\"#f8fafc\" font-size=\"14\" font-weight=\"bold\">Vật m</text>\n      <!-- Pulling Force F<tspan baseline-shift=\"sub\" font-size=\"70%\">k</tspan> -->\n      <line x1=\"280\" y1=\"130\" x2=\"380\" y2=\"130\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr18)\"/>\n      <text x=\"320\" y=\"120\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Lực kéo F</text>\n      <!-- Friction Force F_mst (at contact surface) -->\n      <line x1=\"180\" y1=\"160\" x2=\"80\" y2=\"160\" stroke=\"#f43f5e\" stroke-width=\"3\" marker-end=\"url(#arr18)\"/>\n      <text x=\"90\" y=\"150\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">F<tspan baseline-shift=\"sub\" font-size=\"70%\">ms</tspan> = μ · N</text>\n      <!-- Normal force N and Gravity P -->\n      <line x1=\"230\" y1=\"100\" x2=\"230\" y2=\"40\" stroke=\"#fbbf24\" stroke-width=\"2.5\" marker-end=\"url(#arr18)\"/>\n      <text x=\"240\" y=\"55\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Áp lực N</text>\n      <line x1=\"230\" y1=\"130\" x2=\"230\" y2=\"210\" stroke=\"#fbbf24\" stroke-width=\"2.5\" marker-end=\"url(#arr18)\"/>\n      <text x=\"240\" y=\"200\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Trọng lực P</text>\n      <text x=\"140\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Lực ma sát trượt ngược chiều chuyển động tương đối</text>\n    </svg>"},{"q":"Độ lớn của lực ma sát trượt F<sub>mst</sub> phụ thuộc vào những yếu tố nào?","opts":["Bản chất, tình trạng bề mặt tiếp xúc và áp lực N ép lên bề mặt tiếp xúc.","Diện tích tiếp xúc bề mặt và tốc độ trượt của vật.","Vận tốc trượt càng nhanh thì lực ma sát trượt càng tăng vọt.","Chỉ phụ thuộc vào hình dạng kích thước khối học của vật."],"ans":0,"exp":"• <b>Công thức ma sát trượt:</b> F<sub>mst</sub> = μ_t·N. Độ lớn của lực ma sát trượt tỉ lệ với độ lớn của áp lực N, phụ thuộc vào vật liệu và tình trạng bề mặt tiếp xúc (thể hiện qua hệ số μ_t); không phụ thuộc vào diện tích tiếp xúc và vận tốc của vật.","svgGraph":null},{"q":"Một vật có khối lượng m = 10 kg đang trượt trên mặt sàn nằm ngang. Hệ số ma sát trượt giữa vật và sàn là μ_t = 0,25. Lấy g = 10 m/s². Độ lớn của lực ma sát trượt tác dụng lên vật là:","opts":["25 N.","2,5 N.","250 N.","40 N."],"ans":0,"exp":"• <b>Áp lực mặt sàn nằm ngang:</b> N = P = m·g = 10 · 10 = 100 N.<br>• <b>Lực ma sát trượt:</b> F<sub>mst</sub> = μ_t·N = 0,25 · 100 = 25 N.","svgGraph":null},{"q":"Một thùng hàng nặng 40 kg đặt trên sàn nhà có hệ số ma sát nghỉ cực đại μ_n = 0,4. Lấy g = 10 m/s². Một người dùng lực F<sub>k</sub> = 120 N theo phương ngang để đẩy thùng hàng. Lực ma sát tác dụng lên thùng hàng khi đó là:","opts":["120 N (ma sát nghỉ).","160 N.","40 N.","0 N."],"ans":0,"exp":"• <b>Lực ma sát nghỉ cực đại:</b> F<sub>msn</sub>_max = μ_n·mg = 0,4 · 40 · 10 = 160 N.<br>• Vì lực kéo F<sub>k</sub> = 120 N < 160 N nên thùng hàng chưa chuyển động (đứng yên).<br>• Theo điều kiện cân bằng: F<sub>msn</sub> = F<sub>k</sub> = 120 N.","svgGraph":null},{"q":"Tác dụng của các rãnh khía trên bề mặt lốp xe máy, ô tô là gì?","opts":["Tăng độ bám đường và thoát nước nhanh khi trời mưa để duy trì lực ma sát an toàn.","Giảm khối lượng của bánh xe giúp xe chạy nhẹ hơn.","Tạo tiếng rít vui tai khi xe vào cua ở tốc độ cao.","Làm giảm áp lực của xe lên mặt đường nhựa."],"ans":0,"exp":"• Hoa lốp và các rãnh thoát nước giúp tống khứ màng nước mỏng giữa lốp và mặt đường, chống hiện tượng trượt nước (aquaplaning) và đảm bảo độ bám ma sát tốt.","svgGraph":null},{"q":"Để di chuyển một cỗ máy nặng hàng tấn vào xưởng cơ khí, các công nhân thường đặt các ống thép tròn lót dưới đáy máy rồi đẩy. Biện pháp này nhằm:","opts":["Thay thế lực ma sát trượt rất lớn bằng lực ma sát lăn nhỏ hơn nhiều lần.","Làm giảm trọng lượng của cỗ máy xuống một nửa.","Tăng diện tích tiếp xúc giữa máy và sàn nhà.","Làm cho mặt sàn nhà trơn nhẵn hơn."],"ans":0,"exp":"• Lực ma sát lăn có độ lớn nhỏ hơn rất nhiều lần so với lực ma sát trượt, giúp việc dịch chuyển các vật nặng trở nên nhẹ nhàng hơn.","svgGraph":null}],"19":[{"q":"Khi một vật chuyển động trong môi trường chất lưu (chất lỏng hoặc chất khí), vật luôn chịu tác dụng của:","opts":["Lực cản của chất lưu có xu hướng cản trở chuyển động của vật.","Lực đẩy luôn làm vật tăng tốc độ liên tục.","Một lực có phương vuông góc với vectơ vận tốc.","Lực hấp dẫn kéo vật bay lên trên khí quyển."],"ans":0,"exp":"• Mọi vật chuyển động trong chất lưu đều chịu lực cản do va chạm với các phân tử chất lưu và lực ma sát nhớt giữa bề mặt vật với các lớp chất lưu bao quanh.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr19\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Streamlined Airplane Wing Cross-section -->\n      <path d=\"M 120,120 C 180,70 300,90 380,125 C 300,140 180,135 120,120 Z\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <!-- Airflow lines top (faster, lower pressure) -->\n      <path d=\"M 60,80 Q 180,45 320,60 T 440,90\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.8\"/>\n      <text x=\"210\" y=\"55\" fill=\"#38bdf8\" font-size=\"11\">Dòng khí trên chạy nhanh (Áp suất P₁ thấp)</text>\n      <!-- Airflow lines bottom (slower, higher pressure) -->\n      <path d=\"M 60,150 Q 200,160 320,155 T 440,145\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.8\"/>\n      <text x=\"210\" y=\"180\" fill=\"#94a3b8\" font-size=\"11\">Dòng khí dưới chạy chậm (Áp suất P₂ cao)</text>\n      <!-- Aerodynamic Lift Force F<tspan baseline-shift=\"sub\" font-size=\"70%\">n</tspan> (upward) -->\n      <line x1=\"250\" y1=\"110\" x2=\"250\" y2=\"30\" stroke=\"#34d399\" stroke-width=\"3.5\" marker-end=\"url(#arr19)\"/>\n      <text x=\"260\" y=\"40\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">Lực nâng khí động học F<tspan baseline-shift=\"sub\" font-size=\"70%\">n</tspan></text>\n      <!-- Drag Force F_c (backward) -->\n      <line x1=\"120\" y1=\"120\" x2=\"60\" y2=\"120\" stroke=\"#f43f5e\" stroke-width=\"3\" marker-end=\"url(#arr19)\"/>\n      <text x=\"35\" y=\"115\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">Lực cản F<tspan baseline-shift=\"sub\" font-size=\"70%\">c</tspan></text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Lực nâng khí động học của cánh máy bay dạng khí động học</text>\n    </svg>"},{"q":"Độ lớn của lực cản không khí tác dụng lên một vật chuyển động phụ thuộc chủ yếu vào:","opts":["Vận tốc chuyển động, diện tích cản gió và hình dạng khí động học của vật.","Khối lượng riêng của vật liệu làm nên vật thể đó.","Vĩ độ địa lí và độ cao của mặt phẳng quỹ đạo.","Màu sắc phản xạ ánh sáng của bề mặt vật thể."],"ans":0,"exp":"• Lực cản không khí F<sub>c</sub> tỉ lệ với bình phương vận tốc (v² ở tốc độ cao), diện tích bề mặt vuông góc với dòng khí (S) và hình dạng hình học (hệ số cản C<sub>x</sub>).","svgGraph":null},{"q":"Hình dạng nào sau đây của vật thể giúp làm giảm lực cản của chất lưu xuống mức nhỏ nhất?","opts":["Hình dạng thuôn nhọn khí động học (giọt nước hoặc thân cá heo).","Hình hộp vuông chữ nhật góc cạnh gồ ghề.","Hình bán cầu rỗng quay mặt lõm về phía trước.","Hình đĩa phẳng tròn đặt vuông góc với hướng gió."],"ans":0,"exp":"• Dạng khí động học thuôn dài như giọt nước hoặc thân cá giúp dòng chất lưu chảy êm dịu bao quanh thân mà không tạo các vùng xoáy cuộn phía sau, triệt tiêu đáng kể lực cản.","svgGraph":null},{"q":"Một quả cầu kim loại nhỏ rơi trong một ống nghiệm đựng đầy dầu nhớt đặc. Sau một đoạn đường ngắn, quả cầu chuyển động thẳng đều với vận tốc không đổi v = 0,2 m/s. Trọng lượng quả cầu là P = 0,15 N và lực đẩy Archimedes của dầu là F<sub>A</sub> = 0,05 N. Độ lớn của lực cản nhớt tác dụng lên quả cầu khi rơi đều là:","opts":["0,10 N.","0,20 N.","0,15 N.","0,05 N."],"ans":0,"exp":"• <b>Khi quả cầu rơi thẳng đều:</b> Hợp lực triệt tiêu: P = F<sub>A</sub> + F<sub>c</sub>ản.<br>• <b>Lực cản nhớt:</b> F<sub>c</sub>ản = P - F<sub>A</sub> = 0,15 - 0,05 = 0,10 N.","svgGraph":null},{"q":"Lực đẩy Archimedes tác dụng lên một vật nhúng chìm trong chất lỏng có độ lớn bằng:","opts":["Trọng lượng của phần chất lỏng bị vật chiếm chỗ: F<sub>A</sub> = ρ_lỏng · g · V.","Khối lượng toàn phần của vật nhúng chìm.","Áp suất ở đáy bình chứa chất lỏng.","Trọng lượng của chính vật đó trong chân không."],"ans":0,"exp":"• Định luật Archimedes: F<sub>A</sub> = d·V = ρ·g·V, trong đó ρ là khối lượng riêng của chất lỏng, V là thể tích phần chất lỏng bị vật chiếm chỗ.","svgGraph":null},{"q":"Tại sao các vận động viên đua xe đạp chuyên nghiệp thường mặc trang phục bó sát, đội mũ bảo hiểm hình giọt nước và cúi gập lưng sát ghi-đông khi thi đấu?","opts":["Để giảm tối đa diện tích cản gió và cải thiện hệ số khí động học giúp xe chạy nhanh hơn.","Để làm cho xe đạp có trọng lượng nặng hơn bám đường tốt hơn.","Để cản trở gió không cho các đối thủ phía sau vượt lên.","Để hạ nhiệt độ cơ thể khi thi đấu dưới trời nắng."],"ans":0,"exp":"• Giảm diện tích cản gió S và tạo hình dáng khí động học thuôn mượt giúp giảm đáng kể lực cản không khí, tiết kiệm tối đa sức lực cho vận động viên ở tốc độ cao.","svgGraph":null}],"20":[{"q":"Bước đầu tiên và mang tính quyết định trong quy trình giải bài toán động lực học bằng định luật Newton là:","opts":["Chọn vật khảo sát, vẽ sơ đồ phân tích tất cả các lực tác dụng lên vật và chọn hệ quy chiếu thích hợp.","Bấm máy tính tính ngay vận tốc và gia tốc mà không cần vẽ hình.","Đo trực tiếp độ dài của các vectơ trên trang giấy kẻ ô.","Thay số đại số vào các công thức chuyển động học."],"ans":0,"exp":"• Quy trình chuẩn: (1) Xác định vật khảo sát; (2) Phân tích các lực tác dụng (P, N, F<sub>k</sub>, F<sub>ms</sub>,...); (3) Chọn hệ trục toạ độ Oxy; (4) Viết phương trình vectơ F = ma; (5) Chiếu phương trình lên các trục toạ độ.","svgGraph":null},{"q":"Một vật trượt không vận tốc đầu từ đỉnh một mặt phẳng nghiêng góc α so với phương ngang. Bỏ qua ma sát. Gia tốc chuyển động của vật dọc theo mặt phẳng nghiêng là:","opts":["a = g · sin(α).","a = g · cos(α).","a = g · tan(α).","a = g."],"ans":0,"exp":"• <b>Chiếu phương trình định luật 2 lên phương song song mặt nghiêng:</b><br>P<sub>x</sub> = P·sin(α) = m·a ⇒ m·g·sin(α) = m·a ⇒ a = g·sin(α). Gia tốc không phụ thuộc vào khối lượng vật.","svgGraph":null},{"q":"Một vật trượt xuống một mặt phẳng nghiêng góc α = 30° có hệ số ma sát trượt μ = 0,2. Lấy g = 10 m/s² và √3 ≈ 1,73. Gia tốc trượt của vật xấp xỉ bằng:","opts":["3,27 m/s².","5,00 m/s².","1,73 m/s².","4,50 m/s²."],"ans":0,"exp":"• <b>Công thức gia tốc trên mặt phẳng nghiêng có ma sát:</b><br>a = g·(sin α - μ·cos α)<br>• <b>Thay số:</b> a = 10 · [sin(30°) - 0,2 · cos(30°)] = 10 · [0,5 - 0,2 · 0,866] = 10 · [0,5 - 0,173] = 10 · 0,327 = 3,27 m/s².","svgGraph":null},{"q":"Một người kéo một vali nặng 20 kg trên sàn nằm ngang bằng một lực F = 50 N hợp với phương ngang một góc α = 60°. Lấy g = 10 m/s². Áp lực N mà vali đè lên mặt sàn là:","opts":["156,7 N.","200 N.","243,3 N.","175 N."],"ans":0,"exp":"• <b>Chiếu lực lên trục thẳng đứng Oy:</b> N + F·sin(α) - P = 0<br>• <b>Áp lực:</b> N = P - F·sin(α) = m·g - F·sin(60°) = 20 · 10 - 50 · <span class=\"fraction\"><span class=\"numerator\">√3</span><span class=\"denominator\">2</span></span> = 200 - 43,3 = 156,7 N. (Lực kéo chếch lên làm giảm áp lực).","svgGraph":null},{"q":"Một khối gỗ đặt trên một tấm ván nằm ngang. Nâng từ từ một đầu tấm ván lên cao. Khi góc nghiêng của tấm ván đạt α = 30° thì khối gỗ bắt đầu trượt. Hệ số ma sát nghỉ cực đại giữa khối gỗ và ván là:","opts":["0,577 (tan 30°).","0,500 (sin 30°).","0,866 (cos 30°).","1,000."],"ans":0,"exp":"• Tại góc tới hạn bắt đầu trượt: Thành phần kéo P·sin(α) cân bằng với ma sát nghỉ cực đại μ_n·P·cos(α) ⇒ μ_n = tan(α) = tan(30°) = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">√3</span></span> ≈ 0,577.","svgGraph":null},{"q":"Trong các vụ va chạm ô tô được tái hiện để điều tra tai nạn giao thông, các kĩ sư hiện trường thường dựa vào vết trượt phanh lốp trên mặt đường để xác định yếu tố nào của xe trước khi phanh?","opts":["Vận tốc tức thời của xe ngay trước khi tài xế đạp phanh khẩn cấp: v = √(2·μ·g·s).","Dung tích bình xăng của xe ô tô.","Công suất định mức của ắc quy xe điện.","Số lượng hành khách ngồi trên xe."],"ans":0,"exp":"• Áp dụng định lí động năng hoặc hệ thức độc lập: v² - 0 = 2·a·s = 2·(μ·g)·s ⇒ v = √(2μgs). Đo vết phanh s và đo hệ số ma sát μ của mặt đường sẽ tìm được tốc độ v ban đầu của xe.","svgGraph":null}],"21":[{"q":"Moment của một lực đối với một trục quay là đại lượng đặc trưng cho:","opts":["Tác dụng làm quay của lực và được đo bằng tích của lực với cánh tay đòn của nó (M = F · d).","Khả năng làm biến dạng cơ học của vật thể.","Tốc độ chuyển động tịnh tiến của trọng tâm vật rắn.","Công suất toả nhiệt của lực ma sát quay."],"ans":0,"exp":"• <b>Định nghĩa moment lực:</b> M = F·d. Moment lực đặc trưng cho tác dụng làm quay của lực quanh trục. Trong đó F là độ lớn của lực (N), d là cánh tay đòn (khoảng cách vuông góc từ trục quay đến giá của lực, đo bằng mét). Đơn vị là N·m.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr21\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Rotation axis O -->\n      <circle cx=\"120\" cy=\"120\" r=\"10\" fill=\"#f43f5e\" stroke=\"#fca5a5\" stroke-width=\"2\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"3\" fill=\"#ffffff\"/>\n      <text x=\"100\" y=\"150\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">Trục quay O</text>\n      <!-- Wrench bar -->\n      <line x1=\"120\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#475569\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n      <line x1=\"120\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n      <!-- Force F applied at end -->\n      <circle cx=\"380\" cy=\"120\" r=\"5\" fill=\"#fbbf24\"/>\n      <line x1=\"380\" y1=\"120\" x2=\"380\" y2=\"40\" stroke=\"#fbbf24\" stroke-width=\"3.5\" marker-end=\"url(#arr21)\"/>\n      <text x=\"390\" y=\"55\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">Lực F</text>\n      <!-- Lever arm d bracket -->\n      <line x1=\"120\" y1=\"170\" x2=\"380\" y2=\"170\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <circle cx=\"120\" cy=\"170\" r=\"3\" fill=\"#34d399\"/>\n      <circle cx=\"380\" cy=\"170\" r=\"3\" fill=\"#34d399\"/>\n      <text x=\"220\" y=\"195\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Cánh tay đòn d</text>\n      <text x=\"145\" y=\"228\" fill=\"#94a3b8\" font-size=\"12\">Moment lực làm quay M = F · d</text>\n    </svg>"},{"q":"Cánh tay đòn d của một lực là:","opts":["Khoảng cách vuông góc từ trục quay đến giá của lực.","Khoảng cách từ trục quay đến điểm đặt của lực trên vật.","Chiều dài của toàn bộ thanh đòn quay.","Độ dài của mũi tên vectơ biểu diễn lực tác dụng."],"ans":0,"exp":"• Cánh tay đòn d luôn luôn là khoảng cách vuông góc (đoạn hạ vuông góc) từ trục quay tới đường thẳng chứa vectơ lực (giá của lực).","svgGraph":null},{"q":"Quy tắc moment lực (điều kiện cân bằng của một vật có trục quay cố định) phát biểu rằng:","opts":["Tổng các moment lực làm vật quay theo chiều kim đồng hồ bằng tổng các moment lực làm vật quay ngược chiều kim đồng hồ.","Hợp lực của các lực tác dụng phải có phương vuông góc với cánh tay đòn.","Tổng độ lớn của các lực làm quay theo chiều kim đồng hồ phải bằng tổng độ lớn các lực ngược chiều kim đồng hồ.","Trọng tâm của vật phải luôn nằm trùng với trục quay cố định."],"ans":0,"exp":"• <b>Quy tắc moment:</b> Một vật có trục quay cố định ở trạng thái cân bằng khi: ∑M<sub>thu</sub>ận = ∑M<sub>ngh</sub>ịch.","svgGraph":null},{"q":"Một thanh chắn đường dài L = 6 m có trục quay O cách đầu bên trái 1 m. Để thanh nằm ngang cân bằng, người ta treo vào đầu bên trái một đối trọng khối lượng m₁ = 50 kg. Trọng lượng của thanh phân bố đều có trọng tâm nằm ở chính giữa thanh (cách O một đoạn 2 m). Khối lượng m₂ của thanh chắn là:","opts":["25 kg.","50 kg.","100 kg.","12,5 kg."],"ans":0,"exp":"• <b>Cánh tay đòn đối trọng m₁:</b> d₁ = 1 m.<br>• <b>Trọng tâm thanh G ở chính giữa:</b> cách đầu trái 3 m ⇒ cách O một đoạn: d₂ = 3 - 1 = 2 m.<br>• <b>Quy tắc moment quanh O:</b> m₁·g·d₁ = m₂·g·d₂ ⇒ 50 · 1 = m₂ · 2 ⇒ m₂ = <span class=\"fraction\"><span class=\"numerator\">50</span><span class=\"denominator\">2</span></span> = 25 kg.","svgGraph":null},{"q":"Hai tay của một tài xế tác dụng vào vô lăng ô tô một ngẫu lực gồm hai lực ngược chiều có cùng độ lớn F = 20 N. Bán kính vô lăng là R = 20 cm. Moment của ngẫu lực này là:","opts":["8,0 N·m.","4,0 N·m.","2,0 N·m.","16,0 N·m."],"ans":0,"exp":"• Khoảng cách giữa giá hai lực ngẫu lực bằng đường kính vô lăng: d = 2·R = 2 · 0,2 = 0,4 m.<br>• <b>Moment ngẫu lực:</b> M = F·d = 20 · 0,4 = 8,0 N·m.","svgGraph":null},{"q":"Nguyên nhân chính giúp những người đi thăng bằng trên dây xiếc thường cầm một chiếc sào rất dài và uốn cong chúc xuống dưới là:","opts":["Hạ thấp trọng tâm của toàn bộ hệ người - sào xuống dưới dây và tăng moment quán tính chống lại sự nghiêng ngã.","Tăng khối lượng để dây căng hơn.","Tạo luồng gió nâng người bay lơ lửng.","Che chắn mắt khỏi ánh đèn sân khấu."],"ans":0,"exp":"• Chiếc sào dài uốn cong làm trọng tâm của cả hệ hạ xuống sát hoặc thấp hơn dây xiếc (trạng thái cân bằng bền vững hơn), đồng thời cánh tay đòn dài tạo moment quán tính quay lớn chống lại chuyển động lắc nghiêng mất thăng bằng.","svgGraph":null}],"22":[{"q":"Trong bài thực hành kiểm chứng quy tắc hình bình hành tổng hợp hai lực đồng quy, người ta sử dụng dụng cụ nào để đo trực tiếp độ lớn của các lực?","opts":["Lực kế lò xo chia vạch Newton.","Cân đồng hồ đo khối lượng gam.","Thước kẹp đo chiều dài milimét.","Vôn kế điện tử đo hiệu điện thế."],"ans":0,"exp":"• Lực kế lò xo là dụng cụ đo trực tiếp độ lớn của lực dựa trên định luật Hooke về độ biến dạng của lò xo tỉ lệ thuận với lực tác dụng: F = k·Δl.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr22\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Circular Board with angle scale -->\n      <circle cx=\"250\" cy=\"120\" r=\"95\" fill=\"#1e293b\" stroke=\"#475569\" stroke-width=\"2\"/>\n      <circle cx=\"250\" cy=\"120\" r=\"6\" fill=\"#f8fafc\"/>\n      <text x=\"245\" y=\"140\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">O</text>\n      <!-- Rubber band stretched to O -->\n      <line x1=\"250\" y1=\"215\" x2=\"250\" y2=\"120\" stroke=\"#f43f5e\" stroke-width=\"3\"/>\n      <text x=\"255\" y=\"180\" fill=\"#f43f5e\" font-size=\"11\">Dây cao su</text>\n      <!-- Spring Balance 1 -->\n      <line x1=\"250\" y1=\"120\" x2=\"160\" y2=\"55\" stroke=\"#38bdf8\" stroke-width=\"2.5\" marker-end=\"url(#arr22)\"/>\n      <rect x=\"130\" y=\"35\" width=\"40\" height=\"25\" fill=\"#0284c7\" rx=\"3\"/>\n      <text x=\"135\" y=\"52\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">F₁</text>\n      <!-- Spring Balance 2 -->\n      <line x1=\"250\" y1=\"120\" x2=\"340\" y2=\"55\" stroke=\"#fbbf24\" stroke-width=\"2.5\" marker-end=\"url(#arr22)\"/>\n      <rect x=\"330\" y=\"35\" width=\"40\" height=\"25\" fill=\"#d97706\" rx=\"3\"/>\n      <text x=\"335\" y=\"52\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">F₂</text>\n      <text x=\"140\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Bố trí thí nghiệm kiểm chứng quy tắc hình bình hành lực</text>\n    </svg>"},{"q":"Để kiểm chứng quy tắc tổng hợp hai lực đồng quy F₁ và F₂, bước đối chứng quan trọng nhất là:","opts":["Dùng một lực kế thứ ba kéo dây cao su sao cho nút chỉ O dãn đúng đến vị trí O cân bằng ban đầu.","Tăng gấp đôi độ dãn của dây cao su rồi đo lại.","Tháo rời các lực kế ra và cân từng lực kế trên đĩa cân.","Đo chu kì dao động của dây cao su khi buông tay."],"ans":0,"exp":"• Nút chỉ O về đúng vị trí cũ chứng tỏ lực kéo duy nhất F của lực kế thứ ba gây ra tác dụng hoàn toàn giống hệt như tác dụng đồng thời của hai lực F₁ và F₂.","svgGraph":null},{"q":"Khi đọc số chỉ trên bảng chia độ của lực kế lò xo, thao tác nào sau đây là chuẩn mực?","opts":["Đặt hướng nhìn vuông góc với thang đo chỉ thị của lực kế.","Nhìn nghiêng từ dưới lên để số đo được phóng đại to hơn.","Nhìn nghiêng một góc 45° từ trên xuống.","Cầm lực kế lắc qua lắc lại liên tục trong khi đọc số đo."],"ans":0,"exp":"• Hướng nhìn vuông góc với mặt thang đo giúp loại trừ hoàn toàn sai số thị sai (sai số góc nhìn).","svgGraph":null},{"q":"Trong một lần thí nghiệm, hai lực kế chỉ F₁ = 3,0 N và F₂ = 4,0 N vuông góc nhau (α = 90°). Độ lớn hợp lực lí thuyết vẽ bằng quy tắc hình bình hành là:","opts":["5,0 N.","7,0 N.","1,0 N.","12,0 N."],"ans":0,"exp":"• <b>Hợp lực góc vuông:</b> F = √(3,0² + 4,0²) = √(9 + 16) = √25 = 5,0 N.","svgGraph":null},{"q":"Lực kế đo hợp lực thực nghiệm chỉ F<sub>tn</sub> = 4,9 N, trong khi hợp lực tính từ hình bình hành là F<sub>lt</sub> = 5,0 N. Sai số tỉ đối của phép đo hợp lực là:","opts":["2,0%.","0,1%.","1,0%.","5,0%."],"ans":0,"exp":"• <b>Độ lệch tuyệt đối:</b> ΔF = |F<sub>lt</sub> - F<sub>tn</sub>| = |5,0 - 4,9| = 0,1 N.<br>• <b>Sai số tỉ đối:</b> δF = <span class=\"fraction\"><span class=\"numerator\">0,1</span><span class=\"denominator\">5,0</span></span> · 100% = 2,0%.","svgGraph":null},{"q":"Một tấm ván đồng chất dài L = 2 m được hai công nhân khiêng ở hai đầu. Người A khiêng ở đầu mút, người B khiêng ở đầu mút kia. Một vật nặng được đặt tại vị trí cách người A 0,5 m. So sánh lực nâng của hai người:","opts":["Người A chịu lực nặng gấp 3 lần người B.","Người B chịu lực nặng gấp 3 lần người A.","Hai người chịu lực nặng hoàn toàn bằng nhau.","Người A chịu toàn bộ trọng lượng, người B không chịu lực nào."],"ans":0,"exp":"• Khoảng cách từ vật đến A là d<sub>A</sub> = 0,5 m; đến B là d<sub>B</sub> = 2 - 0,5 = 1,5 m.<br>• Theo quy tắc tổng hợp hai lực song song: <span class=\"fraction\"><span class=\"numerator\">F<sub>A</sub></span><span class=\"denominator\">F<sub>B</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">d<sub>B</sub></span><span class=\"denominator\">d<sub>A</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">1,5</span><span class=\"denominator\">0,5</span></span> = 3. Vậy người A chịu lực nặng gấp 3 lần người B.","svgGraph":null}],"23":[{"q":"Biểu thức tính công của một lực không đổi F làm vật dịch chuyển một quãng đường s theo phương hợp với hướng của lực một góc α là:","opts":["A = F · s · cos(α).","A = F · s · sin(α).","A = F · s / cos(α).","A = F · s · tan(α)."],"ans":0,"exp":"• <b>Công thức tính công:</b> A = F·s·cos(α). Trong hệ SI, lực F đo bằng Newton (N), quãng đường s đo bằng mét (m), công A đo bằng Jun (Joule - J): 1 J = 1 N·m.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr23\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Ground line -->\n      <line x1=\"60\" y1=\"180\" x2=\"440\" y2=\"180\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <!-- Block -->\n      <rect x=\"120\" y=\"120\" width=\"80\" height=\"60\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2.5\" rx=\"4\"/>\n      <!-- Displacement direction s -->\n      <line x1=\"200\" y1=\"180\" x2=\"380\" y2=\"180\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr23)\"/>\n      <text x=\"270\" y=\"200\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Quãng đường s</text>\n      <!-- Pulling Force F angled at alpha -->\n      <line x1=\"200\" y1=\"150\" x2=\"330\" y2=\"75\" stroke=\"#fbbf24\" stroke-width=\"3.5\" marker-end=\"url(#arr23)\"/>\n      <text x=\"340\" y=\"70\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">Lực F</text>\n      <!-- Angle alpha arc -->\n      <line x1=\"200\" y1=\"150\" x2=\"310\" y2=\"150\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <path d=\"M 245,150 A 45 45 0 0 0 240,127\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <text x=\"255\" y=\"140\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">α</text>\n      <text x=\"145\" y=\"45\" fill=\"#f8fafc\" font-size=\"15\" font-weight=\"bold\">A = F · s · cos(α)</text>\n      <text x=\"130\" y=\"228\" fill=\"#94a3b8\" font-size=\"12\">Mô hình tính công cơ học của lực F làm vật dịch chuyển s</text>\n    </svg>"},{"q":"Trong trường hợp nào sau đây lực tác dụng KHÔNG SINH CÔNG cơ học (A = 0)?","opts":["Lực tác dụng có phương vuông góc với phương dịch chuyển của vật (α = 90°).","Lực tác dụng cùng chiều với chiều chuyển động của vật (α = 0°).","Lực tác dụng ngược chiều với chiều chuyển động của vật (α = 180°).","Lực tác dụng hợp với hướng chuyển động một góc nhọn 45°."],"ans":0,"exp":"• Khi α = 90° thì cos(90°) = 0 ⇒ A = F·s·cos(90°) = 0. Ví dụ: Trọng lực không sinh công khi vật chuyển động trên mặt sàn nằm ngang phẳng.","svgGraph":null},{"q":"Một người kéo một thùng gỗ trượt trên sàn nằm ngang bằng một lực kéo F = 150 N hợp với phương ngang góc α = 60°. Thùng gỗ dịch chuyển được quãng đường s = 10 m. Công của lực kéo đã thực hiện là:","opts":["750 J.","1500 J.","1299 J.","0 J."],"ans":0,"exp":"• <b>Công của lực kéo:</b> A = F·s·cos(α) = 150 · 10 · cos(60°) = 1500 · 0,5 = 750 J.","svgGraph":null},{"q":"Một vật có khối lượng m = 2 kg rơi tự do từ độ cao h = 10 m xuống mặt đất. Lấy g = 10 m/s². Công của trọng lực thực hiện trong suốt quá trình rơi này là:","opts":["200 J.","-200 J.","100 J.","0 J."],"ans":0,"exp":"• <b>Công của trọng lực:</b> A<sub>P</sub> = m·g·h (vì trọng lực cùng chiều chuyển động rơi thẳng đứng nên α = 0°).<br>• Thay số: A<sub>P</sub> = 2 · 10 · 10 = 200 J.","svgGraph":null},{"q":"Một ô tô hãm phanh chuyển động thẳng chậm dần đều trên quãng đường 20 m. Lực hãm của phanh có độ lớn không đổi F<sub>h</sub> = 3000 N. Công của lực hãm phanh là:","opts":["-60000 J (-60 kJ).","+60000 J (+60 kJ).","-30000 J.","+150000 J."],"ans":0,"exp":"• Lực hãm ngược chiều chuyển động nên α = 180° ⇒ cos(180°) = -1.<br>• <b>Công của lực hãm:</b> A = F<sub>h</sub> · s · cos(180°) = 3000 · 20 · (-1) = -60000 J = -60 kJ.","svgGraph":null},{"q":"Trong nhà máy thuỷ điện, dạng năng lượng nào của dòng nước ở trên hồ chứa đập cao được chuyển hoá thành điện năng?","opts":["Thế năng trọng trường của nước biến đổi thành động năng làm quay tuabin, sau đó máy phát biến cơ năng thành điện năng.","Nhiệt năng của nước đun sôi tạo hơi nước làm quay quạt gió.","Năng lượng hoá học của các phân tử nước giải phóng electron.","Năng lượng hạt nhân của các đồng vị hydro trong nước."],"ans":0,"exp":"• Chuỗi chuyển hoá năng lượng trong thuỷ điện: Thế năng nước chảy từ trên cao -> Động năng dòng chảy qua tuabin -> Cơ năng quay máy phát điện -> Điện năng.","svgGraph":null}],"24":[{"q":"Công suất là đại lượng đặc trưng cho:","opts":["Tốc độ thực hiện công của lực và được xác định bằng công thực hiện trong một đơn vị thời gian (P = A / t).","Tổng lượng công mà một cỗ máy có thể thực hiện được trong suốt vòng đời.","Mức độ tiêu hao nhiên liệu của động cơ đốt trong.","Khối lượng tối đa mà thiết bị nâng có thể cẩu lên cao."],"ans":0,"exp":"• <b>Định nghĩa công suất:</b> P = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">t</span></span>. Công suất là đại lượng đặc trưng cho tốc độ sinh công. Đơn vị trong hệ SI là Oát (Watt - W): 1 W = 1 J/s.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr24\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Crane Tower -->\n      <line x1=\"120\" y1=\"210\" x2=\"120\" y2=\"40\" stroke=\"#64748b\" stroke-width=\"6\"/>\n      <line x1=\"80\" y1=\"210\" x2=\"160\" y2=\"210\" stroke=\"#64748b\" stroke-width=\"4\"/>\n      <line x1=\"100\" y1=\"40\" x2=\"380\" y2=\"40\" stroke=\"#fbbf24\" stroke-width=\"5\"/>\n      <!-- Pulley Cable lifting container -->\n      <line x1=\"320\" y1=\"40\" x2=\"320\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <rect x=\"290\" y=\"120\" width=\"60\" height=\"40\" fill=\"#0284c7\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"3\"/>\n      <text x=\"305\" y=\"145\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">m</text>\n      <!-- Lifting speed vector v -->\n      <line x1=\"365\" y1=\"140\" x2=\"365\" y2=\"90\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr24)\"/>\n      <text x=\"375\" y=\"115\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">v</text>\n      <!-- Power formula text -->\n      <text x=\"180\" y=\"90\" fill=\"#f8fafc\" font-size=\"15\" font-weight=\"bold\">P = F · v</text>\n      <text x=\"180\" y=\"115\" fill=\"#94a3b8\" font-size=\"12\">(Lực kéo F nâng vật tốc độ v)</text>\n      <text x=\"140\" y=\"228\" fill=\"#94a3b8\" font-size=\"12\">Cần cẩu thực hiện công nâng vật với công suất P = F · v</text>\n    </svg>"},{"q":"Mối liên hệ giữa công suất tức thời P, lực tác dụng F và vận tốc tức thời v khi lực cùng hướng với vận tốc là:","opts":["P = F · v.","P = F / v.","P = F · v².","P = F² · v."],"ans":0,"exp":"• Khi lực F cùng hướng với vận tốc v: P = A/t = (F·s)/t = F·(s/t) = F·v.","svgGraph":null},{"q":"Một cần cẩu nâng một khối bê tông nặng 1 tấn (1000 kg) lên cao 12 m trong thời gian 30 giây với tốc độ không đổi. Lấy g = 10 m/s². Công suất của cần cẩu là:","opts":["4000 W (4 kW).","2000 W (2 kW).","12000 W (12 kW).","400 W."],"ans":0,"exp":"• <b>Lực nâng cần cẩu:</b> F = P = mg = 1000 · 10 = 10000 N.<br>• <b>Công thực hiện:</b> A = F·h = 10000 · 12 = 120000 J.<br>• <b>Công suất:</b> P = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">t</span></span> = <span class=\"fraction\"><span class=\"numerator\">120000</span><span class=\"denominator\">30</span></span> = 4000 W = 4 kW.","svgGraph":null},{"q":"Một ô tô có động cơ công suất P = 60 kW đang chuyển động thẳng đều trên đường nằm ngang với tốc độ v = 20 m/s (72 km/h). Lực kéo của động cơ ô tô khi đó là:","opts":["3000 N.","1200 N.","300 N.","6000 N."],"ans":0,"exp":"• <b>Công thức:</b> P = F·v ⇒ F = <span class=\"fraction\"><span class=\"numerator\">P</span><span class=\"denominator\">v</span></span><br>• <b>Thay số:</b> F = <span class=\"fraction\"><span class=\"numerator\">60000</span><span class=\"denominator\">20</span></span> = 3000 N.","svgGraph":null},{"q":"Một máy bơm nước có công suất định mức P = 1,5 kW hoạt động liên tục trong 2 giờ. Công cơ học mà máy bơm đã thực hiện là:","opts":["1,08·10⁷ J (10,8 MJ).","3,0·10⁶ J.","1,5·10³ J.","5,4·10⁵ J."],"ans":0,"exp":"• <b>Đổi thời gian:</b> t = 2 h = 2 · 3600 = 7200 s.<br>• <b>Công thực hiện:</b> A = P·t = 1500 · 7200 = 10800000 J = 10,8 MJ.","svgGraph":null},{"q":"Trên nhãn mác của một máy hút bụi gia đình có ghi thông số: '220 V - 1800 W'. Ý nghĩa của con số 1800 W là:","opts":["Công suất tiêu thụ điện định mức của máy khi cắm vào nguồn điện chuẩn 220 V.","Công suất hút bụi cơ học có ích thực tế của đầu chổi hút.","Tổng lượng điện năng tiêu thụ trong một tháng sử dụng.","Lực hút cực đại của máy đo bằng Newton."],"ans":0,"exp":"• Số Oát (W) ghi trên thiết bị điện gia dụng là công suất tiêu thụ định mức của thiết bị khi hoạt động ở hiệu điện thế danh định ghi trên nhãn.","svgGraph":null}],"25":[{"q":"Động năng của một vật khối lượng m đang chuyển động với vận tốc v được tính theo công thức:","opts":["W<sub>đ</sub> = 1/2 · m · v².","W<sub>đ</sub> = m · v².","W<sub>đ</sub> = 1/2 · m · v.","W<sub>đ</sub> = 2 · m · v²."],"ans":0,"exp":"• <b>Công thức động năng:</b> W<sub>đ</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v². Động năng là dạng năng lượng mà vật có được do nó đang chuyển động, tỉ lệ thuận với khối lượng m và bình phương vận tốc v². Đơn vị là Joule (J).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr25\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Height reference ground -->\n      <line x1=\"50\" y1=\"200\" x2=\"450\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <text x=\"350\" y=\"218\" fill=\"#64748b\" font-size=\"12\">Mốc thế năng (z = 0, W<tspan baseline-shift=\"sub\" font-size=\"70%\">t</tspan> = 0)</text>\n      <!-- Object at height z -->\n      <rect x=\"180\" y=\"60\" width=\"70\" height=\"50\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <text x=\"205\" y=\"90\" fill=\"#f8fafc\" font-size=\"14\" font-weight=\"bold\">m</text>\n      <!-- Velocity vector v -->\n      <line x1=\"250\" y1=\"85\" x2=\"350\" y2=\"85\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr25)\"/>\n      <text x=\"300\" y=\"75\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">v</text>\n      <!-- Height z bracket -->\n      <line x1=\"150\" y1=\"85\" x2=\"150\" y2=\"200\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"150\" cy=\"85\" r=\"3\" fill=\"#fbbf24\"/>\n      <circle cx=\"150\" cy=\"200\" r=\"3\" fill=\"#fbbf24\"/>\n      <text x=\"125\" y=\"145\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">z</text>\n      <!-- Formula texts -->\n      <text x=\"280\" y=\"140\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">W<tspan baseline-shift=\"sub\" font-size=\"70%\">đ</tspan> = ½·m·v²</text>\n      <text x=\"280\" y=\"170\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">W<tspan baseline-shift=\"sub\" font-size=\"70%\">t</tspan> = m·g·z</text>\n      <text x=\"135\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Hai dạng năng lượng cơ học: Động năng và Thế năng trọng trường</text>\n    </svg>"},{"q":"Thế năng trọng trường của một vật khối lượng m ở độ cao z so với mốc thế năng đã chọn được xác định bằng công thức:","opts":["W<sub>t</sub> = m · g · z.","W<sub>t</sub> = 1/2 · m · g · z.","W<sub>t</sub> = m · g / z.","W<sub>t</sub> = m · g · z²."],"ans":0,"exp":"• <b>Thế năng trọng trường:</b> W<sub>t</sub> = m·g·z, là năng lượng tương tác giữa Trái Đất và vật, phụ thuộc vào vị trí của vật trong trọng trường so với mốc thế năng quy ước.","svgGraph":null},{"q":"Một ô tô có khối lượng m = 1,5 tấn (1500 kg) đang chuyển động với tốc độ v = 72 km/h (20 m/s). Động năng của ô tô là:","opts":["300000 J (300 kJ).","150000 J (150 kJ).","600000 J.","30000 J."],"ans":0,"exp":"• <b>Công thức động năng:</b> W<sub>đ</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v²<br>• <b>Thay số:</b> W<sub>đ</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 1500 · (20)² = 750 · 400 = 300000 J = 300 kJ.","svgGraph":null},{"q":"Một lò xo có độ cứng k = 100 N/m bị nén một đoạn Δl = 4 cm = 0,04 m so với chiều dài tự nhiên. Thế năng đàn hồi dự trữ trong lò xo là:","opts":["0,08 J.","0,16 J.","8,0 J.","0,04 J."],"ans":0,"exp":"• <b>Công thức thế năng đàn hồi:</b> W<sub>t</sub>đh = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>k·(Δl)²<br>• <b>Thay số:</b> W<sub>t</sub>đh = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 100 · (0,04)² = 50 · 0,0016 = 0,08 J (80 mJ).","svgGraph":null},{"q":"Một hòn đá khối lượng m = 400 g (0,4 kg) được ném thẳng đứng lên cao từ mặt đất với vận tốc ban đầu v₀ = 15 m/s. Lấy g = 10 m/s², chọn mốc thế năng tại mặt đất. Động năng ban đầu của hòn đá là:","opts":["45 J.","90 J.","22,5 J.","60 J."],"ans":0,"exp":"• <b>Động năng ban đầu:</b> W<sub>đ</sub>0 = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v₀² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 0,4 · (15)² = 0,2 · 225 = 45 J.","svgGraph":null},{"q":"Một viên đạn khối lượng 10 g đang bay với vận tốc 400 m/s thì xuyên vào một tấm gỗ dày và dừng lại. Lực cản trung bình của tấm gỗ tác dụng lên viên đạn biết bề dày xuyên sâu là 8 cm (0,08 m) có độ lớn là:","opts":["10000 N (10 kN).","5000 N.","20000 N.","800 N."],"ans":0,"exp":"• <b>Định lí động năng:</b> 0 - <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v₀² = -F<sub>c</sub> · d<br>• Thay số: <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 0,01 · 400² = F<sub>c</sub> · 0,08 ⇒ 800 = 0,08·F<sub>c</sub> ⇒ F<sub>c</sub> = <span class=\"fraction\"><span class=\"numerator\">800</span><span class=\"denominator\">0,08</span></span> = 10000 N = 10 kN.","svgGraph":null}],"26":[{"q":"Cơ năng của một vật chuyển động dưới tác dụng của trọng lực là đại lượng bằng:","opts":["Tổng động năng và thế năng trọng trường của vật: W = W<sub>đ</sub> + W<sub>t</sub>.","Hiệu số giữa động năng và thế năng trọng trường.","Tích của động năng với thế năng của vật.","Bình phương của động năng cộng với bình phương thế năng."],"ans":0,"exp":"• <b>Định nghĩa cơ năng:</b> Cơ năng W bằng tổng động năng và thế năng của vật: W = W<sub>đ</sub> + W<sub>t</sub> = ½ m·v² + mgz. Đơn vị là Joule (J).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Simple Pendulum Track -->\n      <line x1=\"250\" y1=\"30\" x2=\"250\" y2=\"180\" stroke=\"#475569\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <!-- Ceiling -->\n      <line x1=\"180\" y1=\"30\" x2=\"320\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"4\"/>\n      <!-- Extreme Position Left A -->\n      <line x1=\"250\" y1=\"30\" x2=\"150\" y2=\"130\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"150\" cy=\"130\" r=\"14\" fill=\"#ef4444\"/>\n      <text x=\"175\" y=\"215\" fill=\"#a7f3d0\" font-size=\"11\" font-weight=\"bold\">Vị trí cân bằng O: Động năng cực đại, thế năng cực tiểu</text>\n      <!-- Extreme Position Right B -->\n      <line x1=\"250\" y1=\"30\" x2=\"350\" y2=\"130\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"350\" cy=\"130\" r=\"14\" fill=\"#ef4444\"/>\n      <text x=\"370\" y=\"130\" fill=\"#fca5a5\" font-size=\"11\" font-weight=\"bold\">Vị trí biên B:</text>\n      <text x=\"70\" y=\"145\" fill=\"#fca5a5\" font-size=\"11\">Thế năng cực đại (v = 0)</text>\n      <!-- Swing arc -->\n      <path d=\"M 150,130 Q 250,200 350,130\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"135\" y=\"55\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">Mô hình con lắc đơn dao động trong trọng trường</text>\n    </svg>"},{"q":"Định luật bảo toàn cơ năng phát biểu rằng: Khi một vật chỉ chịu tác dụng của lực thế (như trọng lực hoặc lực đàn hồi), cơ năng của vật là một đại lượng:","opts":["Bảo toàn (không đổi theo thời gian): W = const.","Tăng dần đều theo thời gian.","Giảm dần về không do định luật vạn vật hấp dẫn.","Biến thiên điều hoà quanh giá trị 0."],"ans":0,"exp":"• <b>Định luật bảo toàn cơ năng:</b> Khi vật chuyển động chỉ chịu tác dụng của trọng lực (hoặc lực đàn hồi), động năng có thể chuyển hoá thành thế năng và ngược lại nhưng tổng cơ năng luôn được bảo toàn: W = W<sub>đ</sub> + W<sub>t</sub> = const.","svgGraph":null},{"q":"Thả rơi tự do một vật m = 1 kg từ độ cao h = 20 m so với mặt đất. Lấy g = 10 m/s², chọn mốc thế năng tại mặt đất. Vận tốc của vật khi chạm đất là:","opts":["20 m/s.","10 m/s.","14,1 m/s.","40 m/s."],"ans":0,"exp":"• <b>Bảo toàn cơ năng giữa đỉnh và mặt đất:</b><br>m·g·h = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v² ⇒ v = √(2·g·h) = √(2 · 10 · 20) = √400 = 20 m/s.","svgGraph":null},{"q":"Một vật được ném thẳng đứng lên cao từ mặt đất với vận tốc ban đầu v₀ = 20 m/s. Lấy g = 10 m/s², bỏ qua sức cản không khí. Ở độ cao nào thì thế năng của vật bằng 3 lần động năng (W<sub>t</sub> = 3·W<sub>đ</sub>)?","opts":["15 m.","10 m.","5 m.","20 m."],"ans":0,"exp":"• <b>Cơ năng tại mặt đất:</b> W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v₀².<br>• <b>Tại vị trí W<sub>t</sub> = 3·W<sub>đ</sub>:</b> W = W<sub>đ</sub> + W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">W<sub>t</sub></span><span class=\"denominator\">3</span></span> + W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">3</span></span>W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">3</span></span>m·g·z.<br>• <b>Bảo toàn cơ năng:</b> <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v₀² = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">3</span></span>m·g·z ⇒ z = <span class=\"fraction\"><span class=\"numerator\">3·v₀²</span><span class=\"denominator\">8g</span></span> = <span class=\"fraction\"><span class=\"numerator\">3 · 400</span><span class=\"denominator\">8 · 10</span></span> = 15 m.","svgGraph":null},{"q":"Một vật trượt từ đỉnh một mặt dốc nghiêng cao h = 5 m xuống chân dốc. Do có ma sát, vận tốc của vật tại chân dốc đo được là v = 8 m/s. Lấy g = 10 m/s². Tỉ lệ phần trăm cơ năng bị mất đi do ma sát là:","opts":["36%.","64%.","50%.","20%."],"ans":0,"exp":"• <b>Cơ năng ban đầu ở đỉnh:</b> W₁ = mgh = m · 10 · 5 = 50m (J).<br>• <b>Cơ năng ở chân dốc:</b> W₂ = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mv² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m · 8² = 32m (J).<br>• <b>Phần cơ năng bị mất:</b> ΔW = W₁ - W₂ = 50m - 32m = 18m (J).<br>• <b>Tỉ lệ phần trăm mất đi:</b> <span class=\"fraction\"><span class=\"numerator\">18m</span><span class=\"denominator\">50m</span></span> · 100% = 36%.","svgGraph":null},{"q":"Ứng dụng nào sau đây dựa trên nguyên tắc chuyển hoá thế năng đàn hồi thành động năng để phóng vật thể đi xa?","opts":["Cung tên và súng cao su.","Động cơ phản lực của máy bay siêu âm.","Tua-bin gió phát điện ven biển.","Lò phản ứng nhiệt hạch."],"ans":0,"exp":"• Kéo căng dây cung hoặc dây cao su tích luỹ thế năng đàn hồi; khi buông tay thế năng giải phóng biến đổi thành động năng đẩy mũi tên hoặc viên đạn bay vọt đi xa.","svgGraph":null}],"27":[{"q":"Hiệu suất H của một động cơ hoặc thiết bị chuyển hoá năng lượng được xác định bằng tỉ số giữa:","opts":["Năng lượng có ích và năng lượng toàn phần cung cấp cho thiết bị: H = (A<sub>ích</sub> / A<sub>to</sub>ànphần) · 100%.","Năng lượng hao phí và năng lượng toàn phần cung cấp.","Năng lượng toàn phần và năng lượng có ích.","Nhiệt lượng toả ra môi trường và công có ích."],"ans":0,"exp":"• <b>Công thức hiệu suất:</b> H = <span class=\"fraction\"><span class=\"numerator\">A<sub>ích</sub></span><span class=\"denominator\">A<sub>to</sub>ànphần</span></span> · 100% = <span class=\"fraction\"><span class=\"numerator\">P<sub>ích</sub></span><span class=\"denominator\">P<sub>to</sub>ànphần</span></span> · 100%. Hiệu suất luôn nhỏ hơn hoặc bằng 100% (H ≤ 1).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr27\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Sankey-like energy flow diagram -->\n      <!-- Input Energy -->\n      <rect x=\"50\" y=\"90\" width=\"120\" height=\"60\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <text x=\"65\" y=\"115\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">NĂNG LƯỢNG</text>\n      <text x=\"65\" y=\"135\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">TOÀN PHẦN</text>\n      <!-- Useful Output Arrow -->\n      <line x1=\"170\" y1=\"110\" x2=\"330\" y2=\"70\" stroke=\"#34d399\" stroke-width=\"4\" marker-end=\"url(#arr27)\"/>\n      <rect x=\"330\" y=\"50\" width=\"130\" height=\"40\" fill=\"#064e3b\" stroke=\"#34d399\" stroke-width=\"2\" rx=\"4\"/>\n      <text x=\"345\" y=\"75\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">CÓ ÍCH (W<tspan baseline-shift=\"sub\" font-size=\"70%\">ích</tspan>)</text>\n      <!-- Waste/Loss Output Arrow -->\n      <line x1=\"170\" y1=\"130\" x2=\"330\" y2=\"170\" stroke=\"#f43f5e\" stroke-width=\"3\" marker-end=\"url(#arr27)\"/>\n      <rect x=\"330\" y=\"150\" width=\"130\" height=\"40\" fill=\"#7f1d1d\" stroke=\"#f43f5e\" stroke-width=\"2\" rx=\"4\"/>\n      <text x=\"345\" y=\"175\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">HAO PHÍ (W<tspan baseline-shift=\"sub\" font-size=\"70%\">hp</tspan>)</text>\n      <text x=\"120\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Sơ đồ dòng năng lượng: W<tspan baseline-shift=\"sub\" font-size=\"70%\">tp</tspan> = W<tspan baseline-shift=\"sub\" font-size=\"70%\">ích</tspan> + W<tspan baseline-shift=\"sub\" font-size=\"70%\">hp</tspan></text>\n    </svg>"},{"q":"Một bóng đèn LED tiêu thụ công suất điện toàn phần P<sub>tp</sub> = 20 W, trong đó công suất phát sáng có ích là P<sub>ích</sub> = 6 W. Hiệu suất chiếu sáng của bóng đèn LED là:","opts":["30%.","33,3%.","70%.","12%."],"ans":0,"exp":"• <b>Công thức hiệu suất:</b> H = <span class=\"fraction\"><span class=\"numerator\">P<sub>ích</sub></span><span class=\"denominator\">P<sub>tp</sub></span></span> · 100% = <span class=\"fraction\"><span class=\"numerator\">6</span><span class=\"denominator\">20</span></span> · 100% = 30%. (70% năng lượng còn lại biến thành nhiệt hao phí).","svgGraph":null},{"q":"Tại sao hiệu suất của các cỗ máy thực tế trong kĩ thuật và đời sống không bao giờ đạt được mức 100%?","opts":["Vì luôn tồn tại ma sát, sức cản hoặc điện trở biến một phần năng lượng thành nhiệt năng hao phí toả ra môi trường.","Vì các kĩ sư chế tạo máy chưa đủ trình độ công nghệ cao.","Vì lực hấp dẫn của Trái Đất triệt tiêu một phần công cơ học.","Vì các định luật Newton chỉ áp dụng cho chất điểm lí tưởng."],"ans":0,"exp":"• Theo nguyên lí nhiệt động lực học, trong bất kì quá trình chuyển hoá năng lượng cơ, điện, nhiệt thực tế nào cũng có sự tiêu tán năng lượng do ma sát hoặc toả nhiệt Joules nên A<sub>ích</sub> luôn nhỏ hơn A<sub>to</sub>ànphần ⇒ H < 100%.","svgGraph":null},{"q":"Một bếp điện có hiệu suất H = 75% được dùng để đun sôi 2 kg nước từ 25°C. Nhiệt lượng có ích làm nước sôi là Q<sub>ích</sub> = 630000 J. Tổng điện năng mà bếp đã tiêu thụ từ lưới điện là:","opts":["840000 J (840 kJ).","472500 J.","630000 J.","1050000 J."],"ans":0,"exp":"• <b>Công thức hiệu suất:</b> H = <span class=\"fraction\"><span class=\"numerator\">Q<sub>ích</sub></span><span class=\"denominator\">A<sub>tp</sub></span></span> ⇒ A<sub>tp</sub> = <span class=\"fraction\"><span class=\"numerator\">Q<sub>ích</sub></span><span class=\"denominator\">H</span></span><br>• <b>Thay số:</b> A<sub>tp</sub> = <span class=\"fraction\"><span class=\"numerator\">630000</span><span class=\"denominator\">0,75</span></span> = 840000 J = 840 kJ.","svgGraph":null},{"q":"Nhãn năng lượng hình tam giác hoặc chữ nhật có từ 1 đến 5 ngôi sao dán trên các thiết bị gia dụng (tủ lạnh, máy giặt, điều hoà) có ý nghĩa gì đối với người tiêu dùng?","opts":["Càng nhiều sao thì thiết bị càng có hiệu suất sử dụng năng lượng cao và càng tiết kiệm điện.","Số sao biểu thị độ bền cơ học của vỏ máy.","Số sao cho biết số năm bảo hành chính hãng của nhà sản xuất.","Càng nhiều sao thì giá bán của sản phẩm càng rẻ."],"ans":0,"exp":"• Cấp sao trên nhãn năng lượng của Bộ Công Thương phản ánh hiệu suất năng lượng: 5 sao là mức tối ưu tiết kiệm điện nhất.","svgGraph":null},{"q":"Hệ số suy giảm hiệu suất trong động cơ đốt trong truyền thống xuất phát chủ yếu từ giai đoạn nào?","opts":["Khí thải nóng xả ra môi trường mang theo một lượng nhiệt lượng khổng lồ không chuyển thành công cơ học.","Điện trở của các bóng đèn xi-nhan trên xe.","Khối lượng của dầu bôi trơn quá nặng.","Áp suất không khí bên trong lốp xe quá căng."],"ans":0,"exp":"• Khoảng 60% năng lượng nhiệt giải phóng từ nhiên liệu xăng/dầu bị mất qua ống xả khí nóng và hệ thống tản nhiệt làm mát động cơ.","svgGraph":null}],"28":[{"q":"Động lượng p của một vật có khối lượng m đang chuyển động với vận tốc v là đại lượng vectơ được định nghĩa bằng:","opts":["Tích của khối lượng m và vectơ vận tốc v của vật: p = m · v.","Tích của khối lượng m và gia tốc a của vật: p = m · a.","Thương số giữa khối lượng và vận tốc của vật: p = m / v.","Một nửa tích khối lượng và bình phương vận tốc: p = ½ m·v²."],"ans":0,"exp":"• <b>Định nghĩa động lượng:</b> p = m·v. Động lượng là đại lượng vectơ có cùng hướng với vectơ vận tốc của vật. Trong hệ SI, đơn vị của động lượng là kg·m/s (hoặc N·s).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr28\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Moving Sphere with mass m -->\n      <circle cx=\"160\" cy=\"120\" r=\"30\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <text x=\"155\" y=\"125\" fill=\"#f8fafc\" font-size=\"15\" font-weight=\"bold\">m</text>\n      <!-- Velocity Vector v -->\n      <line x1=\"190\" y1=\"110\" x2=\"310\" y2=\"110\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr28)\"/>\n      <text x=\"235\" y=\"100\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Vận tốc v</text>\n      <!-- Momentum Vector p -->\n      <line x1=\"190\" y1=\"135\" x2=\"350\" y2=\"135\" stroke=\"#fbbf24\" stroke-width=\"4\" marker-end=\"url(#arr28)\"/>\n      <text x=\"230\" y=\"155\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">Động lượng p = m · v</text>\n      <text x=\"120\" y=\"45\" fill=\"#f8fafc\" font-size=\"15\" font-weight=\"bold\">Động lượng đặc trưng cho khả năng truyền tương tác</text>\n      <text x=\"135\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Vectơ động lượng p luôn cùng hướng với vectơ vận tốc v</text>\n    </svg>"},{"q":"Xung lượng của lực F tác dụng lên vật trong một khoảng thời gian ngắn Δt là F·Δt. Biểu thức liên hệ giữa xung lượng của lực và độ biến thiên động lượng của vật là:","opts":["Δp = p₂ - p₁ = F · Δt.","Δp = F / Δt.","Δp = F · (Δt)².","p = F · Δt² / 2."],"ans":0,"exp":"• <b>Xung lượng của lực:</b> F·Δt = Δp. Độ biến thiên động lượng của một vật trong khoảng thời gian Δt bằng xung lượng của hợp lực tác dụng lên vật trong khoảng thời gian đó.","svgGraph":null},{"q":"Một quả bóng đá khối lượng m = 400 g (0,4 kg) bay với tốc độ v = 20 m/s. Độ lớn động lượng của quả bóng là:","opts":["8,0 kg·m/s.","8000 kg·m/s.","80 kg·m/s.","4,0 kg·m/s."],"ans":0,"exp":"• <b>Công thức tính động lượng:</b> p = m·v = 0,4 · 20 = 8,0 kg·m/s.","svgGraph":null},{"q":"Một quả bóng khối lượng m = 200 g bay theo phương ngang với vận tốc 15 m/s đập vuông góc vào bức tường rồi bật ngược trở lại theo phương cũ với cùng tốc độ 15 m/s. Chọn chiều dương là chiều bật ra. Độ biến thiên động lượng của quả bóng là:","opts":["+6 kg·m/s.","0 kg·m/s.","-6 kg·m/s.","+3 kg·m/s."],"ans":0,"exp":"• <b>Vận tốc ban đầu:</b> v₁ = -15 m/s; vận tốc sau bật: v₂ = +15 m/s.<br>• <b>Độ biến thiên động lượng:</b> Δp = m·(v₂ - v₁) = 0,2 · [15 - (-15)] = 0,2 · 30 = +6 kg·m/s. (Không phải bằng 0 vì hướng vận tốc đã đảo ngược).","svgGraph":null},{"q":"Một lực F = 50 N tác dụng vào một vật đứng yên trong khoảng thời gian Δt = 0,4 s. Động lượng mà vật thu được sau khoảng thời gian này là:","opts":["20 kg·m/s.","125 kg·m/s.","12,5 kg·m/s.","200 kg·m/s."],"ans":0,"exp":"• <b>Theo định lí xung lượng:</b> p₂ - 0 = F·Δt = 50 · 0,4 = 20 N·s = 20 kg·m/s.","svgGraph":null},{"q":"Hệ thức liên hệ giữa động năng W<sub>đ</sub> và độ lớn động lượng p của một vật khối lượng m là:","opts":["W<sub>đ</sub> = p² / (2m).","W<sub>đ</sub> = 2m / p².","W<sub>đ</sub> = 2m · p².","W<sub>đ</sub> = p / (2m)."],"ans":0,"exp":"• <b>Biến đổi:</b> W<sub>đ</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mv² = <span class=\"fraction\"><span class=\"numerator\">(mv)²</span><span class=\"denominator\">2m</span></span> = <span class=\"fraction\"><span class=\"numerator\">p²</span><span class=\"denominator\">2m</span></span>.","svgGraph":null}],"29":[{"q":"Một hệ được gọi là hệ kín (hệ cô lập) về phương diện cơ học khi:","opts":["Không có ngoại lực tác dụng lên các vật trong hệ, hoặc các ngoại lực triệt tiêu lẫn nhau.","Các vật trong hệ đứng yên hoàn toàn không có tương tác nội lực.","Khối lượng của tất cả các vật trong hệ bằng nhau.","Hệ chỉ gồm duy nhất một vật thể đơn lẻ trong vũ trụ."],"ans":0,"exp":"• <b>Định nghĩa hệ kín:</b> Hệ kín là hệ mà các vật trong hệ chỉ tương tác với nhau (nội lực) mà không chịu tác dụng của các lực bên ngoài (ngoại lực), hoặc nếu có ngoại lực thì tổng các ngoại lực phải triệt tiêu: ∑F<sub>ngo</sub>ài = 0.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr29\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Before Collision -->\n      <g transform=\"translate(30, 40)\">\n        <rect x=\"0\" y=\"0\" width=\"200\" height=\"120\" fill=\"#1e293b\" rx=\"6\"/>\n        <text x=\"35\" y=\"25\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Trước va chạm</text>\n        <circle cx=\"50\" cy=\"70\" r=\"18\" fill=\"#ef4444\"/>\n        <text x=\"44\" y=\"75\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">m₁</text>\n        <line x1=\"68\" y1=\"70\" x2=\"110\" y2=\"70\" stroke=\"#ef4444\" stroke-width=\"2.5\" marker-end=\"url(#arr29)\"/>\n        <text x=\"80\" y=\"62\" fill=\"#fca5a5\" font-size=\"10\">v₁</text>\n        <circle cx=\"150\" cy=\"70\" r=\"18\" fill=\"#3b82f6\"/>\n        <text x=\"144\" y=\"75\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">m₂</text>\n        <line x1=\"168\" y1=\"70\" x2=\"195\" y2=\"70\" stroke=\"#3b82f6\" stroke-width=\"2\" marker-end=\"url(#arr29)\"/>\n        <text x=\"175\" y=\"62\" fill=\"#93c5fd\" font-size=\"10\">v₂</text>\n      </g>\n      <!-- After Collision (Stick together: va chạm mềm) -->\n      <g transform=\"translate(260, 40)\">\n        <rect x=\"0\" y=\"0\" width=\"200\" height=\"120\" fill=\"#1e293b\" rx=\"6\"/>\n        <text x=\"35\" y=\"25\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Sau va chạm mềm (dính liền)</text>\n        <circle cx=\"85\" cy=\"70\" r=\"18\" fill=\"#ef4444\"/>\n        <circle cx=\"115\" cy=\"70\" r=\"18\" fill=\"#3b82f6\"/>\n        <text x=\"75\" y=\"105\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">m₁ + m₂</text>\n        <line x1=\"133\" y1=\"70\" x2=\"185\" y2=\"70\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr29)\"/>\n        <text x=\"150\" y=\"62\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">V</text>\n      </g>\n      <text x=\"140\" y=\"210\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">p<tspan baseline-shift=\"sub\" font-size=\"70%\">trước</tspan> = p<tspan baseline-shift=\"sub\" font-size=\"70%\">sau</tspan>  ⇔  m₁v₁ + m₂v₂ = (m₁ + m₂)V</text>\n    </svg>"},{"q":"Định luật bảo toàn động lượng phát biểu rằng:","opts":["Tổng vectơ động lượng của một hệ kín là một đại lượng không đổi (bảo toàn) theo thời gian.","Động lượng của từng vật riêng rẽ trong hệ không bao giờ được phép thay đổi.","Tổng động năng của hệ kín luôn luôn bằng tổng động lượng của hệ đó.","Động lượng của hệ chỉ bảo toàn khi mọi va chạm là hoàn toàn đàn hồi."],"ans":0,"exp":"• <b>Định luật bảo toàn động lượng:</b> Trong một hệ kín, tổng vectơ động lượng của hệ bảo toàn: p = p₁ + p₂ + ... = const.","svgGraph":null},{"q":"Một xe goòng khối lượng m₁ = 200 kg đang chạy với vận tốc v₁ = 3 m/s trên đường ray nằm ngang trơn nhẵn thì va chạm mềm với một xe thứ hai có khối lượng m₂ = 100 kg đang đứng yên trên ray. Sau va chạm hai xe dính liền vào nhau. Vận tốc của hai xe ngay sau va chạm là:","opts":["2 m/s.","1,5 m/s.","1 m/s.","3 m/s."],"ans":0,"exp":"• <b>Bảo toàn động lượng cho va chạm mềm:</b><br>m₁·v₁ + 0 = (m₁ + m₂)·V ⇒ V = <span class=\"fraction\"><span class=\"numerator\">m₁·v₁</span><span class=\"denominator\">m₁ + m₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">200 · 3</span><span class=\"denominator\">200 + 100</span></span> = <span class=\"fraction\"><span class=\"numerator\">600</span><span class=\"denominator\">300</span></span> = 2 m/s.","svgGraph":null},{"q":"Một phi hành gia có khối lượng cả người và đồ bảo hộ là m₁ = 80 kg đang lơ lửng đứng yên ngoài không gian thì ném một bình oxy rỗng khối lượng m₂ = 2 kg ra xa với vận tốc v₂ = 10 m/s. Vận tốc giật lùi của phi hành gia theo hướng ngược lại là:","opts":["-0,25 m/s.","-0,50 m/s.","-1,00 m/s.","-2,50 m/s."],"ans":0,"exp":"• <b>Bảo toàn động lượng:</b> m₁·V + m₂·v₂ = 0 ⇒ V = -<span class=\"fraction\"><span class=\"numerator\">m₂·v₂</span><span class=\"denominator\">m₁</span></span> = -<span class=\"fraction\"><span class=\"numerator\">2 · 10</span><span class=\"denominator\">80</span></span> = -<span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">80</span></span> = -0,25 m/s.","svgGraph":null},{"q":"Hai viên bi cùng khối lượng m chuyển động ngược chiều nhau với cùng tốc độ v trên một rãnh thẳng nhẵn không ma sát. Khi va chạm mềm dính vào nhau, vận tốc của hai viên bi sau va chạm là:","opts":["0 m/s (hai viên bi đứng yên hoàn toàn).","v.","2v.","v/2."],"ans":0,"exp":"• Chọn chiều dương: v₁ = +v; v₂ = -v.<br>• Tổng động lượng trước va chạm: p = m·(+v) + m·(-v) = 0.<br>• Sau va chạm dính liền: (m + m)·V = 0 ⇒ V = 0.","svgGraph":null},{"q":"Định luật bảo toàn động lượng gắn liền với tính chất đối xứng cơ bản nào của không gian trong vật lí hiện đại (Định lí Noether)?","opts":["Tính đồng nhất của không gian (không gian là đồng tính tại mọi vị trí).","Tính đẳng hướng của không gian (mọi hướng đều như nhau).","Tính đồng nhất của dòng thời gian.","Sự cong vênh của không thời gian bốn chiều."],"ans":0,"exp":"• Theo định lí Noether trong vật lí lí thuyết: Định luật bảo toàn động lượng là hệ quả trực tiếp từ tính đồng tính (đối xứng tịnh tiến) của không gian.","svgGraph":null}],"30":[{"q":"Trong bài thực hành đo động lượng của hai xe trước và sau va chạm, thiết bị đệm khí (Air track) được sử dụng nhằm mục đích chính là:","opts":["Triệt tiêu tối đa lực ma sát giữa xe và đường ray để hệ hai xe được coi là hệ kín lý tưởng.","Làm tăng khối lượng của xe khi chuyển động.","Làm cho hai xe tự động dính vào nhau sau va chạm.","Đo trực tiếp vận tốc của xe mà không cần cổng quang điện."],"ans":0,"exp":"• Đệm khí tạo lớp màng không khí nâng xe nổi lơ lửng, triệt tiêu ma sát để điều kiện hệ kín (∑F<sub>ngo</sub>ài = 0) của định luật bảo toàn động lượng được nghiệm đúng chính xác.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Air Track Rail -->\n      <rect x=\"50\" y=\"140\" width=\"400\" height=\"25\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <!-- Air holes on track -->\n      <circle cx=\"100\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"150\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"200\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"250\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"300\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"350\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"400\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <!-- Glider A -->\n      <rect x=\"110\" y=\"105\" width=\"55\" height=\"30\" fill=\"#ef4444\" rx=\"3\"/>\n      <rect x=\"133\" y=\"80\" width=\"8\" height=\"25\" fill=\"#f8fafc\"/>\n      <text x=\"125\" y=\"125\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">Xe A</text>\n      <!-- Glider B -->\n      <rect x=\"260\" y=\"105\" width=\"55\" height=\"30\" fill=\"#3b82f6\" rx=\"3\"/>\n      <rect x=\"283\" y=\"80\" width=\"8\" height=\"25\" fill=\"#f8fafc\"/>\n      <text x=\"275\" y=\"125\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">Xe B</text>\n      <!-- Photogates -->\n      <rect x=\"80\" y=\"70\" width=\"15\" height=\"50\" fill=\"#0284c7\" opacity=\"0.6\"/>\n      <rect x=\"350\" y=\"70\" width=\"15\" height=\"50\" fill=\"#0284c7\" opacity=\"0.6\"/>\n      <text x=\"65\" y=\"60\" fill=\"#38bdf8\" font-size=\"11\">Cổng quang 1</text>\n      <text x=\"335\" y=\"60\" fill=\"#38bdf8\" font-size=\"11\">Cổng quang 2</text>\n      <text x=\"130\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Máng đệm khí đo động lượng trước và sau va chạm</text>\n    </svg>"},{"q":"Vận tốc v của mỗi xe khi đi qua cổng quang điện trong thí nghiệm được tính từ công thức nào (với d là bề rộng của tấm chắn sáng và Δt là thời gian chắn sáng)?","opts":["v = d / Δt.","v = d · Δt.","v = Δt / d.","v = 1/2 · d / Δt."],"ans":0,"exp":"• <b>Công thức vận tốc tức thời:</b> v = <span class=\"fraction\"><span class=\"numerator\">d</span><span class=\"denominator\">Δt</span></span>. Do bề rộng tấm chắn sáng d rất nhỏ nên vận tốc của xe khi đi qua cổng quang điện được coi xấp xỉ bằng vận tốc tức thời tại vị trí cổng.","svgGraph":null},{"q":"Để tạo ra va chạm mềm (dính liền vào nhau sau va chạm) giữa hai xe trong bài thực hành, người ta gắn vào đầu tiếp xúc của hai xe chi tiết nào?","opts":["Miếng dán dính nhám (hoặc đầu kim ghim cắm vào miếng xốp mềm).","Vòng đệm lò xo thép có độ đàn hồi cực cao.","Hai nam châm vĩnh cửu quay hai cực cùng dấu vào nhau.","Một lưỡi dao sắc và một khối gỗ cứng."],"ans":0,"exp":"• Miếng dán nhám (Velcro) hoặc kim cắm xốp giữ hai xe dính chặt vào nhau ngay sau khi chạm để tạo thành va chạm mềm hoàn toàn.","svgGraph":null},{"q":"Trong một lần thí nghiệm va chạm mềm, đo được: tổng động lượng trước va chạm là p = 0,425 kg·m/s và tổng động lượng sau va chạm là p' = 0,412 kg·m/s. Sai số tỉ đối của phép đo động lượng này xấp xỉ bằng:","opts":["3,06%.","1,30%.","0,013%.","6,12%."],"ans":0,"exp":"• <b>Độ lệch tuyệt đối:</b> Δp = |0,425 - 0,412| = 0,013 kg·m/s.<br>• <b>Sai số tỉ đối:</b> δp = <span class=\"fraction\"><span class=\"numerator\">0,013</span><span class=\"denominator\">0,425</span></span> · 100% ≈ 3,06%.","svgGraph":null},{"q":"Nguyên nhân chủ yếu khiến tổng động lượng sau va chạm thực tế thường hơi nhỏ hơn một chút so với tổng động lượng trước va chạm trong phòng thí nghiệm là:","opts":["Vẫn còn một lực ma sát nhỏ còn sót lại giữa xe và ray cùng với sức cản không khí trong quá trình di chuyển.","Khối lượng của hai xe bị bào mòn sau cú va chạm.","Đồng hồ hiện số bị giảm tần số quét điện tử.","Lực hút của Mặt Trăng làm giảm động lượng của hệ."],"ans":0,"exp":"• Dù dùng đệm khí, ma sát nhớt của không khí và ma sát nhỏ của luồng khí xả vẫn tác dụng công cản làm tốc độ xe sau va chạm suy giảm nhẹ, dẫn đến p' hơi nhỏ hơn p.","svgGraph":null},{"q":"Đồ chơi con lắc Newton (gồm 5 viên bi thép treo sát nhau) minh hoạ trực quan định luật vật lí nào khi ta kéo một viên bi ở đầu ra rồi buông tay?","opts":["Đồng thời cả định luật bảo toàn động lượng và định luật bảo toàn động năng trong va chạm đàn hồi.","Chỉ minh hoạ định luật phản xạ ánh sáng.","Hiện tượng giao thoa sóng cơ học trên dây treo.","Định luật cảm ứng điện từ Faraday."],"ans":0,"exp":"• Con lắc Newton là mô hình va chạm đàn hồi liên tiếp giữa các viên bi thép cùng khối lượng, bảo toàn đồng thời cả động lượng và cơ năng (kéo 1 viên bi thì chỉ có đúng 1 viên bi ở đầu kia bật ra với cùng vận tốc).","svgGraph":null}],"31":[{"q":"Chuyển động tròn đều là chuyển động có quỹ đạo tròn và có:","opts":["Tốc độ không đổi theo thời gian.","Vectơ vận tốc không đổi cả về độ lớn lẫn hướng.","Gia tốc luôn bằng 0.","Vectơ vận tốc luôn hướng về tâm quỹ đạo."],"ans":0,"exp":"• <b>Chuyển động tròn đều:</b> Quỹ đạo là đường tròn và tốc độ (độ lớn vận tốc) không đổi theo thời gian.<br>• <i>Lưu ý:</i> Vectơ vận tốc có hướng luôn tiếp tuyến với quỹ đạo nên phương chiều liên tục thay đổi, do đó chuyển động tròn đều luôn có gia tốc (gia tốc hướng tâm), vectơ vận tốc không hề không đổi.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr31\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Circle trajectory -->\n      <circle cx=\"250\" cy=\"120\" r=\"80\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\"/>\n      <!-- Center O -->\n      <circle cx=\"250\" cy=\"120\" r=\"4\" fill=\"#f8fafc\"/>\n      <text x=\"245\" y=\"110\" fill=\"#94a3b8\" font-size=\"13\" font-family=\"sans-serif\">O</text>\n      <!-- Radius R -->\n      <line x1=\"250\" y1=\"120\" x2=\"330\" y2=\"120\" stroke=\"#f8fafc\" stroke-width=\"1.5\"/>\n      <text x=\"285\" y=\"115\" fill=\"#f8fafc\" font-size=\"13\" font-family=\"sans-serif\">r</text>\n      <!-- Point M -->\n      <circle cx=\"330\" cy=\"120\" r=\"5\" fill=\"#38bdf8\"/>\n      <text x=\"340\" y=\"125\" fill=\"#38bdf8\" font-weight=\"bold\" font-size=\"14\" font-family=\"sans-serif\">M</text>\n      <!-- Tangent velocity v -->\n      <line x1=\"330\" y1=\"120\" x2=\"330\" y2=\"40\" stroke=\"#38bdf8\" stroke-width=\"2.5\" marker-end=\"url(#arr31)\"/>\n      <text x=\"338\" y=\"55\" fill=\"#38bdf8\" font-weight=\"bold\" font-size=\"14\" font-family=\"sans-serif\">v (tiếp tuyến)</text>\n    </svg>"},{"q":"Đơn vị đo của tốc độ góc (kí hiệu ω) trong hệ đơn vị đo lường quốc tế SI là:","opts":["Radian trên giây (rad/s).","Vòng trên phút (rpm).","Mét trên giây (m/s).","Độ trên giây (°/s)."],"ans":0,"exp":"• <b>Tốc độ góc:</b> ω = <span class=\"fraction\"><span class=\"numerator\">Δθ</span><span class=\"denominator\">Δt</span></span>. Trong hệ SI, góc quay Δθ đo bằng radian (rad), thời gian Δt đo bằng giây (s), do đó đơn vị của ω là rad/s.","svgGraph":null},{"q":"Mối liên hệ giữa tốc độ dài v, tốc độ góc ω và bán kính quỹ đạo r của chuyển động tròn đều là:","opts":["v = ω · r.","v = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">r</span></span>.","v = <span class=\"fraction\"><span class=\"numerator\">r</span><span class=\"denominator\">ω</span></span>.","v = ω² · r."],"ans":0,"exp":"• <b>Mối liên hệ:</b> Quãng đường s = r · θ ⇒ Vận tốc dài v = <span class=\"fraction\"><span class=\"numerator\">Δs</span><span class=\"denominator\">Δt</span></span> = r · <span class=\"fraction\"><span class=\"numerator\">Δθ</span><span class=\"denominator\">Δt</span></span> = ω · r.","svgGraph":null},{"q":"Kim phút của một chiếc đồng hồ treo tường có chiều dài 10 cm. Tốc độ góc của kim phút bằng:","opts":["≈ 1,75 · 10⁻³ rad/s (chính xác là <span class=\"fraction\"><span class=\"numerator\">π</span><span class=\"denominator\">1800</span></span> rad/s).","≈ 1,45 · 10⁻⁴ rad/s (chính xác là <span class=\"fraction\"><span class=\"numerator\">π</span><span class=\"denominator\">21600</span></span> rad/s).","≈ 0,105 rad/s (chính xác là <span class=\"fraction\"><span class=\"numerator\">π</span><span class=\"denominator\">30</span></span> rad/s).","1 rad/s."],"ans":0,"exp":"• <b>Chu kì quay của kim phút:</b> T = 1 giờ = 3600 s.<br>• <b>Tốc độ góc:</b> ω = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">T</span></span> = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">3600</span></span> = <span class=\"fraction\"><span class=\"numerator\">π</span><span class=\"denominator\">1800</span></span> ≈ 1,75 · 10⁻³ rad/s.","svgGraph":null},{"q":"Chu kì T và tần số f của chuyển động tròn đều liên hệ với tốc độ góc ω theo công thức nào sau đây?","opts":["T = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">ω</span></span> và f = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">T</span></span> = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">2π</span></span>.","T = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">2π</span></span> và f = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">ω</span></span>.","T = 2π · ω và f = 2π / ω.","T = 1 / f = 2π · ω."],"ans":0,"exp":"• Chu kì T là thời gian vật quay hết 1 vòng (góc 2π rad): T = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">ω</span></span>.<br>• Tần số f là số vòng quay trong 1 giây: f = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">T</span></span> = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">2π</span></span> (đơn vị Hertz - Hz hoặc vòng/s).","svgGraph":null},{"q":"Một chất điểm chuyển động tròn đều trên đường tròn bán kính r = 0,5 m với tần số f = 2 Hz. Tốc độ dài của chất điểm là:","opts":["2π m/s (≈ 6,28 m/s).","π m/s (≈ 3,14 m/s).","4π m/s (≈ 12,57 m/s).","1 m/s."],"ans":0,"exp":"• Tốc độ góc: ω = 2π · f = 2π · 2 = 4π rad/s.<br>• Tốc độ dài: v = ω · r = 4π · 0,5 = 2π m/s ≈ 6,28 m/s.","svgGraph":null}],"32":[{"q":"Trong chuyển động tròn đều, vectơ gia tốc hướng tâm luôn có đặc điểm nào sau đây?","opts":["Luôn hướng về tâm đường tròn quỹ đạo và có độ lớn a<sub>ht</sub> = v² / r = ω² · r.","Luôn cùng hướng với vectơ vận tốc tiếp tuyến.","Có hướng không đổi trong suốt quá trình chuyển động.","Có độ lớn tỉ lệ nghịch với bình phương tốc độ góc."],"ans":0,"exp":"• Trong chuyển động tròn đều, vận tốc thay đổi về hướng liên tục, gia tốc sinh ra luôn vuông góc với vận tốc và hướng vào tâm quỹ đạo gọi là gia tốc hướng tâm: a<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">r</span></span> = ω² · r.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs>\n        <marker id=\"arrV32\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker>\n        <marker id=\"arrA32\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#f43f5e\"/></marker>\n      </defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Circle trajectory -->\n      <circle cx=\"250\" cy=\"120\" r=\"75\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\"/>\n      <!-- Center O -->\n      <circle cx=\"250\" cy=\"120\" r=\"4\" fill=\"#f8fafc\"/>\n      <text x=\"235\" y=\"125\" fill=\"#94a3b8\" font-size=\"13\" font-family=\"sans-serif\">O</text>\n      <!-- Point M -->\n      <circle cx=\"250\" cy=\"45\" r=\"5\" fill=\"#38bdf8\"/>\n      <text x=\"258\" y=\"42\" fill=\"#38bdf8\" font-weight=\"bold\" font-size=\"13\" font-family=\"sans-serif\">M</text>\n      <!-- Tangent velocity v -->\n      <line x1=\"250\" y1=\"45\" x2=\"170\" y2=\"45\" stroke=\"#38bdf8\" stroke-width=\"2.5\" marker-end=\"url(#arrV32)\"/>\n      <text x=\"175\" y=\"36\" fill=\"#38bdf8\" font-weight=\"bold\" font-size=\"13\" font-family=\"sans-serif\">v</text>\n      <!-- Centripetal acceleration a<tspan baseline-shift=\"sub\" font-size=\"70%\">ht</tspan> -->\n      <line x1=\"250\" y1=\"45\" x2=\"250\" y2=\"105\" stroke=\"#f43f5e\" stroke-width=\"2.5\" marker-end=\"url(#arrA32)\"/>\n      <text x=\"256\" y=\"90\" fill=\"#f43f5e\" font-weight=\"bold\" font-size=\"13\" font-family=\"sans-serif\">a<tspan baseline-shift=\"sub\" font-size=\"70%\">ht</tspan> (hướng tâm)</text>\n    </svg>"},{"q":"Hợp lực của các lực tác dụng lên một vật chuyển động tròn đều giữ vai trò là lực hướng tâm. Biểu thức của lực hướng tâm là:","opts":["F<sub>ht</sub> = m · a<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">m · v²</span><span class=\"denominator\">r</span></span> = m · ω² · r.","F<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">m · v</span><span class=\"denominator\">r</span></span>.","F<sub>ht</sub> = m · v² · r.","F<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">m · ω</span><span class=\"denominator\">r</span></span>."],"ans":0,"exp":"• Theo định luật II Newton: F<sub>ht</sub> = m · a<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">m · v²</span><span class=\"denominator\">r</span></span> = m · ω² · r. Lực hướng tâm không phải là một loại lực cơ học mới, mà là tên gọi của hợp lực gây ra gia tốc hướng tâm.","svgGraph":null},{"q":"Khi một chiếc ô tô chuyển động qua một khúc cua tròn trên mặt đường nằm ngang, lực nào đóng vai trò chính cung cấp lực hướng tâm giữ cho xe không bị trượt văng ra ngoài?","opts":["Lực ma sát nghỉ giữa lốp xe và mặt đường.","Trọng lực của xe ô tô.","Phản lực pháp tuyến của mặt đường.","Lực đẩy của động cơ xe."],"ans":0,"exp":"• Trên mặt đường nằm ngang, trọng lực P và phản lực N triệt tiêu nhau theo phương thẳng đứng. Thành phần lực ma sát nghỉ hướng vào tâm đường cong đóng vai trò lực hướng tâm giúp xe vào cua an toàn. Khi đường trơn trượt (ma sát nghỉ cực đại không đủ lớn), xe sẽ bị trượt li tâm ra ngoài khúc cua.","svgGraph":null},{"q":"Một vệ tinh nhân tạo có khối lượng m đang bay trên quỹ đạo tròn quanh Trái Đất. Lực nào đóng vai trò là lực hướng tâm giữ cho vệ tinh chuyển động trên quỹ đạo?","opts":["Lực hấp dẫn giữa Trái Đất và vệ tinh.","Lực đẩy của động cơ phản lực gắn trên vệ tinh.","Lực ma sát của bầu khí quyển loãng.","Lực từ trường của Trái Đất."],"ans":0,"exp":"• Trong không gian vũ trụ, lực hấp dẫn do Trái Đất tác dụng lên vệ tinh đóng vai trò là lực hướng tâm: F<sub>hd</sub> = G · (M·m)/r² = m·v²/r, giữ cho vệ tinh bay đều quanh Trái Đất mà không rơi xuống hay bay mất vào không gian.","svgGraph":null},{"q":"Một hòn đá khối lượng m = 0,2 kg được buộc vào đầu một sợi dây nhẹ không giãn dài r = 0,8 m và quay đều trong mặt phẳng nằm ngang với tốc độ v = 4 m/s. Lực căng của sợi dây (bỏ qua trọng lực tác dụng lên đá) có độ lớn là:","opts":["4,0 N.","2,0 N.","8,0 N.","1,6 N."],"ans":0,"exp":"• Lực căng dây T hướng vào tâm quỹ đạo đóng vai trò là lực hướng tâm:<br>T = F<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">m · v²</span><span class=\"denominator\">r</span></span> = <span class=\"fraction\"><span class=\"numerator\">0,2 · 4²</span><span class=\"denominator\">0,8</span></span> = <span class=\"fraction\"><span class=\"numerator\">0,2 · 16</span><span class=\"denominator\">0,8</span></span> = 4,0 N.","svgGraph":null},{"q":"Tại các đoạn đường cua gấp trên quốc lộ hay đường đua xe tốc độ cao, người ta thường thiết kế mặt đường nghiêng vào phía trong tâm đường cong nhằm mục đích gì?","opts":["Hợp lực của trọng lực và phản lực mặt đường có thành phần hướng vào tâm cung cấp lực hướng tâm, giảm tải sự phụ thuộc vào lực ma sát lốp xe.","Để nước mưa thoát nhanh hơn về phía lề đường.","Tăng lực ma sát trượt giữa lốp xe và mặt đường.","Giúp ô tô tăng tốc độ cực đại khi lên dốc."],"ans":0,"exp":"• Khi mặt đường nghiêng góc α vào trong, phản lực N của mặt đường nghiêng so với phương thẳng đứng. Hợp lực F = P + N có thành phần nằm ngang F<sub>x</sub> = m·g·tan(α) hướng về tâm khúc cua, đóng vai trò lực hướng tâm giúp xe ôm cua tốc độ cao an toàn mà không bị văng li tâm dù đường trơn ướt.","svgGraph":null}],"33":[{"q":"Biến dạng nào sau đây của vật rắn được gọi là biến dạng đàn hồi?","opts":["Biến dạng mà vật lấy lại hoàn toàn hình dạng và kích thước ban đầu khi lực tác dụng thôi tác dụng.","Biến dạng mà vật bị gãy vụn ngay khi chịu lực lớn.","Biến dạng mà hình dạng của vật bị thay đổi vĩnh viễn không thể hồi phục lại.","Biến dạng chỉ xảy ra khi nung nóng vật rắn đến nhiệt độ nóng chảy."],"ans":0,"exp":"• <b>Biến dạng đàn hồi:</b> Biến dạng mà vật rắn có thể tự khôi phục lại hoàn toàn hình dạng và kích thước ban đầu khi thôi tác dụng ngoại lực (trong giới hạn đàn hồi). Nếu vượt quá giới hạn đàn hồi, vật sẽ bị biến dạng dư (dẻo) hoặc đứt gãy.","svgGraph":null},{"q":"Nội dung của định luật Hooke (Húc) đối với lò xo biến dạng kéo hoặc nén trong giới hạn đàn hồi là:","opts":["Trong giới hạn đàn hồi, độ lớn của lực đàn hồi tỉ lệ thuận với độ biến dạng của lò xo: F<sub>đh</sub> = k · |Δl|.","Lực đàn hồi tỉ lệ nghịch với độ biến dạng của lò xo.","Lực đàn hồi luôn tỉ lệ thuận với bình phương độ dãn của lò xo.","Độ cứng của lò xo tỉ lệ nghịch với chiều dài tự nhiên của nó và không phụ thuộc vật liệu."],"ans":0,"exp":"• <b>Định luật Hooke:</b> F<sub>đh</sub> = k · |Δl|, trong đó k là độ cứng (hay hệ số đàn hồi) của lò xo (đo bằng N/m), |Δl| = |l - l₀| là độ biến dạng (đo bằng mét - m).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr33\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Axes -->\n      <line x1=\"80\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr33)\"/>\n      <line x1=\"80\" y1=\"200\" x2=\"80\" y2=\"30\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr33)\"/>\n      <text x=\"425\" y=\"225\" fill=\"#94a3b8\" font-size=\"13\" font-family=\"sans-serif\">Δl (m)</text>\n      <text x=\"50\" y=\"45\" fill=\"#94a3b8\" font-size=\"13\" font-family=\"sans-serif\">F<tspan baseline-shift=\"sub\" font-size=\"70%\">đh</tspan> (N)</text>\n      <!-- Linear Hooke law region -->\n      <line x1=\"80\" y1=\"200\" x2=\"320\" y2=\"70\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <circle cx=\"320\" cy=\"70\" r=\"4\" fill=\"#34d399\"/>\n      <text x=\"325\" y=\"65\" fill=\"#34d399\" font-size=\"12\" font-family=\"sans-serif\">Giới hạn đàn hồi</text>\n      <!-- Beyond elastic limit (plastic) -->\n      <path d=\"M320,70 Q370,60 410,110\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2\" stroke-dasharray=\"3 3\"/>\n      <text x=\"375\" y=\"130\" fill=\"#f43f5e\" font-size=\"11\" font-family=\"sans-serif\">Biến dạng dẻo</text>\n    </svg>"},{"q":"Một lò xo nhẹ có chiều dài tự nhiên l₀ = 20 cm và độ cứng k = 100 N/m. Khi treo vào đầu dưới lò xo một quả cân có khối lượng m = 200 g (lấy g = 10 m/s²) thì chiều dài của lò xo khi cân bằng là:","opts":["22 cm (l = 0,22 m).","25 cm.","18 cm.","20,2 cm."],"ans":0,"exp":"• Khi vật cân bằng: P = F<sub>đh</sub> ⇒ m · g = k · Δl.<br>• Độ dãn của lò xo: Δl = <span class=\"fraction\"><span class=\"numerator\">m · g</span><span class=\"denominator\">k</span></span> = <span class=\"fraction\"><span class=\"numerator\">0,2 · 10</span><span class=\"denominator\">100</span></span> = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">100</span></span> = 0,02 m = 2 cm.<br>• Chiều dài lò xo: l = l₀ + Δl = 20 + 2 = 22 cm.","svgGraph":null},{"q":"Độ cứng (hệ số đàn hồi) k của một thanh kim loại hình trụ đồng chất tỉ lệ thuận với đại lượng nào và tỉ lệ nghịch với đại lượng nào?","opts":["Tỉ lệ thuận với tiết diện ngang S và tỉ lệ nghịch với chiều dài tự nhiên l₀ của thanh.","Tỉ lệ thuận với chiều dài tự nhiên l₀ và tỉ lệ nghịch với tiết diện S.","Tỉ lệ thuận với khối lượng của thanh và độc lập với kích thước hình học.","Không phụ thuộc vào hình dạng kích thước mà chỉ phụ thuộc vào nhiệt độ môi trường."],"ans":0,"exp":"• <b>Công thức độ cứng thanh vật rắn:</b> k = E · <span class=\"fraction\"><span class=\"numerator\">S</span><span class=\"denominator\">l₀</span></span>, trong đó E là suất đàn hồi (suất Young) phụ thuộc bản chất vật liệu, S là tiết diện ngang, l₀ là chiều dài ban đầu. Thanh càng to (S lớn) và càng ngắn (l₀ nhỏ) thì càng cứng.","svgGraph":null},{"q":"Khi ta dùng tay uốn cong một chiếc thước nhựa dẻo, lớp vật liệu ở phía mặt lồi của thước chịu loại biến dạng nào, và lớp vật liệu ở phía mặt lõm chịu loại biến dạng nào?","opts":["Mặt lồi chịu biến dạng kéo, mặt lõm chịu biến dạng nén.","Mặt lồi chịu biến dạng nén, mặt lõm chịu biến dạng kéo.","Cả hai mặt đều chỉ chịu biến dạng xoắn.","Cả hai mặt đều chỉ chịu biến dạng cắt."],"ans":0,"exp":"• Biến dạng uốn là sự kết hợp của biến dạng kéo và biến dạng nén: Khi thước bị uốn cong, các thớ vật liệu ở phía ngoài (mặt lồi) bị kéo dài ra, còn các thớ vật liệu ở phía trong (mặt lõm) bị ép ngắn lại.","svgGraph":null},{"q":"Hai lò xo nhẹ giống hệt nhau có cùng độ cứng k được mắc nối tiếp thành một hệ lò xo. Độ cứng tương đương k<sub>nt</sub> của hệ hai lò xo nối tiếp bằng:","opts":["k<sub>nt</sub> = <span class=\"fraction\"><span class=\"numerator\">k</span><span class=\"denominator\">2</span></span>.","k<sub>nt</sub> = 2 · k.","k<sub>nt</sub> = k.","k<sub>nt</sub> = 4 · k."],"ans":0,"exp":"• Khi mắc nối tiếp, cùng chịu một lực kéo F: Δl = Δl₁ + Δl₂ ⇒ <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">k<sub>nt</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">k</span></span> + <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">k</span></span> = <span class=\"fraction\"><span class=\"numerator\">2F</span><span class=\"denominator\">k</span></span> ⇒ k<sub>nt</sub> = <span class=\"fraction\"><span class=\"numerator\">k</span><span class=\"denominator\">2</span></span>. Hệ lò xo trở nên mềm hơn (dễ dãn hơn).","svgGraph":null}],"34":[{"q":"Khối lượng riêng ρ (hoặc D) của một chất được xác định bằng biểu thức nào sau đây?","opts":["ρ = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">V</span></span> (khối lượng của một đơn vị thể tích chất đó).","ρ = m · V.","ρ = <span class=\"fraction\"><span class=\"numerator\">V</span><span class=\"denominator\">m</span></span>.","ρ = P / V."],"ans":0,"exp":"• <b>Định nghĩa khối lượng riêng:</b> ρ = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">V</span></span>. Trong hệ SI, khối lượng m đo bằng kg, thể tích V đo bằng m³, khối lượng riêng ρ đo bằng kg/m³.","svgGraph":null},{"q":"Áp suất p tại một điểm ở độ sâu h trong lòng chất lỏng đứng yên có khối lượng riêng ρ được tính theo công thức nào (p₀ là áp suất khí quyển trên mặt thoáng)?","opts":["p = p₀ + ρ · g · h.","p = p₀ + <span class=\"fraction\"><span class=\"numerator\">ρ · g</span><span class=\"denominator\">h</span></span>.","p = ρ · g · h (không phụ thuộc vào áp suất khí quyển p₀).","p = p₀ + ρ · h / g."],"ans":0,"exp":"• <b>Công thức áp suất thủy tĩnh:</b> p = p₀ + ρ·g·h. Áp suất tại độ sâu h bằng tổng áp suất khí quyển p₀ trên mặt thoáng cộng với áp suất do cột chất lỏng có độ cao h gây ra (p<sub>cl</sub> = ρ·g·h).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr34\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Water beaker -->\n      <rect x=\"140\" y=\"50\" width=\"220\" height=\"150\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2.5\" rx=\"4\"/>\n      <!-- Water body -->\n      <rect x=\"142\" y=\"90\" width=\"216\" height=\"108\" fill=\"#0284c7\" fill-opacity=\"0.3\"/>\n      <!-- Water surface -->\n      <line x1=\"142\" y1=\"90\" x2=\"358\" y2=\"90\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"220\" y=\"80\" fill=\"#94a3b8\" font-size=\"12\" font-family=\"sans-serif\">Mặt thoáng (p₀)</text>\n      <!-- Depth h dimension -->\n      <line x1=\"180\" y1=\"90\" x2=\"180\" y2=\"160\" stroke=\"#fbbf24\" stroke-width=\"1.5\" marker-end=\"url(#arr34)\"/>\n      <text x=\"165\" y=\"130\" fill=\"#fbbf24\" font-size=\"13\" font-family=\"sans-serif\">h</text>\n      <!-- Point M at depth h -->\n      <circle cx=\"250\" cy=\"160\" r=\"5\" fill=\"#f43f5e\"/>\n      <text x=\"262\" y=\"165\" fill=\"#f43f5e\" font-weight=\"bold\" font-size=\"13\" font-family=\"sans-serif\">Điểm M: p = p₀ + ρ·g·h</text>\n    </svg>"},{"q":"Đơn vị đo áp suất trong hệ đơn vị đo lường quốc tế SI là Paxcan (Pascal, kí hiệu Pa). 1 Pa tương đương với:","opts":["1 Newton trên mét vuông (1 N/m²).","1 Newton trên centimét vuông (1 N/cm²).","1 Jun trên mét khối (1 J/m³).","1 Kilôgam trên mét khối (1 kg/m³)."],"ans":0,"exp":"• <b>Áp suất:</b> p = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">S</span></span>. Lực ép F đo bằng Newton (N), diện tích ép S đo bằng mét vuông (m²), do đó 1 Pa = 1 N/m².","svgGraph":null},{"q":"Nguyên lí Pascal phát biểu rằng độ tăng áp suất tác dụng lên một chất lỏng chứa trong bình kín sẽ:","opts":["Được truyền nguyên vẹn tới mọi điểm trong lòng chất lỏng và tới thành bình.","Giảm dần theo hàm bậc nhất theo khoảng cách tính từ điểm tác dụng.","Chỉ truyền theo phương thẳng đứng từ trên xuống đáy bình.","Bị triệt tiêu hoàn toàn sau khi lan truyền qua khoảng cách 1 mét."],"ans":0,"exp":"• <b>Nguyên lí Pascal:</b> Độ tăng áp suất tác dụng lên một chất lỏng không nén được chứa trong bình kín được truyền nguyên vẹn đến mọi phần của chất lỏng và thành bình chứa. Đây là nguyên lí hoạt động của máy nâng thủy lực, phanh dầu ô tô.","svgGraph":null},{"q":"Một thợ lặn đang lặn ở độ sâu h = 20 m dưới mặt nước biển. Biết khối lượng riêng của nước biển là ρ = 1030 kg/m³, áp suất khí quyển p₀ = 1,01 · 10⁵ Pa và gia tốc trọng trường g = 9,8 m/s². Áp suất tác dụng lên người thợ lặn ở độ sâu này xấp xỉ bằng:","opts":["3,03 · 10⁵ Pa (gấp khoảng 3 lần áp suất khí quyển).","2,02 · 10⁵ Pa.","1,01 · 10⁵ Pa.","4,05 · 10⁵ Pa."],"ans":0,"exp":"• Áp suất do cột nước biển: p<sub>cl</sub> = ρ · g · h = 1030 · 9,8 · 20 = 201880 Pa ≈ 2,02 · 10⁵ Pa.<br>• Áp suất toàn phần: p = p₀ + p<sub>cl</sub> = 1,01 · 10⁵ + 2,02 · 10⁵ = 3,03 · 10⁵ Pa.","svgGraph":null},{"q":"Trong một máy nén thủy lực dùng để nâng ô tô, pít-tông nhỏ có diện tích S₁ = 10 cm², pít-tông lớn có diện tích S₂ = 500 cm². Muốn nâng một chiếc ô tô có trọng lượng P = 20 000 N đặt trên pít-tông lớn, ta phải tác dụng một lực F₁ vào pít-tông nhỏ có độ lớn tối thiểu là:","opts":["400 N.","200 N.","1000 N.","50 N."],"ans":0,"exp":"• Ứng dụng nguyên lí Pascal cho máy ép thuỷ lực:<br><span class=\"fraction\"><span class=\"numerator\">F₁</span><span class=\"denominator\">S₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">F₂</span><span class=\"denominator\">S₂</span></span> ⇒ F₁ = F₂ · <span class=\"fraction\"><span class=\"numerator\">S₁</span><span class=\"denominator\">S₂</span></span> = 20 000 · <span class=\"fraction\"><span class=\"numerator\">10</span><span class=\"denominator\">500</span></span> = 20 000 · <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">50</span></span> = 400 N.","svgGraph":null}]},"11":{"1":[{"q":"Dao động điều hoà là một dạng dao động cơ học đặc biệt mà trong đó li độ của vật là:","opts":["Một hàm bậc nhất theo thời gian.","Một hàm cosin (hoặc sin) của thời gian.","Một hàm bậc hai theo thời gian biến thiên liên tục.","Một đại lượng không đổi theo thời gian."],"ans":"B","exp":"• <b>Định nghĩa SGK:</b> Dao động điều hoà là dao động trong đó li độ của vật là một hàm cosin (hoặc sin) của thời gian: x = A·cos(ωt + φ).<br>• Đại lượng A là biên độ, ω là tần số góc, (ωt + φ) là pha dao động.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr1\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <circle cx=\"130\" cy=\"120\" r=\"70\" stroke=\"#334155\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\" fill=\"none\"/>\n      <line x1=\"40\" y1=\"120\" x2=\"220\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr1)\"/>\n      <line x1=\"130\" y1=\"200\" x2=\"130\" y2=\"40\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr1)\"/>\n      <line x1=\"130\" y1=\"120\" x2=\"180\" y2=\"70\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <circle cx=\"180\" cy=\"70\" r=\"5\" fill=\"#38bdf8\"/>\n      <text x=\"185\" y=\"65\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">M(t)</text>\n      <line x1=\"180\" y1=\"70\" x2=\"180\" y2=\"120\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <circle cx=\"180\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <text x=\"175\" y=\"140\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">P(x)</text>\n      <line x1=\"250\" y1=\"120\" x2=\"470\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr1)\"/>\n      <line x1=\"270\" y1=\"200\" x2=\"270\" y2=\"40\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr1)\"/>\n      <path d=\"M 270,70 Q 320,30 370,120 T 470,120\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <text x=\"475\" y=\"125\" fill=\"#94a3b8\" font-size=\"12\">t</text><text x=\"275\" y=\"45\" fill=\"#94a3b8\" font-size=\"12\">x</text>\n      <text x=\"250\" y=\"70\" fill=\"#34d399\" font-size=\"12\">+A</text><text x=\"250\" y=\"175\" fill=\"#34d399\" font-size=\"12\">-A</text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Mô hình hình chiếu của chuyển động tròn đều</text>\n    </svg>"},{"q":"Trong phương trình dao động điều hoà x = A·cos(ωt + φ), đại lượng ω được gọi là:","opts":["Chu kì của dao động, đơn vị là giây (s).","Pha ban đầu của dao động, đơn vị là radian (rad).","Tần số góc của dao động, đơn vị là radian trên giây (rad/s).","Tần số của dao động, đơn vị là héc (Hz)."],"ans":"C","exp":"• A: Biên độ dao động (m, cm).<br>• ω: Tần số góc (rad/s).<br>• (ωt + φ): Pha dao động tại thời điểm t (rad).<br>• φ: Pha ban đầu tại thời điểm t = 0 (rad).","svgGraph":null},{"q":"Một chất điểm dao động điều hoà thực hiện được 60 dao động toàn phần trong thời gian 30 giây. Chu kì dao động của chất điểm là:","opts":["0,5 s.","2,0 s.","120 s.","1800 s."],"ans":"A","exp":"• <b>Hiện tượng:</b> Chu kì T là thời gian thực hiện 1 dao động toàn phần.<br>• <b>Công thức:</b> T = <span class=\"fraction\"><span class=\"numerator\">Δt</span><span class=\"denominator\">N</span></span><br>• <b>Thay số:</b> T = <span class=\"fraction\"><span class=\"numerator\">30</span><span class=\"denominator\">60</span></span> = 0,5 s.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà với phương trình x = 8·cos(2πt - π/6) (cm). Biên độ và pha ban đầu của dao động lần lượt là:","opts":["A = 8 cm; φ = -π/6 rad.","A = 8 cm; φ = π/6 rad.","A = 16 cm; φ = 2π rad.","A = 4 cm; φ = -π/6 rad."],"ans":"A","exp":"• Đối chiếu với x = A·cos(ωt + φ):<br>- Biên độ A = 8 cm.<br>- Pha ban đầu φ = -π/6 rad.","svgGraph":null},{"q":"Một con lắc dao động với tần số góc ω = 10 rad/s. Tần số dao động f của con lắc xấp xỉ bằng:","opts":["1,59 Hz.","6,28 Hz.","3,14 Hz.","62,8 Hz."],"ans":"A","exp":"• <b>Công thức:</b> f = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">2π</span></span><br>• <b>Thay số:</b> f = <span class=\"fraction\"><span class=\"numerator\">10</span><span class=\"denominator\">2π</span></span> ≈ 1,59 Hz.","svgGraph":null},{"q":"Pha ban đầu φ của dao động điều hoà cho phép ta xác định:","opts":["Tốc độ cực đại của vật trong quá trình dao động.","Vị trí và chiều chuyển động của vật ở thời điểm ban đầu t = 0.","Năng lượng toàn phần mà vật dao động tích luỹ.","Khoảng thời gian ngắn nhất vật đổi chiều chuyển động."],"ans":"B","exp":"• Tại thời điểm ban đầu t = 0: x₀ = A·cos(φ) và v₀ = -ωA·sin(φ).<br>• Do đó pha ban đầu φ xác định chính xác vị trí và chiều chuyển động của vật lúc bắt đầu quan sát.","svgGraph":null}],"2":[{"q":"Hình bên dưới là đồ thị li độ - thời gian của một vật dao động điều hoà. Biên độ dao động A và chu kì T của vật là:","opts":["A = 4 cm; T = 2 s.","A = 8 cm; T = 2 s.","A = 4 cm; T = 4 s.","A = 2 cm; T = 1 s."],"ans":"A","exp":"• <b>Từ đồ thị:</b><br>- Giá trị đỉnh cao nhất của đồ thị là x = 4 cm, do đó biên độ A = 4 cm.<br>- Khoảng thời gian giữa hai đỉnh sóng liên tiếp (hoặc từ vị trí x = 0 qua một chu trình đầy đủ) là từ t = 0 s đến t = 2 s, do đó chu kì T = 2 s.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <line x1=\"60\" y1=\"60\" x2=\"460\" y2=\"60\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"60\" y1=\"180\" x2=\"460\" y2=\"180\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"40\" y1=\"120\" x2=\"470\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr2)\"/>\n      <line x1=\"60\" y1=\"210\" x2=\"60\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr2)\"/>\n      <text x=\"475\" y=\"125\" fill=\"#94a3b8\" font-size=\"13\">t (s)</text><text x=\"65\" y=\"35\" fill=\"#94a3b8\" font-size=\"13\">x (cm)</text>\n      <text x=\"48\" y=\"125\" fill=\"#94a3b8\" font-size=\"12\">0</text><text x=\"42\" y=\"65\" fill=\"#38bdf8\" font-size=\"12\">4</text><text x=\"35\" y=\"185\" fill=\"#38bdf8\" font-size=\"12\">-4</text>\n      <text x=\"155\" y=\"138\" fill=\"#fbbf24\" font-size=\"12\">1</text><text x=\"255\" y=\"138\" fill=\"#fbbf24\" font-size=\"12\">2</text><text x=\"355\" y=\"138\" fill=\"#fbbf24\" font-size=\"12\">3</text><text x=\"455\" y=\"138\" fill=\"#fbbf24\" font-size=\"12\">4</text>\n      <path d=\"M 60,60 C 110,60 110,180 160,180 C 210,180 210,60 260,60 C 310,60 310,180 360,180 C 410,180 410,60 460,60\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n    </svg>"},{"q":"Đồ thị li độ - thời gian của một dao động điều hoà là một đường cong hình sin. Dựa vào đồ thị, đại lượng nào sau đây KHÔNG THỂ xác định trực tiếp được ngay mà phải qua tính toán?","opts":["Biên độ dao động A.","Chu kì dao động T.","Li độ x tại một thời điểm t cho trước.","Khối lượng m của vật dao động."],"ans":"D","exp":"• Đồ thị x-t cho biết trực tiếp: Biên độ A, chu kì T, tần số f = 1/T, pha ban đầu φ và li độ x tại mọi thời điểm.<br>• Khối lượng m là đại lượng quán tính động lực học, không biểu hiện trực tiếp trên đồ thị hình học x-t.","svgGraph":null},{"q":"Tại thời điểm ban đầu t = 0, một vật dao động điều hoà đang ở vị trí biên dương (x = +A). Pha ban đầu φ của dao động này là:","opts":["φ = 0 rad.","φ = π rad.","φ = π/2 rad.","φ = -π/2 rad."],"ans":"A","exp":"• Tại t = 0: x₀ = A·cos(φ) = +A ⇔ cos(φ) = 1 ⇔ φ = 0 rad.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà trên trục Ox. Trong thời gian 1 phút, vật thực hiện được 120 dao động toàn phần. Tần số góc ω của dao động là:","opts":["4π rad/s.","2π rad/s.","2 rad/s.","120π rad/s."],"ans":"A","exp":"• Tần số: f = N/Δt = 120/60 = 2 Hz.<br>• Tần số góc: ω = 2π·f = 2π · 2 = 4π rad/s.","svgGraph":null},{"q":"Một vật dao động điều hoà theo phương trình x = 5·cos(10t + π/4) (cm). Độ dịch chuyển (li độ) của vật tại thời điểm t = 0 là:","opts":["2,5√2 cm.","5 cm.","2,5 cm.","0 cm."],"ans":"A","exp":"• Tại t = 0: x = 5·cos(π/4) = 5 · <span class=\"fraction\"><span class=\"numerator\">√2</span><span class=\"denominator\">2</span></span> = 2,5√2 cm (≈ 3,54 cm).","svgGraph":null},{"q":"Quỹ đạo chuyển động của một vật dao động điều hoà là một đoạn thẳng dài 14 cm. Biên độ dao động của vật là:","opts":["7 cm.","14 cm.","28 cm.","3,5 cm."],"ans":"A","exp":"• Chiều dài quỹ đạo: L = 2A ⇒ A = L/2 = 14/2 = 7 cm.","svgGraph":null}],"3":[{"q":"Một chất điểm dao động điều hoà theo phương trình x = A·cos(ωt + φ). Biểu thức vận tốc v của chất điểm là:","opts":["v = -ωA·sin(ωt + φ).","v = ωA·cos(ωt + φ).","v = -ω²A·sin(ωt + φ).","v = ω²A·cos(ωt + φ)."],"ans":"A","exp":"• Vận tốc là đạo hàm bậc nhất của li độ theo thời gian: v = x' = -ωA·sin(ωt + φ) = ωA·cos(ωt + φ + π/2).<br>• Vận tốc biến thiên điều hoà cùng tần số góc ω và sớm pha π/2 so với li độ.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr3\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <line x1=\"30\" y1=\"120\" x2=\"470\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr3)\"/>\n      <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr3)\"/>\n      <text x=\"475\" y=\"125\" fill=\"#94a3b8\" font-size=\"12\">t</text>\n      <path d=\"M 50,60 Q 100,60 150,120 T 250,180 T 350,120 T 450,60\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <path d=\"M 50,120 Q 100,180 150,180 T 250,60 T 350,120 T 450,180\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2\" stroke-dasharray=\"4,3\"/>\n      <path d=\"M 50,180 Q 100,180 150,120 T 250,60 T 350,120 T 450,180\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n      <rect x=\"260\" y=\"25\" width=\"200\" height=\"40\" fill=\"#1e293b\" rx=\"5\"/>\n      <line x1=\"270\" y1=\"38\" x2=\"295\" y2=\"38\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <text x=\"305\" y=\"42\" fill=\"#38bdf8\" font-size=\"11\">Li độ x(t)</text>\n      <line x1=\"270\" y1=\"53\" x2=\"295\" y2=\"53\" stroke=\"#34d399\" stroke-width=\"2\" stroke-dasharray=\"4,2\"/>\n      <text x=\"305\" y=\"57\" fill=\"#34d399\" font-size=\"11\">Vận tốc v(t)</text>\n      <line x1=\"370\" y1=\"38\" x2=\"395\" y2=\"38\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n      <text x=\"405\" y=\"42\" fill=\"#f43f5e\" font-size=\"11\">Gia tốc a(t)</text>\n    </svg>"},{"q":"Trong dao động điều hoà, gia tốc của vật biến thiên điều hoà và có mối quan hệ về pha so với li độ là:","opts":["Ngược pha với li độ.","Cùng pha với li độ.","Sớm pha π/2 so với li độ.","Trễ pha π/2 so với li độ."],"ans":"A","exp":"• Biểu thức gia tốc: a = -ω²x = ω²A·cos(ωt + φ + π).<br>• Dấu âm chứng tỏ véctơ gia tốc a luôn ngược chiều với li độ x, nghĩa là ngược pha với li độ.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà với biên độ A = 5 cm và tần số góc ω = 10 rad/s. Tốc độ cực đại v<sub>max</sub> của chất điểm là:","opts":["50 cm/s.","2 cm/s.","0,5 cm/s.","500 cm/s."],"ans":"A","exp":"• <b>Công thức:</b> v<sub>max</sub> = ω·A<br>• <b>Thay số:</b> v<sub>max</sub> = 10 · 5 = 50 cm/s (khi vật đi qua vị trí cân bằng).","svgGraph":null},{"q":"Một chất điểm dao động điều hoà có biên độ A = 4 cm và chu kì T = 2 s. Gia tốc cực đại a<sub>max</sub> của chất điểm là:","opts":["4π² cm/s².","2π² cm/s².","8π cm/s².","16π² cm/s²."],"ans":"A","exp":"• Tần số góc: ω = 2π/T = 2π/2 = π rad/s.<br>• Gia tốc cực đại: a<sub>max</sub> = ω²A = π² · 4 = 4π² cm/s² (≈ 39,5 cm/s²).","svgGraph":null},{"q":"Một chất điểm dao động điều hoà với phương trình x = 6·cos(5t) (cm). Khi vật có li độ x = 3 cm thì độ lớn gia tốc của vật là:","opts":["75 cm/s².","15 cm/s².","150 cm/s².","30 cm/s²."],"ans":"A","exp":"• Độ lớn gia tốc: |a| = ω²|x| = 5² · 3 = 25 · 3 = 75 cm/s².","svgGraph":null},{"q":"Hệ thức độc lập thời gian giữa vận tốc v và gia tốc a của vật dao động điều hoà là:","opts":["<span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">ω²</span></span> + <span class=\"fraction\"><span class=\"numerator\">a²</span><span class=\"denominator\">ω⁴</span></span> = A².","<span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">ω⁴</span></span> + <span class=\"fraction\"><span class=\"numerator\">a²</span><span class=\"denominator\">ω²</span></span> = A².","v² + a² = ω²A².","v²·ω² + a² = A²."],"ans":"A","exp":"• Vì a = -ω²x ⇒ x² = a²/ω⁴.<br>• Thay vào hệ thức x² + v²/ω² = A² ta được: <span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">ω²</span></span> + <span class=\"fraction\"><span class=\"numerator\">a²</span><span class=\"denominator\">ω⁴</span></span> = A².","svgGraph":null}],"4":[{"q":"Một chất điểm dao động điều hoà với phương trình x = 10·cos(4πt + π/3) (cm). Tốc độ của chất điểm khi đi qua vị trí cân bằng là:","opts":["40π cm/s.","10π cm/s.","4π cm/s.","160π² cm/s."],"ans":"A","exp":"• Tốc độ qua VCB đạt giá trị cực đại: v<sub>max</sub> = ωA.<br>• Thay số: v<sub>max</sub> = 4π · 10 = 40π cm/s (≈ 125,7 cm/s).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr4\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <circle cx=\"250\" cy=\"120\" r=\"80\" stroke=\"#334155\" stroke-width=\"2\" fill=\"none\"/>\n      <line x1=\"120\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr4)\"/>\n      <line x1=\"250\" y1=\"210\" x2=\"250\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr4)\"/>\n      <line x1=\"250\" y1=\"120\" x2=\"290\" y2=\"50.7\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <circle cx=\"290\" cy=\"50.7\" r=\"5\" fill=\"#38bdf8\"/>\n      <text x=\"295\" y=\"45\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">M₀ (t=0)</text>\n      <text x=\"260\" y=\"100\" fill=\"#fbbf24\" font-size=\"12\">π/3</text>\n      <line x1=\"290\" y1=\"50.7\" x2=\"290\" y2=\"120\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <circle cx=\"290\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <text x=\"285\" y=\"140\" fill=\"#f43f5e\" font-size=\"12\">x₀ = 5 cm</text>\n      <text x=\"330\" y=\"135\" fill=\"#34d399\" font-size=\"12\">+10 cm</text>\n      <text x=\"145\" y=\"135\" fill=\"#34d399\" font-size=\"12\">-10 cm</text>\n      <text x=\"180\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Vòng tròn lượng giác biểu diễn pha dao động</text>\n    </svg>"},{"q":"Một con lắc lò xo dao động điều hoà với biên độ A = 8 cm và chu kì T = 1,2 s. Khoảng thời gian ngắn nhất để vật đi từ vị trí cân bằng x = 0 đến vị trí x = 4 cm là:","opts":["0,1 s.","0,2 s.","0,3 s.","0,6 s."],"ans":"A","exp":"• Vị trí x = 4 cm = A/2.<br>• Thời gian ngắn nhất đi từ VCB (x = 0) đến x = A/2 là: Δt = T/12.<br>• Thay số: Δt = 1,2 / 12 = 0,1 s.","svgGraph":null},{"q":"Một vật dao động điều hoà với biên độ A = 10 cm. Quãng đường vật đi được trong khoảng thời gian bằng 2,5 chu kì (2,5T) là:","opts":["100 cm.","50 cm.","25 cm.","200 cm."],"ans":"A","exp":"• Trong 1 chu kì vật luôn đi được quãng đường S₁ = 4A.<br>• Trong 0,5 chu kì vật luôn đi được quãng đường S₀.5 = 2A.<br>• Tổng quãng đường: S = 2 · (4A) + 2A = 10A = 10 · 10 = 100 cm.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà với tần số góc ω = 5 rad/s. Khi li độ x = 4 cm thì vận tốc v = 15 cm/s. Biên độ dao động của chất điểm là:","opts":["5 cm.","7 cm.","3 cm.","25 cm."],"ans":"A","exp":"• Áp dụng hệ thức độc lập: A = √(x² + v²/ω²).<br>• Thay số: A = √(4² + (15/5)²) = √(16 + 9) = √25 = 5 cm.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà quanh vị trí cân bằng. Trong khoảng thời gian ngắn nhất giữa hai lần liên tiếp vật đi qua li độ x = 5 cm, vật đi được quãng đường dài 10 cm. Biên độ dao động A là:","opts":["10 cm.","5 cm.","5√2 cm.","15 cm."],"ans":"A","exp":"• Vật đi từ x = 5 cm ra biên A rồi quay lại x = 5 cm: Quãng đường S = 2(A - 5).<br>• Theo đề bài: 2(A - 5) = 10 ⇒ A - 5 = 5 ⇒ A = 10 cm.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà có gia tốc a và li độ x liên hệ với nhau qua hệ thức a = -100x (cm/s²), trong đó x tính bằng cm. Chu kì dao động của chất điểm là:","opts":["0,2π s.","0,1π s.","10 s.","2 s."],"ans":"A","exp":"• Từ a = -ω²x và a = -100x ⇒ ω² = 100 ⇒ ω = 10 rad/s.<br>• Chu kì: T = 2π/ω = 2π/10 = 0,2π s (≈ 0,628 s).","svgGraph":null}],"5":[{"q":"Cơ năng của một vật dao động điều hoà có khối lượng m, tần số góc ω và biên độ A được xác định bởi công thức:","opts":["W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A².","W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mωA².","W = mω²A².","W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A."],"ans":"A","exp":"• Cơ năng của vật dao động điều hoà bằng tổng động năng và thế năng, luôn được bảo toàn và tỉ lệ với bình phương biên độ dao động: W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>kA².","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr5\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <line x1=\"50\" y1=\"190\" x2=\"450\" y2=\"190\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr5)\"/>\n      <line x1=\"250\" y1=\"210\" x2=\"250\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr5)\"/>\n      <text x=\"455\" y=\"195\" fill=\"#94a3b8\" font-size=\"12\">x</text>\n      <text x=\"255\" y=\"40\" fill=\"#94a3b8\" font-size=\"12\">W</text>\n      <line x1=\"90\" y1=\"60\" x2=\"410\" y2=\"60\" stroke=\"#fbbf24\" stroke-width=\"2.5\"/>\n      <text x=\"415\" y=\"65\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">W = const</text>\n      <path d=\"M 90,60 Q 250,220 410,60\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <path d=\"M 90,190 Q 250,-70 410,190\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2.5\"/>\n      <text x=\"80\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">-A</text>\n      <text x=\"400\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">+A</text>\n      <text x=\"240\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">0</text>\n      <circle cx=\"179.3\" cy=\"125\" r=\"4\" fill=\"#f43f5e\"/>\n      <circle cx=\"320.7\" cy=\"125\" r=\"4\" fill=\"#f43f5e\"/>\n      <text x=\"280\" y=\"145\" fill=\"#f43f5e\" font-size=\"11\">W<tspan baseline-shift=\"sub\" font-size=\"70%\">đ</tspan> = W<tspan baseline-shift=\"sub\" font-size=\"70%\">t</tspan></text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Đồ thị động năng và thế năng theo li độ x</text>\n    </svg>"},{"q":"Trong quá trình dao động điều hoà, thế năng của vật đạt giá trị cực đại khi vật ở vị trí:","opts":["Biên dương hoặc biên âm (x = ±A).","Vị trí cân bằng (x = 0).","Vị trí có li độ x = ±A/2.","Vị trí có vận tốc đạt cực đại."],"ans":"A","exp":"• Thế năng: W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²x².<br>• Khi x = ±A, độ lớn li độ cực đại nên thế năng đạt cực đại: W<sub>t</sub>,max = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A² = W.","svgGraph":null},{"q":"Một vật dao động điều hoà với chu kì T. Động năng và thế năng của vật biến thiên tuần hoàn theo thời gian với chu kì bằng:","opts":["T/2.","T.","2T.","4T."],"ans":"A","exp":"• Biểu thức thế năng và động năng chứa cos²(ωt + φ) và sin²(ωt + φ).<br>• Khi hạ bậc: cos²(α) = <span class=\"fraction\"><span class=\"numerator\">1 + cos(2α)</span><span class=\"denominator\">2</span></span> ⇒ tần số góc tăng gấp đôi (2ω), do đó chu kì giảm một nửa: T' = T/2.","svgGraph":null},{"q":"Một con lắc lò xo có độ cứng k = 100 N/m dao động điều hoà với biên độ A = 5 cm. Cơ năng của con lắc là:","opts":["0,125 J.","1,25 J.","0,25 J.","125 J."],"ans":"A","exp":"• Đổi đơn vị: A = 5 cm = 0,05 m.<br>• Công thức: W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>kA² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 100 · (0,05)² = 0,125 J.","svgGraph":null},{"q":"Một vật có khối lượng m = 200 g dao động điều hoà với tần số f = 5 Hz và biên độ A = 4 cm. Cơ năng của vật (lấy π² ≈ 10) là:","opts":["0,16 J.","0,08 J.","0,32 J.","1,6 J."],"ans":"A","exp":"• ω = 2π·f = 10π rad/s.<br>• Đổi m = 0,2 kg; A = 0,04 m.<br>• W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 0,2 · (10π)² · (0,04)² = 0,1 · 1000 · 0,0016 = 0,16 J.","svgGraph":null},{"q":"Khi vật dao động điều hoà đi qua vị trí có động năng bằng thế năng (W<sub>đ</sub> = W<sub>t</sub>) thì độ lớn li độ của vật là:","opts":["|x| = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">√2</span></span>.","|x| = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">2</span></span>.","|x| = <span class=\"fraction\"><span class=\"numerator\">A√3</span><span class=\"denominator\">2</span></span>.","|x| = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">4</span></span>."],"ans":"A","exp":"• Khi W<sub>đ</sub> = W<sub>t</sub> ⇒ W = W<sub>đ</sub> + W<sub>t</sub> = 2W<sub>t</sub>.<br>• <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A² = 2 · (<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²x²) ⇒ x² = <span class=\"fraction\"><span class=\"numerator\">A²</span><span class=\"denominator\">2</span></span> ⇒ |x| = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">√2</span></span>.","svgGraph":null}],"6":[{"q":"Hiện tượng biên độ và cơ năng của dao động giảm dần theo thời gian được gọi là:","opts":["Dao động tắt dần.","Dao động cưỡng bức.","Dao động duy trì.","Hiện tượng cộng hưởng."],"ans":"A","exp":"• Dao động tắt dần là dao động có biên độ và cơ năng giảm dần theo thời gian do ma sát và lực cản của môi trường chuyển hoá cơ năng thành nhiệt năng.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr6\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <line x1=\"30\" y1=\"120\" x2=\"230\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr6)\"/>\n      <line x1=\"40\" y1=\"200\" x2=\"40\" y2=\"40\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr6)\"/>\n      <path d=\"M 40,60 Q 60,60 80,120 T 120,160 T 155,100 T 185,130 T 215,120\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n      <text x=\"235\" y=\"125\" fill=\"#94a3b8\" font-size=\"11\">t</text>\n      <text x=\"45\" y=\"45\" fill=\"#94a3b8\" font-size=\"11\">x</text>\n      <text x=\"55\" y=\"220\" fill=\"#f43f5e\" font-size=\"12\">Dao động tắt dần</text>\n      <line x1=\"270\" y1=\"190\" x2=\"470\" y2=\"190\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr6)\"/>\n      <line x1=\"280\" y1=\"200\" x2=\"280\" y2=\"40\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr6)\"/>\n      <path d=\"M 290,180 Q 340,170 370,60 Q 400,170 450,180\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <line x1=\"370\" y1=\"60\" x2=\"370\" y2=\"190\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <circle cx=\"370\" cy=\"60\" r=\"4\" fill=\"#fbbf24\"/>\n      <text x=\"355\" y=\"205\" fill=\"#fbbf24\" font-size=\"11\">f = f₀</text>\n      <text x=\"475\" y=\"195\" fill=\"#94a3b8\" font-size=\"11\">f<tspan baseline-shift=\"sub\" font-size=\"70%\">cb</tspan></text>\n      <text x=\"285\" y=\"45\" fill=\"#94a3b8\" font-size=\"11\">A<tspan baseline-shift=\"sub\" font-size=\"70%\">cb</tspan></text>\n      <text x=\"315\" y=\"220\" fill=\"#38bdf8\" font-size=\"12\">Đường cong cộng hưởng</text>\n    </svg>"},{"q":"Một thiết bị đóng cửa tự động sử dụng lò xo kéo và piston giảm xóc hoạt động dựa trên ứng dụng của:","opts":["Dao động tắt dần.","Dao động cưỡng bức.","Hiện tượng cộng hưởng cơ.","Chuyển động rơi tự do."],"ans":"A","exp":"• Piston chứa dầu tạo lực cản lớn làm cho dao động của cánh cửa bị tắt dần nhanh chóng, giúp cửa đóng êm ái mà không bị va đập lắc qua lắc lại.","svgGraph":null},{"q":"Hiện tượng cộng hưởng xảy ra trong dao động cưỡng bức khi:","opts":["Tần số của lực cưỡng bức bằng tần số riêng của hệ dao động.","Biên độ của lực cưỡng bức đạt giá trị cực đại.","Lực ma sát của môi trường triệt tiêu hoàn toàn.","Chu kì của lực cưỡng bức lớn gấp đôi chu kì riêng của hệ."],"ans":"A","exp":"• Khi tần số của ngoại lực tuần hoàn f bằng tần số riêng f₀ của hệ, biên độ dao động cưỡng bức đạt giá trị cực đại. Hiện tượng này gọi là hiện tượng cộng hưởng cơ.","svgGraph":null},{"q":"Một con lắc lò xo có tần số dao động riêng f₀ = 10 Hz. Tác dụng vào con lắc một ngoại lực tuần hoàn có tần số f. Hiện tượng cộng hưởng xảy ra khi tần số f có giá trị bằng:","opts":["10 Hz.","5 Hz.","20 Hz.","15 Hz."],"ans":"A","exp":"• Điều kiện xảy ra cộng hưởng là tần số ngoại lực bằng tần số riêng: f = f₀ = 10 Hz.","svgGraph":null},{"q":"Bộ phận giảm xóc (phuộc nhún) ở bánh xe máy và ô tô hoạt động dựa trên nguyên tắc của loại dao động nào?","opts":["Dao động tắt dần.","Dao động cưỡng bức.","Dao động điều hoà tự do.","Hiện tượng cộng hưởng."],"ans":"A","exp":"• Khi xe đi qua đoạn đường gồ ghề, lò xo bị nén và có xu hướng dao động liên tục. Bộ giảm xóc tạo lực cản nhớt làm dao động tắt dần nhanh chóng, giúp xe nhanh ổn định thăng bằng.","svgGraph":null},{"q":"Đoàn quân đi đều bước qua một cây cầu treo có thể làm cầu rung lắc dữ dội và có nguy cơ bị sập là do:","opts":["Tần số bước chân trùng với tần số dao động riêng của cầu gây ra hiện tượng cộng hưởng.","Trọng lượng của đoàn quân quá nặng vượt tải trọng tĩnh của cầu.","Gió thổi mạnh làm thay đổi biên độ dao động riêng của cầu.","Chất lượng vật liệu làm cầu bị giảm dần theo thời gian."],"ans":"A","exp":"• Tần số bước chân đều đặn của đoàn quân đóng vai trò là ngoại lực tuần hoàn. Khi tần số này trùng với tần số riêng của cầu, hiện tượng cộng hưởng xảy ra làm biên độ rung lắc tăng vọt dẫn tới nguy cơ sập cầu.","svgGraph":null}],"7":[{"q":"Một con lắc lò xo dao động điều hoà với cơ năng W = 0,2 J. Tại vị trí có động năng bằng 3 lần thế năng (W<sub>đ</sub> = 3W<sub>t</sub>), thế năng của con lắc có giá trị bằng:","opts":["0,05 J.","0,15 J.","0,067 J.","0,1 J."],"ans":"A","exp":"• Ta có: W = W<sub>đ</sub> + W<sub>t</sub> = 3W<sub>t</sub> + W<sub>t</sub> = 4W<sub>t</sub>.<br>• Suy ra thế năng: W<sub>t</sub> = W / 4 = 0,2 / 4 = 0,05 J.<br>• Động năng lúc này: W<sub>đ</sub> = 3 · 0,05 = 0,15 J.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà với biên độ A = 10 cm. Vị trí có thế năng bằng 3 lần động năng (W<sub>t</sub> = 3W<sub>đ</sub>) cách vị trí cân bằng một khoảng là:","opts":["5√3 cm.","5 cm.","5√2 cm.","2,5 cm."],"ans":"A","exp":"• Ta có: W<sub>t</sub> = 3W<sub>đ</sub> ⇒ W<sub>đ</sub> = W<sub>t</sub> / 3.<br>• Cơ năng: W = W<sub>đ</sub> + W<sub>t</sub> = W<sub>t</sub>/3 + W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">3</span></span>W<sub>t</sub> ⇒ W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">4</span></span>W.<br>• Do W<sub>t</sub> ∝ x² và W ∝ A² nên: x² = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">4</span></span>A² ⇒ |x| = A·<span class=\"fraction\"><span class=\"numerator\">√3</span><span class=\"denominator\">2</span></span> = 10 · <span class=\"fraction\"><span class=\"numerator\">√3</span><span class=\"denominator\">2</span></span> = 5√3 cm.","svgGraph":null},{"q":"Một vật có khối lượng m = 400 g dao động điều hoà có đồ thị thế năng theo thời gian là một đường cong hình sin biến thiên từ 0 đến 0,5 J với chu kì biến thiên là 0,25 s. Chu kì dao động của vật là:","opts":["0,5 s.","0,25 s.","0,125 s.","1,0 s."],"ans":"A","exp":"• Chu kì biến thiên của thế năng là T' = T/2.<br>• Suy ra chu kì dao động của vật: T = 2·T' = 2 · 0,25 = 0,5 s.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà có cơ năng W = 36 mJ. Khi chất điểm có thế năng W<sub>t</sub> = 9 mJ thì tỉ số giữa động năng và thế năng là:","opts":["3.","4.","1/3.","1/4."],"ans":"A","exp":"• Động năng: W<sub>đ</sub> = W - W<sub>t</sub> = 36 - 9 = 27 mJ.<br>• Tỉ số: W<sub>đ</sub> / W<sub>t</sub> = 27 / 9 = 3.","svgGraph":null},{"q":"Một con lắc lò xo dao động điều hoà với biên độ A. Khi vật đi từ vị trí cân bằng x = 0 đến vị trí có li độ x = A/√2 thì tỉ lệ thế năng tăng thêm so với cơ năng là:","opts":["50%.","25%.","70,7%.","100%."],"ans":"A","exp":"• Tại x = 0 thì W<sub>t</sub> = 0.<br>• Tại x = A/√2 thì W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²(A/√2)² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>mω²A² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>W = 50%W.<br>• Như vậy thế năng đã tăng thêm 50% cơ năng.","svgGraph":null},{"q":"Một con lắc lò xo dao động điều hoà với cơ năng W. Khi tốc độ của vật bằng một nửa tốc độ cực đại (v = v<sub>max</sub>/2) thì thế năng của con lắc bằng:","opts":["<span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">4</span></span>W.","<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>W.","<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>W.","<span class=\"fraction\"><span class=\"numerator\">√3</span><span class=\"denominator\">2</span></span>W."],"ans":"A","exp":"• Khi v = v<sub>max</sub>/2 ⇒ W<sub>đ</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mv² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m(v<sub>max</sub>/2)² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>W.<br>• Suy ra thế năng: W<sub>t</sub> = W - W<sub>đ</sub> = W - <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>W = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">4</span></span>W.","svgGraph":null}],"8":[{"q":"Sóng cơ học là:","opts":["Quá trình lan truyền dao động cơ học và năng lượng trong một môi trường vật chất theo thời gian.","Sự chuyển động tịnh tiến của các phần tử môi trường từ nguồn sóng ra xa.","Quá trình lan truyền của các hạt vật chất chuyển động với vận tốc không đổi.","Sự biến dạng vĩnh viễn của môi trường đàn hồi khi có ngoại lực tác dụng."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Sóng cơ là dao động cơ lan truyền trong môi trường vật chất.<br>• Khi sóng truyền qua, các phần tử môi trường chỉ dao động tại chỗ quanh vị trí cân bằng của chúng, không chuyển dời theo sóng; chỉ có pha dao động và năng lượng sóng được truyền đi xa.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr8\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <line x1=\"40\" y1=\"120\" x2=\"470\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr8)\"/>\n      <line x1=\"60\" y1=\"210\" x2=\"60\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr8)\"/>\n      <text x=\"475\" y=\"125\" fill=\"#94a3b8\" font-size=\"12\">x (m)</text><text x=\"65\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">u (mm)</text>\n      <!-- Sinusoidal wave profile -->\n      <path d=\"M 60,120 Q 110,40 160,120 T 260,120 T 360,120 T 460,120\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <!-- Wavelength lambda line -->\n      <line x1=\"110\" y1=\"50\" x2=\"310\" y2=\"50\" stroke=\"#fbbf24\" stroke-width=\"2\" stroke-dasharray=\"4,3\"/>\n      <circle cx=\"110\" cy=\"50\" r=\"4\" fill=\"#fbbf24\"/>\n      <circle cx=\"310\" cy=\"50\" r=\"4\" fill=\"#fbbf24\"/>\n      <text x=\"195\" y=\"42\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">Bước sóng λ</text>\n      <!-- Particles vibrating vertically -->\n      <circle cx=\"210\" cy=\"190\" r=\"5\" fill=\"#f43f5e\"/>\n      <line x1=\"210\" y1=\"160\" x2=\"210\" y2=\"210\" stroke=\"#f43f5e\" stroke-width=\"2\" marker-end=\"url(#arr8)\"/>\n      <text x=\"220\" y=\"200\" fill=\"#f43f5e\" font-size=\"11\">Phần tử dao động tại chỗ</text>\n      <!-- Wave propagation direction -->\n      <line x1=\"330\" y1=\"90\" x2=\"400\" y2=\"90\" stroke=\"#34d399\" stroke-width=\"2.5\" marker-end=\"url(#arr8)\"/>\n      <text x=\"340\" y=\"80\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">v (truyền sóng)</text>\n      <text x=\"130\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Hình ảnh sóng hình sin lan truyền trong không gian</text>\n    </svg>"},{"q":"Bước sóng λ là:","opts":["Quãng đường mà sóng truyền được trong một chu kì dao động.","Khoảng cách giữa hai điểm bất kì trên cùng một phương truyền sóng.","Quãng đường sóng truyền được trong thời gian một giây.","Khoảng cách giữa một đỉnh sóng và một hõm sóng gần nhau nhất."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Bước sóng λ là quãng đường sóng truyền đi trong 1 chu kì: λ = v·T = <span class=\"fraction\"><span class=\"numerator\">v</span><span class=\"denominator\">f</span></span>.<br>• Bước sóng cũng chính là khoảng cách ngắn nhất giữa hai điểm trên cùng một phương truyền sóng dao động cùng pha.","svgGraph":null},{"q":"Một sóng cơ hình sin truyền trong một môi trường với tốc độ v = 20 m/s và tần số f = 50 Hz. Bước sóng của sóng này là:","opts":["0,4 m.","2,5 m.","1000 m.","0,02 m."],"ans":"A","exp":"• <b>Công thức:</b> λ = <span class=\"fraction\"><span class=\"numerator\">v</span><span class=\"denominator\">f</span></span><br>• <b>Thay số:</b> λ = <span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">50</span></span> = 0,4 m (40 cm).","svgGraph":null},{"q":"Một người quan sát thấy một chiếc phao trên mặt biển nhấp nhô lên xuống tại chỗ 10 lần trong khoảng thời gian 18 giây. Khoảng cách giữa hai đỉnh sóng lân cận là 3 m. Tốc độ truyền sóng trên mặt biển là:","opts":["1,5 m/s.","3,0 m/s.","1,67 m/s.","0,6 m/s."],"ans":"A","exp":"• Phao nhô lên 10 lần ứng với 9 chu kì dao động: 9T = 18 s ⇒ T = 2 s.<br>• Khoảng cách giữa 2 đỉnh lân cận là bước sóng: λ = 3 m.<br>• Tốc độ truyền sóng: v = <span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">T</span></span> = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> = 1,5 m/s.","svgGraph":null},{"q":"Một sóng cơ truyền dọc theo trục Ox có phương trình u = 5·cos(20πt - 4πx) (mm), trong đó x tính bằng mét, t tính bằng giây. Tốc độ truyền sóng là:","opts":["5 m/s.","20 m/s.","4 m/s.","80 m/s."],"ans":"A","exp":"• Phương trình sóng chuẩn: u = A·cos(ωt - <span class=\"fraction\"><span class=\"numerator\">2πx</span><span class=\"denominator\">λ</span></span>).<br>• Đồng nhất hệ số: ω = 20π rad/s và <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">λ</span></span> = 4π ⇒ λ = 0,5 m.<br>• Tần số: f = ω/(2π) = 10 Hz.<br>• Tốc độ truyền sóng: v = λ·f = 0,5 · 10 = 5 m/s.","svgGraph":null},{"q":"Độ lệch pha giữa hai điểm M và N nằm trên cùng một phương truyền sóng cách nhau một khoảng d được tính bởi công thức:","opts":["Δφ = <span class=\"fraction\"><span class=\"numerator\">2πd</span><span class=\"denominator\">λ</span></span>.","Δφ = <span class=\"fraction\"><span class=\"numerator\">πd</span><span class=\"denominator\">λ</span></span>.","Δφ = <span class=\"fraction\"><span class=\"numerator\">2πλ</span><span class=\"denominator\">d</span></span>.","Δφ = <span class=\"fraction\"><span class=\"numerator\">v·d</span><span class=\"denominator\">λ</span></span>."],"ans":"A","exp":"• Thời gian sóng truyền từ M đến N là Δt = d/v.<br>• Độ lệch pha tương ứng: Δφ = ω·Δt = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">T</span></span> · <span class=\"fraction\"><span class=\"numerator\">d</span><span class=\"denominator\">v</span></span> = <span class=\"fraction\"><span class=\"numerator\">2πd</span><span class=\"denominator\">λ</span></span>.","svgGraph":null}],"9":[{"q":"Sóng ngang là sóng trong đó các phần tử môi trường có phương dao động:","opts":["Vuông góc với phương truyền sóng.","Trùng với phương truyền sóng.","Song song với phương truyền sóng.","Hợp với phương truyền sóng một góc 45°."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b><br>- Sóng ngang: Phương dao động vuông góc với phương truyền sóng (ví dụ sóng trên mặt nước, sóng trên dây đàn).<br>- Sóng dọc: Phương dao động trùng với phương truyền sóng (ví dụ sóng âm trong không khí, sóng nén dãn của lò xo).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr9\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Sóng ngang -->\n      <text x=\"50\" y=\"35\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">SÓNG NGANG (Transverse wave)</text>\n      <line x1=\"40\" y1=\"80\" x2=\"220\" y2=\"80\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr9)\"/>\n      <text x=\"225\" y=\"85\" fill=\"#64748b\" font-size=\"11\">Phương truyền</text>\n      <!-- Vertical vibration -->\n      <line x1=\"120\" y1=\"50\" x2=\"120\" y2=\"110\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n      <circle cx=\"120\" cy=\"80\" r=\"5\" fill=\"#f43f5e\"/>\n      <text x=\"130\" y=\"65\" fill=\"#f43f5e\" font-size=\"11\">Dao động ⊥</text>\n      <!-- Sóng dọc -->\n      <text x=\"280\" y=\"35\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">SÓNG DỌC (Longitudinal wave)</text>\n      <line x1=\"270\" y1=\"80\" x2=\"450\" y2=\"80\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr9)\"/>\n      <text x=\"455\" y=\"85\" fill=\"#64748b\" font-size=\"11\">Phương truyền</text>\n      <!-- Horizontal vibration -->\n      <line x1=\"330\" y1=\"80\" x2=\"390\" y2=\"80\" stroke=\"#fbbf24\" stroke-width=\"3\"/>\n      <circle cx=\"360\" cy=\"80\" r=\"5\" fill=\"#fbbf24\"/>\n      <text x=\"330\" y=\"105\" fill=\"#fbbf24\" font-size=\"11\">Dao động // (nén - giãn)</text>\n      <!-- Bottom summary -->\n      <rect x=\"50\" y=\"140\" width=\"400\" height=\"70\" fill=\"#1e293b\" rx=\"6\"/>\n      <text x=\"70\" y=\"165\" fill=\"#38bdf8\" font-size=\"12\">• Sóng ngang truyền trong chất rắn và bề mặt chất lỏng.</text>\n      <text x=\"70\" y=\"195\" fill=\"#34d399\" font-size=\"12\">• Sóng dọc truyền được trong cả chất rắn, chất lỏng và chất khí.</text>\n    </svg>"},{"q":"Sóng dọc là loại sóng có thể truyền được trong các môi trường nào sau đây?","opts":["Chất rắn, chất lỏng và chất khí.","Chỉ truyền trong chất rắn.","Chỉ truyền trong chất khí và chân không.","Chỉ truyền trên bề mặt chất lỏng."],"ans":"A","exp":"• Sóng dọc xuất hiện khi có lực đàn hồi chống lại sự nén - giãn thể tích, do đó sóng dọc truyền được trong cả 3 trạng thái của vật chất: Rắn, Lỏng và Khí (sóng cơ không truyền được trong chân không).","svgGraph":null},{"q":"Cường độ sóng I tại một điểm là năng lượng sóng truyền qua một đơn vị diện tích đặt vuông góc với phương truyền sóng trong một đơn vị thời gian. Đơn vị của cường độ sóng trong hệ SI là:","opts":["W/m².","J/s.","N/m.","W·m²."],"ans":"A","exp":"• <b>Công thức:</b> I = <span class=\"fraction\"><span class=\"numerator\">P</span><span class=\"denominator\">S</span></span> = <span class=\"fraction\"><span class=\"numerator\">E</span><span class=\"denominator\">S·t</span></span>.<br>• Trong đó công suất P tính bằng Oát (W), diện tích S tính bằng m², do đó cường độ sóng I có đơn vị là W/m² (Oát trên mét vuông).","svgGraph":null},{"q":"Một nguồn âm đẳng hướng phát sóng âm trong không gian. Tại điểm M cách nguồn 2 m, cường độ âm là I. Tại điểm N cách nguồn 4 m, cường độ âm là:","opts":["I/4.","I/2.","2I.","4I."],"ans":"A","exp":"• Cường độ âm của nguồn đẳng hướng: I = <span class=\"fraction\"><span class=\"numerator\">P</span><span class=\"denominator\">4πr²</span></span> ∝ <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">r²</span></span>.<br>• Khi r tăng từ 2 m lên 4 m (gấp đôi) thì r² tăng 4 lần ⇒ cường độ âm giảm 4 lần: I<sub>N</sub> = I / 4.","svgGraph":null},{"q":"Hiện tượng nào sau đây chứng tỏ sóng cơ học mang năng lượng?","opts":["Sóng biển đánh làm vỡ bờ kè đá và cuốn trôi tàu thuyền.","Nước biển có vị mặn do hoà tan nhiều muối khoáng.","Mặt hồ phẳng lặng không có gợn sóng khi trời lặng gió.","Ánh sáng mặt trời chiếu sáng bầu khí quyển."],"ans":"A","exp":"• Sóng biển làm vỡ kè đá và di chuyển tàu thuyền chứng tỏ sóng cơ mang năng lượng và sinh công cơ học tác dụng lên các vật cản.","svgGraph":null},{"q":"Một nguồn phát sóng cơ có công suất P = 12,56 W phát đều ra mọi hướng trong môi trường không hấp thụ sóng. Lấy π ≈ 3,14. Cường độ sóng tại điểm cách nguồn 1 m là:","opts":["1,0 W/m².","3,14 W/m².","0,5 W/m².","2,0 W/m²."],"ans":"A","exp":"• <b>Công thức:</b> I = <span class=\"fraction\"><span class=\"numerator\">P</span><span class=\"denominator\">4πr²</span></span><br>• <b>Thay số:</b> I = <span class=\"fraction\"><span class=\"numerator\">12,56</span><span class=\"denominator\">4 · 3,14 · 1²</span></span> = <span class=\"fraction\"><span class=\"numerator\">12,56</span><span class=\"denominator\">12,56</span></span> = 1,0 W/m².","svgGraph":null}],"10":[{"q":"Trong thí nghiệm đo tần số của sóng âm bằng dao động kí điện tử, tín hiệu âm thanh thu từ micrô được hiển thị trên màn hình dưới dạng:","opts":["Đường cong hình sin biểu diễn hiệu điện thế biến thiên theo thời gian.","Một đoạn thẳng nằm ngang song song với trục thời gian.","Một đường thẳng dốc đứng có độ dốc không đổi.","Các vạch sáng phân kì không có chu kì xác định."],"ans":"A","exp":"• Micrô chuyển đổi dao động âm (áp suất không khí) thành tín hiệu điện dao động cùng tần số.<br>• Dao động kí điện tử vẽ đồ thị hiệu điện thế u theo thời gian t dưới dạng đường cong hình sin.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr10\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Oscilloscope screen frame -->\n      <rect x=\"70\" y=\"25\" width=\"360\" height=\"190\" fill=\"#031a14\" stroke=\"#059669\" stroke-width=\"3\" rx=\"10\"/>\n      <!-- Oscilloscope grid lines -->\n      <line x1=\"70\" y1=\"120\" x2=\"430\" y2=\"120\" stroke=\"#047857\" stroke-width=\"1.5\"/>\n      <line x1=\"250\" y1=\"25\" x2=\"250\" y2=\"215\" stroke=\"#047857\" stroke-width=\"1.5\"/>\n      <line x1=\"130\" y1=\"25\" x2=\"130\" y2=\"215\" stroke=\"#065f46\" stroke-width=\"0.8\" stroke-dasharray=\"2,2\"/>\n      <line x1=\"190\" y1=\"25\" x2=\"190\" y2=\"215\" stroke=\"#065f46\" stroke-width=\"0.8\" stroke-dasharray=\"2,2\"/>\n      <line x1=\"310\" y1=\"25\" x2=\"310\" y2=\"215\" stroke=\"#065f46\" stroke-width=\"0.8\" stroke-dasharray=\"2,2\"/>\n      <line x1=\"370\" y1=\"25\" x2=\"370\" y2=\"215\" stroke=\"#065f46\" stroke-width=\"0.8\" stroke-dasharray=\"2,2\"/>\n      <!-- Sine wave trace in neon green -->\n      <path d=\"M 70,120 Q 100,50 130,120 T 190,120 T 250,120 T 310,120 T 370,120 T 430,120\" fill=\"none\" stroke=\"#10b981\" stroke-width=\"3\"/>\n      <!-- Measure 1 period T -->\n      <line x1=\"100\" y1=\"45\" x2=\"220\" y2=\"45\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"100\" cy=\"45\" r=\"3\" fill=\"#fbbf24\"/>\n      <circle cx=\"220\" cy=\"45\" r=\"3\" fill=\"#fbbf24\"/>\n      <text x=\"140\" y=\"40\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Chu kì T (n ô x TIME/DIV)</text>\n      <text x=\"85\" y=\"205\" fill=\"#34d399\" font-size=\"11\">Màn hình hiển thị dao động kí điện tử (Oscilloscope)</text>\n    </svg>"},{"q":"Trên màn hình dao động kí, núm xoay TIME/DIV đang đặt ở mức 0,5 ms/div (0,5 mili giây trên một ô chia). Một chu kì dao động của sóng âm chiếm đúng 4 ô chia ngang. Tần số của sóng âm là:","opts":["500 Hz.","250 Hz.","2000 Hz.","1000 Hz."],"ans":"A","exp":"• <b>Bước 1: Tính chu kì T:</b><br>T = (số ô) · (giá trị mỗi ô) = 4 · 0,5 ms = 2 ms = 2·10⁻³ s.<br>• <b>Bước 2: Tính tần số f:</b><br>f = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">T</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2·10⁻³</span></span> = 500 Hz.","svgGraph":null},{"q":"Dụng cụ nào sau đây có chức năng biến đổi dao động cơ học của sóng âm thành dao động điện từ có cùng tần số?","opts":["Micrô (Microphone).","Loa điện động (Speaker).","Máy phát tần số âm.","Bộ khuếch đại tín hiệu điện."],"ans":"A","exp":"• Micrô là cảm biến âm thanh biến đổi dao động áp suất cơ học của không khí thành tín hiệu hiệu điện thế xoay chiều cùng quy luật tần số để đưa vào dao động kí.","svgGraph":null},{"q":"Khi đo tần số một nốt nhạc phát ra từ cây đàn ghi-ta, dao động kí hiển thị một chu kì dài 4 ô với thang đo 0,25 ms/div. Tần số của nốt nhạc này là:","opts":["1000 Hz.","500 Hz.","250 Hz.","2000 Hz."],"ans":"A","exp":"• T = 4 · 0,25 ms = 1,0 ms = 10⁻³ s.<br>• f = 1/T = 1/10⁻³ = 1000 Hz.","svgGraph":null},{"q":"Đơn vị đo tần số Héc (Hz) tương đương với đơn vị cơ bản nào sau đây?","opts":["s⁻¹ (1/giây).","s (giây).","m/s.","rad/s."],"ans":"A","exp":"• f = 1/T nên 1 Hz = 1 s⁻¹ (số lần dao động trong một giây).","svgGraph":null},{"q":"Để quan sát được trọn vẹn 2 chu kì của một tín hiệu âm thanh có tần số f = 250 Hz trên màn hình dao động kí có bề rộng 8 ô, ta nên chọn thang đo TIME/DIV phù hợp nhất là:","opts":["1,0 ms/div.","0,1 ms/div.","10 ms/div.","0,01 ms/div."],"ans":"A","exp":"• Chu kì: T = 1/250 = 4 ms.<br>• Thời gian cho 2 chu kì: Δt = 2T = 8 ms.<br>• Màn hình có 8 ô ngang nên mỗi ô cần hiển thị: TIME/DIV = 8 ms / 8 div = 1,0 ms/div.","svgGraph":null}],"11":[{"q":"Sóng điện từ là:","opts":["Điện từ trường lan truyền trong không gian theo thời gian.","Sóng cơ học lan truyền trong môi trường chân không.","Dòng chuyển dời có hướng của các electron tự do trong dây dẫn.","Quá trình lan truyền dao động đàn hồi của môi trường chất rắn."],"ans":"A","exp":"• Theo thuyết điện từ của Maxwell, điện trường biến thiên sinh ra từ trường xoáy, từ trường biến thiên sinh ra điện trường xoáy. Quá trình tương tác này tạo thành điện từ trường lan truyền trong không gian gọi là sóng điện từ.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr11\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- EM Spectrum Bar -->\n      <rect x=\"30\" y=\"50\" width=\"440\" height=\"45\" fill=\"#1e293b\" rx=\"6\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n      <!-- Colors in spectrum -->\n      <rect x=\"30\" y=\"50\" width=\"80\" height=\"45\" fill=\"#3b82f6\" opacity=\"0.3\"/>\n      <rect x=\"110\" y=\"50\" width=\"70\" height=\"45\" fill=\"#ef4444\" opacity=\"0.3\"/>\n      <rect x=\"180\" y=\"50\" width=\"60\" height=\"45\" fill=\"#eab308\" opacity=\"0.5\"/>\n      <rect x=\"240\" y=\"50\" width=\"70\" height=\"45\" fill=\"#8b5cf6\" opacity=\"0.3\"/>\n      <rect x=\"310\" y=\"50\" width=\"80\" height=\"45\" fill=\"#06b6d4\" opacity=\"0.3\"/>\n      <rect x=\"390\" y=\"50\" width=\"80\" height=\"45\" fill=\"#10b981\" opacity=\"0.3\"/>\n      <!-- Labels -->\n      <text x=\"40\" y=\"77\" fill=\"#93c5fd\" font-size=\"11\" font-weight=\"bold\">Vô tuyến</text>\n      <text x=\"120\" y=\"77\" fill=\"#fca5a5\" font-size=\"11\" font-weight=\"bold\">Hồng ngoại</text>\n      <text x=\"188\" y=\"77\" fill=\"#fef08a\" font-size=\"11\" font-weight=\"bold\">Ánh sáng</text>\n      <text x=\"250\" y=\"77\" fill=\"#c4b5fd\" font-size=\"11\" font-weight=\"bold\">Tử ngoại</text>\n      <text x=\"335\" y=\"77\" fill=\"#67e8f9\" font-size=\"11\" font-weight=\"bold\">Tia X</text>\n      <text x=\"405\" y=\"77\" fill=\"#6ee7b7\" font-size=\"11\" font-weight=\"bold\">Tia Gamma</text>\n      <!-- Arrow: Lambda decreasing, frequency increasing -->\n      <line x1=\"40\" y1=\"130\" x2=\"460\" y2=\"130\" stroke=\"#f43f5e\" stroke-width=\"2\" marker-end=\"url(#arr11)\"/>\n      <text x=\"150\" y=\"123\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">Tần số f và năng lượng photon tăng dần →</text>\n      <line x1=\"460\" y1=\"165\" x2=\"40\" y2=\"165\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr11)\"/>\n      <text x=\"160\" y=\"183\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">← Bước sóng λ tăng dần</text>\n      <text x=\"150\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Sơ đồ thang sóng điện từ (Electromagnetic Spectrum)</text>\n    </svg>"},{"q":"Trong chân không, mọi sóng điện từ đều lan truyền với cùng một tốc độ xấp xỉ bằng:","opts":["3·10⁸ m/s.","340 m/s.","3·10⁵ m/s.","1500 m/s."],"ans":"A","exp":"• Tốc độ truyền sóng điện từ trong chân không là hằng số phổ quát: c ≈ 3·10⁸ m/s (300.000 km/s).","svgGraph":null},{"q":"Đặc điểm nào sau đây là ĐÚNG đối với sóng điện từ?","opts":["Sóng điện từ là sóng ngang, trong đó vectơ điện trường E và vectơ cảm ứng từ B luôn vuông góc với nhau và vuông góc với phương truyền sóng.","Sóng điện từ là sóng dọc và không thể lan truyền trong môi trường chân không.","Vectơ điện trường E và vectơ cảm ứng từ B luôn dao động ngược pha với nhau.","Tốc độ truyền của sóng điện từ trong các môi trường điện môi luôn lớn hơn tốc độ truyền trong chân không."],"ans":"A","exp":"• Sóng điện từ là sóng ngang: véctơ E ⊥ véctơ B ⊥ phương truyền sóng v.<br>• Tại mỗi điểm, E và B luôn biến thiên cùng pha, cùng tần số.<br>• Trong môi trường có chiết suất n > 1, tốc độ truyền sóng v = c/n < c.","svgGraph":null},{"q":"Một đài phát thanh phát sóng vô tuyến có tần số f = 100 MHz. Bước sóng của sóng phát thanh này trong không khí là:","opts":["3,0 m.","30 m.","0,3 m.","300 m."],"ans":"A","exp":"• f = 100 MHz = 100·10⁶ Hz = 10⁸ Hz.<br>• Bước sóng: λ = <span class=\"fraction\"><span class=\"numerator\">c</span><span class=\"denominator\">f</span></span> = <span class=\"fraction\"><span class=\"numerator\">3·10⁸</span><span class=\"denominator\">10⁸</span></span> = 3,0 m.","svgGraph":null},{"q":"Quang phổ ánh sáng nhìn thấy mà mắt người cảm nhận được có bước sóng trong khoảng xấp xỉ từ:","opts":["380 nm đến 760 nm.","10 nm đến 380 nm.","760 nm đến 1 mm.","1 mm đến 1 m."],"ans":"A","exp":"• Ánh sáng nhìn thấy trải dài từ màu tím (khoảng 380 nm = 0,38 μm) đến màu đỏ (khoảng 760 nm = 0,76 μm).","svgGraph":null},{"q":"Tia hồng ngoại và tia tử ngoại đều có bản chất chung là:","opts":["Sóng điện từ nhưng có bước sóng và năng lượng photon khác nhau.","Dòng các hạt mang điện chuyển động với vận tốc cao.","Sóng cơ học lan truyền trong không khí ở tần số cao.","Bức xạ nhiệt chỉ phát ra từ các vật có nhiệt độ trên 1000°C."],"ans":"A","exp":"• Cả hai đều là sóng điện từ, tuân theo các quy luật truyền thẳng, phản xạ, khúc xạ và giao thoa; điểm khác biệt là bước sóng (hồng ngoại có λ > 760 nm, tử ngoại có λ < 380 nm).","svgGraph":null}],"12":[{"q":"Hiện tượng giao thoa sóng là hiện tượng hai sóng kết hợp khi gặp nhau thì:","opts":["Có những vị trí tăng cường lẫn nhau và có những vị trí triệt tiêu lẫn nhau.","Luôn luôn tăng cường lẫn nhau tại mọi điểm trong vùng không gian gặp nhau.","Luôn luôn làm biến mất hoàn toàn dao động sóng trong toàn bộ môi trường.","Làm thay đổi tần số dao động của các phần tử môi trường nơi gặp nhau."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Hiện tượng giao thoa là hiện tượng hai hay nhiều sóng kết hợp gặp nhau, tạo nên các gợn sóng ổn định với những điểm dao động cực đại (tăng cường) và những điểm đứng yên (triệt tiêu).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Source S1 and S2 -->\n      <circle cx=\"120\" cy=\"120\" r=\"7\" fill=\"#38bdf8\"/>\n      <circle cx=\"380\" cy=\"120\" r=\"7\" fill=\"#38bdf8\"/>\n      <text x=\"110\" y=\"145\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">S₁</text>\n      <text x=\"370\" y=\"145\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">S₂</text>\n      <!-- Central maximum line (k=0) -->\n      <line x1=\"250\" y1=\"20\" x2=\"250\" y2=\"220\" stroke=\"#34d399\" stroke-width=\"2.5\"/>\n      <text x=\"255\" y=\"35\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">Cực đại k = 0</text>\n      <!-- Hyperbolas k = 1 and k = -1 (Maxima) -->\n      <path d=\"M 280,20 Q 295,120 280,220\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"290\" y=\"45\" fill=\"#38bdf8\" font-size=\"11\">k = +1</text>\n      <path d=\"M 220,20 Q 205,120 220,220\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"180\" y=\"45\" fill=\"#38bdf8\" font-size=\"11\">k = -1</text>\n      <!-- Hyperbolas Minima (Dotted) -->\n      <path d=\"M 315,20 Q 340,120 315,220\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"1.8\" stroke-dasharray=\"4,3\"/>\n      <path d=\"M 185,20 Q 160,120 185,220\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"1.8\" stroke-dasharray=\"4,3\"/>\n      <text x=\"325\" y=\"65\" fill=\"#f43f5e\" font-size=\"10\">Cực tiểu k = 0</text>\n      <text x=\"115\" y=\"65\" fill=\"#f43f5e\" font-size=\"10\">Cực tiểu k = -1</text>\n      <text x=\"140\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Giao thoa hai nguồn kết hợp cùng pha</text>\n    </svg>"},{"q":"Hai nguồn sóng được gọi là hai nguồn kết hợp khi chúng phát ra hai sóng có:","opts":["Cùng tần số và có hiệu số pha không đổi theo thời gian.","Cùng biên độ nhưng có tần số và tốc độ dao động hoàn toàn khác nhau.","Cùng phương dao động nhưng bước sóng thay đổi liên tục theo không gian.","Cùng chu kì nhưng hiệu số pha biến thiên tuần hoàn theo thời gian."],"ans":"A","exp":"• <b>Điều kiện giao thoa sóng:</b> Hai nguồn kết hợp là hai nguồn dao động cùng phương, cùng tần số (hoặc chu kì) và có hiệu số pha không đổi theo thời gian.","svgGraph":null},{"q":"Trong thí nghiệm giao thoa sóng trên mặt nước với hai nguồn kết hợp S₁ và S₂ dao động cùng pha, bước sóng là λ. Vị trí các điểm dao động với biên độ cực đại thoả mãn hiệu đường đi d₂ - d₁ bằng:","opts":["k·λ (với k = 0, ±1, ±2, ...).","(k + 0,5)·λ (với k = 0, ±1, ±2, ...).","(2k + 1)·λ (với k = 0, ±1, ±2, ...).","k·λ/2 (với k = 0, ±1, ±2, ...)."],"ans":"A","exp":"• <b>Điều kiện cực đại giao thoa:</b> Điểm dao động với biên độ cực đại khi hiệu đường đi từ hai nguồn tới điểm đó bằng một số nguyên lần bước sóng: d₂ - d₁ = k·λ (k ∈ ℤ).","svgGraph":null},{"q":"Trong thí nghiệm giao thoa sóng nước với hai nguồn cùng pha dao động với tần số f = 25 Hz. Tốc độ truyền sóng trên mặt nước là v = 50 cm/s. Khoảng cách giữa hai điểm dao động với biên độ cực đại liên tiếp trên đoạn nối hai nguồn là:","opts":["1,0 cm.","2,0 cm.","0,5 cm.","4,0 cm."],"ans":"A","exp":"• <b>Bước 1: Tính bước sóng λ:</b><br>λ = <span class=\"fraction\"><span class=\"numerator\">v</span><span class=\"denominator\">f</span></span> = <span class=\"fraction\"><span class=\"numerator\">50</span><span class=\"denominator\">25</span></span> = 2,0 cm.<br>• <b>Bước 2: Khoảng cách giữa 2 cực đại liên tiếp trên S₁S₂:</b><br>d = <span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">2</span></span> = <span class=\"fraction\"><span class=\"numerator\">2,0</span><span class=\"denominator\">2</span></span> = 1,0 cm.","svgGraph":null},{"q":"Trong thí nghiệm giao thoa khe Young, khoảng cách hai khe a = 0,5 mm, khoảng cách từ hai khe tới màn D = 1 m. Chiếu bằng ánh sáng đơn sắc có bước sóng λ = 0,6 μm. Khoảng vân i đo được trên màn là:","opts":["1,2 mm.","0,6 mm.","2,4 mm.","1,5 mm."],"ans":"A","exp":"• <b>Công thức tính khoảng vân:</b> i = <span class=\"fraction\"><span class=\"numerator\">λD</span><span class=\"denominator\">a</span></span><br>• <b>Thay số:</b> i = <span class=\"fraction\"><span class=\"numerator\">0,6·10⁻⁶ · 1</span><span class=\"denominator\">0,5·10⁻³</span></span> = 1,2·10⁻³ m = 1,2 mm.","svgGraph":null},{"q":"Trong thí nghiệm Young, trên màn quan sát người ta đo được khoảng cách giữa 5 vân sáng liên tiếp là 4,8 mm. Khoảng vân i bằng:","opts":["1,2 mm.","0,96 mm.","1,6 mm.","2,4 mm."],"ans":"A","exp":"• <b>Quy tắc đếm khoảng vân:</b> Khoảng cách giữa n vân sáng liên tiếp chứa (n - 1) khoảng vân:<br>L = (n - 1)·i ⇒ 4·i = 4,8 mm ⇒ i = <span class=\"fraction\"><span class=\"numerator\">4,8</span><span class=\"denominator\">4</span></span> = 1,2 mm.","svgGraph":null}],"13":[{"q":"Sóng dừng là hình ảnh sóng tạo thành bởi:","opts":["Sự giao thoa của sóng tới và sóng phản xạ truyền ngược chiều trên cùng một phương.","Sự tắt dần nhanh chóng của một dao động sóng khi truyền vào môi trường có ma sát lớn.","Sự lan truyền của hai sóng cơ học vuông pha có cùng bước sóng.","Một dao động không truyền đi mà đứng yên tại nguồn phát."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Sóng dừng là hiện tượng giao thoa giữa sóng tới và sóng phản xạ trên cùng một phương truyền sóng, tạo ra hệ thống các điểm luôn đứng yên gọi là nút sóng và các điểm luôn dao động với biên độ cực đại gọi là bụng sóng.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Nodes and Antinodes on horizontal string -->\n      <line x1=\"50\" y1=\"120\" x2=\"450\" y2=\"120\" stroke=\"#475569\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <!-- Loop 1 -->\n      <path d=\"M 50,120 Q 116,50 183,120 Q 250,50 316,120 Q 383,50 450,120\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <path d=\"M 50,120 Q 116,190 183,120 Q 250,190 316,120 Q 383,190 450,120\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\" stroke-dasharray=\"4,4\"/>\n      <!-- Node circles -->\n      <circle cx=\"50\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <circle cx=\"183\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <circle cx=\"316\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <circle cx=\"450\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <!-- Antinode circles -->\n      <circle cx=\"116\" cy=\"50\" r=\"4\" fill=\"#34d399\"/>\n      <circle cx=\"250\" cy=\"50\" r=\"4\" fill=\"#34d399\"/>\n      <circle cx=\"383\" cy=\"50\" r=\"4\" fill=\"#34d399\"/>\n      <!-- Labels -->\n      <text x=\"45\" y=\"145\" fill=\"#f43f5e\" font-size=\"11\">Nút</text>\n      <text x=\"178\" y=\"145\" fill=\"#f43f5e\" font-size=\"11\">Nút</text>\n      <text x=\"311\" y=\"145\" fill=\"#f43f5e\" font-size=\"11\">Nút</text>\n      <text x=\"440\" y=\"145\" fill=\"#f43f5e\" font-size=\"11\">Nút</text>\n      <text x=\"100\" y=\"38\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">Bụng</text>\n      <text x=\"235\" y=\"38\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">Bụng</text>\n      <!-- Lambda / 2 bracket -->\n      <line x1=\"50\" y1=\"195\" x2=\"183\" y2=\"195\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"50\" cy=\"195\" r=\"3\" fill=\"#fbbf24\"/>\n      <circle cx=\"183\" cy=\"195\" r=\"3\" fill=\"#fbbf24\"/>\n      <text x=\"100\" y=\"215\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">λ/2 (1 bó sóng)</text>\n      <text x=\"180\" y=\"235\" fill=\"#94a3b8\" font-size=\"12\">Sóng dừng với 3 bó sóng (k = 3)</text>\n    </svg>"},{"q":"Khi xảy ra hiện tượng phản xạ sóng cơ trên vật cản cố định, tại điểm phản xạ sóng phản xạ luôn dao động:","opts":["Ngược pha với sóng tới.","Cùng pha với sóng tới.","Vuông pha với sóng tới.","Lệch pha π/4 so với sóng tới."],"ans":"A","exp":"• <b>Quy tắc phản xạ sóng:</b> Khi phản xạ trên vật cản cố định, sóng phản xạ ngược pha với sóng tới tại điểm phản xạ. Nếu là vật cản tự do thì cùng pha.","svgGraph":null},{"q":"Điều kiện để có sóng dừng trên sợi dây đàn hồi chiều dài L có hai đầu cố định là:","opts":["L = k·λ/2 (với k = 1, 2, 3, ... là số bó sóng).","L = (2k + 1)·λ/4 (với k = 0, 1, 2, ...).","L = k·λ (với k = 1, 2, 3, ...).","L = (2k + 1)·λ/2 (với k = 0, 1, 2, ...)."],"ans":"A","exp":"• <b>Điều kiện 2 đầu cố định:</b> Chiều dài dây phải bằng một số nguyên lần nửa bước sóng: L = k·<span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">2</span></span>, trong đó k là số bó sóng, số bụng sóng = k và số nút sóng = k + 1.","svgGraph":null},{"q":"Một sợi dây đàn hồi dài L = 1,2 m hai đầu cố định đang có sóng dừng với 3 bó sóng. Bước sóng λ của sóng trên dây là:","opts":["0,8 m.","0,4 m.","1,2 m.","2,4 m."],"ans":"A","exp":"• <b>Công thức sóng dừng 2 đầu cố định:</b> L = k·<span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">2</span></span><br>• <b>Thay số với k = 3 bó sóng:</b> 1,2 = 3 · <span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">2</span></span> ⇒ λ = <span class=\"fraction\"><span class=\"numerator\">1,2 · 2</span><span class=\"denominator\">3</span></span> = 0,8 m (80 cm).","svgGraph":null},{"q":"Một sợi dây dài 90 cm có một đầu gắn vào âm thoa dao động với tần số f = 100 Hz, đầu còn lại tự do. Tốc độ truyền sóng trên dây là v = 40 m/s. Số nút sóng quan sát được trên dây là:","opts":["5 nút sóng.","4 nút sóng.","6 nút sóng.","9 nút sóng."],"ans":"A","exp":"• <b>Bước 1: Tính bước sóng λ:</b><br>λ = <span class=\"fraction\"><span class=\"numerator\">v</span><span class=\"denominator\">f</span></span> = <span class=\"fraction\"><span class=\"numerator\">40</span><span class=\"denominator\">100</span></span> = 0,4 m = 40 cm.<br>• <b>Bước 2: Tìm k từ điều kiện 1 đầu cố định 1 đầu tự do:</b><br>L = (2k + 1)·<span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">4</span></span> ⇒ 90 = (2k + 1) · <span class=\"fraction\"><span class=\"numerator\">40</span><span class=\"denominator\">4</span></span> = (2k + 1)·10 ⇒ 2k + 1 = 9 ⇒ k = 4.<br>• <b>Bước 3:</b> Số nút sóng = k + 1 = 4 + 1 = 5 nút.","svgGraph":null},{"q":"Trên một sợi dây đang có sóng dừng ổn định với bước sóng λ = 24 cm. Hai điểm M và N trên dây cùng nằm trong một bó sóng, cách nhau 4 cm. Độ lệch pha dao động giữa M và N bằng:","opts":["0 rad (cùng pha).","π rad (ngược pha).","π/2 rad (vuông pha).","π/3 rad."],"ans":"A","exp":"• Trong hiện tượng sóng dừng, mọi điểm nằm giữa hai nút liên tiếp (tức trong cùng một bó sóng) đều dao động đồng pha với nhau (độ lệch pha bằng 0).","svgGraph":null}],"14":[{"q":"Một sóng cơ truyền dọc theo trục Ox có phương trình u = 5·cos(4πt - 0,02πx) (mm), trong đó x tính bằng cm và t tính bằng giây. Tốc độ truyền sóng là:","opts":["200 cm/s.","100 cm/s.","50 cm/s.","400 cm/s."],"ans":"A","exp":"• <b>Dạng tổng quát phương trình sóng:</b> u = A·cos(ωt - <span class=\"fraction\"><span class=\"numerator\">2πx</span><span class=\"denominator\">λ</span></span>)<br>• Đồng nhất hệ số: <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">λ</span></span> = 0,02π ⇒ λ = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">0,02</span></span> = 100 cm.<br>• Tần số: f = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">2π</span></span> = <span class=\"fraction\"><span class=\"numerator\">4π</span><span class=\"denominator\">2π</span></span> = 2 Hz.<br>• Tốc độ truyền sóng: v = λ·f = 100 · 2 = 200 cm/s.","svgGraph":null},{"q":"Trong thí nghiệm giao thoa sóng nước với hai nguồn đồng bộ S₁ và S₂ cách nhau 18 cm, bước sóng λ = 3 cm. Số điểm cực đại giao thoa trên đoạn nối hai nguồn S₁S₂ là:","opts":["11 điểm.","12 điểm.","13 điểm.","9 điểm."],"ans":"A","exp":"• <b>Công thức xác định số cực đại trên đoạn S₁S₂:</b><br>-<span class=\"fraction\"><span class=\"numerator\">S₁S₂</span><span class=\"denominator\">λ</span></span> < k < +<span class=\"fraction\"><span class=\"numerator\">S₁S₂</span><span class=\"denominator\">λ</span></span><br>• Thay số: -<span class=\"fraction\"><span class=\"numerator\">18</span><span class=\"denominator\">3</span></span> < k < +<span class=\"fraction\"><span class=\"numerator\">18</span><span class=\"denominator\">3</span></span> ⇒ -6 < k < +6.<br>• Vì k nguyên nên k ∈ {-5, -4, ..., 0, ..., 4, 5} ⇒ có 2 · 5 + 1 = 11 giá trị cực đại.","svgGraph":null},{"q":"Một sóng âm truyền từ không khí vào nước. Biết tốc độ truyền âm trong không khí là 340 m/s và trong nước là 1480 m/s. Khi đi vào nước thì:","opts":["Tần số không đổi, bước sóng tăng xấp xỉ 4,35 lần.","Tần số tăng 4,35 lần, bước sóng không đổi.","Cả tần số và bước sóng đều tăng 4,35 lần.","Tần số không đổi, bước sóng giảm 4,35 lần."],"ans":"A","exp":"• <b>Bản chất:</b> Tần số f của sóng do nguồn quyết định nên không đổi khi truyền qua các môi trường.<br>• <b>Bước sóng:</b> λ = <span class=\"fraction\"><span class=\"numerator\">v</span><span class=\"denominator\">f</span></span>, vì v tăng từ 340 m/s lên 1480 m/s nên bước sóng tăng: <span class=\"fraction\"><span class=\"numerator\">1480</span><span class=\"denominator\">340</span></span> ≈ 4,35 lần.","svgGraph":null},{"q":"Trong thí nghiệm Young về giao thoa ánh sáng, nguồn phát ánh sáng có bước sóng λ = 500 nm. Khoảng cách giữa hai khe là 1 mm, khoảng cách từ mặt phẳng chứa hai khe đến màn là 2 m. Vị trí của vân sáng bậc 4 cách vân sáng trung tâm một khoảng:","opts":["4,0 mm.","2,0 mm.","5,0 mm.","1,0 mm."],"ans":"A","exp":"• <b>Khoảng vân i:</b> i = <span class=\"fraction\"><span class=\"numerator\">λD</span><span class=\"denominator\">a</span></span> = <span class=\"fraction\"><span class=\"numerator\">500·10⁻⁶ · 2</span><span class=\"denominator\">1</span></span> = 1,0 mm.<br>• <b>Vị trí vân sáng bậc 4:</b> x₄ = 4·i = 4 · 1,0 = 4,0 mm.","svgGraph":null},{"q":"Trên mặt một chất lỏng có hai nguồn kết hợp dao động cùng pha tại A và B cách nhau 10 cm, bước sóng λ = 1,6 cm. Điểm M trên mặt nước cách A 12 cm và cách B 8,8 cm. Điểm M nằm trên vân:","opts":["Cực đại giao thoa bậc 2.","Cực tiểu giao thoa thứ 2.","Cực đại giao thoa bậc 3.","Cực tiểu giao thoa thứ 3."],"ans":"A","exp":"• <b>Xét hiệu đường đi tại M:</b> d₁ - d₂ = 12 - 8,8 = 3,2 cm.<br>• <b>Tỉ số:</b> <span class=\"fraction\"><span class=\"numerator\">d₁ - d₂</span><span class=\"denominator\">λ</span></span> = <span class=\"fraction\"><span class=\"numerator\">3,2</span><span class=\"denominator\">1,6</span></span> = 2.<br>• Vì tỉ số bằng số nguyên 2 nên điểm M nằm trên vân cực đại giao thoa bậc 2.","svgGraph":null},{"q":"Một âm có mức cường độ âm L = 80 dB. Biết cường độ âm chuẩn I₀ = 10⁻¹² W/m². Cường độ âm của âm đó là:","opts":["10⁻⁴ W/m².","10⁻⁸ W/m².","10⁻⁶ W/m².","10⁻² W/m²."],"ans":"A","exp":"• <b>Công thức mức cường độ âm:</b> L(dB) = 10·lg(<span class=\"fraction\"><span class=\"numerator\">I</span><span class=\"denominator\">I₀</span></span>)<br>• Thay số: 80 = 10·lg(<span class=\"fraction\"><span class=\"numerator\">I</span><span class=\"denominator\">10⁻¹²</span></span>) ⇒ lg(<span class=\"fraction\"><span class=\"numerator\">I</span><span class=\"denominator\">10⁻¹²</span></span>) = 8 ⇒ <span class=\"fraction\"><span class=\"numerator\">I</span><span class=\"denominator\">10⁻¹²</span></span> = 10⁸ ⇒ I = 10⁻⁴ W/m².","svgGraph":null}],"15":[{"q":"Trong thí nghiệm đo tốc độ truyền âm trong không khí bằng ống cộng hưởng hình trụ có pittông di động, hiện tượng cộng hưởng âm xảy ra khi:","opts":["Âm nghe được qua miệng ống đột ngột to nhất tại các vị trí xác định của pittông.","Mọi âm thanh bị dập tắt hoàn toàn bên trong ống nghiệm.","Tần số của máy phát tự động nhảy lên gấp đôi giá trị ban đầu.","Pittông bị đẩy bật ra khỏi ống do áp suất không khí tăng đột biến."],"ans":"A","exp":"• Khi sóng âm phát từ loa tạo sóng dừng trong cột không khí bên trong ống, tại miệng ống là một bụng sóng làm cho âm thanh cộng hưởng phát ra ngoài có âm lượng lớn nhất.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr15\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Glass tube outline -->\n      <rect x=\"100\" y=\"70\" width=\"320\" height=\"70\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <!-- Speaker at open end -->\n      <polygon points=\"60,85 85,75 85,135 60,125\" fill=\"#f59e0b\"/>\n      <rect x=\"45\" y=\"95\" width=\"15\" height=\"20\" fill=\"#64748b\"/>\n      <text x=\"50\" y=\"155\" fill=\"#f59e0b\" font-size=\"11\">Nguồn âm</text>\n      <!-- Water level / Piston at L1 -->\n      <rect x=\"250\" y=\"72\" width=\"168\" height=\"66\" fill=\"#0284c7\" opacity=\"0.4\"/>\n      <line x1=\"250\" y1=\"70\" x2=\"250\" y2=\"140\" stroke=\"#f43f5e\" stroke-width=\"4\"/>\n      <text x=\"240\" y=\"60\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">Mặt nước (Nút)</text>\n      <!-- Standing sound wave inside air column -->\n      <path d=\"M 85,75 Q 165,105 250,105\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <path d=\"M 85,135 Q 165,105 250,105\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <text x=\"88\" y=\"65\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">Miệng ống (Bụng)</text>\n      <!-- Column length L1 = lambda / 4 -->\n      <line x1=\"85\" y1=\"170\" x2=\"250\" y2=\"170\" stroke=\"#fbbf24\" stroke-width=\"2\" marker-end=\"url(#arr15)\"/>\n      <text x=\"145\" y=\"190\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">L₁ ≈ λ/4</text>\n      <text x=\"130\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Thí nghiệm cột khí cộng hưởng đo tốc độ truyền âm</text>\n    </svg>"},{"q":"Trong thí nghiệm đo tốc độ truyền âm bằng ống cộng hưởng hình trụ, người ta ghi nhận hai vị trí liên tiếp của mực nước cho âm nghe to nhất là L₁ và L₂ (L₂ > L₁). Bước sóng λ của âm được tính theo công thức:","opts":["λ = 2·(L₂ - L₁).","λ = L₂ - L₁.","λ = 4·(L₂ - L₁).","λ = (L₂ - L₁)/2."],"ans":"A","exp":"• <b>Nguyên lí:</b> Khoảng cách giữa hai vị trí cộng hưởng liên tiếp của cột không khí (hai mực nước liên tiếp cho âm to nhất) bằng nửa bước sóng:<br>L₂ - L₁ = <span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">2</span></span> ⇒ λ = 2·(L₂ - L₁).","svgGraph":null},{"q":"Công thức liên hệ dùng để tính tốc độ truyền âm v từ tần số đã biết f và bước sóng xác định được λ là:","opts":["v = λ·f.","v = f/λ.","v = λ/f.","v = 2·λ·f."],"ans":"A","exp":"• Tốc độ truyền sóng bằng tích của bước sóng và tần số: v = λ·f.","svgGraph":null},{"q":"Trong thí nghiệm đo tốc độ truyền âm với nguồn âm tần số f = 680 Hz, người ta ghi nhận hai vị trí cộng hưởng liên tiếp tại L₁ = 12 cm và L₂ = 37 cm. Tốc độ truyền âm đo được là:","opts":["340 m/s.","170 m/s.","680 m/s.","320 m/s."],"ans":"A","exp":"• <b>Bước 1: Tính bước sóng λ:</b><br>λ = 2·(L₂ - L₁) = 2 · (37 - 12) = 2 · 25 = 50 cm = 0,5 m.<br>• <b>Bước 2: Tính tốc độ truyền âm v:</b><br>v = λ·f = 0,5 · 680 = 340 m/s.","svgGraph":null},{"q":"Tại sao trong thí nghiệm ống cộng hưởng, người ta không lấy ngay chiều dài cộng hưởng đầu tiên L₁ để tính λ = 4·L₁ mà phải tìm hiệu số (L₂ - L₁)?","opts":["Vì miệng ống hở có hiệu ứng mép ngoài khiến bụng sóng nhô ra ngoài miệng ống một đoạn nhỏ.","Vì đáy ống có ma sát làm sóng âm bị phản xạ chậm hơn so với lí thuyết.","Vì nước bị bay hơi làm thay đổi thể tích cột khí một cách liên tục.","Vì tần số của âm thoa bị giảm dần theo thời gian dao động."],"ans":"A","exp":"• Tại miệng hở của ống, bụng sóng không nằm chính xác ngay tại mép ống mà nhô ra ngoài một khoảng hiệu chỉnh c ≈ 0,6·r (với r là bán kính trong của ống). Phép đo hiệu số (L₂ - L₁) sẽ triệt tiêu hoàn toàn sai số điểm mép này.","svgGraph":null},{"q":"Kết quả đo tốc độ truyền âm trong không khí thu được là v = (342 ± 4) m/s. Sai số tỉ đối của phép đo là:","opts":["1,17%.","0,58%.","2,34%.","1,50%."],"ans":"A","exp":"• <b>Công thức sai số tỉ đối:</b> δ = <span class=\"fraction\"><span class=\"numerator\">Δv</span><span class=\"denominator\">v<sub>tb</sub></span></span> · 100%<br>• <b>Thay số:</b> δ = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">342</span></span> · 100% ≈ 1,17%.","svgGraph":null}],"16":[{"q":"Theo định luật Coulomb, độ lớn của lực tương tác tĩnh điện giữa hai điện tích điểm đặt trong chân không tỉ lệ thuận với:","opts":["Tích độ lớn của hai điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.","Bình phương khoảng cách giữa chúng và tỉ lệ nghịch với tích độ lớn hai điện tích.","Tổng độ lớn của hai điện tích và tỉ lệ nghịch với khoảng cách giữa chúng.","Tích độ lớn của hai điện tích và tỉ lệ nghịch với khoảng cách giữa chúng."],"ans":"A","exp":"• <b>Định luật Coulomb:</b> F = k·<span class=\"fraction\"><span class=\"numerator\">|q₁q₂|</span><span class=\"denominator\">r²</span></span> với hằng số tĩnh điện k = 9·10⁹ N·m²/C².<br>• Lực tương tác tỉ lệ thuận với tích độ lớn hai điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr16\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Distance axis -->\n      <line x1=\"80\" y1=\"120\" x2=\"420\" y2=\"120\" stroke=\"#334155\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n      <!-- Positive charge q1 -->\n      <circle cx=\"160\" cy=\"120\" r=\"18\" fill=\"#ef4444\" stroke=\"#fca5a5\" stroke-width=\"2\"/>\n      <text x=\"153\" y=\"126\" fill=\"#ffffff\" font-size=\"18\" font-weight=\"bold\">+</text>\n      <text x=\"145\" y=\"160\" fill=\"#f87171\" font-size=\"13\" font-weight=\"bold\">q₁ > 0</text>\n      <!-- Negative charge q2 -->\n      <circle cx=\"340\" cy=\"120\" r=\"18\" fill=\"#3b82f6\" stroke=\"#93c5fd\" stroke-width=\"2\"/>\n      <text x=\"335\" y=\"126\" fill=\"#ffffff\" font-size=\"20\" font-weight=\"bold\">-</text>\n      <text x=\"325\" y=\"160\" fill=\"#60a5fa\" font-size=\"13\" font-weight=\"bold\">q₂ &lt; 0</text>\n      <!-- Attractive forces F12 and F21 -->\n      <line x1=\"160\" y1=\"120\" x2=\"230\" y2=\"120\" stroke=\"#fbbf24\" stroke-width=\"3\" marker-end=\"url(#arr16)\"/>\n      <text x=\"175\" y=\"105\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">F₂₁ (hút)</text>\n      <line x1=\"340\" y1=\"120\" x2=\"270\" y2=\"120\" stroke=\"#fbbf24\" stroke-width=\"3\" marker-end=\"url(#arr16)\"/>\n      <text x=\"275\" y=\"105\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">F₁₂ (hút)</text>\n      <!-- Distance r -->\n      <line x1=\"160\" y1=\"180\" x2=\"340\" y2=\"180\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <circle cx=\"160\" cy=\"180\" r=\"3\" fill=\"#34d399\"/>\n      <circle cx=\"340\" cy=\"180\" r=\"3\" fill=\"#34d399\"/>\n      <text x=\"245\" y=\"173\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Khoảng cách r</text>\n      <text x=\"135\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Tương tác hút tĩnh điện giữa hai điện tích trái dấu</text>\n    </svg>"},{"q":"Nếu khoảng cách giữa hai điện tích điểm tăng lên gấp 3 lần thì lực tương tác Coulomb giữa chúng sẽ:","opts":["Giảm đi 9 lần.","Tăng lên 9 lần.","Giảm đi 3 lần.","Tăng lên 3 lần."],"ans":"A","exp":"• <b>Công thức Coulomb:</b> F = k·<span class=\"fraction\"><span class=\"numerator\">|q₁q₂|</span><span class=\"denominator\">r²</span></span><br>• Vì lực F tỉ lệ nghịch với r² nên khi r tăng lên 3 lần thì lực F giảm đi 3² = 9 lần.","svgGraph":null},{"q":"Hai điện tích điểm q₁ = +2·10⁻⁸ C và q₂ = -4·10⁻⁸ C đặt cách nhau 6 cm trong không khí (lấy ε = 1, hằng số k = 9·10⁹ N·m²/C²). Lực tương tác giữa chúng là lực:","opts":["Hút, có độ lớn bằng 2·10⁻³ N.","Đẩy, có độ lớn bằng 2·10⁻³ N.","Hút, có độ lớn bằng 1,2·10⁻³ N.","Đẩy, có độ lớn bằng 4·10⁻³ N."],"ans":"A","exp":"• Hai điện tích trái dấu (q₁ > 0, q₂ < 0) nên tương tác <b>hút nhau</b>.<br>• <b>Độ lớn:</b> F = 9·10⁹ · <span class=\"fraction\"><span class=\"numerator\">|2·10⁻⁸ · (-4·10⁻⁸)|</span><span class=\"denominator\">(0,06)²</span></span> = 9·10⁹ · <span class=\"fraction\"><span class=\"numerator\">8·10⁻¹⁶</span><span class=\"denominator\">3,6·10⁻³</span></span> = 2·10⁻³ N.","svgGraph":null},{"q":"Hai quả cầu kim loại nhỏ giống hệt nhau mang điện tích q₁ = +6 μC và q₂ = -2 μC cho tiếp xúc nhau rồi tách ra. Điện tích trên mỗi quả cầu sau khi tách ra là:","opts":["+2 μC.","+4 μC.","-4 μC.","+8 μC."],"ans":"A","exp":"• <b>Công thức chia đều điện tích khi tiếp xúc:</b><br>q' = <span class=\"fraction\"><span class=\"numerator\">q₁ + q₂</span><span class=\"denominator\">2</span></span> = <span class=\"fraction\"><span class=\"numerator\">+6 + (-2)</span><span class=\"denominator\">2</span></span> = <span class=\"fraction\"><span class=\"numerator\">+4</span><span class=\"denominator\">2</span></span> = +2 μC.","svgGraph":null},{"q":"Đưa một thanh thuỷ tinh nhiễm điện dương lại gần (không chạm vào) một quả cầu kim loại trung hoà điện đang đặt trên giá cách điện. Phần mặt quả cầu gần thanh thuỷ tinh nhất sẽ:","opts":["Nhiễm điện âm do hiện tượng nhiễm điện hưởng ứng.","Nhiễm điện dương do nhận các ion dương từ thanh thuỷ tinh.","Không nhiễm điện vì không có sự tiếp xúc trực tiếp.","Nhiễm điện dương trên toàn bộ bề mặt quả cầu."],"ans":"A","exp":"• Thanh thuỷ tinh dương hút các electron tự do trong kim loại dồn về phía gần nó, làm đầu gần nhiễm điện âm còn đầu xa thiếu electron nên nhiễm điện dương. Đây là hiện tượng nhiễm điện do hưởng ứng.","svgGraph":null},{"q":"Hai điện tích điểm đặt cách nhau một khoảng r trong chân không thì hút nhau một lực F = 16·10⁻⁵ N. Nếu đặt chúng trong dầu hoả có hằng số điện môi ε = 2 và giữ nguyên khoảng cách r thì lực hút giữa chúng là:","opts":["8·10⁻⁵ N.","32·10⁻⁵ N.","4·10⁻⁵ N.","16·10⁻⁵ N."],"ans":"A","exp":"• <b>Quan hệ lực trong điện môi:</b> F' = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">ε</span></span><br>• <b>Thay số:</b> F' = <span class=\"fraction\"><span class=\"numerator\">16·10⁻⁵</span><span class=\"denominator\">2</span></span> = 8·10⁻⁵ N.","svgGraph":null}],"17":[{"q":"Điện trường là:","opts":["Dạng vật chất bao quanh điện tích và truyền tương tác điện lên các điện tích khác đặt trong nó.","Môi trường chỉ xuất hiện xung quanh các dây dẫn có dòng điện chạy qua.","Không gian chân không hoàn toàn không có bất kì hạt vật chất nào tồn tại.","Trường hấp dẫn do khối lượng của các hạt mang điện sinh ra xung quanh nó."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Điện trường là một dạng vật chất đặc biệt bao quanh các điện tích, gắn liền với điện tích và truyền tương tác giữa các điện tích thông qua lực điện trường tác dụng lên điện tích đặt trong nó.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr17\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Central positive charge -->\n      <circle cx=\"250\" cy=\"120\" r=\"22\" fill=\"#ef4444\" stroke=\"#fca5a5\" stroke-width=\"2.5\"/>\n      <text x=\"242\" y=\"128\" fill=\"#ffffff\" font-size=\"24\" font-weight=\"bold\">+</text>\n      <text x=\"240\" y=\"160\" fill=\"#f87171\" font-size=\"13\" font-weight=\"bold\">Q > 0</text>\n      <!-- Electric field lines radiating outward -->\n      <line x1=\"250\" y1=\"95\" x2=\"250\" y2=\"25\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"250\" y1=\"145\" x2=\"250\" y2=\"215\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"225\" y1=\"120\" x2=\"155\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"275\" y1=\"120\" x2=\"345\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"233\" y1=\"103\" x2=\"183\" y2=\"53\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"267\" y1=\"103\" x2=\"317\" y2=\"53\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"233\" y1=\"137\" x2=\"183\" y2=\"187\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"267\" y1=\"137\" x2=\"317\" y2=\"187\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <!-- Label test point M -->\n      <circle cx=\"345\" cy=\"120\" r=\"4\" fill=\"#34d399\"/>\n      <text x=\"355\" y=\"125\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Điểm M</text>\n      <text x=\"355\" y=\"140\" fill=\"#fbbf24\" font-size=\"11\">Véctơ E hướng xa Q dương</text>\n      <text x=\"135\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Đường sức điện trường của một điện tích điểm dương</text>\n    </svg>"},{"q":"Cường độ điện trường tại một điểm là đại lượng đặc trưng cho điện trường về:","opts":["Phương diện tác dụng lực và được xác định bằng thương số F/q.","Khả năng dự trữ thế năng điện của không gian.","Tốc độ truyền dao động điện từ trong chân không.","Số lượng hạt mang điện có trong một đơn vị thể tích."],"ans":"A","exp":"• <b>Định nghĩa vectơ cường độ điện trường:</b> E = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">q</span></span>.<br>• Cường độ điện trường đặc trưng cho tác dụng lực của điện trường tại điểm khảo sát, có đơn vị là V/m hoặc N/C.","svgGraph":null},{"q":"Một điện tích thử q = +2·10⁻⁸ C đặt tại một điểm trong điện trường chịu tác dụng của lực điện có độ lớn F = 6·10⁻⁴ N. Cường độ điện trường tại điểm đó có độ lớn là:","opts":["30000 V/m.","12000 V/m.","300 V/m.","60000 V/m."],"ans":"A","exp":"• <b>Công thức cường độ điện trường:</b> E = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">q</span></span><br>• <b>Thay số:</b> E = <span class=\"fraction\"><span class=\"numerator\">6·10⁻⁴</span><span class=\"denominator\">2·10⁻⁸</span></span> = 3·10⁴ V/m = 30000 V/m.","svgGraph":null},{"q":"Cường độ điện trường do một điện tích điểm Q = +4·10⁻⁹ C gây ra tại một điểm cách nó r = 10 cm trong không khí (hằng số k = 9·10⁹ N·m²/C²) là:","opts":["3600 V/m.","360 V/m.","1800 V/m.","7200 V/m."],"ans":"A","exp":"• <b>Công thức điện trường của điện tích điểm:</b> E = k·<span class=\"fraction\"><span class=\"numerator\">|Q|</span><span class=\"denominator\">r²</span></span><br>• <b>Thay số:</b> E = 9·10⁹ · <span class=\"fraction\"><span class=\"numerator\">4·10⁻⁹</span><span class=\"denominator\">(0,1)²</span></span> = <span class=\"fraction\"><span class=\"numerator\">36</span><span class=\"denominator\">0,01</span></span> = 3600 V/m.","svgGraph":null},{"q":"Khi một electron chuyển động tự do không vận tốc ban đầu trong một điện trường đều, dưới tác dụng duy nhất của lực điện, electron sẽ chuyển động:","opts":["Nhanh dần đều ngược hướng với các đường sức điện trường.","Nhanh dần đều cùng hướng với các đường sức điện trường.","Chậm dần đều ngược hướng với các đường sức điện trường.","Thẳng đều theo hướng bất kì."],"ans":"A","exp":"• Electron mang điện tích âm (q = -e < 0) nên lực điện tác dụng lên nó F = qE ngược hướng với vectơ điện trường E.<br>• Do đó electron chuyển động nhanh dần đều ngược chiều đường sức điện.","svgGraph":null},{"q":"Cường độ điện trường do điện tích điểm Q gây ra tại điểm M cách nó một khoảng r là E. Nếu khoảng cách từ điện tích đến điểm khảo sát giảm đi 2 lần thì cường độ điện trường tại đó sẽ:","opts":["Tăng lên 4 lần.","Giảm đi 4 lần.","Tăng lên 2 lần.","Giảm đi 2 lần."],"ans":"A","exp":"• <b>Công thức:</b> E = k·<span class=\"fraction\"><span class=\"numerator\">|Q|</span><span class=\"denominator\">r²</span></span><br>• E tỉ lệ nghịch với bình phương khoảng cách r². Khi r giảm 2 lần thì r² giảm 4 lần ⇒ E tăng lên 4 lần.","svgGraph":null}],"18":[{"q":"Điện trường đều là điện trường có vectơ cường độ điện trường tại mọi điểm đều:","opts":["Cùng phương, cùng chiều và có độ lớn bằng nhau.","Có độ lớn bằng nhau nhưng phương chiều biến thiên liên tục theo không gian.","Đồng quy về một điểm cố định trong không gian.","Thay đổi độ lớn theo thời gian theo quy luật hàm sin."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Điện trường đều là điện trường mà vectơ cường độ điện trường tại mọi điểm đều có cùng phương, cùng chiều và cùng độ lớn; các đường sức điện là những đường thẳng song song cách đều nhau.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr18\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Positive top plate -->\n      <rect x=\"70\" y=\"40\" width=\"360\" height=\"15\" fill=\"#ef4444\" rx=\"3\"/>\n      <text x=\"50\" y=\"52\" fill=\"#ef4444\" font-size=\"16\" font-weight=\"bold\">+</text>\n      <text x=\"440\" y=\"52\" fill=\"#f87171\" font-size=\"12\">Bản dương (+)</text>\n      <!-- Negative bottom plate -->\n      <rect x=\"70\" y=\"185\" width=\"360\" height=\"15\" fill=\"#3b82f6\" rx=\"3\"/>\n      <text x=\"50\" y=\"197\" fill=\"#3b82f6\" font-size=\"20\" font-weight=\"bold\">-</text>\n      <text x=\"440\" y=\"197\" fill=\"#60a5fa\" font-size=\"12\">Bản âm (-)</text>\n      <!-- Uniform electric field lines going downward -->\n      <line x1=\"120\" y1=\"58\" x2=\"120\" y2=\"182\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr18)\"/>\n      <line x1=\"180\" y1=\"58\" x2=\"180\" y2=\"182\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr18)\"/>\n      <line x1=\"240\" y1=\"58\" x2=\"240\" y2=\"182\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr18)\"/>\n      <line x1=\"300\" y1=\"58\" x2=\"300\" y2=\"182\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr18)\"/>\n      <line x1=\"360\" y1=\"58\" x2=\"360\" y2=\"182\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr18)\"/>\n      <!-- Trajectory of electron moving into field -->\n      <path d=\"M 80,140 Q 180,140 260,70\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2.5\" stroke-dasharray=\"4,3\"/>\n      <circle cx=\"260\" cy=\"70\" r=\"5\" fill=\"#fbbf24\"/>\n      <text x=\"270\" y=\"70\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">Quỹ đạo hạt (Parabol)</text>\n      <text x=\"245\" y=\"115\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">E</text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Điện trường đều giữa hai bản tụ điện phẳng song song</text>\n    </svg>"},{"q":"Hệ thức liên hệ giữa hiệu điện thế U và cường độ điện trường E trong điện trường đều là:","opts":["U = E·d (với d là hình chiếu của độ dịch chuyển lên phương đường sức).","U = E / d.","E = U·d.","U = E·d²."],"ans":"A","exp":"• <b>Mối liên hệ giữa U và E:</b> E = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">d</span></span> hay U = E·d, trong đó d là khoảng cách giữa hai mặt đẳng thế đo dọc theo đường sức.","svgGraph":null},{"q":"Hai bản kim loại phẳng rộng đặt song song cách nhau d = 2 cm, được nối với nguồn điện có hiệu điện thế U = 100 V. Cường độ điện trường đều giữa hai bản có độ lớn là:","opts":["5000 V/m.","200 V/m.","50 V/m.","2500 V/m."],"ans":"A","exp":"• <b>Công thức:</b> E = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">d</span></span><br>• <b>Thay số với d = 2 cm = 0,02 m:</b> E = <span class=\"fraction\"><span class=\"numerator\">100</span><span class=\"denominator\">0,02</span></span> = 5000 V/m.","svgGraph":null},{"q":"Một quả cầu nhỏ tích điện q = +10⁻⁶ C có khối lượng m = 1 g được treo bởi một sợi dây mảnh cách điện trong điện trường đều có phương nằm ngang. Khi quả cầu cân bằng, dây treo lệch góc α = 45° so với phương thẳng đứng. Lấy g = 10 m/s². Độ lớn cường độ điện trường E là:","opts":["10⁴ V/m.","10⁵ V/m.","10³ V/m.","2·10⁴ V/m."],"ans":"A","exp":"• <b>Điều kiện cân bằng:</b> tan(α) = <span class=\"fraction\"><span class=\"numerator\">F<sub>d</sub></span><span class=\"denominator\">P</span></span> = <span class=\"fraction\"><span class=\"numerator\">qE</span><span class=\"denominator\">mg</span></span><br>• Với α = 45° ⇒ tan(45°) = 1 ⇒ qE = mg.<br>• Thay số: E = <span class=\"fraction\"><span class=\"numerator\">mg</span><span class=\"denominator\">q</span></span> = <span class=\"fraction\"><span class=\"numerator\">10⁻³ · 10</span><span class=\"denominator\">10⁻⁶</span></span> = 10⁴ V/m.","svgGraph":null},{"q":"Một điện tích q = -2 μC dịch chuyển dọc theo một đường sức của điện trường đều từ điểm M đến điểm N cách nhau 10 cm theo chiều đường sức. Biết E = 1000 V/m. Công của lực điện trường thực hiện là:","opts":["-2·10⁻⁴ J.","+2·10⁻⁴ J.","-2·10⁻² J.","+2·10⁻² J."],"ans":"A","exp":"• <b>Công thức tính công của lực điện:</b> A = q·E·d<br>• Vì đi cùng chiều đường sức nên d = +10 cm = +0,1 m.<br>• <b>Thay số:</b> A = (-2·10⁻⁶) · 1000 · 0,1 = -2·10⁻⁴ J (công cản).","svgGraph":null},{"q":"Hai điểm M và N nằm trên cùng một đường sức của điện trường đều có cường độ E = 400 V/m. Đoạn MN dài 5 cm và vectơ MN cùng chiều với đường sức điện. Hiệu điện thế U<sub>MN</sub> bằng:","opts":["20 V.","-20 V.","80 V.","2000 V."],"ans":"A","exp":"• <b>Công thức:</b> U<sub>MN</sub> = E·d<sub>MN</sub><br>• Vì cùng chiều đường sức nên d<sub>MN</sub> = +5 cm = +0,05 m.<br>• Thay số: U<sub>MN</sub> = 400 · 0,05 = 20 V.","svgGraph":null}],"19":[{"q":"Công của lực điện trường khi dịch chuyển một điện tích q từ điểm M đến điểm N trong điện trường tĩnh:","opts":["Chỉ phụ thuộc vào vị trí điểm đầu M và điểm cuối N, không phụ thuộc vào hình dạng đường đi.","Tỉ lệ thuận với chiều dài thực tế của quỹ đạo dịch chuyển giữa hai điểm.","Luôn luôn bằng không đối với mọi quỹ đạo cong bất kì trong điện trường.","Phụ thuộc chặt chẽ vào thời gian và vận tốc dịch chuyển của điện tích."],"ans":"A","exp":"• <b>Tính chất trường thế:</b> Lực điện trường là lực thế (trường tĩnh điện là trường thế). Công của lực điện trường khi làm điện tích di chuyển giữa hai điểm không phụ thuộc hình dạng đường đi mà chỉ phụ thuộc vị trí điểm đầu và điểm cuối.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Uniform electric field background lines -->\n      <line x1=\"60\" y1=\"50\" x2=\"440\" y2=\"50\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n      <line x1=\"60\" y1=\"120\" x2=\"440\" y2=\"120\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n      <line x1=\"60\" y1=\"190\" x2=\"440\" y2=\"190\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n      <!-- Start point M and End point N -->\n      <circle cx=\"120\" cy=\"120\" r=\"7\" fill=\"#ef4444\"/>\n      <text x=\"110\" y=\"145\" fill=\"#ef4444\" font-size=\"14\" font-weight=\"bold\">M</text>\n      <circle cx=\"380\" cy=\"120\" r=\"7\" fill=\"#3b82f6\"/>\n      <text x=\"385\" y=\"145\" fill=\"#3b82f6\" font-size=\"14\" font-weight=\"bold\">N</text>\n      <!-- Path 1: Straight line -->\n      <line x1=\"120\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <text x=\"230\" y=\"110\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">Đường đi (1) thẳng</text>\n      <!-- Path 2: Curved line -->\n      <path d=\"M 120,120 Q 250,30 380,120\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2.5\" stroke-dasharray=\"4,3\"/>\n      <text x=\"210\" y=\"45\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Đường đi (2) cong</text>\n      <!-- Path 3: Zigzag -->\n      <path d=\"M 120,120 L 200,190 L 300,170 L 380,120\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2.5\" stroke-dasharray=\"3,3\"/>\n      <text x=\"220\" y=\"205\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Đường đi (3) gấp khúc</text>\n      <!-- Conclusion -->\n      <text x=\"145\" y=\"228\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">A₍₁₎ = A₍₂₎ = A₍₃₎ = q·E·d</text>\n    </svg>"},{"q":"Thế năng điện W<sub>M</sub> của một điện tích q tại điểm M trong điện trường đặc trưng cho:","opts":["Khả năng sinh công của điện trường khi đặt điện tích q tại điểm M.","Tốc độ chuyển động của điện tích khi đi qua điểm M.","Nhiệt lượng toả ra khi điện tích phóng tia lửa điện.","Điện dung của vật dẫn chứa điện tích q."],"ans":"A","exp":"• <b>Định nghĩa thế năng điện:</b> Thế năng của một điện tích q tại điểm M trong điện trường đặc trưng cho khả năng sinh công của điện trường khi dịch chuyển điện tích q từ điểm M ra vô cực (hoặc về mốc thế năng quy ước): W<sub>M</sub> = A<sub>M</sub>∞.","svgGraph":null},{"q":"Mối liên hệ giữa công của lực điện trường A<sub>MN</sub> và độ giảm thế năng điện (W<sub>M</sub> - W<sub>N</sub>) là:","opts":["A<sub>MN</sub> = W<sub>M</sub> - W<sub>N</sub>.","A<sub>MN</sub> = W<sub>N</sub> - W<sub>M</sub>.","A<sub>MN</sub> = W<sub>M</sub> + W<sub>N</sub>.","A<sub>MN</sub> = (W<sub>M</sub> - W<sub>N</sub>)/2."],"ans":"A","exp":"• <b>Định lí thế năng:</b> Công của lực điện trường khi điện tích dịch chuyển từ M đến N bằng độ giảm thế năng điện của điện tích giữa hai điểm đó: A<sub>MN</sub> = W<sub>M</sub> - W<sub>N</sub>.","svgGraph":null},{"q":"Một điện tích q = +5 μC dịch chuyển từ điểm M đến điểm N trong một điện trường, lực điện thực hiện một công A<sub>MN</sub> = 2·10⁻³ J. Nếu chọn mốc thế năng tại điểm N (W<sub>N</sub> = 0) thì thế năng điện tại M là:","opts":["2·10⁻³ J.","-2·10⁻³ J.","4·10⁻³ J.","10⁻³ J."],"ans":"A","exp":"• <b>Công thức độ giảm thế năng:</b> A<sub>MN</sub> = W<sub>M</sub> - W<sub>N</sub><br>• Với W<sub>N</sub> = 0 ⇒ W<sub>M</sub> = A<sub>MN</sub> = 2·10⁻³ J.","svgGraph":null},{"q":"Một proton (điện tích q = +1,6·10⁻¹⁹ C, khối lượng m = 1,67·10⁻²⁷ kg) được tăng tốc từ trạng thái nghỉ bởi hiệu điện thế U = 1000 V. Động năng mà proton thu được sau khi tăng tốc là:","opts":["1,6·10⁻¹⁶ J.","3,2·10⁻¹⁶ J.","1,6·10⁻¹⁹ J.","8,0·10⁻¹⁷ J."],"ans":"A","exp":"• <b>Định lí động năng:</b> W<sub>đ</sub> - 0 = A = q·U<br>• <b>Thay số:</b> W<sub>đ</sub> = 1,6·10⁻¹⁹ · 1000 = 1,6·10⁻¹⁶ J (tương đương 1 keV).","svgGraph":null},{"q":"Đơn vị đo thế năng điện trong hệ SI là:","opts":["Joule (J).","Volt (V).","Coulomb (C).","Newton (N)."],"ans":"A","exp":"• Thế năng là một dạng năng lượng, do đó đơn vị chuẩn của nó trong hệ SI là Joule (J).","svgGraph":null}],"20":[{"q":"Điện thế tại một điểm M trong điện trường là đại lượng đặc trưng cho điện trường về:","opts":["Khả năng tạo ra thế năng khi đặt tại đó một điện tích q và được xác định bằng V<sub>M</sub> = W<sub>M</sub> / q.","Tác dụng lực tác dụng lên một đơn vị điện tích thử đặt tại điểm đó.","Khả năng tích luỹ điện tích của một tụ điện phẳng.","Tốc độ truyền dòng điện chạy trong dây dẫn kim loại."],"ans":"A","exp":"• <b>Định nghĩa điện thế SGK:</b> Điện thế tại điểm M đặc trưng cho điện trường về phương diện tạo ra thế năng: V<sub>M</sub> = <span class=\"fraction\"><span class=\"numerator\">W<sub>M</sub></span><span class=\"denominator\">q</span></span> = <span class=\"fraction\"><span class=\"numerator\">A<sub>M</sub>∞</span><span class=\"denominator\">q</span></span>. Đơn vị là Volt (V).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr20\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Equipotential surfaces (circles around Q+) -->\n      <circle cx=\"150\" cy=\"120\" r=\"18\" fill=\"#ef4444\"/>\n      <text x=\"143\" y=\"127\" fill=\"#ffffff\" font-size=\"20\" font-weight=\"bold\">+</text>\n      <text x=\"140\" y=\"155\" fill=\"#f87171\" font-size=\"12\">Q > 0</text>\n      <!-- Equipotential lines -->\n      <circle cx=\"150\" cy=\"120\" r=\"45\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"180\" y=\"70\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">V₁ = 30 V</text>\n      <circle cx=\"150\" cy=\"120\" r=\"75\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"215\" y=\"55\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">V₂ = 20 V</text>\n      <circle cx=\"150\" cy=\"120\" r=\"105\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"245\" y=\"40\" fill=\"#60a5fa\" font-size=\"11\" font-weight=\"bold\">V₃ = 10 V</text>\n      <!-- Electric field arrow perpendicular to equipotential -->\n      <line x1=\"150\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"2.5\" marker-end=\"url(#arr20)\"/>\n      <text x=\"320\" y=\"110\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">Vectơ E</text>\n      <text x=\"290\" y=\"145\" fill=\"#94a3b8\" font-size=\"11\">E hướng từ nơi thế cao (30V) sang nơi thế thấp (10V)</text>\n      <text x=\"130\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Mặt đẳng thế và hướng giảm của điện thế theo vectơ E</text>\n    </svg>"},{"q":"Hiệu điện thế giữa hai điểm M và N trong điện trường là:","opts":["U<sub>MN</sub> = V<sub>M</sub> - V<sub>N</sub>.","U<sub>MN</sub> = V<sub>M</sub> + V<sub>N</sub>.","U<sub>MN</sub> = V<sub>N</sub> - V<sub>M</sub>.","U<sub>MN</sub> = V<sub>M</sub> / V<sub>N</sub>."],"ans":"A","exp":"• <b>Định nghĩa hiệu điện thế:</b> Hiệu điện thế giữa hai điểm M và N là hiệu số điện thế giữa M và N: U<sub>MN</sub> = V<sub>M</sub> - V<sub>N</sub> = A<sub>MN</sub> / q.","svgGraph":null},{"q":"Khi dịch chuyển một điện tích q = +4·10⁻⁶ C từ điểm M đến điểm N trong điện trường, lực điện thực hiện một công A<sub>MN</sub> = 8·10⁻⁴ J. Hiệu điện thế U<sub>MN</sub> giữa hai điểm đó là:","opts":["200 V.","3200 V.","50 V.","400 V."],"ans":"A","exp":"• <b>Công thức hiệu điện thế:</b> U<sub>MN</sub> = <span class=\"fraction\"><span class=\"numerator\">A<sub>MN</sub></span><span class=\"denominator\">q</span></span><br>• <b>Thay số:</b> U<sub>MN</sub> = <span class=\"fraction\"><span class=\"numerator\">8·10⁻⁴</span><span class=\"denominator\">4·10⁻⁶</span></span> = 200 V.","svgGraph":null},{"q":"Điện thế tại điểm M là V<sub>M</sub> = 15 V, điện thế tại điểm N là V<sub>N</sub> = 5 V. Một điện tích q = -1,5 C dịch chuyển từ M đến N. Công của lực điện trường thực hiện là:","opts":["-15 J.","+15 J.","-30 J.","+30 J."],"ans":"A","exp":"• <b>Bước 1: Tính hiệu điện thế U<sub>MN</sub>:</b><br>U<sub>MN</sub> = V<sub>M</sub> - V<sub>N</sub> = 15 - 5 = 10 V.<br>• <b>Bước 2: Tính công của lực điện A<sub>MN</sub>:</b><br>A<sub>MN</sub> = q·U<sub>MN</sub> = (-1,5) · 10 = -15 J.","svgGraph":null},{"q":"Một đám mây dông tích điện ở độ cao 1200 m so với mặt đất có điện thế V = -6·10⁷ V. Lấy mốc điện thế mặt đất bằng 0 V. Cường độ điện trường trung bình giữa đám mây và mặt đất xấp xỉ bằng:","opts":["5·10⁴ V/m.","5·10² V/m.","7,2·10¹⁰ V/m.","2·10⁴ V/m."],"ans":"A","exp":"• <b>Hiệu điện thế:</b> U = |V<sub>đất</sub> - V<sub>m</sub>ây| = 6·10⁷ V.<br>• <b>Cường độ điện trường:</b> E = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">d</span></span> = <span class=\"fraction\"><span class=\"numerator\">6·10⁷</span><span class=\"denominator\">1200</span></span> = 50000 V/m = 5·10⁴ V/m.","svgGraph":null},{"q":"Cho hai điểm M và N trong điện trường có điện thế lần lượt là V<sub>M</sub> = 40 V và V<sub>N</sub> = -10 V. Hiệu điện thế U<sub>NM</sub> giữa hai điểm đó bằng:","opts":["-50 V.","+50 V.","+30 V.","-30 V."],"ans":"A","exp":"• <b>Công thức:</b> U<sub>NM</sub> = V<sub>N</sub> - V<sub>M</sub> = -10 - 40 = -50 V. (Chú ý thứ tự chỉ số: U<sub>NM</sub> = -U<sub>MN</sub>).","svgGraph":null}],"21":[{"q":"Tụ điện là một hệ gồm:","opts":["Hai vật dẫn đặt gần nhau và ngăn cách nhau bằng một lớp chất điện môi.","Hai vật dẫn tiếp xúc trực tiếp với nhau để truyền dẫn dòng điện liên tục.","Một vật dẫn duy nhất được bao bọc trong một khối kim loại dày.","Hai chất bán dẫn ghép nối tiếp nhau tạo nên một điốt chỉnh lưu."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Tụ điện là một hệ hai vật dẫn đặt gần nhau và ngăn cách nhau bởi một lớp cách điện (chất điện môi). Tụ điện dùng để tích và phóng điện tích.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Parallel plate capacitor -->\n      <!-- Plate 1 Left -->\n      <rect x=\"180\" y=\"40\" width=\"16\" height=\"150\" fill=\"#ef4444\" rx=\"3\"/>\n      <text x=\"183\" y=\"120\" fill=\"#ffffff\" font-size=\"14\" font-weight=\"bold\">+</text>\n      <text x=\"135\" y=\"120\" fill=\"#f87171\" font-size=\"12\" font-weight=\"bold\">+Q</text>\n      <!-- Plate 2 Right -->\n      <rect x=\"290\" y=\"40\" width=\"16\" height=\"150\" fill=\"#3b82f6\" rx=\"3\"/>\n      <text x=\"294\" y=\"120\" fill=\"#ffffff\" font-size=\"16\" font-weight=\"bold\">-</text>\n      <text x=\"315\" y=\"120\" fill=\"#60a5fa\" font-size=\"12\" font-weight=\"bold\">-Q</text>\n      <!-- Dielectric layer in between -->\n      <rect x=\"196\" y=\"42\" width=\"94\" height=\"146\" fill=\"#10b981\" opacity=\"0.25\"/>\n      <text x=\"212\" y=\"120\" fill=\"#34d399\" font-size=\"12\">Điện môi ε</text>\n      <!-- Connecting leads -->\n      <line x1=\"80\" y1=\"115\" x2=\"180\" y2=\"115\" stroke=\"#94a3b8\" stroke-width=\"3\"/>\n      <line x1=\"306\" y1=\"115\" x2=\"400\" y2=\"115\" stroke=\"#94a3b8\" stroke-width=\"3\"/>\n      <!-- Distance d bracket -->\n      <line x1=\"196\" y1=\"200\" x2=\"290\" y2=\"200\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"196\" cy=\"200\" r=\"3\" fill=\"#fbbf24\"/>\n      <circle cx=\"290\" cy=\"200\" r=\"3\" fill=\"#fbbf24\"/>\n      <text x=\"238\" y=\"218\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">d</text>\n      <text x=\"130\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Cấu tạo tụ điện phẳng: hai bản cực song song cách nhau bởi điện môi</text>\n    </svg>"},{"q":"Điện dung C của tụ điện là đại lượng đặc trưng cho:","opts":["Khả năng tích điện của tụ điện ở một hiệu điện thế nhất định, tính bằng C = Q/U.","Mức độ cản trở dòng điện một chiều của tụ điện.","Nhiệt lượng toả ra khi tụ điện phóng điện qua bóng đèn.","Độ bền cơ học của các bản cực kim loại."],"ans":"A","exp":"• <b>Định nghĩa điện dung:</b> Điện dung C của tụ điện là đại lượng đặc trưng cho khả năng tích điện của tụ ở một hiệu điện thế U: C = <span class=\"fraction\"><span class=\"numerator\">Q</span><span class=\"denominator\">U</span></span>. Đơn vị đo là Fara (F).","svgGraph":null},{"q":"Một tụ điện có điện dung C = 20 μF được nối vào hai cực của nguồn điện có hiệu điện thế U = 12 V. Điện tích tích được trên các bản tụ là:","opts":["2,4·10⁻⁴ C.","1,2·10⁻⁴ C.","4,8·10⁻⁴ C.","6,0·10⁻⁵ C."],"ans":"A","exp":"• <b>Công thức:</b> Q = C·U<br>• <b>Thay số:</b> Q = 20·10⁻⁶ · 12 = 2,4·10⁻⁴ C (240 μC).","svgGraph":null},{"q":"Trên vỏ một tụ điện có ghi nhãn: '100 μF - 50 V'. Con số 50 V cho biết:","opts":["Hiệu điện thế giới hạn (cực đại) mà tụ chịu được; nếu vượt quá tụ sẽ bị đánh thủng.","Hiệu điện thế bắt buộc phải đặt vào để tụ có thể tích điện được.","Hiệu điện thế tối thiểu để duy trì lớp cách điện bên trong tụ.","Suất điện động mà tụ điện tự phát ra khi phóng điện."],"ans":"A","exp":"• Giá trị điện áp ghi trên tụ là hiệu điện thế định mức (hoặc hiệu điện thế đánh thủng giới hạn). Đặt hiệu điện thế vượt quá giá trị này sẽ làm lớp điện môi bị đánh thủng dẫn điện gây hỏng tụ.","svgGraph":null},{"q":"Năng lượng điện trường dự trữ trong tụ điện có điện dung C = 50 μF khi được nạp điện đến hiệu điện thế U = 20 V là:","opts":["0,01 J.","0,02 J.","0,05 J.","0,1 J."],"ans":"A","exp":"• <b>Công thức năng lượng:</b> W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>·C·U²<br>• <b>Thay số:</b> W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 50·10⁻⁶ · (20)² = 25·10⁻⁶ · 400 = 0,01 J (10 mJ).","svgGraph":null},{"q":"Trong các thiết bị điện tử, tụ điện có vai trò cơ bản là:","opts":["Tích lũy năng lượng điện trường và phóng điện nhanh, lọc phẳng tín hiệu điện xoay chiều.","Biến đổi năng lượng điện thành cơ năng quay liên tục như động cơ điện.","Phát ra dòng điện một chiều vĩnh cửu như một nguồn pin hoá học.","Đo trực tiếp cường độ dòng điện chạy qua mạch nối tiếp."],"ans":"A","exp":"• Tụ điện tích trữ và phóng điện năng, lọc phẳng gợn sóng điện áp trong mạch nguồn một chiều, truyền tín hiệu xoay chiều và chặn dòng một chiều.","svgGraph":null}],"22":[{"q":"Dòng điện trong kim loại là dòng chuyển dời có hướng của các:","opts":["Electron tự do ngược chiều điện trường.","Ion dương cùng chiều điện trường.","Ion âm ngược chiều điện trường.","Hạt mang điện tích dương và hạt mang điện tích âm ngược chiều nhau."],"ans":"A","exp":"• <b>Bản chất dòng điện trong kim loại:</b> Trong kim loại, các electron hoá trị bứt ra khỏi nguyên tử thành các electron tự do. Dưới tác dụng của điện trường, các electron tự do dịch chuyển có hướng ngược chiều điện trường tạo nên dòng điện.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr22\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Cylindrical wire section -->\n      <rect x=\"80\" y=\"60\" width=\"340\" height=\"110\" fill=\"#1e293b\" stroke=\"#475569\" stroke-width=\"2\" rx=\"10\"/>\n      <!-- Electric field direction E (left to right) -->\n      <line x1=\"120\" y1=\"35\" x2=\"380\" y2=\"35\" stroke=\"#38bdf8\" stroke-width=\"2.5\" marker-end=\"url(#arr22)\"/>\n      <text x=\"235\" y=\"28\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">Điện trường E</text>\n      <!-- Conventional current direction I (left to right) -->\n      <line x1=\"120\" y1=\"195\" x2=\"380\" y2=\"195\" stroke=\"#fbbf24\" stroke-width=\"2.5\" marker-end=\"url(#arr22)\"/>\n      <text x=\"210\" y=\"215\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">Chiều dòng điện quy ước (I)</text>\n      <!-- Positive lattice ions (fixed) -->\n      <circle cx=\"150\" cy=\"90\" r=\"10\" fill=\"#ef4444\"/><text x=\"146\" y=\"94\" fill=\"#ffffff\" font-size=\"11\">+</text>\n      <circle cx=\"250\" cy=\"90\" r=\"10\" fill=\"#ef4444\"/><text x=\"246\" y=\"94\" fill=\"#ffffff\" font-size=\"11\">+</text>\n      <circle cx=\"350\" cy=\"90\" r=\"10\" fill=\"#ef4444\"/><text x=\"346\" y=\"94\" fill=\"#ffffff\" font-size=\"11\">+</text>\n      <circle cx=\"200\" cy=\"140\" r=\"10\" fill=\"#ef4444\"/><text x=\"196\" y=\"144\" fill=\"#ffffff\" font-size=\"11\">+</text>\n      <circle cx=\"300\" cy=\"140\" r=\"10\" fill=\"#ef4444\"/><text x=\"296\" y=\"144\" fill=\"#ffffff\" font-size=\"11\">+</text>\n      <!-- Free electrons drifting right to left -->\n      <circle cx=\"280\" cy=\"110\" r=\"6\" fill=\"#60a5fa\"/><text x=\"277\" y=\"113\" fill=\"#ffffff\" font-size=\"9\">-</text>\n      <line x1=\"280\" y1=\"110\" x2=\"220\" y2=\"110\" stroke=\"#60a5fa\" stroke-width=\"2\" marker-end=\"url(#arr22)\"/>\n      <text x=\"175\" y=\"114\" fill=\"#60a5fa\" font-size=\"11\">Tốc độ trôi v</text>\n      <text x=\"120\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Chuyển động trôi của electron ngược chiều điện trường</text>\n    </svg>"},{"q":"Cường độ dòng điện không đổi I chạy qua tiết diện thẳng của dây dẫn được xác định bằng công thức:","opts":["I = q / t.","I = q · t.","I = t / q.","I = q² / t."],"ans":"A","exp":"• <b>Định nghĩa cường độ dòng điện:</b> I = <span class=\"fraction\"><span class=\"numerator\">q</span><span class=\"denominator\">t</span></span>, là đại lượng đặc trưng cho tác dụng mạnh hay yếu của dòng điện, đo bằng lượng điện tích chuyển qua tiết diện thẳng của dây dẫn trong một đơn vị thời gian. Đơn vị là Ampe (A).","svgGraph":null},{"q":"Một dòng điện không đổi có cường độ I = 2 A chạy qua dây dẫn kim loại. Điện lượng chuyển qua tiết diện thẳng của dây trong thời gian 5 phút là:","opts":["600 C.","10 C.","300 C.","1200 C."],"ans":"A","exp":"• <b>Đổi đơn vị thời gian:</b> t = 5 phút = 5 · 60 = 300 s.<br>• <b>Công thức:</b> q = I·t = 2 · 300 = 600 C.","svgGraph":null},{"q":"Số electron tự do dịch chuyển qua tiết diện thẳng của dây dẫn kim loại trong 1 giây khi có dòng điện I = 1,6 A chạy qua là:","opts":["1,0·10¹⁹ hạt.","1,6·10¹⁹ hạt.","6,25·10¹⁸ hạt.","2,5·10¹⁹ hạt."],"ans":"A","exp":"• <b>Điện lượng qua dây trong 1 s:</b> q = I·t = 1,6 · 1 = 1,6 C.<br>• <b>Số hạt electron:</b> N = <span class=\"fraction\"><span class=\"numerator\">q</span><span class=\"denominator\">e</span></span> = <span class=\"fraction\"><span class=\"numerator\">1,6</span><span class=\"denominator\">1,6·10⁻¹⁹</span></span> = 1,0·10¹⁹ hạt.","svgGraph":null},{"q":"Một dây đồng tiết diện S = 1 mm² mang dòng điện I = 3,2 A. Biết mật độ electron tự do của đồng là n = 8,5·10²⁸ m⁻³. Lấy e = 1,6·10⁻¹⁹ C. Tốc độ trôi trung bình của electron trong dây đồng xấp xỉ bằng:","opts":["0,235 mm/s.","2,35 mm/s.","0,0235 mm/s.","1,25 mm/s."],"ans":"A","exp":"• <b>Công thức tốc độ trôi:</b> v = <span class=\"fraction\"><span class=\"numerator\">I</span><span class=\"denominator\">n·e·S</span></span><br>• <b>Thay số với S = 10⁻⁶ m²:</b><br>v = <span class=\"fraction\"><span class=\"numerator\">3,2</span><span class=\"denominator\">8,5·10²⁸ · 1,6·10⁻¹⁹ · 10⁻⁶</span></span> = <span class=\"fraction\"><span class=\"numerator\">3,2</span><span class=\"denominator\">13,6·10³</span></span> ≈ 2,35·10⁻⁴ m/s = 0,235 mm/s.","svgGraph":null},{"q":"Dòng điện chạy qua một dây dẫn có cường độ thay đổi theo thời gian theo phương trình q(t) = 3t² + 2t (C). Cường độ dòng điện tức thời tại thời điểm t = 2 s là:","opts":["14 A.","16 A.","12 A.","8 A."],"ans":"A","exp":"• <b>Công thức đạo hàm cường độ tức thời:</b> i(t) = q'(t) = 6t + 2.<br>• <b>Tại t = 2 s:</b> i(2) = 6 · 2 + 2 = 14 A.","svgGraph":null}],"23":[{"q":"Theo định luật Ohm đối với đoạn mạch chỉ chứa điện trở thuần R, cường độ dòng điện I chạy qua đoạn mạch:","opts":["Tỉ lệ thuận với hiệu điện thế U giữa hai đầu đoạn mạch và tỉ lệ nghịch với điện trở R.","Tỉ lệ thuận với điện trở R và tỉ lệ nghịch với hiệu điện thế U giữa hai đầu.","Tỉ lệ thuận với bình phương hiệu điện thế U giữa hai đầu đoạn mạch.","Không phụ thuộc vào hiệu điện thế U mà chỉ do bản chất vật dẫn quyết định."],"ans":"A","exp":"• <b>Định luật Ohm cho đoạn mạch:</b> I = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">R</span></span>. Cường độ dòng điện tỉ lệ thuận với hiệu điện thế giữa hai đầu điện trở và tỉ lệ nghịch với giá trị điện trở đó.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr23\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- U-I characteristic axes -->\n      <line x1=\"60\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr23)\"/>\n      <line x1=\"80\" y1=\"220\" x2=\"80\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr23)\"/>\n      <text x=\"445\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">U (V)</text>\n      <text x=\"85\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">I (A)</text>\n      <!-- Resistor 1 line (straight through origin) -->\n      <line x1=\"80\" y1=\"200\" x2=\"380\" y2=\"60\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <text x=\"390\" y=\"65\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">Vật dẫn kim loại (R = const)</text>\n      <!-- Resistor 2 curve (Non-ohmic / light bulb) -->\n      <path d=\"M 80,200 Q 200,160 380,120\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2.5\" stroke-dasharray=\"4,3\"/>\n      <text x=\"390\" y=\"125\" fill=\"#f43f5e\" font-size=\"12\">Dây tóc bóng đèn (R tăng khi nóng)</text>\n      <!-- Slope label -->\n      <text x=\"210\" y=\"115\" fill=\"#fbbf24\" font-size=\"12\">Độ dốc = 1/R</text>\n      <text x=\"130\" y=\"228\" fill=\"#94a3b8\" font-size=\"12\">Đặc tuyến Vôn - Ampe (U - I) của vật dẫn tuân theo định luật Ohm</text>\n    </svg>"},{"q":"Điện trở của một đoạn dây kim loại hình trụ đồng chất có chiều dài L, tiết diện S và điện trở suất ρ được tính theo công thức:","opts":["R = ρ · L / S.","R = ρ · S / L.","R = L · S / ρ.","R = ρ · L · S."],"ans":"A","exp":"• <b>Công thức điện trở dây dẫn:</b> R = ρ·<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">S</span></span>. Điện trở tỉ lệ thuận với chiều dài L, điện trở suất ρ và tỉ lệ nghịch với tiết diện S.","svgGraph":null},{"q":"Đặt hiệu điện thế U = 24 V vào hai đầu một điện trở R = 12 Ω. Cường độ dòng điện chạy qua điện trở là:","opts":["2 A.","0,5 A.","288 A.","12 A."],"ans":"A","exp":"• <b>Định luật Ohm:</b> I = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">R</span></span><br>• <b>Thay số:</b> I = <span class=\"fraction\"><span class=\"numerator\">24</span><span class=\"denominator\">12</span></span> = 2 A.","svgGraph":null},{"q":"Một sợi dây mayso có điện trở R = 20 Ω được cắt đều thành hai đoạn bằng nhau rồi mắc song song hai đoạn đó với nhau. Điện trở tương đương của bộ dây mới là:","opts":["5 Ω.","10 Ω.","20 Ω.","2,5 Ω."],"ans":"A","exp":"• <b>Mỗi đoạn có điện trở:</b> R' = <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">2</span></span> = <span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">2</span></span> = 10 Ω.<br>• <b>Ghép song song hai đoạn:</b> R<sub>tđ</sub> = <span class=\"fraction\"><span class=\"numerator\">R'</span><span class=\"denominator\">2</span></span> = <span class=\"fraction\"><span class=\"numerator\">10</span><span class=\"denominator\">2</span></span> = 5 Ω.","svgGraph":null},{"q":"Một dây dẫn bằng đồng có chiều dài L = 100 m và tiết diện S = 0,5 mm² = 0,5·10⁻⁶ m². Biết điện trở suất của đồng là ρ = 1,7·10⁻⁸ Ω·m. Điện trở của đoạn dây đồng này là:","opts":["3,4 Ω.","0,85 Ω.","1,7 Ω.","6,8 Ω."],"ans":"A","exp":"• <b>Công thức điện trở:</b> R = ρ·<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">S</span></span><br>• <b>Thay số:</b> R = 1,7·10⁻⁸ · <span class=\"fraction\"><span class=\"numerator\">100</span><span class=\"denominator\">0,5·10⁻⁶</span></span> = <span class=\"fraction\"><span class=\"numerator\">1,7·10⁻⁶</span><span class=\"denominator\">0,5·10⁻⁶</span></span> = 3,4 Ω.","svgGraph":null},{"q":"Quang điện trở (LDR) là linh kiện điện tử có điện trở:","opts":["Giảm mạnh khi được chiếu sáng thích hợp.","Tăng vọt khi được chiếu ánh sáng nhìn thấy.","Hoàn toàn không thay đổi khi cường độ ánh sáng thay đổi.","Biến đổi tỉ lệ nghịch với hiệu điện thế đặt vào nó."],"ans":"A","exp":"• Quang điện trở làm bằng chất bán dẫn; khi được chiếu sáng thích hợp xảy ra hiện tượng quang điện trong tạo thêm các hạt dẫn điện (electron và lỗ trống) làm độ dẫn điện tăng lên, dẫn tới điện trở của nó giảm mạnh.","svgGraph":null}],"24":[{"q":"Suất điện động E của nguồn điện là đại lượng đặc trưng cho:","opts":["Khả năng thực hiện công của các lực lạ bên trong nguồn điện để tách và dịch chuyển điện tích.","Tác dụng cản trở dòng điện của vật liệu chế tạo nguồn điện.","Nhiệt lượng toả ra khi nguồn điện bị đoản mạch.","Khả năng tích điện tĩnh trên hai cực khi nối mạch kín."],"ans":"A","exp":"• <b>Định nghĩa suất điện động:</b> E = <span class=\"fraction\"><span class=\"numerator\">A<sub>la</sub></span><span class=\"denominator\">q</span></span>, đo bằng thương số giữa công của lực lạ khi dịch chuyển một điện tích dương ngược chiều điện trường từ cực âm sang cực dương bên trong nguồn và độ lớn điện tích đó. Đơn vị là Volt (V).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr24\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Source symbol box -->\n      <rect x=\"80\" y=\"50\" width=\"340\" height=\"80\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"10\"/>\n      <!-- EMF source symbol -->\n      <line x1=\"160\" y1=\"70\" x2=\"160\" y2=\"110\" stroke=\"#ef4444\" stroke-width=\"3\"/>\n      <line x1=\"175\" y1=\"80\" x2=\"175\" y2=\"100\" stroke=\"#3b82f6\" stroke-width=\"3\"/>\n      <text x=\"150\" y=\"65\" fill=\"#ef4444\" font-size=\"14\" font-weight=\"bold\">+</text>\n      <text x=\"175\" y=\"65\" fill=\"#3b82f6\" font-size=\"16\" font-weight=\"bold\">-</text>\n      <text x=\"135\" y=\"125\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">E</text>\n      <!-- Internal resistance r -->\n      <rect x=\"230\" y=\"80\" width=\"50\" height=\"20\" fill=\"#334155\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n      <text x=\"250\" y=\"95\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">r</text>\n      <text x=\"215\" y=\"125\" fill=\"#fbbf24\" font-size=\"11\">Điện trở trong r</text>\n      <!-- External load resistor R -->\n      <rect x=\"200\" y=\"180\" width=\"100\" height=\"30\" fill=\"#0f766e\" stroke=\"#2dd4bf\" stroke-width=\"2\" rx=\"5\"/>\n      <text x=\"235\" y=\"200\" fill=\"#ffffff\" font-size=\"13\" font-weight=\"bold\">R (ngoài)</text>\n      <!-- Circuit wires -->\n      <line x1=\"80\" y1=\"90\" x2=\"40\" y2=\"90\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <line x1=\"40\" y1=\"90\" x2=\"40\" y2=\"195\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <line x1=\"40\" y1=\"195\" x2=\"200\" y2=\"195\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <line x1=\"420\" y1=\"90\" x2=\"460\" y2=\"90\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <line x1=\"460\" y1=\"90\" x2=\"460\" y2=\"195\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <line x1=\"460\" y1=\"195\" x2=\"300\" y2=\"195\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <!-- Current arrow -->\n      <line x1=\"330\" y1=\"195\" x2=\"380\" y2=\"195\" stroke=\"#f43f5e\" stroke-width=\"2\" marker-end=\"url(#arr24)\"/>\n      <text x=\"350\" y=\"185\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">I</text>\n      <text x=\"145\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Mạch điện kín gồm nguồn (E, r) và điện trở ngoài R</text>\n    </svg>"},{"q":"Theo định luật Ohm cho toàn mạch kín gồm nguồn (E, r) nối với điện trở ngoài R, cường độ dòng điện trong mạch xác định bởi:","opts":["I = E / (R + r).","I = E / (R - r).","I = (E + U) / R.","I = E · (R + r)."],"ans":"A","exp":"• <b>Định luật Ohm cho toàn mạch:</b> I = <span class=\"fraction\"><span class=\"numerator\">E</span><span class=\"denominator\">R + r</span></span>. Cường độ dòng điện tỉ lệ thuận với suất điện động của nguồn và tỉ lệ nghịch với tổng trở toàn phần của mạch.","svgGraph":null},{"q":"Một nguồn điện có suất điện động E = 12 V và điện trở trong r = 1 Ω được mắc vào điện trở ngoài R = 5 Ω thành mạch kín. Cường độ dòng điện trong mạch và hiệu điện thế hai đầu nguồn điện lần lượt là:","opts":["I = 2 A; U<sub>ngoài</sub> = 10 V.","I = 2,4 A; U<sub>ngoài</sub> = 12 V.","I = 2 A; U<sub>ngoài</sub> = 12 V.","I = 2,4 A; U<sub>ngoài</sub> = 10 V."],"ans":"A","exp":"• <b>Cường độ dòng điện:</b> I = <span class=\"fraction\"><span class=\"numerator\">E</span><span class=\"denominator\">R + r</span></span> = <span class=\"fraction\"><span class=\"numerator\">12</span><span class=\"denominator\">5 + 1</span></span> = <span class=\"fraction\"><span class=\"numerator\">12</span><span class=\"denominator\">6</span></span> = 2 A.<br>• <b>Hiệu điện thế mạch ngoài:</b> U<sub>ngoài</sub> = I·R = 2 · 5 = 10 V (hoặc U = E - I·r = 12 - 2·1 = 10 V).","svgGraph":null},{"q":"Một bộ pin gồm 4 pin giống nhau mắc nối tiếp, mỗi pin có suất điện động e = 1,5 V và điện trở trong r₀ = 0,5 Ω. Suất điện động và điện trở trong của bộ nguồn lần lượt là:","opts":["E<sub>b</sub> = 6,0 V; r<sub>b</sub> = 2,0 Ω.","E<sub>b</sub> = 6,0 V; r<sub>b</sub> = 0,5 Ω.","E<sub>b</sub> = 1,5 V; r<sub>b</sub> = 2,0 Ω.","E<sub>b</sub> = 3,0 V; r<sub>b</sub> = 1,0 Ω."],"ans":"A","exp":"• <b>Ghép nối tiếp 4 pin:</b><br>E<sub>b</sub> = 4 · e = 4 · 1,5 = 6,0 V.<br>r<sub>b</sub> = 4 · r₀ = 4 · 0,5 = 2,0 Ω.","svgGraph":null},{"q":"Một nguồn điện có suất điện động E = 6 V, điện trở trong r = 2 Ω được nối với mạch ngoài có điện trở R để tạo thành mạch kín. Biết hiệu điện thế giữa hai cực của nguồn là U = 4 V. Giá trị điện trở R là:","opts":["4 Ω.","2 Ω.","6 Ω.","8 Ω."],"ans":"A","exp":"• <b>Bước 1: Tính cường độ dòng điện trong mạch:</b><br>U = E - I·r ⇒ 4 = 6 - I · 2 ⇒ 2I = 2 ⇒ I = 1 A.<br>• <b>Bước 2: Tính điện trở ngoài R:</b><br>R = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">I</span></span> = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">1</span></span> = 4 Ω.","svgGraph":null},{"q":"Khi một nguồn điện được nối với một biến trở R, hiệu suất của nguồn điện đạt H = 80%. Tỉ số giữa điện trở mạch ngoài R và điện trở trong r của nguồn là:","opts":["4.","0,8.","5.","1,25."],"ans":"A","exp":"• <b>Công thức hiệu suất nguồn:</b> H = <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">R + r</span></span> = 0,8<br>• R = 0,8·(R + r) = 0,8R + 0,8r ⇒ 0,2R = 0,8r ⇒ <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">r</span></span> = <span class=\"fraction\"><span class=\"numerator\">0,8</span><span class=\"denominator\">0,2</span></span> = 4.","svgGraph":null}],"25":[{"q":"Theo định luật Joule – Lenz, nhiệt lượng toả ra trên một dây dẫn thuần điện trở tỉ lệ thuận với:","opts":["Bình phương cường độ dòng điện, điện trở của dây và thời gian dòng điện chạy qua.","Cường độ dòng điện, điện trở của dây và bình phương thời gian.","Bình phương điện trở của dây và cường độ dòng điện.","Hiệu điện thế giữa hai đầu và nghịch đảo của thời gian."],"ans":"A","exp":"• <b>Định luật Joule – Lenz:</b> Q = I²·R·t. Nhiệt lượng toả ra trên một vật dẫn tỉ lệ thuận với bình phương cường độ dòng điện, với điện trở của vật dẫn và thời gian dòng điện chạy qua.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr25\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Power vs Resistance R curve -->\n      <line x1=\"60\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr25)\"/>\n      <line x1=\"80\" y1=\"220\" x2=\"80\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr25)\"/>\n      <text x=\"445\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">R (Ω)</text>\n      <text x=\"85\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">P<tspan baseline-shift=\"sub\" font-size=\"70%\">ngoài</tspan> (W)</text>\n      <!-- Curve of P vs R -->\n      <path d=\"M 80,200 Q 150,50 240,60 T 420,160\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <!-- Peak power at R = r -->\n      <circle cx=\"240\" cy=\"60\" r=\"5\" fill=\"#fbbf24\"/>\n      <line x1=\"240\" y1=\"60\" x2=\"240\" y2=\"200\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <line x1=\"80\" y1=\"60\" x2=\"240\" y2=\"60\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <text x=\"225\" y=\"215\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">R = r</text>\n      <text x=\"15\" y=\"65\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">P<tspan baseline-shift=\"sub\" font-size=\"70%\">max</tspan> = E² / (4r)</text>\n      <text x=\"250\" y=\"50\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Điểm cực đại công suất</text>\n      <text x=\"130\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Đồ thị công suất mạch ngoài cực đại khi R = r</text>\n    </svg>"},{"q":"Công suất điện tiêu thụ trên một đoạn mạch bất kì có hiệu điện thế U và cường độ dòng điện I được tính bằng công thức:","opts":["P = U·I.","P = U / I.","P = U²·I.","P = U·I²."],"ans":"A","exp":"• <b>Công thức công suất điện:</b> P = A/t = (U·I·t)/t = U·I. Đơn vị đo công suất là Oát (Watt - W).","svgGraph":null},{"q":"Một bóng đèn sợi đốt ghi nhãn: '220 V - 100 W' hoạt động bình thường ở mạng điện 220 V trong thời gian 5 giờ. Điện năng bóng đèn tiêu thụ là:","opts":["0,5 kW·h (1,8·10⁶ J).","500 kW·h.","0,2 kW·h.","1,1 kW·h."],"ans":"A","exp":"• <b>Tính theo kW·h:</b> A = P·t = 0,1 kW · 5 h = 0,5 kW·h.<br>• <b>Quy đổi ra Joule:</b> A = 0,5 · 3,6·10⁶ J = 1,8·10⁶ J.","svgGraph":null},{"q":"Một nguồn điện có suất điện động E = 12 V và điện trở trong r = 2 Ω được mắc với một biến trở R. Công suất tiêu thụ lớn nhất trên biến trở R có thể đạt được là:","opts":["18 W.","36 W.","72 W.","9 W."],"ans":"A","exp":"• <b>Điều kiện công suất cực đại:</b> R = r = 2 Ω.<br>• <b>Công suất cực đại:</b> P<sub>max</sub> = <span class=\"fraction\"><span class=\"numerator\">E²</span><span class=\"denominator\">4r</span></span> = <span class=\"fraction\"><span class=\"numerator\">(12)²</span><span class=\"denominator\">4 · 2</span></span> = <span class=\"fraction\"><span class=\"numerator\">144</span><span class=\"denominator\">8</span></span> = 18 W.","svgGraph":null},{"q":"Hai bóng đèn Đ₁ (110 V - 60 W) và Đ₂ (110 V - 100 W) được mắc nối tiếp vào mạng điện 220 V. Độ sáng thực tế của hai bóng đèn so với định mức là:","opts":["Đèn 60 W sáng hơn bình thường (dễ cháy hỏng), đèn 100 W sáng yếu hơn bình thường.","Cả hai đèn đều sáng bình thường đúng công suất định mức.","Đèn 100 W sáng rực rỡ hơn đèn 60 W.","Cả hai đèn đều sáng mờ mờ như nhau."],"ans":"A","exp":"• Điện trở định mức: R = U<sub>dm</sub>²/P<sub>dm</sub> ⇒ R₁ = 110²/60 ≈ 201,7 Ω, R₂ = 110²/100 = 121 Ω.<br>• Khi mắc nối tiếp, cùng dòng điện I ⇒ U₁/U₂ = R₁/R₂ > 1 ⇒ U₁ > 110 V và U₂ < 110 V.<br>• Do đó đèn 60 W bị quá áp sáng rực dễ cháy, còn đèn 100 W non áp sáng yếu.","svgGraph":null},{"q":"Số đếm của công tơ điện trong gia đình phản ánh:","opts":["Tổng điện năng (kW·h) mà gia đình đã tiêu thụ trong chu kì tính cước.","Công suất cực đại tức thời của các đồ dùng điện tại một thời điểm.","Hiệu điện thế trung bình của lưới điện trong tháng.","Cường độ dòng điện đỉnh đi vào cầu dao tổng."],"ans":"A","exp":"• Công tơ điện là thiết bị đo điện năng tiêu thụ của gia đình. Một số đếm trên công tơ tương ứng với 1 kW·h điện năng tiêu thụ (tương đương 3,6·10⁶ J).","svgGraph":null}],"26":[{"q":"Trong bài thực hành khảo sát pin điện hoá, đồ thị biểu diễn mối quan hệ giữa hiệu điện thế U hai đầu mạch ngoài và cường độ dòng điện I có dạng:","opts":["Một đoạn thẳng có độ dốc âm cắt trục tung tại giá trị suất điện động E.","Một đường thẳng đi qua gốc toạ độ hướng lên trên.","Một đường cong parabol đi qua gốc toạ độ.","Một đường thẳng nằm ngang song song với trục hoành cường độ dòng điện."],"ans":"A","exp":"• <b>Phương trình đặc tuyến ngoài của nguồn:</b> U = E - I·r.<br>• Đồ thị U theo I là một đoạn thẳng dốc xuống có hệ số góc bằng -r, cắt trục tung (khi I = 0) tại điểm U = E.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr26\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Axes -->\n      <line x1=\"60\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr26)\"/>\n      <line x1=\"80\" y1=\"220\" x2=\"80\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr26)\"/>\n      <text x=\"445\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">I (A)</text>\n      <text x=\"85\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">U (V)</text>\n      <!-- Downward line U = E - Ir -->\n      <line x1=\"80\" y1=\"60\" x2=\"380\" y2=\"180\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <!-- Intercept on U-axis: E -->\n      <circle cx=\"80\" cy=\"60\" r=\"5\" fill=\"#ef4444\"/>\n      <text x=\"50\" y=\"65\" fill=\"#ef4444\" font-size=\"14\" font-weight=\"bold\">E</text>\n      <text x=\"95\" y=\"65\" fill=\"#ef4444\" font-size=\"11\">Điểm cắt U = E (khi I = 0)</text>\n      <!-- Experimental data points -->\n      <circle cx=\"140\" cy=\"84\" r=\"4\" fill=\"#fbbf24\"/>\n      <circle cx=\"200\" cy=\"108\" r=\"4\" fill=\"#fbbf24\"/>\n      <circle cx=\"260\" cy=\"132\" r=\"4\" fill=\"#fbbf24\"/>\n      <circle cx=\"320\" cy=\"156\" r=\"4\" fill=\"#fbbf24\"/>\n      <!-- Slope annotation -->\n      <text x=\"260\" y=\"105\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Độ dốc: -r = ΔU / ΔI</text>\n      <text x=\"130\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Đồ thị thực nghiệm U = E - Ir đo suất điện động và r</text>\n    </svg>"},{"q":"Để đo suất điện động E và điện trở trong r của pin điện hoá, sơ đồ mạch thí nghiệm cần gồm:","opts":["Pin cần đo, điện trở bảo vệ, biến trở R, vôn kế mắc song song hai cực nguồn, ampe kế mắc nối tiếp trong mạch.","Pin cần đo, ampe kế mắc song song với nguồn và vôn kế mắc nối tiếp.","Pin cần đo chỉ cần nối trực tiếp với một ampe kế duy nhất có thang đo lớn.","Pin cần đo nối tiếp với một tụ điện và một bóng đèn công suất cao."],"ans":"A","exp":"• Vôn kế có điện trở rất lớn mắc song song với hai cực của nguồn để đo hiệu điện thế U.<br>• Ampe kế có điện trở rất nhỏ mắc nối tiếp để đo dòng điện I.<br>• Biến trở R dùng để thay đổi các giá trị (I, U) ghi nhận số liệu.","svgGraph":null},{"q":"Trong quá trình đo, tại sao mạch thí nghiệm luôn phải có một điện trở bảo vệ R₀ (cỡ vài ohm) mắc nối tiếp với biến trở R?","opts":["Để khi vô tình vặn biến trở R về giá trị 0 Ω thì mạch không bị đoản mạch làm hỏng pin và ampe kế.","Để khuếch đại suất điện động của pin lên mức cao hơn dễ đọc thang đo.","Để triệt tiêu hoàn toàn sai số dụng cụ đo của ampe kế và vôn kế.","Để ngăn không cho dòng điện xoay chiều xâm nhập vào hệ thống."],"ans":"A","exp":"• Khi vặn biến trở về 0, nếu không có R₀ thì điện trở mạch ngoài bằng 0 dẫn tới dòng điện tăng vọt (đoản mạch) làm cháy pin và hỏng ampe kế. R₀ đóng vai trò hạn dòng an toàn.","svgGraph":null},{"q":"Nếu sử dụng vôn kế có điện trở R<sub>V</sub> chưa đủ lớn (R<sub>V</sub> hữu hạn) để đo hiệu điện thế hai cực của nguồn, sai số mắc phải sẽ làm cho giá trị suất điện động đo được:","opts":["Nhỏ hơn giá trị suất điện động thực tế của nguồn.","Lớn hơn giá trị suất điện động thực tế của nguồn.","Hoàn toàn không bị ảnh hưởng vì dòng qua vôn kế luôn bằng 0.","Bằng đúng hai lần suất điện động thực tế."],"ans":"A","exp":"• Khi R<sub>V</sub> hữu hạn, vôn kế nối vào nguồn vẫn có một dòng rò nhỏ I<sub>V</sub> = E / (r + R<sub>V</sub>) chạy qua nguồn, do đó số chỉ vôn kế là U<sub>V</sub> = E - I<sub>V</sub>·r < E. Vì vậy suất điện động đo được luôn nhỏ hơn giá trị thực.","svgGraph":null},{"q":"Kết quả đo suất điện động của một pin hoá học được biểu diễn dưới dạng: E = (1,50 ± 0,02) V. Sai số tỉ đối của phép đo suất điện động này là:","opts":["1,33%.","0,67%.","2,00%.","0,02%."],"ans":"A","exp":"• <b>Công thức sai số tỉ đối:</b> δ = <span class=\"fraction\"><span class=\"numerator\">ΔE</span><span class=\"denominator\">E<sub>tb</sub></span></span> · 100%<br>• <b>Thay số:</b> δ = <span class=\"fraction\"><span class=\"numerator\">0,02</span><span class=\"denominator\">1,50</span></span> · 100% ≈ 1,33%.","svgGraph":null},{"q":"Khi một pin điện hoá đã dùng lâu ngày bị 'chai pin', hiện tượng vật lí nào sau đây xảy ra bên trong pin?","opts":["Điện trở trong r của pin tăng lên đáng kể, làm hiệu điện thế cấp cho tải sụt giảm nhanh chóng.","Suất điện động của pin tăng vọt làm quá áp thiết bị tải.","Điện trở trong r của pin giảm dần về 0 khiến pin tự xả hết điện tích.","Lực lạ bên trong pin biến đổi hoàn toàn thành lực tĩnh điện Coulomb."],"ans":"A","exp":"• Khi pin bị chai do các phản ứng hoá học phụ và cạn dung dịch điện phân, điện trở trong r tăng vọt (từ dưới 1 Ω lên hàng chục hoặc hàng trăm Ω). Khi có tải tiêu thụ, sụt áp I·r bên trong pin rất lớn khiến điện áp ngoài U = E - Ir sụt mạnh không đủ cấp điện cho thiết bị.","svgGraph":null}]},"12":{"1":[{"q":"Theo mô hình động học phân tử về cấu trúc của chất, tính chất nào sau đây là đặc trưng cơ bản nhất của thể khí so với thể lỏng và thể rắn?","opts":["Các phân tử ở rất xa nhau, lực tương tác phân tử rất yếu, chuyển động hoàn toàn hỗn loạn chiếm toàn bộ thể tích bình chứa.","Các phân tử chỉ dao động nhiệt xung quanh các vị trí cân bằng cố định xác định.","Chất khí có thể tích riêng xác định nhưng hình dạng hoàn toàn phụ thuộc vào bình chứa.","Khoảng cách giữa các phân tử khí xấp xỉ bằng kích thước của chính các phân tử đó."],"ans":0,"exp":"• <b>Bản chất vật lí:</b> Ở thể khí, khoảng cách giữa các phân tử rất lớn (gấp hàng chục lần kích thước phân tử), do đó lực tương tác phân tử là rất yếu.<br>• Các phân tử khí chuyển động hỗn loạn không ngừng về mọi phía và chiếm toàn bộ dung tích của bình chứa khí.","svgGraph":"<svg viewBox=\"0 0 460 220\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <radialGradient id=\"solG\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#38bdf8\"/><stop offset=\"100%\" stop-color=\"#0284c7\"/></radialGradient>\n    <radialGradient id=\"liqG\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#34d399\"/><stop offset=\"100%\" stop-color=\"#059669\"/></radialGradient>\n    <radialGradient id=\"gasG\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#f43f5e\"/><stop offset=\"100%\" stop-color=\"#be123c\"/></radialGradient>\n    <filter id=\"glow\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\"><feGaussianBlur stdDeviation=\"3\" result=\"blur\"/><feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/></filter>\n  </defs>\n  <!-- Box Solid -->\n  <rect x=\"15\" y=\"30\" width=\"130\" height=\"150\" rx=\"10\" fill=\"rgba(2,132,199,0.12)\" stroke=\"#0284c7\" stroke-width=\"1.8\"/>\n  <text x=\"80\" y=\"200\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"700\">THỂ RẮN</text>\n  <text x=\"80\" y=\"214\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">Trật tự, dao động tại chỗ</text>\n  <!-- 16 Solid molecules orderly -->\n  <g fill=\"url(#solG)\">\n    <circle cx=\"45\" cy=\"65\" r=\"9\"/><circle cx=\"68\" cy=\"65\" r=\"9\"/><circle cx=\"91\" cy=\"65\" r=\"9\"/><circle cx=\"114\" cy=\"65\" r=\"9\"/>\n    <circle cx=\"45\" cy=\"90\" r=\"9\"/><circle cx=\"68\" cy=\"90\" r=\"9\"/><circle cx=\"91\" cy=\"90\" r=\"9\"/><circle cx=\"114\" cy=\"90\" r=\"9\"/>\n    <circle cx=\"45\" cy=\"115\" r=\"9\"/><circle cx=\"68\" cy=\"115\" r=\"9\"/><circle cx=\"91\" cy=\"115\" r=\"9\"/><circle cx=\"114\" cy=\"115\" r=\"9\"/>\n    <circle cx=\"45\" cy=\"140\" r=\"9\"/><circle cx=\"68\" cy=\"140\" r=\"9\"/><circle cx=\"91\" cy=\"140\" r=\"9\"/><circle cx=\"114\" cy=\"140\" r=\"9\"/>\n  </g>\n  <!-- Box Liquid -->\n  <rect x=\"165\" y=\"30\" width=\"130\" height=\"150\" rx=\"10\" fill=\"rgba(5,150,105,0.12)\" stroke=\"#059669\" stroke-width=\"1.8\"/>\n  <text x=\"230\" y=\"200\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"13\" font-weight=\"700\">THỂ LỎNG</text>\n  <text x=\"230\" y=\"214\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">Sát nhau, trượt tự do</text>\n  <g fill=\"url(#liqG)\">\n    <circle cx=\"190\" cy=\"100\" r=\"9\"/><circle cx=\"215\" cy=\"95\" r=\"9\"/><circle cx=\"240\" cy=\"105\" r=\"9\"/><circle cx=\"265\" cy=\"98\" r=\"9\"/>\n    <circle cx=\"195\" cy=\"125\" r=\"9\"/><circle cx=\"225\" cy=\"128\" r=\"9\"/><circle cx=\"250\" cy=\"132\" r=\"9\"/><circle cx=\"270\" cy=\"122\" r=\"9\"/>\n    <circle cx=\"185\" cy=\"155\" r=\"9\"/><circle cx=\"210\" cy=\"158\" r=\"9\"/><circle cx=\"238\" cy=\"155\" r=\"9\"/><circle cx=\"262\" cy=\"152\" r=\"9\"/>\n  </g>\n  <!-- Box Gas -->\n  <rect x=\"315\" y=\"30\" width=\"130\" height=\"150\" rx=\"10\" fill=\"rgba(190,18,60,0.12)\" stroke=\"#be123c\" stroke-width=\"1.8\"/>\n  <text x=\"380\" y=\"200\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"700\">THỂ KHÍ</text>\n  <text x=\"380\" y=\"214\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">Ở rất xa nhau, hỗn loạn</text>\n  <g fill=\"url(#gasG)\">\n    <circle cx=\"340\" cy=\"55\" r=\"8\"/><line x1=\"340\" y1=\"55\" x2=\"355\" y2=\"70\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n    <circle cx=\"415\" cy=\"70\" r=\"8\"/><line x1=\"415\" y1=\"70\" x2=\"395\" y2=\"85\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n    <circle cx=\"360\" cy=\"115\" r=\"8\"/><line x1=\"360\" y1=\"115\" x2=\"375\" y2=\"135\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n    <circle cx=\"420\" cy=\"145\" r=\"8\"/><line x1=\"420\" y1=\"145\" x2=\"400\" y2=\"135\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n    <circle cx=\"345\" cy=\"160\" r=\"8\"/><line x1=\"345\" y1=\"160\" x2=\"330\" y2=\"145\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n  </g>\n</svg>"},{"q":"Điểm khác biệt căn bản nhất về mặt cấu trúc và tính chất vật lí giữa chất rắn kết tinh và chất rắn vô định hình là:","opts":["Chất rắn kết tinh có cấu trúc mạng tinh thể và có nhiệt độ nóng chảy xác định, còn chất rắn vô định hình không có nhiệt độ nóng chảy xác định.","Chất rắn kết tinh luôn dẫn điện tốt hơn chất rắn vô định hình trong mọi điều kiện.","Chất rắn vô định hình có hình dạng hình học xác định khi bị nung nóng.","Chất rắn kết tinh có tính đẳng hướng đối với mọi tính chất vật lí."],"ans":0,"exp":"• <b>Chất rắn kết tinh:</b> Các hạt liên kết theo một trật tự tuần hoàn hình học gọi là <i>mạng tinh thể</i>, có <b>nhiệt độ nóng chảy hoàn toàn xác định</b> (ở áp suất chuẩn).<br>• <b>Chất rắn vô định hình</b> (như thủy tinh, nhựa đường): Không có cấu trúc mạng tuần hoàn, khi bị đốt nóng sẽ mềm dần rồi chuyển sang lỏng, <b>không có nhiệt độ nóng chảy xác định</b>.","svgGraph":null},{"q":"Hiện tượng nào sau đây là minh chứng thực tế rõ nét nhất cho sự thăng hoa (chuyển trực tiếp từ thể rắn sang thể khí mà không qua thể lỏng)?","opts":["Viên băng phiến (long não) đặt trong tủ quần áo có kích thước nhỏ dần sau một thời gian.","Giọt sương đọng trên lá cây tan biến khi mặt trời lên cao.","Cục nước đá tan chảy thành nước trong cốc thủy tinh.","Nước sôi trong ấm tạo thành làn khói trắng bốc lên."],"ans":0,"exp":"• <b>Thăng hoa</b> là quá trình một chất chuyển trực tiếp từ <b>thể rắn sang thể khí</b> mà không trải qua thể lỏng.<br>• Viên băng phiến (long não) hoặc đá khô (CO₂ rắn) tự biến đổi trực tiếp thành hơi lan tỏa trong không khí chính là hiện tượng thăng hoa.","svgGraph":null},{"q":"Biết khối lượng mol của nước là 18 g/mol và số Avogadro N<sub>A</sub> = 6,022 × 10²³ mol⁻¹. Số lượng phân tử nước chứa trong một cốc nước có thể tích V = 180 cm³ (biết khối lượng riêng của nước là D = 1 g/cm³) là:","opts":["6,022 × 10²⁴ phân tử","6,022 × 10²³ phân tử","1,084 × 10²⁵ phân tử","3,345 × 10²³ phân tử"],"ans":0,"exp":"• Khối lượng nước trong cốc:<div class='formula-box'><span class='math-sym'>m = D · V = 1 × 180 = 180 g</span></div>• Số mol nước:<div class='formula-box'><span class='math-sym'>n = <div class='fraction'><span class='numerator'>m</span><span class='denominator'>M</span></div> = <div class='fraction'><span class='numerator'>180</span><span class='denominator'>18</span></div> = 10 mol</span></div>• Số phân tử nước:<div class='formula-box'><span class='math-sym'>N = n · N<sub>A</sub> = 10 × 6,022 × 10²³ = 6,022 × 10²⁴ phân tử</span></div>","svgGraph":null},{"q":"Hình vẽ dưới đây biểu diễn đường đặc tuyến nhiệt độ theo thời gian khi đun nóng liên tục một khối chất rắn kết tinh từ thể rắn đến khi chuyển thể hoàn toàn. Dựa vào đồ thị, chất rắn này bắt đầu nóng chảy ở nhiệt độ nào và quá trình nóng chảy diễn ra trong khoảng thời gian bao lâu?","opts":["Nóng chảy ở 80°C, diễn ra trong 4 phút (từ phút thứ 3 đến phút thứ 7)","Nóng chảy ở 60°C, diễn ra trong 3 phút (từ phút thứ 0 đến phút thứ 3)","Nóng chảy ở 100°C, diễn ra trong 5 phút (từ phút thứ 7 đến phút thứ 12)","Nóng chảy ở 80°C, diễn ra trong 7 phút (từ phút thứ 0 đến phút thứ 7)"],"ans":0,"exp":"• Trên đồ thị, đoạn nằm ngang song song trục thời gian biểu diễn quá trình chuyển thể (nóng chảy) vì nhiệt độ được giữ không đổi dù liên tục nhận nhiệt.<br>• Đoạn nằm ngang ở giá trị nhiệt độ <span class='math-sym'>T = 80°C</span> (đây chính là nhiệt độ nóng chảy của chất).<br>• Thời điểm bắt đầu nóng chảy: phút thứ 3; kết thúc nóng chảy: phút thứ 7.<br>• Thời gian diễn ra nóng chảy: <span class='math-sym'>Δt = 7 - 3 = 4 phút</span>.","svgGraph":"<svg viewBox=\"0 0 440 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <!-- Lưới mờ -->\n            <line x1=\"50\" y1=\"60\" x2=\"400\" y2=\"60\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"120\" x2=\"400\" y2=\"120\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"180\" x2=\"400\" y2=\"180\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <line x1=\"140\" y1=\"210\" x2=\"140\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"260\" y1=\"210\" x2=\"260\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <!-- Trục tọa độ -->\n            <line x1=\"50\" y1=\"210\" x2=\"410\" y2=\"210\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"415\" y=\"215\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">t (phút)</text>\n            <text x=\"30\" y=\"25\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">T (°C)</text>\n            <text x=\"36\" y=\"225\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            \n            <!-- Giá trị trục -->\n            <text x=\"135\" y=\"230\" fill=\"#cbd5e1\" font-size=\"13\">3</text>\n            <text x=\"255\" y=\"230\" fill=\"#cbd5e1\" font-size=\"13\">7</text>\n            \n            <text x=\"20\" y=\"185\" fill=\"#cbd5e1\" font-size=\"13\">25°</text>\n            <text x=\"20\" y=\"125\" fill=\"#cbd5e1\" font-size=\"13\">80°</text>\n            <text x=\"15\" y=\"65\" fill=\"#cbd5e1\" font-size=\"13\">110°</text>\n\n            <!-- Đường đặc tuyến -->\n            <line x1=\"50\" y1=\"180\" x2=\"140\" y2=\"120\" stroke=\"#06b6d4\" stroke-width=\"3.5\" />\n            <circle cx=\"50\" cy=\"180\" r=\"4\" fill=\"#06b6d4\" />\n            <circle cx=\"140\" cy=\"120\" r=\"5\" fill=\"#f43f5e\" />\n\n            <line x1=\"140\" y1=\"120\" x2=\"260\" y2=\"120\" stroke=\"#f43f5e\" stroke-width=\"4\" />\n            <circle cx=\"260\" cy=\"120\" r=\"5\" fill=\"#f43f5e\" />\n\n            <line x1=\"260\" y1=\"120\" x2=\"360\" y2=\"60\" stroke=\"#10b981\" stroke-width=\"3.5\" />\n            <circle cx=\"360\" cy=\"60\" r=\"4\" fill=\"#10b981\" />\n\n            <!-- Nhãn vùng -->\n            <text x=\"65\" y=\"145\" fill=\"#06b6d4\" font-size=\"13\" font-weight=\"700\">Rắn</text>\n            <text x=\"175\" y=\"110\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"800\">Nóng chảy</text>\n            <text x=\"300\" y=\"85\" fill=\"#10b981\" font-size=\"13\" font-weight=\"700\">Lỏng</text>\n          </svg>"},{"q":"Công nghệ sấy thăng hoa (Freeze Drying) hiện đại ứng dụng trong bảo quản thực phẩm cao cấp và dược phẩm dựa trên nguyên lí vật lí nào?","opts":["Làm đông lạnh thực phẩm ở nhiệt độ rất thấp, sau đó giảm mạnh áp suất môi trường xuống dưới điểm ba thể để nước đá thăng hoa trực tiếp thành hơi.","Đun nóng nhanh thực phẩm lên nhiệt độ trên 100°C ở áp suất cực cao để nước sôi tức thì.","Dùng lực ly tâm cực đại để vắt kiệt toàn bộ các phân tử nước tự do ra khỏi tế bào sinh học.","Ngâm thực phẩm vào dung dịch muối đậm đặc để rút nước qua màng bán thấm."],"ans":0,"exp":"• <b>Sấy thăng hoa:</b> Thực phẩm trước hết được cấp đông sâu để nước đóng băng hoàn toàn. Sau đó đặt vào buồng chân không áp suất cực thấp.<br>• Ở áp suất chân không thấp hơn áp suất điểm ba trạng thái của nước (<span class='math-sym'>p < 611 Pa</span>), băng đá sẽ <b>thăng hoa trực tiếp thành hơi nước</b> mà không chảy lỏng, giữ nguyên vẹn 100% hình dạng, màu sắc và vitamin của thực phẩm.","svgGraph":null}],"2":[{"q":"Trong nhiệt động lực học, nội năng (U) của một vật thể được định nghĩa chuẩn xác là:","opts":["Tổng động năng chuyển động nhiệt hỗn loạn của các phân tử cấu tạo nên vật và thế năng tương tác giữa chúng.","Tổng động năng chuyển động có hướng của toàn bộ vật thể so với mặt đất.","Thế năng trọng trường của vật thể đặt ở một độ cao xác định so với mốc thế năng.","Năng lượng bức xạ điện từ mà vật thể liên tục phát ra ngoài môi trường xung quanh."],"ans":0,"exp":"• <b>Định nghĩa SGK Vật Lí 12:</b> Nội năng của một vật là tổng động năng của các phân tử cấu tạo nên vật (do chuyển động nhiệt) và thế năng tương tác giữa chúng.<br>• Ký hiệu là <span class='math-sym'>U</span>, đơn vị trong hệ SI là Jun (J). Nội năng phụ thuộc vào nhiệt độ <span class='math-sym'>T</span> và thể tích <span class='math-sym'>V</span> của vật: <span class='math-sym'>U = f(T, V)</span>.","svgGraph":null},{"q":"Điểm khác biệt bản chất nhất giữa hai quá trình làm biến đổi nội năng: 'Thực hiện công' và 'Truyền nhiệt' là gì?","opts":["Thực hiện công có sự chuyển hoá năng lượng từ dạng khác (cơ năng, điện năng...) thành nội năng; còn truyền nhiệt là sự truyền trực tiếp nội năng mà không có sự chuyển hoá dạng năng lượng.","Thực hiện công luôn làm nội năng tăng, còn truyền nhiệt luôn làm nội năng giảm.","Truyền nhiệt chỉ xảy ra khi có sự tiếp xúc trực tiếp giữa các vật rắn.","Thực hiện công chỉ xảy ra đối với các khối chất khí trong xilanh kín."],"ans":0,"exp":"• <b>Bản chất năng lượng:</b><br>- <i>Thực hiện công:</i> Có sự chuyển hoá giữa các dạng năng lượng khác (ví dụ cơ năng cọ xát thành nội năng làm vật nóng lên).<br>- <i>Truyền nhiệt:</i> Không có sự chuyển hoá dạng năng lượng, chỉ là sự trao đổi chuyển giao nội năng từ vật có nhiệt độ cao sang vật có nhiệt độ thấp hơn.","svgGraph":null},{"q":"Người ta truyền cho một khối khí trong xilanh nhiệt lượng Q = 250 J. Khối khí nở ra thực hiện công A' = 150 J đẩy pittong đi lên. Độ biến thiên nội năng ΔU của khối khí là:","opts":["ΔU = +100 J","ΔU = +400 J","ΔU = -100 J","ΔU = -400 J"],"ans":0,"exp":"• Theo quy ước dấu:<br>- Khí nhận nhiệt lượng: <span class='math-sym'>Q = +250 J</span>.<br>- Khí thực hiện công <span class='math-sym'>A' = 150 J</span> nên công hệ nhận vào mang dấu âm: <span class='math-sym'>A = -150 J</span>.<br>• Độ biến thiên nội năng:<div class='formula-box'><span class='math-sym'>ΔU = A + Q = -150 + 250 = +100 J</span></div>Nội năng của khối khí tăng thêm 100 J.","svgGraph":null},{"q":"Một khối khí bị nén trong xilanh bởi một lực ngoài thực hiện công A = 180 J lên khối khí. Biết trong quá trình nén, khối khí đã tỏa ra môi trường xung quanh một nhiệt lượng 60 J. Nội năng của khối khí biến đổi như thế nào?","opts":["Tăng thêm 120 J","Giảm đi 120 J","Tăng thêm 240 J","Giảm đi 240 J"],"ans":0,"exp":"• Theo quy ước dấu:<br>- Khí nhận công: <span class='math-sym'>A = +180 J</span>.<br>- Khí tỏa nhiệt ra môi trường: <span class='math-sym'>Q = -60 J</span>.<br>• Độ biến thiên nội năng:<div class='formula-box'><span class='math-sym'>ΔU = A + Q = 180 + (-60) = +120 J</span></div>Vì <span class='math-sym'>ΔU > 0</span> nên nội năng của khối khí <b>tăng thêm 120 J</b>.","svgGraph":null},{"q":"Hình vẽ dưới đây là đồ thị biểu diễn quá trình dãn nở đẳng áp của một khối khí lí tưởng từ trạng thái (1) có thể tích V₁ = 2 lít đến trạng thái (2) có thể tích V₂ = 6 lít ở áp suất không đổi p = 2 × 10⁵ Pa. Công do khối khí này sinh ra trong quá trình dãn nở có độ lớn bằng:","opts":["800 J","1200 J","400 J","1600 J"],"ans":0,"exp":"• Trong quá trình đẳng áp (<span class='math-sym'>p = const</span>), độ lớn của công do khối khí sinh ra bằng diện tích hình chữ nhật bên dưới đường đồ thị trong hệ tọa độ <span class='math-sym'>p - V</span>:<div class='formula-box'><span class='math-sym'>A' = p · ΔV = p · (V₂ - V₁)</span></div>• Đổi đơn vị: <span class='math-sym'>V₁ = 2 lít = 2 × 10⁻³ m³; V₂ = 6 lít = 6 × 10⁻³ m³ ⟹ ΔV = 4 × 10⁻³ m³</span>.<br>• Tính công:<div class='formula-box'><span class='math-sym'>A' = 2 × 10⁵ × 4 × 10⁻³ = 800 J</span></div>","svgGraph":"<svg viewBox=\"0 0 440 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <!-- Lưới nền -->\n            <line x1=\"60\" y1=\"90\" x2=\"380\" y2=\"90\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"140\" y1=\"210\" x2=\"140\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"320\" y1=\"210\" x2=\"320\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <!-- Vùng diện tích công gạch sọc/màu -->\n            <rect x=\"140\" y=\"90\" width=\"180\" height=\"120\" fill=\"rgba(6, 182, 212, 0.15)\" stroke=\"rgba(6, 182, 212, 0.4)\" stroke-dasharray=\"3\"/>\n            <text x=\"205\" y=\"155\" fill=\"#38bdf8\" font-size=\"16\" font-weight=\"800\">Diện tích = A</text>\n\n            <!-- Trục tọa độ -->\n            <line x1=\"60\" y1=\"210\" x2=\"400\" y2=\"210\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"60\" y1=\"210\" x2=\"60\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"405\" y=\"215\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">V (lít)</text>\n            <text x=\"25\" y=\"25\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">p (10⁵ Pa)</text>\n            <text x=\"46\" y=\"225\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            \n            <!-- Giá trị trục -->\n            <text x=\"135\" y=\"230\" fill=\"#cbd5e1\" font-size=\"13\">2</text>\n            <text x=\"315\" y=\"230\" fill=\"#cbd5e1\" font-size=\"13\">6</text>\n            <text x=\"36\" y=\"95\" fill=\"#cbd5e1\" font-size=\"13\">2</text>\n\n            <!-- Đường quá trình 1 -> 2 -->\n            <line x1=\"140\" y1=\"90\" x2=\"320\" y2=\"90\" stroke=\"#f43f5e\" stroke-width=\"4\" marker-mid=\"url(#arrow)\" />\n            <circle cx=\"140\" cy=\"90\" r=\"5\" fill=\"#06b6d4\" />\n            <circle cx=\"320\" cy=\"90\" r=\"5\" fill=\"#f43f5e\" />\n            \n            <text x=\"130\" y=\"75\" fill=\"#06b6d4\" font-size=\"15\" font-weight=\"800\">(1)</text>\n            <text x=\"325\" y=\"75\" fill=\"#f43f5e\" font-size=\"15\" font-weight=\"800\">(2)</text>\n          </svg>"},{"q":"Một động cơ nhiệt hoạt động tuần hoàn nhận từ nguồn nóng nhiệt lượng Q₁ = 1000 J trong mỗi chu trình và truyền cho nguồn lạnh nhiệt lượng Q₂ = 650 J. Hiệu suất nhiệt của động cơ này là:","opts":["35%","65%","53,8%","70%"],"ans":0,"exp":"• Công có ích động cơ sinh ra trong một chu trình:<div class='formula-box'><span class='math-sym'>A = Q₁ - Q₂ = 1000 - 650 = 350 J</span></div>• Hiệu suất của động cơ nhiệt:<div class='formula-box'><span class='math-sym'>H = <div class='fraction'><span class='numerator'>A</span><span class='denominator'>Q₁</span></div> = <div class='fraction'><span class='numerator'>350</span><span class='denominator'>1000</span></div> = 0,35 = 35%</span></div>","svgGraph":null}],"3":[{"q":"Theo quan điểm của thuyết động học phân tử, nhiệt độ là đại lượng vật lí đặc trưng cho:","opts":["Động năng tịnh tiến trung bình của các phân tử cấu tạo nên vật thể.","Tổng thế năng tương tác giữa tất cả các phân tử trong vật.","Vận tốc chuyển động có hướng của khối tâm vật thể.","Mật độ hạt phân tử phân bố trên một đơn vị thể tích của chất."],"ans":0,"exp":"• <b>Bản chất vi mô:</b> Nhiệt độ không phản ánh vận tốc của từng phân tử riêng lẻ mà là thước đo <b>động năng tịnh tiến trung bình</b> của tập hợp vô số phân tử cấu tạo nên vật: <span class='math-sym'>E<sub>đ</sub> = (<span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span>) · k · T</span>.<br>• Vật có nhiệt độ càng cao thì các phân tử chuyển động nhiệt hỗn loạn càng nhanh.","svgGraph":null},{"q":"Khái niệm 'Độ không tuyệt đối' (0 K trong thang nhiệt độ Kelvin) có ý nghĩa vật lí cơ bản là:","opts":["Nhiệt độ thấp nhất theo lí thuyết mà tại đó động năng chuyển động nhiệt của các phân tử triệt tiêu về mức cực tiểu.","Nhiệt độ tại đó nước tinh khiết bắt đầu đóng băng ở áp suất chuẩn 1 atm.","Nhiệt độ thấp nhất từng được ghi nhận trong khí quyển bề mặt Trái Đất.","Nhiệt độ mà tại đó tất cả các chất lỏng đều bắt đầu sôi mãnh liệt."],"ans":0,"exp":"• <b>Độ không tuyệt đối (0 K hay -273,15°C):</b> Là nhiệt độ thấp nhất có thể có về mặt nhiệt động lực học.<br>• Ở nhiệt độ này, chuyển động nhiệt hỗn loạn của các phân tử giảm về mức thấp nhất (triệt tiêu theo cơ học cổ điển, dừng ở trạng thái năng lượng điểm không theo cơ học lượng tử).","svgGraph":null},{"q":"Thân nhiệt bình thường của người khỏe mạnh là 37,0°C. Giá trị nhiệt độ này tương ứng trong thang nhiệt độ Kelvin (T) và thang Fahrenheit (t<sub>F</sub>) lần lượt là:","opts":["T = 310,15 K và t<sub>F</sub> = 98,6°F","T = 300,15 K và t<sub>F</sub> = 98,6°F","T = 310,15 K và t<sub>F</sub> = 104,2°F","T = 236,15 K và t<sub>F</sub> = 66,6°F"],"ans":0,"exp":"• Đổi sang Kelvin:<div class='formula-box'><span class='math-sym'>T = t + 273,15 = 37 + 273,15 = 310,15 K</span></div>• Đổi sang Fahrenheit:<div class='formula-box'><span class='math-sym'>t<sub>F</sub> = 1,8 · t + 32 = 1,8 × 37 + 32 = 66,6 + 32 = 98,6°F</span></div>","svgGraph":null},{"q":"Tại giá trị nhiệt độ nào thì số chỉ trên thang nhiệt độ Celsius (t) và thang nhiệt độ Fahrenheit (t<sub>F</sub>) có cùng một giá trị bằng số?","opts":["-40°","0°","-20°","40°"],"ans":0,"exp":"• Ta có công thức liên hệ: <span class='math-sym'>t<sub>F</sub> = 1,8 · t + 32</span>.<br>• Đặt <span class='math-sym'>t<sub>F</sub> = t = x</span>, ta có phương trình:<div class='formula-box'><span class='math-sym'>x = 1,8 · x + 32 ⟺ 0,8 · x = -32 ⟺ x = -40</span></div>Như vậy, tại <b>-40°C = -40°F</b>, hai thang đo cho cùng một giá trị số chỉ.","svgGraph":null},{"q":"Một học sinh tự chế tạo một nhiệt kế chất lỏng chưa chia độ. Khi nhúng vào nước đá đang tan (0°C), chiều cao cột chất lỏng là h₀ = 40 mm. Khi nhúng vào hơi nước sôi (100°C), chiều cao cột chất lỏng là h₁₀₀ = 240 mm (xem đồ thị bên dưới). Khi dùng nhiệt kế này đo nhiệt độ phòng thì thấy chiều cao cột chất lỏng là h = 88 mm. Nhiệt độ phòng đo được là:","opts":["24°C","22°C","20°C","28°C"],"ans":0,"exp":"• Giả thiết chiều cao cột chất lỏng phụ thuộc bậc nhất (tuyến tính) vào nhiệt độ:<br><div class='formula-box'><span class='math-sym'>h(t) = h₀ + <div class='fraction'><span class='numerator'>h₁₀₀ - h₀</span><span class='denominator'>100</span></div> · t</span></div>• Độ tăng chiều cao cho mỗi 1°C:<div class='formula-box'><span class='math-sym'>k = <div class='fraction'><span class='numerator'>240 - 40</span><span class='denominator'>100</span></div> = <div class='fraction'><span class='numerator'>200</span><span class='denominator'>100</span></div> = 2 mm/°C</span></div>• Với <span class='math-sym'>h = 88 mm</span>:<div class='formula-box'><span class='math-sym'>t = <div class='fraction'><span class='numerator'>h - h₀</span><span class='denominator'>k</span></div> = <div class='fraction'><span class='numerator'>88 - 40</span><span class='denominator'>2</span></div> = <div class='fraction'><span class='numerator'>48</span><span class='denominator'>2</span></div> = 24°C</span></div>","svgGraph":"<svg viewBox=\"0 0 440 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <!-- Lưới mờ -->\n            <line x1=\"50\" y1=\"180\" x2=\"380\" y2=\"180\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"60\" x2=\"380\" y2=\"60\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"330\" y1=\"210\" x2=\"330\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <!-- Trục tọa độ -->\n            <line x1=\"50\" y1=\"210\" x2=\"400\" y2=\"210\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"405\" y=\"215\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">t (°C)</text>\n            <text x=\"25\" y=\"25\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">h (mm)</text>\n            <text x=\"36\" y=\"225\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            \n            <!-- Giá trị trục -->\n            <text x=\"18\" y=\"185\" fill=\"#cbd5e1\" font-size=\"13\">40</text>\n            <text x=\"12\" y=\"65\" fill=\"#cbd5e1\" font-size=\"13\">240</text>\n            <text x=\"318\" y=\"228\" fill=\"#cbd5e1\" font-size=\"13\">100</text>\n\n            <!-- Đường tuyến tính h theo t -->\n            <line x1=\"50\" y1=\"180\" x2=\"330\" y2=\"60\" stroke=\"#06b6d4\" stroke-width=\"3.5\" />\n            <circle cx=\"50\" cy=\"180\" r=\"5\" fill=\"#f43f5e\" />\n            <circle cx=\"330\" cy=\"60\" r=\"5\" fill=\"#f43f5e\" />\n\n            <!-- Điểm đo hx = 88 mm -->\n            <line x1=\"50\" y1=\"151\" x2=\"117\" y2=\"151\" stroke=\"#f59e0b\" stroke-dasharray=\"3\"/>\n            <line x1=\"117\" y1=\"151\" x2=\"117\" y2=\"210\" stroke=\"#f59e0b\" stroke-dasharray=\"3\"/>\n            <circle cx=\"117\" cy=\"151\" r=\"5\" fill=\"#f59e0b\" />\n            \n            <text x=\"22\" y=\"155\" fill=\"#f59e0b\" font-size=\"12\" font-weight=\"700\">88</text>\n            <text x=\"110\" y=\"228\" fill=\"#f59e0b\" font-size=\"13\" font-weight=\"800\">t<tspan baseline-shift=\"sub\" font-size=\"70%\">x</tspan> = ?</text>\n          </svg>"},{"q":"Một cặp nhiệt điện đồng - constantan có hệ số nhiệt điện động α_T = 40 μV/K. Nối một đầu mối hàn vào nước đá đang tan ở 0°C (273,15 K) và nhúng đầu mối hàn còn lại vào lò nung nhiệt độ cao thì đo được suất điện động nhiệt điện là E = 24 mV. Nhiệt độ của lò nung là:","opts":["600°C","573°C","873°C","480°C"],"ans":0,"exp":"• Công thức suất điện động nhiệt điện:<div class='formula-box'><span class='math-sym'>E = α_T · (T - T₀) = α_T · (t - t₀)</span></div>• Đổi đơn vị: <span class='math-sym'>E = 24 mV = 24.000 μV</span>, <span class='math-sym'>α_T = 40 μV/°C</span>, <span class='math-sym'>t₀ = 0°C</span>.<br>• Nhiệt độ của lò nung:<div class='formula-box'><span class='math-sym'>t - 0 = <div class='fraction'><span class='numerator'>E</span><span class='denominator'>α_T</span></div> = <div class='fraction'><span class='numerator'>24000</span><span class='denominator'>40</span></div> = 600°C</span></div>","svgGraph":null}],"4":[{"q":"Theo định nghĩa chuẩn trong chương trình Vật Lí 12, nhiệt dung riêng của một chất là:","opts":["Nhiệt lượng cần cung cấp để 1 kg chất đó chuyển hoàn toàn từ thể lỏng sang thể khí.","Nhiệt lượng tỏa ra khi làm đông đặc hoàn toàn một khối lượng chất lỏng xác định.","Nhiệt lượng cần thiết để làm cho 1 kg chất đó tăng nhiệt độ thêm 1 K (hoặc 1°C).","Tổng động năng nhiệt của tất cả các phân tử cấu tạo nên một vật thể xác định."],"ans":2,"exp":"Nhiệt dung riêng được xác định bằng công thức:<div class='formula-box'><span class='math-sym'>c</span> = <div class='fraction'><span class='numerator math-sym'>Q</span><span class='denominator math-sym'>m · ΔT</span></div></div>Đại lượng này biểu thị nhiệt lượng cần truyền cho <b>1 kg</b> chất để nhiệt độ tăng thêm <b>1 K (hoặc 1°C)</b>.<br>Đơn vị chuẩn trong hệ SI là: <b style='color:#38bdf8;'>J/(kg·K)</b>.","svgGraph":null},{"q":"Trong các hệ thống tản nhiệt làm mát động cơ đốt trong (xe máy tay ga, ô tô), dung dịch có thành phần chủ yếu là nước được sử dụng làm chất tải nhiệt chính. Nguyên nhân vật lí cơ bản nhất là do:","opts":["Nước có tính dẫn điện cao giúp tiêu tán nhanh điện tích tĩnh phát sinh do cọ xát trong xi-lanh.","Nước có nhiệt dung riêng rất lớn, có khả năng hấp thụ nhiệt lượng cực lớn từ buồng đốt mà nhiệt độ tăng không quá nhiều.","Nước có khối lượng riêng nhỏ nhất trong số các chất lỏng bôi trơn kỹ thuật.","Nước bay hơi rất nhanh ở nhiệt độ phòng, tạo hiệu ứng giảm nhiệt độ cục bộ liên tục."],"ans":1,"exp":"Nhiệt dung riêng của nước <span class='math-sym'>c ≈ 4180 J/(kg·K)</span> cao hơn hẳn các chất lỏng khác. Nhờ đó, một khối lượng nước tuần hoàn nhất định có thể hấp thụ và vận chuyển một nhiệt lượng cực lớn:<div class='formula-box'><span class='math-sym'>Q = m · c · Δt</span></div>Lượng nhiệt lớn được tải ra két tản nhiệt mà nhiệt độ của khối nước tăng không quá cao, giữ buồng đốt luôn ở ngưỡng an toàn.","svgGraph":null},{"q":"Một ấm đun nước siêu tốc công suất định mức P = 1500 W, hiệu suất nhiệt H = 80%. Dùng ấm đun m = 1,5 kg nước từ nhiệt độ 20°C đến sôi ở 100°C. Biết nhiệt dung riêng của nước c = 4200 J/(kg·K). Thời gian đun cần thiết là:","opts":["336 giây (~ 5,6 phút)","420 giây (~ 7,0 phút)","504 giây (~ 8,4 phút)","280 giây (~ 4,7 phút)"],"ans":1,"exp":"• Nhiệt lượng có ích để làm sôi nước:<div class='formula-box'><span class='math-sym'>Q<sub>ích</sub> = m · c · (t₂ - t₁) = 1,5 × 4200 × (100 - 20) = 504.000 J</span></div>• Điện năng tiêu thụ toàn phần:<div class='formula-box'><span class='math-sym'>A = Q<sub>ích</sub> / H = 504.<span class=\"fraction\"><span class=\"numerator\">000</span><span class=\"denominator\">0</span></span>,8 = 630.000 J</span></div>• Thời gian đun:<div class='formula-box'><span class='math-sym'>t = A / P = 630.<span class=\"fraction\"><span class=\"numerator\">000</span><span class=\"denominator\">1500</span></span> = 420 giây (7 phút)</span></div>","svgGraph":null},{"q":"Thả một thỏi nhôm khối lượng 0,4 kg ở nhiệt độ 100°C vào bình nhiệt lượng kế chứa 0,8 kg nước ở 20°C. Bỏ qua hao phí nhiệt ra bình và môi trường. Cho c<sub>nhôm</sub> = 880 J/(kg·K), c<sub>nước</sub> = 4200 J/(kg·K). Nhiệt độ cân bằng t của hệ xấp xỉ bằng:","opts":["27,6°C","32,4°C","40,0°C","58,2°C"],"ans":0,"exp":"Phương trình cân bằng nhiệt:<div class='formula-box'><span class='math-sym'>Q<sub>tỏa</sub> = Q<sub>thu</sub> ⇔ m<sub>Al</sub> · c<sub>Al</sub> · (100 - t) = m<sub>n</sub>ước · c<sub>nước</sub> · (t - 20)</span></div>Thay số: <span class='math-sym'>0,4 × 880 × (100 - t) = 0,8 × 4200 × (t - 20)</span><br>⇔ <span class='math-sym'>352(100 - t) = 3360(t - 20)</span><br>⇔ <span class='math-sym'>35200 - 352t = 3360t - 67200 ⟹ 3712t = 102400 ⟹ t ≈ 27,59°C</span>.","svgGraph":null},{"q":"Hình vẽ bên dưới là đồ thị biểu diễn sự phụ thuộc của nhiệt độ (T) theo thời gian đun (t) của hai chất lỏng (1) và (2) có cùng khối lượng m. Cả hai được cấp nhiệt từ hai nguồn hoàn toàn giống nhau có công suất không đổi P. Dựa vào đồ thị, kết luận nào sau đây đúng về tỉ số nhiệt dung riêng <span class=\"fraction\"><span class=\"numerator\">c₁</span><span class=\"denominator\">c₂</span></span>?","opts":["<span class=\"fraction\"><span class=\"numerator\">c₁</span><span class=\"denominator\">c₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>","<span class=\"fraction\"><span class=\"numerator\">c₁</span><span class=\"denominator\">c₂</span></span> = 2","<span class=\"fraction\"><span class=\"numerator\">c₁</span><span class=\"denominator\">c₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>","<span class=\"fraction\"><span class=\"numerator\">c₁</span><span class=\"denominator\">c₂</span></span> = 1"],"ans":0,"exp":"• Phương trình truyền nhiệt: <span class='math-sym'>Q = P · t = m · c · ΔT ⟹ ΔT = (P / (m · c)) · t</span><br>• Độ dốc (hệ số góc) của đồ thị:<div class='formula-box'><span class='math-sym'>k = tan(α) = <div class='fraction'><span class='numerator'>ΔT</span><span class='denominator'>t</span></div> = <div class='fraction'><span class='numerator'>P</span><span class='denominator'>m · c</span></div></span></div>Vì <span class='math-sym'>P</span> và <span class='math-sym'>m</span> như nhau nên hệ số góc <span class='math-sym'>k</span> tỉ lệ nghịch với nhiệt dung riêng <span class='math-sym'>c</span>.<br>• Từ đồ thị tại cùng thời điểm <span class='math-sym'>t₀</span>: đường (1) tăng <span class='math-sym'>2T₀</span> còn đường (2) tăng <span class='math-sym'>T₀</span> nên độ dốc <span class='math-sym'>k₁ = 2k₂</span>.<br>Do đó: <div class='formula-box'><span class='math-sym'><div class='fraction'><span class='numerator'>c₁</span><span class='denominator'>c₂</span></div> = <div class='fraction'><span class='numerator'>k₂</span><span class='denominator'>k₁</span></div> = <div class='fraction'><span class='numerator'>1</span><span class='denominator'>2</span></div></span></div>","svgGraph":"<svg viewBox=\"0 0 440 250\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <line x1=\"50\" y1=\"50\" x2=\"400\" y2=\"50\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"125\" x2=\"400\" y2=\"125\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"220\" y1=\"200\" x2=\"220\" y2=\"30\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <line x1=\"50\" y1=\"200\" x2=\"410\" y2=\"200\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"50\" y1=\"200\" x2=\"50\" y2=\"20\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"415\" y=\"205\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">t (s)</text>\n            <text x=\"32\" y=\"24\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">T (°C)</text>\n            <text x=\"38\" y=\"215\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            <text x=\"215\" y=\"222\" fill=\"#cbd5e1\" font-size=\"13\">t₀</text>\n            <text x=\"18\" y=\"130\" fill=\"#cbd5e1\" font-size=\"13\">T₀</text>\n            <text x=\"10\" y=\"55\" fill=\"#cbd5e1\" font-size=\"13\">2T₀</text>\n\n            <line x1=\"50\" y1=\"200\" x2=\"220\" y2=\"50\" stroke=\"#f43f5e\" stroke-width=\"3.5\" />\n            <circle cx=\"220\" cy=\"50\" r=\"5\" fill=\"#f43f5e\" />\n            <text x=\"228\" y=\"48\" fill=\"#f43f5e\" font-size=\"15\" font-weight=\"800\">Chất (1)</text>\n\n            <line x1=\"50\" y1=\"200\" x2=\"220\" y2=\"125\" stroke=\"#06b6d4\" stroke-width=\"3.5\" />\n            <circle cx=\"220\" cy=\"125\" r=\"5\" fill=\"#06b6d4\" />\n            <text x=\"228\" y=\"125\" fill=\"#06b6d4\" font-size=\"15\" font-weight=\"800\">Chất (2)</text>\n          </svg>"}],"5":[{"q":"Theo chương trình Vật Lí 12, nhiệt nóng chảy riêng của một chất rắn kết tinh là:","opts":["Nhiệt lượng cần cung cấp cho 1 kg chất đó để chuyển hoàn toàn từ thể rắn sang thể lỏng ở nhiệt độ nóng chảy.","Nhiệt lượng cần thiết để làm tăng nhiệt độ của 1 kg chất rắn thêm 1 K.","Nhiệt lượng tỏa ra khi làm hóa hơi hoàn toàn một đơn vị khối lượng chất lỏng.","Nhiệt độ mà tại đó mạng tinh thể của chất rắn bắt đầu bị phá vỡ hoàn toàn."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Nhiệt nóng chảy riêng (ký hiệu <span class='math-sym'>λ</span>) của một chất là nhiệt lượng cần thiết để <b>1 kg</b> chất đó chuyển hoàn toàn từ thể rắn sang thể lỏng ở nhiệt độ nóng chảy.<br>• Công thức xác định:<div class='formula-box'><span class='math-sym'>λ = <div class='fraction'><span class='numerator'>Q</span><span class='denominator'>m</span></div></span></div>• Đơn vị chuẩn trong hệ SI là: <b style='color:#38bdf8;'>J/kg</b>.","svgGraph":null},{"q":"Biết nhiệt nóng chảy riêng của nước đá là λ ≈ 3,34 × 10⁵ J/kg. Ý nghĩa thực tiễn của con số này là:","opts":["Cần cung cấp nhiệt lượng 3,34 × 10⁵ J để làm nóng chảy hoàn toàn 1 kg nước đá ở 0°C thành nước ở 0°C.","Mỗi khi 1 kg nước đá hạ nhiệt độ xuống 1°C thì nó sẽ tỏa ra năng lượng 3,34 × 10⁵ J.","Nhiệt lượng tỏa ra khi đun sôi 1 kg nước đá từ 0°C đến 100°C là 3,34 × 10⁵ J.","Để nâng nhiệt độ của 1 kg nước đá từ 0°C lên 1°C cần cung cấp 3,34 × 10⁵ J."],"ans":0,"exp":"• Đại lượng <span class='math-sym'>λ = 3,34 × 10⁵ J/kg</span> biểu thị: Cần truyền một nhiệt lượng bằng <b>3,34 × 10⁵ Jun</b> cho 1 kg nước đá ở đúng 0°C để phá vỡ toàn bộ cấu trúc mạng tinh thể băng và chuyển hoàn toàn thành nước lỏng ở 0°C.","svgGraph":null},{"q":"Cần cung cấp một nhiệt lượng bao nhiêu để làm nóng chảy hoàn toàn 1,5 kg nước đá ở nhiệt độ 0°C? Cho biết nhiệt nóng chảy riêng của nước đá là λ = 3,34 × 10⁵ J/kg.","opts":["5,01 × 10⁵ J (501 kJ)","2,23 × 10⁵ J (223 kJ)","6,68 × 10⁵ J (668 kJ)","3,34 × 10⁵ J (334 kJ)"],"ans":0,"exp":"• Nhiệt lượng nóng chảy:<div class='formula-box'><span class='math-sym'>Q = λ · m = 3,34 × 10⁵ × 1,5 = 5,01 × 10⁵ J = 501 kJ</span></div>","svgGraph":null},{"q":"Cần cung cấp tổng nhiệt lượng bao nhiêu để làm chuyển 2,0 kg nước đá từ nhiệt độ -10°C thành nước lỏng hoàn toàn ở 0°C? Cho biết nhiệt dung riêng của nước đá c<sub>đá</sub> = 2100 J/(kg·K), nhiệt nóng chảy riêng của nước đá λ = 3,34 × 10⁵ J/kg.","opts":["710 kJ","668 kJ","42 kJ","752 kJ"],"ans":0,"exp":"• Giai đoạn 1: Nâng nhiệt độ nước đá từ -10°C lên 0°C:<div class='formula-box'><span class='math-sym'>Q₁ = m · c<sub>đá</sub> · Δt = 2,0 × 2100 × (0 - (-10)) = 42.000 J = 42 kJ</span></div>• Giai đoạn 2: Làm nóng chảy hoàn toàn nước đá ở 0°C:<div class='formula-box'><span class='math-sym'>Q₂ = m · λ = 2,0 × 3,34 × 10⁵ = 668.000 J = 668 kJ</span></div>• Tổng nhiệt lượng cần thiết:<div class='formula-box'><span class='math-sym'>Q = Q₁ + Q₂ = 42 + 668 = 710 kJ</span></div>","svgGraph":null},{"q":"Hình vẽ dưới đây là đồ thị biểu diễn sự thay đổi nhiệt độ theo thời gian khi nung nóng một mẫu chì khối lượng m = 0,5 kg bằng nguồn nhiệt có công suất không đổi P = 500 W. Giai đoạn chì nóng chảy diễn ra ở nhiệt độ 327°C và kéo dài trong khoảng thời gian Δt = 25 giây (từ giây thứ 15 đến giây thứ 40). Bỏ qua hao phí nhiệt ra môi trường. Nhiệt nóng chảy riêng của chì xác định từ đồ thị là:","opts":["2,5 × 10⁴ J/kg","5,0 × 10⁴ J/kg","1,25 × 10⁴ J/kg","2,5 × 10⁵ J/kg"],"ans":0,"exp":"• Nhiệt lượng nguồn cấp trong giai đoạn nóng chảy:<div class='formula-box'><span class='math-sym'>Q = P · Δt = 500 × 25 = 12.500 J</span></div>• Nhiệt nóng chảy riêng của chì:<div class='formula-box'><span class='math-sym'>λ = <div class='fraction'><span class='numerator'>Q</span><span class='denominator'>m</span></div> = <div class='fraction'><span class='numerator'>12500</span><span class='denominator'>0,5</span></div> = 25.000 J/kg = 2,5 × 10⁴ J/kg</span></div>","svgGraph":"<svg viewBox=\"0 0 440 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <!-- Lưới mờ -->\n            <line x1=\"50\" y1=\"180\" x2=\"380\" y2=\"180\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"110\" x2=\"380\" y2=\"110\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"140\" y1=\"210\" x2=\"140\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"280\" y1=\"210\" x2=\"280\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <!-- Trục tọa độ -->\n            <line x1=\"50\" y1=\"210\" x2=\"400\" y2=\"210\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"405\" y=\"215\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">t (s)</text>\n            <text x=\"25\" y=\"25\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">T (°C)</text>\n            <text x=\"36\" y=\"225\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            \n            <!-- Giá trị trục -->\n            <text x=\"18\" y=\"185\" fill=\"#cbd5e1\" font-size=\"13\">27°</text>\n            <text x=\"12\" y=\"115\" fill=\"#cbd5e1\" font-size=\"13\">327°</text>\n            <text x=\"132\" y=\"228\" fill=\"#cbd5e1\" font-size=\"13\">15</text>\n            <text x=\"272\" y=\"228\" fill=\"#cbd5e1\" font-size=\"13\">40</text>\n\n            <!-- Đường đặc tuyến -->\n            <line x1=\"50\" y1=\"180\" x2=\"140\" y2=\"110\" stroke=\"#06b6d4\" stroke-width=\"3.5\" />\n            <circle cx=\"50\" cy=\"180\" r=\"4\" fill=\"#06b6d4\" />\n            \n            <line x1=\"140\" y1=\"110\" x2=\"280\" y2=\"110\" stroke=\"#f43f5e\" stroke-width=\"4\" />\n            <circle cx=\"140\" cy=\"110\" r=\"5\" fill=\"#f43f5e\" />\n            <circle cx=\"280\" cy=\"110\" r=\"5\" fill=\"#f43f5e\" />\n\n            <line x1=\"280\" y1=\"110\" x2=\"360\" y2=\"55\" stroke=\"#10b981\" stroke-width=\"3.5\" />\n            <circle cx=\"360\" cy=\"55\" r=\"4\" fill=\"#10b981\" />\n\n            <!-- Nhãn -->\n            <text x=\"175\" y=\"98\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"800\">Δt = 25s (Nóng chảy)</text>\n          </svg>"},{"q":"Thả một cục nước đá khối lượng m₁ = 0,2 kg ở 0°C vào một bình nhiệt lượng kế chứa m₂ = 0,5 kg nước ở 30°C. Bỏ qua nhiệt dung của bình và mất mát nhiệt ra ngoài. Cho c<sub>nước</sub> = 4200 J/(kg·K), λ = 3,34 × 10⁵ J/kg. Hiện tượng và trạng thái cuối cùng của hệ là:","opts":["Nước đá tan hoàn toàn và nhiệt độ cân bằng cuối cùng xấp xỉ bằng 8,7°C.","Nước đá không tan hết và nhiệt độ cân bằng dừng lại ở 0°C.","Nước đá tan hoàn toàn và nhiệt độ cân bằng đạt 15,0°C.","Nước đóng băng thêm và nhiệt độ hạ xuống dưới 0°C."],"ans":0,"exp":"• Nhiệt lượng nước tỏa ra tối đa khi hạ từ 30°C về 0°C:<div class='formula-box'><span class='math-sym'>Q<sub>tỏa</sub><sub>max</sub> = m₂ · c · (30 - 0) = 0,5 × 4200 × 30 = 63.000 J</span></div>• Nhiệt lượng cần để làm tan hoàn toàn 0,2 kg đá ở 0°C:<div class='formula-box'><span class='math-sym'>Q<sub>tan</sub> = m₁ · λ = 0,2 × 3,34 × 10⁵ = 66.800 J</span></div>• <i>Khoan đã!</i> Ta thấy <span class='math-sym'>Q<sub>tỏa</sub><sub>max</sub> (63.000 J) < Q<sub>tan</sub> (66.800 J)</span>!<br>Do đó nước hạ về 0°C mà nhiệt lượng tỏa ra vẫn chưa đủ để làm tan hết đá ⟹ <b>Đá không tan hết, hệ ở trạng thái cân bằng tại đúng 0°C</b>!<br>Khối lượng đá tan được: <span class='math-sym'>m<sub>tan</sub> = <span class=\"fraction\"><span class=\"numerator\">63000</span><span class=\"denominator\">334000</span></span> ≈ 0,1886 kg</span>. Còn dư <span class='math-sym'>~0,0114 kg</span> đá chưa tan.<br><i>Đáp án chính xác nhất là:</i> Đá không tan hết và nhiệt độ dừng lại ở 0°C.","svgGraph":null}],"6":[{"q":"Theo định nghĩa trong chương trình Vật Lí 12, nhiệt hoá hơi riêng của một chất lỏng là:","opts":["Nhiệt lượng cần thiết để làm cho 1 kg chất lỏng đó hoá hơi hoàn toàn ở nhiệt độ sôi.","Nhiệt lượng tỏa ra khi làm ngưng tụ hoàn toàn một thể tích hơi xác định.","Nhiệt lượng cần cung cấp để 1 kg chất lỏng tăng nhiệt độ thêm 1°C khi đang sôi.","Nhiệt độ mà tại đó các bọt khí bắt đầu nổi lên mãnh liệt trong lòng chất lỏng."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Nhiệt hoá hơi riêng (ký hiệu <span class='math-sym'>L</span>) của một chất lỏng là nhiệt lượng cần cung cấp cho <b>1 kg</b> chất lỏng đó để nó hoá hơi hoàn toàn ở nhiệt độ sôi.<br>• Công thức tính:<div class='formula-box'><span class='math-sym'>L = <div class='fraction'><span class='numerator'>Q</span><span class='denominator'>m</span></div></span></div>• Đơn vị chuẩn trong hệ SI là: <b style='color:#38bdf8;'>J/kg</b>.","svgGraph":null},{"q":"Sự khác nhau căn bản nhất giữa quá trình 'Bay hơi' và quá trình 'Sôi' của chất lỏng là:","opts":["Bay hơi diễn ra ở mọi nhiệt độ và chỉ xảy ra trên bề mặt chất lỏng; còn sự sôi chỉ xảy ra ở nhiệt độ sôi xác định và diễn ra đồng thời ở cả trong lòng lẫn trên mặt thoáng.","Bay hơi cần cung cấp nhiệt lượng còn sự sôi thì tự phát tỏa nhiệt ra môi trường.","Bay hơi làm khối lượng chất lỏng tăng lên còn sự sôi làm thể tích khối chất lỏng co lại.","Bay hơi chỉ xảy ra đối với nước ngọt, còn sự sôi chỉ xảy ra với dung dịch nước muối."],"ans":0,"exp":"• <b>So sánh chuẩn SGK:</b><br>- <i>Sự bay hơi:</i> Xảy ra ở <b>mọi nhiệt độ</b>, chỉ diễn ra trên <b>bề mặt thoáng</b> của chất lỏng.<br>- <i>Sự sôi:</i> Là trường hợp hoá hơi đặc biệt, chỉ xảy ra tại <b>nhiệt độ sôi xác định</b> (ở một áp suất ngoài nhất định), diễn ra <b>ở cả trong lòng</b> (hình thành bọt khí) và <b>trên bề mặt thoáng</b>.","svgGraph":null},{"q":"Cần cung cấp một nhiệt lượng bao nhiêu để làm hoá hơi hoàn toàn 0,8 kg nước đang sôi ở 100°C trong ấm? Cho biết nhiệt hoá hơi riêng của nước là L = 2,26 × 10⁶ J/kg.","opts":["1,808 × 10⁶ J (1808 kJ)","2,825 × 10⁶ J (2825 kJ)","1,130 × 10⁶ J (1130 kJ)","2,260 × 10⁶ J (2260 kJ)"],"ans":0,"exp":"• Nhiệt lượng hoá hơi:<div class='formula-box'><span class='math-sym'>Q = L · m = 2,26 × 10⁶ × 0,8 = 1,808 × 10⁶ J = 1808 kJ</span></div>","svgGraph":null},{"q":"Một ấm đun nước bằng điện có công suất hữu ích P = 1130 W dùng để đun nước. Sau khi nước trong ấm đạt nhiệt độ sôi 100°C, người ta để ấm tiếp tục sôi trong thời gian t = 4 phút (240 giây). Khối lượng nước đã hoá hơi thoát ra khỏi ấm trong khoảng thời gian này là:","opts":["0,12 kg (120 g)","0,24 kg (240 g)","0,06 kg (60 g)","0,18 kg (180 g)"],"ans":0,"exp":"• Nhiệt lượng ấm cung cấp khi nước đang sôi:<div class='formula-box'><span class='math-sym'>Q = P · t = 1130 × 240 = 271.200 J</span></div>• Khối lượng nước đã hoá hơi:<div class='formula-box'><span class='math-sym'>m = <div class='fraction'><span class='numerator'>Q</span><span class='denominator'>L</span></div> = <div class='fraction'><span class='numerator'>271200</span><span class='denominator'>2,26 × 10⁶</span></div> = 0,12 kg = 120 g</span></div>","svgGraph":null},{"q":"Hình vẽ bên dưới là đồ thị ghi nhận khối lượng m (gam) của ấm và nước đang sôi theo thời gian đun t (phút) bằng cân điện tử kỹ thuật số. Biết công suất nhiệt cấp liên tục là P = 750 W không đổi. Trong khoảng thời gian từ t₁ = 2 phút đến t₂ = 6 phút, khối lượng giảm từ m₁ = 600 g xuống m₂ = 520 g. Nhiệt hoá hơi riêng của nước xác định từ số liệu đồ thị này là:","opts":["2,25 × 10⁶ J/kg","2,40 × 10⁶ J/kg","2,10 × 10⁶ J/kg","2,50 × 10⁶ J/kg"],"ans":0,"exp":"• Thời gian khảo sát: <span class='math-sym'>Δt = 6 - 2 = 4 phút = 240 giây</span>.<br>• Nhiệt lượng ấm cung cấp:<div class='formula-box'><span class='math-sym'>Q = P · Δt = 750 × 240 = 180.000 J</span></div>• Độ giảm khối lượng nước hoá hơi: <span class='math-sym'>Δm = 600 - 520 = 80 g = 0,08 kg</span>.<br>• Nhiệt hoá hơi riêng tính được:<div class='formula-box'><span class='math-sym'>L = <div class='fraction'><span class='numerator'>Q</span><span class='denominator'>Δm</span></div> = <div class='fraction'><span class='numerator'>180000</span><span class='denominator'>0,08</span></div> = 2.250.000 J/kg = 2,25 × 10⁶ J/kg</span></div>","svgGraph":"<svg viewBox=\"0 0 440 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <!-- Lưới mờ -->\n            <line x1=\"50\" y1=\"80\" x2=\"380\" y2=\"80\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"140\" x2=\"380\" y2=\"140\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"130\" y1=\"210\" x2=\"130\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"290\" y1=\"210\" x2=\"290\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <!-- Trục tọa độ -->\n            <line x1=\"50\" y1=\"210\" x2=\"400\" y2=\"210\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"405\" y=\"215\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">t (phút)</text>\n            <text x=\"25\" y=\"25\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">m (gam)</text>\n            <text x=\"36\" y=\"225\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            \n            <!-- Giá trị trục -->\n            <text x=\"18\" y=\"85\" fill=\"#cbd5e1\" font-size=\"13\">600</text>\n            <text x=\"18\" y=\"145\" fill=\"#cbd5e1\" font-size=\"13\">520</text>\n            <text x=\"125\" y=\"228\" fill=\"#cbd5e1\" font-size=\"13\">2</text>\n            <text x=\"285\" y=\"228\" fill=\"#cbd5e1\" font-size=\"13\">6</text>\n\n            <!-- Đường giảm khối lượng tuyến tính -->\n            <line x1=\"130\" y1=\"80\" x2=\"290\" y2=\"140\" stroke=\"#06b6d4\" stroke-width=\"3.5\" />\n            <circle cx=\"130\" cy=\"80\" r=\"5\" fill=\"#f43f5e\" />\n            <circle cx=\"290\" cy=\"140\" r=\"5\" fill=\"#f43f5e\" />\n\n            <!-- Nhãn Δm -->\n            <text x=\"175\" y=\"100\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"800\">Δm = 80g</text>\n            <text x=\"170\" y=\"195\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"700\">Δt = 4 phút</text>\n          </svg>"},{"q":"Cần cung cấp tổng nhiệt lượng bao nhiêu để đun 1,0 kg nước từ 20°C đến sôi ở 100°C và làm hoá hơi 20% lượng nước đó? Cho c<sub>nước</sub> = 4200 J/(kg·K), L = 2,26 × 10⁶ J/kg. Bỏ qua hao phí nhiệt ra môi trường.","opts":["7,88 × 10⁵ J (788 kJ)","3,36 × 10⁵ J (336 kJ)","4,52 × 10⁵ J (452 kJ)","9,12 × 10⁵ J (912 kJ)"],"ans":0,"exp":"• Nhiệt lượng làm tăng nhiệt độ 1 kg nước từ 20°C lên 100°C:<div class='formula-box'><span class='math-sym'>Q₁ = m · c · (100 - 20) = 1,0 × 4200 × 80 = 336.000 J = 336 kJ</span></div>• Khối lượng nước hoá hơi: <span class='math-sym'>m<sub>h</sub>ơi = 20% × 1,0 = 0,2 kg</span>.<br>• Nhiệt lượng làm hoá hơi 0,2 kg nước sôi:<div class='formula-box'><span class='math-sym'>Q₂ = m<sub>h</sub>ơi · L = 0,2 × 2,26 × 10⁶ = 452.000 J = 452 kJ</span></div>• Tổng nhiệt lượng cần cung cấp:<div class='formula-box'><span class='math-sym'>Q = Q₁ + Q₂ = 336 + 452 = 788 kJ = 7,88 × 10⁵ J</span></div>","svgGraph":null}],"7":[{"q":"Trong một hệ nhiệt động lực học cô lập hoàn toàn chỉ gồm các vật trao đổi nhiệt và cơ năng với nhau, phát biểu nào sau đây thể hiện đúng định luật bảo toàn năng lượng?","opts":["Tổng đại số độ biến thiên nội năng của tất cả các vật trong hệ cô lập luôn bằng 0: ∑ ΔU<sub>i</sub> = 0.","Nhiệt lượng của các vật nóng luôn lớn hơn nhiệt lượng mà các vật lạnh thu vào.","Hệ có thể tự phát sinh công mà không tiêu hao bất kì dạng năng lượng nào.","Nội năng của mỗi vật riêng lẻ trong hệ luôn không đổi theo thời gian."],"ans":0,"exp":"• <b>Nguyên lí bảo toàn:</b> Trong một hệ cô lập (không trao đổi năng lượng với bên ngoài), năng lượng chỉ truyền từ vật này sang vật khác hoặc chuyển hóa giữa các dạng: <span class='math-sym'>∑ ΔU<sub>i</sub> = 0</span>.<br>• Khi chỉ có trao đổi nhiệt đơn thuần: <span class='math-sym'>∑ Q<sub>i</sub> = 0 ⟺ Q<sub>tỏa</sub> = Q<sub>thu</sub></span>.","svgGraph":null},{"q":"Hiệu suất nhiệt (H) của một thiết bị đun nước dùng điện được định nghĩa chuẩn xác bằng:","opts":["Tỉ số giữa nhiệt lượng có ích dùng để làm nóng và sôi nước với toàn bộ điện năng tiêu thụ: H = <span class=\"fraction\"><span class=\"numerator\">Q<sub>ích</sub></span><span class=\"denominator\">A</span></span>.","Tỉ số giữa nhiệt lượng hao phí tỏa ra ngoài môi trường với nhiệt lượng có ích.","Tỉ số giữa điện năng tiêu thụ với nhiệt dung riêng của nước.","Tỉ số giữa khối lượng nước trong ấm với thời gian đun nước sôi."],"ans":0,"exp":"• <b>Định nghĩa hiệu suất:</b><div class='formula-box'><span class='math-sym'>H = <div class='fraction'><span class='numerator'>Q<sub>ích</sub></span><span class='denominator'>A<sub>to</sub>àn phần</span></div> = <div class='fraction'><span class='numerator'>m · c · Δt</span><span class='denominator'>P · t</span></div></span></div>Luôn có <span class='math-sym'>H < 1</span> (hay <span class='math-sym'>H < 100%</span>) do luôn có mất mát nhiệt ra vỏ ấm và không khí.","svgGraph":null},{"q":"Dùng một ấm điện có hiệu suất nhiệt H = 80% để đun m = 2,0 kg nước từ 25°C đến khi sôi ở 100°C. Biết c<sub>nước</sub> = 4200 J/(kg·K) và giá tiền điện là 2500 đồng/kWh. Số tiền điện phải trả cho một lần đun này xấp xỉ là:","opts":["547 đồng","438 đồng","685 đồng","820 đồng"],"ans":0,"exp":"• Nhiệt lượng có ích làm sôi nước:<div class='formula-box'><span class='math-sym'>Q<sub>ích</sub> = m · c · (100 - 25) = 2 × 4200 × 75 = 630.000 J</span></div>• Điện năng tiêu thụ thực tế của ấm:<div class='formula-box'><span class='math-sym'>A = <div class='fraction'><span class='numerator'>Q<sub>ích</sub></span><span class='denominator'>H</span></div> = <div class='fraction'><span class='numerator'>630000</span><span class='denominator'>0,8</span></div> = 787.500 J</span></div>• Đổi sang số điện (kWh):<div class='formula-box'><span class='math-sym'>A = <div class='fraction'><span class='numerator'>787500</span><span class='denominator'>3,6 × 10⁶</span></div> ≈ 0,21875 kWh</span></div>• Tiền điện: <span class='math-sym'>0,21875 × 2500 ≈ 546,875 đồng ≈ 547 đồng</span>.","svgGraph":null},{"q":"Thả m₁ = 0,1 kg nước đá ở 0°C vào m₂ = 0,4 kg nước ở 40°C đựng trong bình cách nhiệt. Bỏ qua trao đổi nhiệt với bình. Cho c<sub>nước</sub> = 4200 J/(kg·K), λ = 3,34 × 10⁵ J/kg. Nhiệt độ cân bằng t của hệ sau khi đá tan hết là:","opts":["16,1°C","20,0°C","12,5°C","24,2°C"],"ans":0,"exp":"• Nhiệt lượng cần để làm nóng chảy hoàn toàn 0,1 kg đá:<div class='formula-box'><span class='math-sym'>Q<sub>tan</sub> = m₁ · λ = 0,1 × 3,34 × 10⁵ = 33.400 J</span></div>• Nhiệt lượng nước tỏa ra khi hạ từ 40°C về 0°C:<div class='formula-box'><span class='math-sym'>Q<sub>tỏa</sub><sub>max</sub> = 0,4 × 4200 × 40 = 67.200 J > 33.400 J</span></div>⟹ Đá tan hoàn toàn và nhiệt độ cân bằng <span class='math-sym'>t > 0°C</span>.<br>• Phương trình cân bằng nhiệt:<div class='formula-box'><span class='math-sym'>m₁ · λ + m₁ · c · (t - 0) = m₂ · c · (40 - t)</span></div>⇔ <span class='math-sym'>33400 + 0,1 × 4200 · t = 0,4 × 4200 · (40 - t)</span><br>⇔ <span class='math-sym'>33400 + 420t = 67200 - 1680t ⟹ 2100t = 33800 ⟹ t ≈ 16,095°C ≈ 16,1°C</span>.","svgGraph":null},{"q":"Hình vẽ dưới đây biểu diễn đường đun nóng liên tục một khối chất tinh khiết khối lượng m = 1,0 kg bằng nguồn nhiệt công suất không đổi P = 1000 W. Giai đoạn nóng chảy diễn ra trong khoảng thời gian Δt₁ = 200 s; giai đoạn hoá hơi sôi diễn ra trong khoảng thời gian Δt₂ = 1200 s. Tỉ số giữa nhiệt hoá hơi riêng và nhiệt nóng chảy riêng (<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">λ</span></span>) của chất này là:","opts":["<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">λ</span></span> = 6","<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">λ</span></span> = 3","<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">λ</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">6</span></span>","<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">λ</span></span> = 12"],"ans":0,"exp":"• Nhiệt nóng chảy riêng: <span class='math-sym'>λ = (P · Δt₁) / m</span>.<br>• Nhiệt hoá hơi riêng: <span class='math-sym'>L = (P · Δt₂) / m</span>.<br>• Lập tỉ số:<div class='formula-box'><span class='math-sym'><div class='fraction'><span class='numerator'>L</span><span class='denominator'>λ</span></div> = <div class='fraction'><span class='numerator'>Δt₂</span><span class='denominator'>Δt₁</span></div> = <div class='fraction'><span class='numerator'>1200</span><span class='denominator'>200</span></div> = 6</span></div>Nhiệt hoá hơi riêng của chất lớn gấp 6 lần nhiệt nóng chảy riêng.","svgGraph":"<svg viewBox=\"0 0 480 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n  <defs>\n    <marker id=\"arrow7\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n    </marker>\n  </defs>\n  <!-- Luoi mo -->\n  <line x1=\"50\" y1=\"170\" x2=\"440\" y2=\"170\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  <line x1=\"50\" y1=\"90\" x2=\"440\" y2=\"90\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  <line x1=\"90\" y1=\"220\" x2=\"90\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  <line x1=\"160\" y1=\"220\" x2=\"160\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  <line x1=\"220\" y1=\"220\" x2=\"220\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  <line x1=\"410\" y1=\"220\" x2=\"410\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  \n  <!-- Truc toa do -->\n  <line x1=\"50\" y1=\"220\" x2=\"460\" y2=\"220\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arrow7)\"/>\n  <line x1=\"50\" y1=\"220\" x2=\"50\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arrow7)\"/>\n  \n  <text x=\"462\" y=\"224\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"700\">t (s)</text>\n  <text x=\"22\" y=\"26\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"700\">T (°C)</text>\n  <text x=\"38\" y=\"235\" fill=\"#94a3b8\" font-size=\"13\">O</text>\n  \n  <!-- Moc gia tri -->\n  <text x=\"18\" y=\"174\" fill=\"#cbd5e1\" font-size=\"12\">T₁</text>\n  <text x=\"18\" y=\"94\" fill=\"#cbd5e1\" font-size=\"12\">T₂</text>\n  <text x=\"82\" y=\"236\" fill=\"#cbd5e1\" font-size=\"11\">100</text>\n  <text x=\"150\" y=\"236\" fill=\"#cbd5e1\" font-size=\"11\">300</text>\n  <text x=\"210\" y=\"236\" fill=\"#cbd5e1\" font-size=\"11\">500</text>\n  <text x=\"398\" y=\"236\" fill=\"#cbd5e1\" font-size=\"11\">1700</text>\n\n  <!-- Duong dun nong lien tuc -->\n  <!-- Ran tang nhiet: 0 -> 100s -->\n  <line x1=\"50\" y1=\"210\" x2=\"90\" y2=\"170\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n  <!-- Nong chay: 100 -> 300s (Dt1 = 200s) -->\n  <line x1=\"90\" y1=\"170\" x2=\"160\" y2=\"170\" stroke=\"#f43f5e\" stroke-width=\"4\" />\n  <circle cx=\"90\" cy=\"170\" r=\"4\" fill=\"#f43f5e\" />\n  <circle cx=\"160\" cy=\"170\" r=\"4\" fill=\"#f43f5e\" />\n  <!-- Long tang nhiet: 300 -> 500s -->\n  <line x1=\"160\" y1=\"170\" x2=\"220\" y2=\"90\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n  <!-- Hoa hoi: 500 -> 1700s (Dt2 = 1200s) -->\n  <line x1=\"220\" y1=\"90\" x2=\"410\" y2=\"90\" stroke=\"#eab308\" stroke-width=\"4\" />\n  <circle cx=\"220\" cy=\"90\" r=\"4\" fill=\"#eab308\" />\n  <circle cx=\"410\" cy=\"90\" r=\"4\" fill=\"#eab308\" />\n  <!-- Hoi tang nhiet tiep -->\n  <line x1=\"410\" y1=\"90\" x2=\"445\" y2=\"50\" stroke=\"#10b981\" stroke-width=\"3\" />\n\n  <!-- Chu thich -->\n  <text x=\"96\" y=\"158\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"700\">Δt₁ = 200 s (Nóng chảy)</text>\n  <text x=\"240\" y=\"78\" fill=\"#eab308\" font-size=\"11\" font-weight=\"700\">Δt₂ = 1200 s (Hoá hơi sôi)</text>\n</svg>"},{"q":"Một bếp gas công nghiệp sử dụng khí hoá lỏng LPG có năng suất tỏa nhiệt q = 46 × 10⁶ J/kg. Hiệu suất của bếp là H = 60%. Cần đốt cháy bao nhiêu gam gas LPG để đun sôi 5,0 kg nước từ 20°C và làm hoá hơi hoàn toàn 1,0 kg nước trong số đó? Cho c<sub>nước</sub> = 4200 J/(kg·K), L = 2,26 × 10⁶ J/kg.","opts":["143 gam","86 gam","238 gam","172 gam"],"ans":0,"exp":"• Nhiệt lượng làm tăng 5 kg nước từ 20°C lên 100°C:<div class='formula-box'><span class='math-sym'>Q₁ = 5 × 4200 × (100 - 20) = 1.680.000 J</span></div>• Nhiệt lượng làm hoá hơi 1 kg nước sôi:<div class='formula-box'><span class='math-sym'>Q₂ = 1 × 2,26 × 10⁶ = 2.260.000 J</span></div>• Tổng nhiệt lượng có ích: <span class='math-sym'>Q<sub>ích</sub> = 1.680.000 + 2.260.000 = 3.940.000 J</span>.<br>• Nhiệt lượng toàn phần khí gas cần tỏa ra:<div class='formula-box'><span class='math-sym'>Q<sub>tp</sub> = <div class='fraction'><span class='numerator'>Q<sub>ích</sub></span><span class='denominator'>H</span></div> = <div class='fraction'><span class='numerator'>3940000</span><span class='denominator'>0,6</span></div> ≈ 6.566.667 J</span></div>• Khối lượng gas cần đốt cháy:<div class='formula-box'><span class='math-sym'>m<sub>gas</sub> = <div class='fraction'><span class='numerator'>Q<sub>tp</sub></span><span class='denominator'>q</span></div> = <div class='fraction'><span class='numerator'>6566667</span><span class='denominator'>46 × 10⁶</span></div> ≈ 0,14275 kg ≈ 143 gam</span></div>","svgGraph":null}],"8":[{"q":"Theo nội dung của thuyết động học phân tử chất khí, nhận định nào sau đây là <b>không chính xác</b>?","opts":["Chất khí được cấu tạo từ các phân tử có kích thước rất nhỏ so với khoảng cách giữa chúng.","Các phân tử khí luôn chuyển động hỗn loạn không ngừng; nhiệt độ càng cao thì chuyển động càng nhanh.","Khi chuyển động hỗn loạn, các phân tử khí va chạm vào nhau và va chạm vào thành bình gây nên áp suất.","Lực tương tác hút và đẩy giữa các phân tử khí luôn có độ lớn cực đại ở mọi khoảng cách."],"ans":3,"exp":"• <b>Theo thuyết động học phân tử:</b> Giữa các phân tử có lực hút và lực đẩy phân tử, nhưng khi khoảng cách giữa các phân tử rất lớn (như ở thể khí), lực tương tác phân tử là <b>rất yếu (có thể bỏ qua)</b>.<br>• Do đó nhận định D cho rằng lực tương tác luôn có độ lớn cực đại là hoàn toàn sai.","svgGraph":null},{"q":"Khái niệm <b>khí lí tưởng</b> trong vật lí được định nghĩa dựa trên những giả thuyết đơn giản hoá nào sau đây?","opts":["Các phân tử khí được coi là các chất điểm và chỉ tương tác với nhau khi va chạm đàn hồi.","Chất khí không có khối lượng và không gây ra áp suất lên thành bình chứa.","Các phân tử khí luôn đứng yên ở các vị trí cân bằng cố định trong không gian.","Lực hút giữa các phân tử khí luôn lớn hơn lực đẩy ở mọi nhiệt độ."],"ans":0,"exp":"• <b>Mô hình khí lí tưởng:</b><br>1. Thể tích của bản thân các phân tử khí không đáng kể so với thể tích bình chứa (coi phân tử là <i>chất điểm</i>).<br>2. Các phân tử khí chỉ tương tác với nhau khi <i>va chạm</i> (coi là va chạm đàn hồi).","svgGraph":null},{"q":"Nguyên nhân trực tiếp dẫn tới <b>chuyển động Brown</b> của các hạt khói bụi hoặc hạt phấn hoa lơ lửng trong không khí là do:","opts":["Sự va chạm không cân bằng, ngẫu nhiên từ mọi phía của vô số các phân tử không khí chuyển động nhiệt vào hạt bụi.","Trọng lực của Trái Đất thay đổi liên tục theo thời gian tác dụng lên hạt bụi.","Lực từ trường của Trái Đất làm hạt bụi chuyển động theo đường xoắn ốc.","Sự bốc hơi liên tục của các chất lỏng bám trên bề mặt hạt bụi."],"ans":0,"exp":"• <b>Giải thích hiện tượng Brown:</b> Vì hạt bụi có kích thước rất nhỏ, trong từng khoảnh khắc ngắn, số phân tử khí va chạm vào hạt từ các phía là không bằng nhau.<br>• Hợp lực va chạm không cân bằng đã đẩy hạt bụi chuyển động dích dắc hỗn loạn ngẫu nhiên.","svgGraph":null},{"q":"Một bình kín dung tích không đổi chứa một lượng khí lí tưởng ở nhiệt độ không đổi. Nếu bơm thêm khí vào bình sao cho mật độ phân tử khí tăng gấp 3 lần thì áp suất của khí trong bình sẽ:","opts":["Tăng gấp 3 lần.","Giảm đi 3 lần.","Không đổi vì thể tích bình và nhiệt độ không đổi.","Tăng gấp 9 lần."],"ans":0,"exp":"• <b>Công thức áp suất theo mật độ phân tử:</b> <span class=\"math-sym\">p</span> = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">3</span></span><span class=\"math-sym\">n</span><sub>0</sub><span class=\"math-sym\">E</span><sub>d</sub>.<br>• Vì nhiệt độ <span class=\"math-sym\">T</span> không đổi nên động năng trung bình không đổi. Mật độ phân tử <span class=\"math-sym\">n</span><sub>0</sub> tăng 3 lần thì áp suất <span class=\"math-sym\">p</span> tăng 3 lần.","svgGraph":null},{"q":"Khoảng cách trung bình giữa các phân tử của chất khí ở điều kiện nhiệt độ và áp suất tiêu chuẩn thường có độ lớn vào khoảng:","opts":["Lớn hơn kích thước của chính phân tử khoảng vài chục lần.","Xấp xỉ bằng đường kính của phân tử.","Nhỏ hơn đường kính của phân tử.","Bằng hàng triệu lần kích thước bình chứa."],"ans":0,"exp":"• Ở điều kiện tiêu chuẩn, đường kính phân tử cỡ <span class=\"math-sym\">10</span><sup>-10</sup> m (0,1 nm), trong khi khoảng cách trung bình giữa các phân tử khí cỡ vài nm (gấp khoảng 20 - 50 lần kích thước phân tử).","svgGraph":null},{"q":"Khi mở nắp một lọ nước hoa ở một góc trong phòng học kín gió, chỉ sau một khoảng thời gian ngắn, các bạn học sinh ngồi ở góc đối diện đều ngửi thấy mùi thơm. Hiện tượng này được giải thích chủ yếu là do:","opts":["Các phân tử nước hoa chuyển động hỗn loạn không ngừng và khuếch tán, xen lẫn vào khoảng trống giữa các phân tử không khí.","Không khí trong phòng có lực hút tĩnh điện kéo các phân tử nước hoa lan tỏa khắp phòng.","Các phân tử nước hoa chỉ chuyển động theo một hướng xác định từ nơi có nồng độ cao đến nơi có nồng độ thấp.","Trọng lực của Trái Đất hút các phân tử nước hoa rơi xuống sàn và lan truyền phẳng dọc theo mặt đất."],"ans":0,"exp":"• <b>Hiện tượng khuếch tán:</b> Theo mô hình động học phân tử chất khí, các phân tử nước hoa sau khi bay hơi sẽ chuyển động nhiệt hỗn loạn không ngừng về mọi phía, liên tục va chạm với các phân tử không khí và tự động lan tỏa xen kẽ vào các khoảng trống giữa các phân tử khí trong phòng.<br>• Quá trình này diễn ra hoàn toàn tự phát mà không cần có gió hay lực hút bên ngoài.","svgGraph":null}],"9":[{"q":"Quá trình biến đổi trạng thái của một lượng khí xác định trong đó <b>nhiệt độ được giữ không đổi</b> được gọi là:","opts":["Quá trình đẳng nhiệt.","Quá trình đẳng áp.","Quá trình đẳng tích.","Quá trình đoạn nhiệt."],"ans":0,"exp":"• <b>Định nghĩa:</b> Quá trình biến đổi trạng thái trong đó nhiệt độ <span class=\"math-sym\">T</span> không đổi gọi là quá trình đẳng nhiệt.","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Graph 1: p-V -->\n  <g transform=\"translate(30, 20)\">\n    <line x1=\"20\" y1=\"160\" x2=\"180\" y2=\"160\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n    <polygon points=\"180,160 172,156 172,164\" fill=\"#94a3b8\"/>\n    <text x=\"185\" y=\"164\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\">V</text>\n    <line x1=\"20\" y1=\"160\" x2=\"20\" y2=\"10\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n    <polygon points=\"20,10 16,18 24,18\" fill=\"#94a3b8\"/>\n    <text x=\"15\" y=\"8\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\">p</text>\n    <text x=\"10\" y=\"172\" fill=\"#94a3b8\" font-size=\"11\">O</text>\n    <!-- Hyperbola T2 > T1 -->\n    <path d=\"M 35,40 Q 55,90 160,135\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n    <text x=\"165\" y=\"132\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"700\">T₂</text>\n    <path d=\"M 30,70 Q 45,115 150,150\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"2.5\"/>\n    <text x=\"155\" y=\"148\" fill=\"#06b6d4\" font-size=\"11\" font-weight=\"700\">T₁</text>\n    <text x=\"95\" y=\"182\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"700\" text-anchor=\"middle\">Đồ thị p - V (Đường cong Hyperbol)</text>\n  </g>\n  <!-- Graph 2: p - 1/V -->\n  <g transform=\"translate(240, 20)\">\n    <line x1=\"20\" y1=\"160\" x2=\"180\" y2=\"160\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n    <polygon points=\"180,160 172,156 172,164\" fill=\"#94a3b8\"/>\n    <text x=\"185\" y=\"164\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\">1/V</text>\n    <line x1=\"20\" y1=\"160\" x2=\"20\" y2=\"10\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n    <polygon points=\"20,10 16,18 24,18\" fill=\"#94a3b8\"/>\n    <text x=\"15\" y=\"8\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\">p</text>\n    <text x=\"10\" y=\"172\" fill=\"#94a3b8\" font-size=\"11\">O</text>\n    <!-- Straight line through O -->\n    <line x1=\"20\" y1=\"160\" x2=\"160\" y2=\"45\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n    <text x=\"165\" y=\"45\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"700\">T₂</text>\n    <line x1=\"20\" y1=\"160\" x2=\"160\" y2=\"85\" stroke=\"#06b6d4\" stroke-width=\"2.5\"/>\n    <text x=\"165\" y=\"85\" fill=\"#06b6d4\" font-size=\"11\" font-weight=\"700\">T₁</text>\n    <text x=\"95\" y=\"182\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"700\" text-anchor=\"middle\">Đồ thị p theo 1/V (Đoạn thẳng)</text>\n  </g>\n</svg>"},{"q":"Biểu thức toán học nào sau đây mô tả đúng <b>Định luật Boyle</b> đối với một lượng khí lí tưởng xác định ở nhiệt độ không đổi?","opts":["p · V = hằng số.","<span class=\"fraction\"><span class=\"numerator\">p</span><span class=\"denominator\">V</span></span> = hằng số.","<span class=\"fraction\"><span class=\"numerator\">V</span><span class=\"denominator\">T</span></span> = hằng số.","<span class=\"fraction\"><span class=\"numerator\">p</span><span class=\"denominator\">T</span></span> = hằng số."],"ans":0,"exp":"• <b>Định luật Boyle:</b> Ở nhiệt độ không đổi, tích của áp suất <span class=\"math-sym\">p</span> và thể tích <span class=\"math-sym\">V</span> của một khối lượng khí xác định là một hằng số: <span class=\"math-sym\">p · V</span> = const.","svgGraph":null},{"q":"Một khối khí lí tưởng có thể tích ban đầu là 8,0 lít ở áp suất 1,5 bar. Nếu nén đẳng nhiệt khối khí này đến khi áp suất đạt 4,0 bar thì thể tích của khối khí khi đó là:","opts":["3,0 lít.","2,5 lít.","4,5 lít.","6,0 lít."],"ans":0,"exp":"• <b>Áp dụng định luật Boyle:</b> <span class=\"math-sym\">p</span><sub>1</sub><span class=\"math-sym\">V</span><sub>1</sub> = <span class=\"math-sym\">p</span><sub>2</sub><span class=\"math-sym\">V</span><sub>2</sub>.<br>• <span class=\"math-sym\">V</span><sub>2</sub> = <span class=\"fraction\"><span class=\"numerator\">p₁ · V₁</span><span class=\"denominator\">p₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">1,5 × 8,0</span><span class=\"denominator\">4,0</span></span> = <b>3,0 lít</b>.","svgGraph":null},{"q":"Một bọt khí nổi lên từ đáy một hồ nước sâu 10 m lên tới mặt nước. Coi nhiệt độ của nước là như nhau ở mọi độ sâu và áp suất khí quyển là 1,0 · 10⁵ Pa. Lấy g = 9,8 m/s² và khối lượng riêng của nước là 1000 kg/m³. Thể tích của bọt khí khi lên tới mặt nước so với ở đáy hồ sẽ:","opts":["Tăng gần gấp 2 lần.","Giảm đi một nửa.","Không đổi.","Tăng gần gấp 4 lần."],"ans":0,"exp":"• Áp suất ở đáy hồ: <span class=\"math-sym\">p</span><sub>1</sub> = <span class=\"math-sym\">p</span><sub>0</sub> + <span class=\"math-sym\">ρgh</span> = 10⁵ + 1000 × 9,8 × 10 = 1,98 · 10⁵ Pa ≈ 2<span class=\"math-sym\">p</span><sub>0</sub>.<br>• Khi lên mặt nước, áp suất chỉ còn <span class=\"math-sym\">p</span><sub>2</sub> = <span class=\"math-sym\">p</span><sub>0</sub> = 1,0 · 10⁵ Pa.<br>• Vì nhiệt độ không đổi: <span class=\"math-sym\">V</span><sub>2</sub> = <span class=\"math-sym\">V</span><sub>1</sub> · (<span class=\"math-sym\">p</span><sub>1</sub>/<span class=\"math-sym\">p</span><sub>2</sub>) ≈ 2<span class=\"math-sym\">V</span><sub>1</sub> (thể tích bọt khí tăng xấp xỉ gấp đôi).","svgGraph":null},{"q":"Trong động tác hít vào của con người, cơ hoành hạ xuống và các cơ liên sườn co lại làm thể tích lồng ngực (phổi) tăng lên. Dựa vào định luật Boyle (coi nhiệt độ cơ thể không đổi), hãy giải thích tại sao không khí từ môi trường ngoài lại tràn vào phổi?","opts":["Thể tích phổi tăng làm áp suất khí trong phổi giảm xuống thấp hơn áp suất khí quyển, khiến không khí ngoài tràn vào.","Thể tích phổi tăng làm áp suất khí trong phổi tăng mạnh, tạo lực hút kéo không khí bên ngoài vào.","Nhiệt độ trong phổi tăng đột ngột làm không khí bên ngoài bị hút vào để cân bằng nhiệt độ.","Thể tích phổi tăng làm tăng khối lượng riêng của chất khí trong phổi tạo chênh lệch trọng lực."],"ans":0,"exp":"• <b>Cơ chế hô hấp theo Định luật Boyle:</b> Quá trình hô hấp diễn ra ở nhiệt độ cơ thể không đổi (T = const). Khi hít vào, cơ hoành hạ xuống và các cơ liên sườn co lại làm tăng thể tích lồng ngực (V tăng). Theo định luật Boyle, áp suất khí trong phổi giảm xuống thấp hơn áp suất khí quyển (p < p<sub>kh</sub>í quyển), khiến không khí tự động tràn vào phổi.<br>• Khi thở ra, cơ hoành nâng lên làm giảm thể tích lồng ngực (V giảm), áp suất trong phổi tăng cao hơn bên ngoài (p > p<sub>kh</sub>í quyển), đẩy khí CO₂ ra ngoài.","svgGraph":null},{"q":"Tại sao khi nén khí trong thí nghiệm kiểm chứng định luật Boyle, ta phải dịch chuyển pit-tông một cách thật chậm rãi?","opts":["Để nhiệt lượng sinh ra do ma sát và nén khí kịp truyền ra môi trường, đảm bảo nhiệt độ của khối khí không đổi.","Để tránh làm vỡ áp kế đo áp suất gắn trên xilanh.","Để các phân tử khí có đủ thời gian biến mất khỏi xilanh.","Để thể tích khí luôn giữ cố định không đổi trong quá trình nén."],"ans":0,"exp":"• <b>Kỹ năng thực hành:</b> Khi nén nhanh, công cơ học biến thành nội năng làm chất khí nóng lên (<span class=\"math-sym\">T</span> tăng, quá trình đoạn nhiệt).<br>• Do đó phải nén <b>rất chậm</b> để chất khí kịp trao đổi nhiệt với môi trường, giữ nhiệt độ <span class=\"math-sym\">T</span> ổn định.","svgGraph":null}],"10":[{"q":"Quá trình biến đổi trạng thái của một lượng khí xác định trong đó <b>áp suất được giữ không đổi</b> được gọi là:","opts":["Quá trình đẳng áp.","Quá trình đẳng nhiệt.","Quá trình đẳng tích.","Quá trình đoạn nhiệt."],"ans":0,"exp":"• <b>Định nghĩa:</b> Quá trình biến đổi trạng thái khi áp suất <span class=\"math-sym\">p</span> không đổi gọi là quá trình đẳng áp.","svgGraph":null},{"q":"Hệ thức nào sau đây mô tả đúng mối quan hệ giữa thể tích V và nhiệt độ tuyệt đối T trong <b>Định luật Charles</b>?","opts":["<span class=\"fraction\"><span class=\"numerator\">V</span><span class=\"denominator\">T</span></span> = hằng số (hay <span class=\"fraction\"><span class=\"numerator\">V₁</span><span class=\"denominator\">T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">V₂</span><span class=\"denominator\">T₂</span></span>).","V · T = hằng số.","<span class=\"fraction\"><span class=\"numerator\">V</span><span class=\"denominator\">t</span></span> = hằng số (với t là nhiệt độ Celsius).","p · V = hằng số."],"ans":0,"exp":"• <b>Định luật Charles:</b> Trong quá trình đẳng áp của một lượng khí xác định, thể tích tỉ lệ thuận với nhiệt độ tuyệt đối: <span class=\"math-sym\">V / T</span> = const.","svgGraph":null},{"q":"Một khối khí lí tưởng có thể tích 4,5 lít ở nhiệt độ 27°C. Khi nung nóng đẳng áp khối khí đó đến nhiệt độ 127°C thì thể tích của khối khí sẽ là:","opts":["6,0 lít.","5,5 lít.","7,5 lít.","9,0 lít."],"ans":0,"exp":"• <b>Đổi sang thang Kelvin:</b><br>• <span class=\"math-sym\">T</span><sub>1</sub> = 27 + 273 = 300 K.<br>• <span class=\"math-sym\">T</span><sub>2</sub> = 127 + 273 = 400 K.<br>• <span class=\"math-sym\">V</span><sub>2</sub> = <span class=\"math-sym\">V</span><sub>1</sub> · <span class=\"fraction\"><span class=\"numerator\">T₂</span><span class=\"denominator\">T₁</span></span> = 4,5 × <span class=\"fraction\"><span class=\"numerator\">400</span><span class=\"denominator\">300</span></span> = <b>6,0 lít</b>.","svgGraph":null},{"q":"Một quả bóng bay chứa khí hidro để ngoài trời nắng to bị căng phồng lên và có thể bị nổ. Hiện tượng này được giải thích chủ yếu bằng:","opts":["Khi nhiệt độ tăng, khí trong bóng giãn nở làm tăng thể tích và áp suất lên màng bóng theo định luật Charles.","Màng cao su của bóng bay bị co lại khi gặp nhiệt độ cao.","Áp suất khí quyển bên ngoài quả bóng tăng đột ngột.","Khí hidro phản ứng hóa học tự cháy với màng cao su."],"ans":0,"exp":"• Khi nhiệt độ ngoài trời tăng cao, khí bên trong nhận nhiệt và dãn nở đẳng áp hoặc tăng áp suất tác dụng lên thành cao su, vượt quá giới hạn đàn hồi gây nổ.","svgGraph":null},{"q":"Một quả bóng bàn vô tình bị giẫm bẹp một phần nhưng vỏ bóng chưa bị rách thủng. Khi nhúng quả bóng đó vào trong một cốc nước sôi, vỏ bóng phồng trở lại như cũ. Hiện tượng này được giải thích dựa trên cơ sở vật lí nào sau đây?","opts":["Nhiệt độ không khí bên trong bóng tăng lên làm khối khí dãn nở đẳng áp, tăng thể tích đẩy vỏ bóng phồng lại.","Nước nóng thấm qua lớp vỏ nhựa làm tăng lượng phân tử khí chứa bên trong quả bóng bàn.","Nhiệt độ cao làm vỏ bóng bàn bằng chất dẻo co rút mạnh ép không khí dồn vào tâm quả bóng.","Áp suất của nước nóng bên ngoài ép đều vào vỏ bóng từ mọi phía làm phục hồi hình cầu ban đầu."],"ans":0,"exp":"• <b>Ứng dụng Định luật Charles:</b> Khi nhúng bóng vào nước sôi, áp suất khí bên trong coi như xấp xỉ áp suất khí quyển (p ≈ const). Khi nhiệt độ tăng từ T₁ lên T₂, theo định luật Charles: <span class=\"fraction\"><span class=\"numerator\">V₁</span><span class=\"denominator\">T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">V₂</span><span class=\"denominator\">T₂</span></span> nên thể tích khí tăng tỉ lệ thuận, khí nở ra tạo áp lực đẩy vỏ bóng phồng căng trở lại như cũ.<br>• Lưu ý: Phương pháp này chỉ áp dụng thành công khi vỏ bóng bàn chưa bị thủng hoặc rách nứt.","svgGraph":null},{"q":"Khinh khí cầu du lịch có thể bay lơ lửng và nâng giỏ chở người lên không trung nhờ đầu đốt gas đặt dưới đáy quả khí cầu. Nguyên lí vật lí chủ yếu của hoạt động này là gì?","opts":["Đốt nóng làm không khí trong khí cầu dãn nở, khối lượng riêng giảm nhỏ hơn không khí lạnh xung quanh, tạo lực nâng Ác-si-mét.","Ngọn lửa đốt tạo ra dòng khí phản lực phụt thẳng xuống mặt đất đẩy khinh khí cầu bay lên như tên lửa.","Khí nóng bên trong khí cầu biến đổi hóa học thành khí hydrogen có khối lượng siêu nhẹ.","Đầu đốt gas tích điện dương cho khí cầu tạo lực đẩy tĩnh điện với bề mặt Trái Đất."],"ans":0,"exp":"• <b>Nguyên lí bay của khinh khí cầu:</b> Quá trình đốt nóng không khí bên trong khoang mở ở đáy diễn ra ở áp suất khí quyển coi như không đổi (p = const).<br>• Theo định luật Charles, khi đốt nóng, không khí trong khí cầu nở ra. Vì khối lượng riêng ρ = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">V</span></span> nên khối lượng riêng của không khí nóng nhỏ hơn không khí lạnh bên ngoài (ρ<sub>n</sub>óng < ρ_lạnh).<br>• Theo định luật Archimedes, lực đẩy Archimedes F<sub>A</sub> = ρ_lạnh · V · g lớn hơn tổng trọng lực của khí cầu và khoang tải, giúp khinh khí cầu bay lên.","svgGraph":null}],"11":[{"q":"Phương trình trạng thái của một lượng khí lí tưởng xác định (phương trình Clapeyron) được viết dưới dạng nào sau đây?","opts":["<span class=\"fraction\"><span class=\"numerator\">p₁ · V₁</span><span class=\"denominator\">T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂ · V₂</span><span class=\"denominator\">T₂</span></span> = hằng số.","p₁ · V₁ · T₁ = p₂ · V₂ · T₂.","<span class=\"fraction\"><span class=\"numerator\">p₁ · T₁</span><span class=\"denominator\">V₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂ · T₂</span><span class=\"denominator\">V₂</span></span>.","<span class=\"fraction\"><span class=\"numerator\">p₁</span><span class=\"denominator\">V₁ · T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂</span><span class=\"denominator\">V₂ · T₂</span></span>."],"ans":0,"exp":"• <b>Phương trình Clapeyron:</b> Đối với một khối lượng khí xác định: <span class=\"fraction\"><span class=\"numerator\">p · V</span><span class=\"denominator\">T</span></span> = const, hay <span class=\"fraction\"><span class=\"numerator\">p₁ · V₁</span><span class=\"denominator\">T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂ · V₂</span><span class=\"denominator\">T₂</span></span>.","svgGraph":null},{"q":"Phương trình Clapeyron – Mendeleev biểu diễn mối quan hệ giữa áp suất p, thể tích V, nhiệt độ tuyệt đối T và số mol n của khí lí tưởng là:","opts":["p · V = n · R · T (với R = 8,31 J/(mol·K)).","p · V = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">M</span></span> · k · T.","p · T = n · R · V.","<span class=\"fraction\"><span class=\"numerator\">p · V</span><span class=\"denominator\">T</span></span> = n · k."],"ans":0,"exp":"• <b>Phương trình Clapeyron - Mendeleev:</b> <span class=\"math-sym\">p · V</span> = <span class=\"math-sym\">n · R · T</span> = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">M</span></span><span class=\"math-sym\">R · T</span>.<br>• Trong đó <span class=\"math-sym\">R ≈ 8,31</span> J/(mol·K) là hằng số khí lí tưởng.","svgGraph":null},{"q":"Trong cấp cứu y tế, một bình thép chuyên dụng có dung tích 10 lít chứa khí oxygen (O₂) ở nhiệt độ 27°C và áp suất cao 150 atm. Coi oxygen là khí lí tưởng (M = 32 g/mol, R = 0,0821 atm·L/(mol·K)), khối lượng khí oxygen chứa trong bình là:","opts":["Khoảng 1,95 kg.","Khoảng 3,90 kg.","Khoảng 0,98 kg.","Khoảng 5,85 kg."],"ans":0,"exp":"• <b>Áp dụng phương trình Clapeyron - Mendeleev:</b><br>p · V = n · R · T = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">M</span></span> · R · T ⟹ m = <span class=\"fraction\"><span class=\"numerator\">p · V · M</span><span class=\"denominator\">R · T</span></span>.<br>• Với p = 150 atm, V = 10 L, T = 27 + 273 = 300 K, M = 32 g/mol:<br>m = <span class=\"fraction\"><span class=\"numerator\">150 · 10 · 32</span><span class=\"denominator\">0,0821 · 300</span></span> ≈ 1949 g ≈ 1,95 kg.","svgGraph":null},{"q":"Nồi áp suất là một thiết bị gia dụng giúp ninh nhừ xương và nấu chín thức ăn rất nhanh chóng. Cơ chế vật lí chủ yếu giúp nồi áp suất rút ngắn thời gian nấu nướng là gì?","opts":["Van kín giữ thể tích không đổi; khi nhiệt độ tăng, áp suất tăng cao làm nhiệt độ sôi của nước tăng vượt quá 100°C.","Nắp kín giữ nhiệt giúp thức ăn hấp thụ 100% nhiệt lượng mà không bị tỏa ra môi trường xung quanh.","Áp suất hơi rất cao tác dụng lực cơ học trực tiếp bẻ gãy cấu trúc liên kết sợi của thực phẩm.","Các phân tử hơi nước va chạm với vận tốc ánh sáng làm phân rã các tế bào thực phẩm nhanh hơn."],"ans":0,"exp":"• <b>Nguyên lí nồi áp suất:</b> Khi nấu trong nồi áp suất đậy kín có gioăng cao su, thể tích không đổi (V ≈ const). Nước sôi hóa hơi làm áp suất trong nồi tăng vọt lên khoảng 1,5 - 2 atm.<br>• Nhiệt độ sôi của chất lỏng phụ thuộc thuận vào áp suất mặt thoáng: Áp suất càng cao thì nhiệt độ sôi của nước càng tăng (lên tới 115 - 120°C). Nước sôi ở nhiệt độ cao truyền nhiệt nhanh gấp nhiều lần, giúp thức ăn chín nhừ nhanh chóng và tiết kiệm tới 70% thời gian cũng như năng lượng đun nấu.","svgGraph":null},{"q":"Trước khi lên đường cao tốc vào buổi sáng se lạnh (20°C), bác tài xế đo áp suất lốp xe là 2,2 bar. Sau khi chạy tốc độ cao liên tục vào giữa trưa nắng, nhiệt độ không khí trong lốp xe tăng lên đến 60°C. Coi thể tích lốp xe dãn nở không đáng kể. Áp suất khí trong lốp lúc này là:","opts":["2,50 bar.","2,85 bar.","2,35 bar.","3,10 bar."],"ans":0,"exp":"• Coi thể tích không đổi (đẳng tích): <span class=\"math-sym\">T</span><sub>1</sub> = 20 + 273 = 293 K; <span class=\"math-sym\">T</span><sub>2</sub> = 60 + 273 = 333 K.<br>• <span class=\"math-sym\">p</span><sub>2</sub> = <span class=\"math-sym\">p</span><sub>1</sub> · (<span class=\"math-sym\">T</span><sub>2</sub>/<span class=\"math-sym\">T</span><sub>1</sub>) = 2,2 × (<span class=\"fraction\"><span class=\"numerator\">333</span><span class=\"denominator\">293</span></span>) ≈ <b>2,50 bar</b>.","svgGraph":null},{"q":"Khối lượng riêng của không khí ở điều kiện tiêu chuẩn (0°C và 1,013 · 10⁵ Pa) là 1,29 kg/m³. Ở nhiệt độ 100°C và áp suất 2,026 · 10⁵ Pa, khối lượng riêng của không khí xấp xỉ bằng:","opts":["1,89 kg/m³.","2,58 kg/m³.","1,45 kg/m³.","0,95 kg/m³."],"ans":0,"exp":"• Áp dụng công thức: <span class=\"math-sym\">ρ</span> = <span class=\"fraction\"><span class=\"numerator\">pM</span><span class=\"denominator\">RT</span></span> ⇒ <span class=\"fraction\"><span class=\"numerator\">ρ₂</span><span class=\"denominator\">ρ₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂</span><span class=\"denominator\">p₁</span></span> · <span class=\"fraction\"><span class=\"numerator\">T₁</span><span class=\"denominator\">T₂</span></span>.<br>• <span class=\"math-sym\">ρ</span><sub>2</sub> = 1,29 × (2,<span class=\"fraction\"><span class=\"numerator\">026</span><span class=\"denominator\">1</span></span>,013) × (<span class=\"fraction\"><span class=\"numerator\">273</span><span class=\"denominator\">373</span></span>) = 1,29 × 2 × 0,732 ≈ <b>1,89 kg/m³</b>.","svgGraph":null}],"12":[{"q":"Biểu thức nào sau đây thể hiện mối liên hệ giữa áp suất p của khí lí tưởng với mật độ phân tử n₀ và động năng tịnh tiến trung bình Ed của phân tử?","opts":["p = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">3</span></span> · n₀ · Ed.","p = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">3</span></span> · n₀ · Ed.","p = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> · n₀ · Ed.","p = n₀ · k · Ed."],"ans":0,"exp":"• <b>Hệ thức cơ bản:</b> <span class=\"math-sym\">p</span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">3</span></span><span class=\"math-sym\">n</span><sub>0</sub><span class=\"math-sym\">m</span><span class=\"math-sym\">v²</span> = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">3</span></span><span class=\"math-sym\">n</span><sub>0</sub>(<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span><span class=\"math-sym\">m</span><span class=\"math-sym\">v²</span>) = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">3</span></span><span class=\"math-sym\">n</span><sub>0</sub><span class=\"math-sym\">E</span><sub>d</sub>.","svgGraph":null},{"q":"Động năng tịnh tiến trung bình của phân tử khí lí tưởng tỉ lệ thuận với nhiệt độ tuyệt đối T theo hệ thức:","opts":["Ed = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> · k · T (với k là hằng số Boltzmann).","Ed = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · k · T.","Ed = 3 · k · T.","Ed = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> · R · T."],"ans":0,"exp":"• <b>Mối quan hệ giữa động năng và nhiệt độ:</b> <span class=\"math-sym\">E</span><sub>d</sub> = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span><span class=\"math-sym\">kT</span>.<br>• Trong đó <span class=\"math-sym\">k ≈ 1,38 · 10⁻²³</span> J/K là hằng số Boltzmann.","svgGraph":null},{"q":"Hằng số Boltzmann k liên hệ với hằng số khí lí tưởng R và số Avogadro NA theo biểu thức nào?","opts":["k = <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">N<sub>A</sub></span></span>.","k = R · N<sub>A</sub>.","k = <span class=\"fraction\"><span class=\"numerator\">N<sub>A</sub></span><span class=\"denominator\">R</span></span>.","k = <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">2N<sub>A</sub></span></span>."],"ans":0,"exp":"• <b>Định nghĩa hằng số Boltzmann:</b> <span class=\"math-sym\">k</span> = <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">N<sub>A</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">8,31</span><span class=\"denominator\">6,022 · 10²³</span></span> ≈ 1,38 · 10⁻²³ J/K.","svgGraph":null},{"q":"Dựa vào mô hình động học phân tử chất khí, hãy giải thích tại sao khi giữ thể tích bình chứa không đổi, nếu ta tăng nhiệt độ của khối khí thì áp suất khí tác dụng lên thành bình lại tăng lên?","opts":["Nhiệt độ tăng làm tốc độ và động năng phân tử tăng, phân tử va chạm vào thành bình thường xuyên hơn và mạnh hơn.","Nhiệt độ tăng làm số lượng phân tử khí bên trong bình tự sinh thêm nhiều hơn làm tăng mật độ.","Nhiệt độ tăng làm kích thước của từng phân tử khí nở to ra chiếm nhiều không gian thể tích hơn.","Nhiệt độ tăng làm lực hút tĩnh điện giữa phân tử khí với thành bình tăng lên đột ngột."],"ans":0,"exp":"• <b>Giải thích vi mô về áp suất:</b> Áp suất chất khí tác dụng lên thành bình là kết quả của vô số va chạm của các phân tử khí vào thành bình trong mỗi giây.<br>• Khi nhiệt độ tăng, các phân tử chuyển động nhanh hơn, va chạm vào thành bình thường xuyên hơn và mạnh hơn làm tăng áp suất.<br>• Công thức p = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">3</span></span> · n₀ · m · v² cho thấy áp suất tỉ lệ với mật độ phân tử n₀ và động năng trung bình của phân tử.","svgGraph":null},{"q":"Động năng tịnh tiến trung bình của một phân tử khí ở nhiệt độ 27°C xấp xỉ bằng bao nhiêu? Lấy k = 1,38 · 10⁻²³ J/K.","opts":["6,21 · 10⁻²¹ J.","4,14 · 10⁻²¹ J.","8,28 · 10⁻²¹ J.","5,58 · 10⁻²¹ J."],"ans":0,"exp":"• <span class=\"math-sym\">T</span> = 27 + 273 = 300 K.<br>• <span class=\"math-sym\">E</span><sub>d</sub> = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span><span class=\"math-sym\">kT</span> = 1,5 × 1,38 · 10⁻²³ × 300 = <b>6,21 · 10⁻²¹ J</b>.","svgGraph":null},{"q":"Bầu khí quyển Trái Đất giữ lại được các khí như oxygen (O₂) và nitrogen (N₂), nhưng hầu như không giữ được các khí nhẹ như hydrogen (H₂) và helium (He). Nguyên nhân vật lí cơ bản là do:","opts":["Ở cùng nhiệt độ, phân tử H₂ và He có khối lượng nhỏ nên tốc độ căn quân phương rất lớn, dễ vượt tốc độ vũ trụ cấp I để thoát ly.","Khí H₂ và He bị từ trường Trái Đất tạo lực từ đẩy ngược ra ngoài không gian liên hành tinh.","Tầng ôzôn phản xạ hoàn toàn và chỉ cho phép khí nặng đi qua vào khí quyển.","Lực hấp dẫn của Trái Đất chỉ tác dụng lên các chất khí có khối lượng phân tử lớn hơn 20 g/mol."],"ans":0,"exp":"• <b>Tốc độ căn quân phương:</b> v<sub>rms</sub> = √(<span class=\"fraction\"><span class=\"numerator\">3RT</span><span class=\"denominator\">M</span></span>). Phân tử khí hydro (H₂, khối lượng mol M = 2 g/mol) có khối lượng phân tử nhẹ hơn rất nhiều so với oxy (O₂, M = 32 g/mol) và nitơ (N₂, M = 28 g/mol).<br>• Ở cùng nhiệt độ, tốc độ chuyển động nhiệt của phân tử hydro rất lớn (cỡ 1,9 km/s), lớn hơn tốc độ thoát ly của Trái Đất đối với các phân tử ở tầng cao khí quyển. Trải qua hàng tỉ năm, hầu hết các phân tử hydro nhẹ đã bay thoát khỏi trường hấp dẫn của Trái Đất vào không gian vũ trụ.","svgGraph":null},{"q":"Theo mô hình động học phân tử chất khí và nhiệt động lực học cổ điển, 'Độ không tuyệt đối' (0 K, ứng với -273,15°C) có ý nghĩa vật lí sâu sắc là gì?","opts":["Nhiệt độ lí thuyết mà tại đó động năng tịnh tiến trung bình của các phân tử khí bằng 0, mọi chuyển động nhiệt đều ngừng lại.","Nhiệt độ mà tại đó tất cả các chất khí thực đều chuyển thành chất khí lí tưởng hoàn hảo.","Nhiệt độ mà tại đó khối lượng của chất khí tăng lên đến giá trị vô cùng lớn.","Nhiệt độ mà tại đó nước tinh khiết bắt đầu đóng băng ở áp suất tiêu chuẩn 1 atm."],"ans":0,"exp":"• <b>Ý nghĩa của 0 K:</b> Từ công thức E<sub>d</sub> = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> · k · T, khi nhiệt độ tuyệt đối T → 0 K, động năng chuyển động nhiệt tịnh tiến trung bình của các phân tử tiệm cận tới 0. Khi đó, về mặt lí thuyết cổ điển, mọi chuyển động nhiệt của phân tử đều dừng lại.<br>• Theo nguyên lí thứ ba của nhiệt động lực học (Định luật Nernst), không thể bằng bất kì quá trình hữu hạn nào làm hạ nhiệt độ của một hệ vật chất xuống đúng 0 K (Độ không tuyệt đối chỉ là giới hạn lí thuyết).","svgGraph":null}],"13":[{"q":"Trong một chu trình biến đổi khép kín (chu trình kín) của chất khí lí tưởng, sau khi đi hết một vòng kín và trở về trạng thái ban đầu thì biến thiên nội năng ΔU của khối khí bằng:","opts":["Bằng 0.","Luôn có giá trị dương.","Luôn có giá trị âm.","Bằng tổng công sinh ra trong chu trình."],"ans":0,"exp":"• <b>Nội năng là hàm của trạng thái:</b> Vì trạng thái cuối trùng với trạng thái đầu (<span class=\"math-sym\">T</span><sub>cuối</sub> = <span class=\"math-sym\">T</span><sub>đầu</sub>) nên biến thiên nội năng: <b>ΔU = 0</b>.","svgGraph":null},{"q":"Theo ý nghĩa hình học, công toàn phần A' mà khối khí sinh ra trong một chu trình kín thuận chiều kim đồng hồ trên hệ tọa độ (p, V) được xác định bằng:","opts":["Diện tích của hình phẳng được bao quanh bởi chu trình đó trên giản đồ (p, V).","Chu vi của đường cong chu trình kín.","Độ dài trục hoành của chu trình.","Tích của áp suất lớn nhất và thể tích lớn nhất của chu trình."],"ans":0,"exp":"• <b>Ý nghĩa hình học của công:</b> Công <span class=\"math-sym\">A'</span> mà khí sinh ra trong chu trình bằng diện tích hình giới hạn bởi chu trình trên giản đồ <span class=\"math-sym\">(p, V)</span>.","svgGraph":null},{"q":"Hai bình kín dung tích V₁ = 2,0 lít và V₂ = 3,0 lít chứa cùng một loại khí ở cùng nhiệt độ, áp suất ban đầu lần lượt là p₁ = 1,0 atm và p₂ = 2,0 atm. Nối hai bình bằng một ống nhỏ có khóa, mở khóa để hai bình thông nhau và giữ nhiệt độ không đổi. Áp suất của hỗn hợp khí khi cân bằng là:","opts":["1,6 atm.","1,5 atm.","1,8 atm.","1,4 atm."],"ans":0,"exp":"• Bảo toàn số mol khí (nhiệt độ T không đổi): <span class=\"math-sym\">pV</span><sub>chung</sub> = <span class=\"math-sym\">p</span><sub>1</sub><span class=\"math-sym\">V</span><sub>1</sub> + <span class=\"math-sym\">p</span><sub>2</sub><span class=\"math-sym\">V</span><sub>2</sub>.<br>• <span class=\"math-sym\">p</span> = <span class=\"fraction\"><span class=\"numerator\">p₁V₁ + p₂V₂</span><span class=\"denominator\">V₁ + V₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">1,0 × 2,0 + 2,0 × 3,0</span><span class=\"denominator\">2,0 + 3,0</span></span> = <span class=\"fraction\"><span class=\"numerator\">8,0</span><span class=\"denominator\">5,0</span></span> = <b>1,6 atm</b>.","svgGraph":null},{"q":"Một quả bóng thám không đo khí tượng chứa khí heli được thả từ mặt đất (p₁ = 1,0 atm, T₁ = 300 K) bay lên cao vào tầng bình lưu. Khi lên tới độ cao trên 30 km, quả bóng bị nổ tung. Nguyên nhân chính là do:","opts":["Càng lên cao áp suất khí quyển ngoài càng giảm mạnh, làm thể tích quả bóng dãn nở vượt giới hạn đàn hồi của vỏ bóng.","Càng lên cao nhiệt độ khí quyển tăng lên hàng nghìn độ C làm khí heli bên trong bốc cháy.","Gió trên tầng cao thổi với vận tốc siêu thanh cọ xát làm rách thủng màng cao su của vỏ bóng.","Lực hấp dẫn của Trái Đất ở độ cao 30 km triệt tiêu hoàn toàn làm vỏ bóng tự phát nổ."],"ans":0,"exp":"• <b>Giải thích theo Phương trình trạng thái:</b> Áp dụng <span class=\"fraction\"><span class=\"numerator\">p₁ · V₁</span><span class=\"denominator\">T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂ · V₂</span><span class=\"denominator\">T₂</span></span>. Thể tích lốp xe coi như gần như không đổi (V ≈ const).<br>• Khi xe chạy đường dài với tốc độ cao, ma sát giữa lốp xe với mặt đường và lực cản sinh nhiệt lớn làm nhiệt độ không khí trong lốp tăng vọt (T tăng). Do thể tích không đổi, áp suất khí nén trong lốp tăng tỉ lệ thuận với nhiệt độ (p tăng). Nếu lốp đã cũ hoặc bị bơm quá căng từ trước, áp suất vượt quá giới hạn chịu lực của vỏ lốp sẽ dẫn tới nổ lốp rất nguy hiểm.","svgGraph":null},{"q":"Người ta dùng bơm tay có thể tích mỗi lần bơm là 100 cm³ để bơm không khí ở áp suất khí quyển 1,0 · 10⁵ Pa vào một quả bóng rổ có thể tích 2,5 lít (coi không đổi). Trước khi bơm, bóng chứa không khí ở áp suất khí quyển. Bỏ qua ma sát và coi nhiệt độ không đổi. Để áp suất khí trong bóng đạt 2,4 · 10⁵ Pa thì số lần bơm tối thiểu là:","opts":["35 lần.","25 lần.","30 lần.","40 lần."],"ans":0,"exp":"• Thể tích khí ban đầu: <span class=\"math-sym\">V</span><sub>1</sub> = <span class=\"math-sym\">V</span><sub>bóng</sub> + <span class=\"math-sym\">n · V</span><sub>bơm</sub> = 2500 + <span class=\"math-sym\">n</span> × 100 (cm³), ở áp suất <span class=\"math-sym\">p</span><sub>1</sub> = 1,0 · 10⁵ Pa.<br>• Sau khi bơm: khí chứa trong bóng thể tích <span class=\"math-sym\">V</span><sub>2</sub> = 2500 cm³ ở áp suất <span class=\"math-sym\">p</span><sub>2</sub> = 2,4 · 10⁵ Pa.<br>• Định luật Boyle: <span class=\"math-sym\">p</span><sub>1</sub><span class=\"math-sym\">V</span><sub>1</sub> = <span class=\"math-sym\">p</span><sub>2</sub><span class=\"math-sym\">V</span><sub>2</sub> ⇒ 1,0 × (2500 + 100<span class=\"math-sym\">n</span>) = 2,4 × 2500 = 6000.<br>• 100<span class=\"math-sym\">n</span> = 3500 ⇒ <span class=\"math-sym\">n</span> = <b>35 lần</b>.","svgGraph":null},{"q":"Một xilanh nằm ngang kín hai đầu, bên trong có một pit-tông cách nhiệt chia xilanh thành hai ngăn bằng nhau, mỗi ngăn có thể tích 3,0 lít chứa khí ở áp suất 1,0 atm và 27°C. Đun nóng một ngăn lên đến 127°C và giữ nguyên ngăn kia ở 27°C. Pit-tông dịch chuyển sang phía ngăn lạnh cho đến khi áp suất hai bên bằng nhau. Thể tích ngăn nóng lúc này là:","opts":["3,43 lít.","3,60 lít.","3,25 lít.","3,75 lít."],"ans":0,"exp":"• Tổng thể tích hai ngăn không đổi: <span class=\"math-sym\">V</span><sub>nóng</sub> + <span class=\"math-sym\">V</span><sub>lạnh</sub> = 6,0 lít.<br>• Khi cân bằng: áp suất hai ngăn bằng nhau <span class=\"math-sym\">p</span><sub>nóng</sub> = <span class=\"math-sym\">p</span><sub>lạnh</sub>.<br>• Số mol mỗi ngăn không đổi: <span class=\"math-sym\">n</span><sub>1</sub> = <span class=\"math-sym\">n</span><sub>2</sub> ⇒ <span class=\"fraction\"><span class=\"numerator\">V<sub>n</sub>óng</span><span class=\"denominator\">T<sub>n</sub>óng</span></span> = <span class=\"fraction\"><span class=\"numerator\">V<sub>l</sub>ạnh</span><span class=\"denominator\">T<sub>l</sub>ạnh</span></span>.<br>• <span class=\"fraction\"><span class=\"numerator\">V<sub>n</sub>óng</span><span class=\"denominator\">400</span></span> = <span class=\"fraction\"><span class=\"numerator\">6,0 - V<sub>n</sub>óng</span><span class=\"denominator\">300</span></span> ⇒ 3<span class=\"math-sym\">V</span><sub>nóng</sub> = 24 - 4<span class=\"math-sym\">V</span><sub>nóng</sub> ⇒ 7<span class=\"math-sym\">V</span><sub>nóng</sub> = 24 ⇒ <span class=\"math-sym\">V</span><sub>nóng</sub> ≈ <b>3,43 lít</b>.","svgGraph":null}],"14":[{"q":"Từ trường là một dạng vật chất đặc biệt tồn tại trong không gian xung quanh:","opts":["Nam châm, các hạt mang điện chuyển động hoặc dòng điện.","Chỉ xung quanh các điện tích đứng yên.","Chỉ xung quanh các khối kim loại có nhiệt độ rất cao.","Chỉ xung quanh lõi sắt non được nối đất."],"ans":0,"exp":"• <b>Bản chất từ trường:</b> Từ trường là môi trường vật chất tồn tại xung quanh nam châm, xung quanh dòng điện (các điện tích chuyển động) và tác dụng lực từ lên các nam châm hoặc dòng điện khác đặt trong nó.","svgGraph":null},{"q":"Quy ước về chiều của đường sức từ ở bên ngoài thanh nam châm thẳng là:","opts":["Đi ra từ cực Bắc (N) và đi vào cực Nam (S).","Đi ra từ cực Nam (S) và đi vào cực Bắc (N).","Đồng quy về tâm của thanh nam châm.","Phát xuất từ cả hai cực và phân kì ra vô cực."],"ans":0,"exp":"• <b>Quy ước chiều đường sức từ:</b> Ở bên ngoài nam châm, đường sức từ đi ra từ cực Bắc (North) và đi vào cực Nam (South) (khẩu quyết: <i>Ra Bắc vào Nam</i>).","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Bar magnet in center -->\n  <rect x=\"170\" y=\"85\" width=\"60\" height=\"40\" fill=\"#ef4444\" stroke=\"#f87171\" stroke-width=\"1.5\" rx=\"4\"/>\n  <text x=\"200\" y=\"110\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"16\" font-weight=\"800\">N</text>\n  <rect x=\"230\" y=\"85\" width=\"60\" height=\"40\" fill=\"#3b82f6\" stroke=\"#60a5fa\" stroke-width=\"1.5\" rx=\"4\"/>\n  <text x=\"260\" y=\"110\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"16\" font-weight=\"800\">S</text>\n  <!-- Field lines loops -->\n  <!-- Outer top -->\n  <path d=\"M 190,85 C 190,15 270,15 270,85\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"5,2\"/>\n  <polygon points=\"230,23 238,20 238,26\" fill=\"#38bdf8\"/>\n  <!-- Middle top -->\n  <path d=\"M 200,85 C 200,45 260,45 260,85\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <polygon points=\"230,48 238,45 238,51\" fill=\"#38bdf8\"/>\n  <!-- Outer bottom -->\n  <path d=\"M 190,125 C 190,195 270,195 270,125\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"5,2\"/>\n  <polygon points=\"230,187 238,184 238,190\" fill=\"#38bdf8\"/>\n  <!-- Middle bottom -->\n  <path d=\"M 200,125 C 200,165 260,165 260,125\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <polygon points=\"230,162 238,159 238,165\" fill=\"#38bdf8\"/>\n  <!-- Out from N -->\n  <path d=\"M 170,105 L 80,105\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <polygon points=\"110,105 118,101 118,109\" fill=\"#38bdf8\"/>\n  <!-- Into S -->\n  <path d=\"M 290,105 L 380,105\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <polygon points=\"350,105 342,101 342,109\" fill=\"#38bdf8\"/>\n  <!-- Rule caption -->\n  <text x=\"230\" y=\"202\" fill=\"#34d399\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\">Quy ước: Vào cực Nam (S) - Ra cực Bắc (N)</text>\n</svg>"},{"q":"Đặc điểm nào sau đây là <b>đặc trưng phân biệt cơ bản</b> giữa đường sức từ của từ trường và đường sức điện của điện trường tĩnh?","opts":["Đường sức từ luôn là những đường cong khép kín hoặc vô hạn ở hai đầu.","Đường sức từ luôn xuất phát từ điện tích dương và kết thúc ở điện tích âm.","Các đường sức từ có thể cắt nhau tại những điểm có từ trường rất mạnh.","Nơi nào từ trường càng mạnh thì các đường sức từ vẽ càng thưa."],"ans":0,"exp":"• <b>Tính chất xoáy của từ trường:</b> Đường sức từ là những <b>đường cong khép kín</b> (từ trường là trường xoáy, không có điện tích từ riêng rẽ), khác với điện trường tĩnh có đường sức xuất phát từ điện tích dương và kết thúc ở điện tích âm.","svgGraph":null},{"q":"Tương tác nào sau đây <b>không phải</b> là tương tác từ?","opts":["Tương tác hút nhau giữa hai quả cầu tích điện trái dấu đứng yên.","Tương tác giữa hai thanh nam châm đặt gần nhau.","Tương tác giữa một dây dẫn mang dòng điện và một kim nam châm.","Tương tác đẩy nhau giữa hai dòng điện thẳng song song ngược chiều."],"ans":0,"exp":"• Hai điện tích đứng yên tương tác với nhau bằng <b>lực tĩnh điện (lực Coulomb)</b>, không phải lực từ.","svgGraph":null},{"q":"Để phát hiện sự tồn tại của từ trường tại một vị trí trong phòng thí nghiệm, dụng cụ thực nghiệm đơn giản và hiệu quả nhất là dùng:","opts":["Một kim nam châm nhỏ có thể quay tự do quanh trục thẳng đứng (nam châm thử).","Một thanh kim loại bằng nhôm không nhiễm điện.","Một chiếc nhiệt kế rượu.","Một quả cầu tích điện đứng yên."],"ans":0,"exp":"• Nam châm thử sẽ bị lệch khỏi hướng Bắc - Nam địa lí khi đưa vào vùng có từ trường lạ.","svgGraph":null},{"q":"Hai dây dẫn thẳng song song mang dòng điện cùng chiều đặt gần nhau sẽ:","opts":["Hút nhau.","Đẩy nhau.","Không tương tác.","Vừa hút vừa đẩy tuần hoàn."],"ans":0,"exp":"• <b>Quy tắc tương tác dòng điện:</b> Hai dòng điện song song <b>cùng chiều thì hút nhau</b>, <b>ngược chiều thì đẩy nhau</b>.","svgGraph":null}],"15":[{"q":"Độ lớn của lực từ tác dụng lên một đoạn dây dẫn thẳng có chiều dài L mang dòng điện không đổi I đặt trong từ trường đều B được tính bằng công thức:","opts":["F = I · B · L · sinα (với α là góc giữa dây dẫn và vectơ B).","F = I · B · L · cosα.","F = <span class=\"fraction\"><span class=\"numerator\">I · B</span><span class=\"denominator\">L · sinα</span></span>.","F = <span class=\"fraction\"><span class=\"numerator\">B · L</span><span class=\"denominator\">I · cosα</span></span>."],"ans":0,"exp":"• <b>Định luật Ampère:</b> <span class=\"math-sym\">F = I · B · L · sin α</span>. Lực từ đạt cực đại khi dây dẫn vuông góc với đường sức từ (α = 90°).","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <linearGradient id=\"handG\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\"><stop offset=\"0%\" stop-color=\"#4f46e5\"/><stop offset=\"100%\" stop-color=\"#06b6d4\"/></linearGradient>\n  </defs>\n  <!-- Vector F (Thumb, up) -->\n  <g transform=\"translate(180, 25)\">\n    <line x1=\"50\" y1=\"120\" x2=\"50\" y2=\"20\" stroke=\"#f43f5e\" stroke-width=\"4\"/>\n    <polygon points=\"50,10 42,28 58,28\" fill=\"#f43f5e\"/>\n    <text x=\"65\" y=\"25\" fill=\"#f43f5e\" font-size=\"16\" font-weight=\"800\">F (Lực từ)</text>\n    <!-- Vector I (4 fingers, right) -->\n    <line x1=\"50\" y1=\"120\" x2=\"160\" y2=\"120\" stroke=\"#10b981\" stroke-width=\"4\"/>\n    <polygon points=\"170,120 152,112 152,128\" fill=\"#10b981\"/>\n    <text x=\"175\" y=\"125\" fill=\"#10b981\" font-size=\"16\" font-weight=\"800\">I (Dòng điện)</text>\n    <!-- Vector B (Field into palm, perspective dots) -->\n    <circle cx=\"50\" cy=\"120\" r=\"10\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n    <line x1=\"43\" y1=\"113\" x2=\"57\" y2=\"127\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n    <line x1=\"57\" y1=\"113\" x2=\"43\" y2=\"127\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n    <text x=\"35\" y=\"150\" fill=\"#38bdf8\" font-size=\"15\" font-weight=\"800\">B (Cảm ứng từ đi vào lòng bàn tay ⊗)</text>\n  </g>\n  <rect x=\"25\" y=\"30\" width=\"135\" height=\"145\" rx=\"12\" fill=\"rgba(79,70,229,0.15)\" stroke=\"#818cf8\" stroke-width=\"1.5\"/>\n  <text x=\"92\" y=\"55\" fill=\"#818cf8\" font-size=\"13\" font-weight=\"800\" text-anchor=\"middle\">QUY TẮC</text>\n  <text x=\"92\" y=\"73\" fill=\"#818cf8\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\">BÀN TAY TRÁI</text>\n  <text x=\"92\" y=\"105\" fill=\"#cbd5e1\" font-size=\"10\" text-anchor=\"middle\">• Lòng tay hứng B</text>\n  <text x=\"92\" y=\"125\" fill=\"#cbd5e1\" font-size=\"10\" text-anchor=\"middle\">• 4 ngón chỉ chiều I</text>\n  <text x=\"92\" y=\"145\" fill=\"#cbd5e1\" font-size=\"10\" text-anchor=\"middle\">• Ngón cái 90° chỉ F</text>\n</svg>"},{"q":"Đơn vị đo của cảm ứng từ B trong hệ đơn vị chuẩn SI là:","opts":["Tesla (T).","Weber (Wb).","Henry (H).","Volt (V)."],"ans":0,"exp":"• Đơn vị của cảm ứng từ là <b>Tesla (ký hiệu: T)</b>. 1 T = 1 N / (A·m).","svgGraph":null},{"q":"Một đoạn dây dẫn thẳng dài 0,2 m mang dòng điện 5,0 A đặt trong từ trường đều có cảm ứng từ B = 0,4 T. Dây dẫn vuông góc với các đường sức từ. Lực từ tác dụng lên đoạn dây dẫn có độ lớn là:","opts":["0,40 N.","0,20 N.","0,80 N.","0,04 N."],"ans":0,"exp":"• Vì dây vuông góc với từ trường nên sinα = sin 90° = 1.<br>• <span class=\"math-sym\">F = I · B · L</span> = 5,0 × 0,4 × 0,2 = <b>0,40 N</b>.","svgGraph":null},{"q":"Trong đời sống hằng ngày, thiết bị nào sau đây hoạt động dựa trên ứng dụng trực tiếp của lực từ tác dụng lên khung dây dẫn có dòng điện đặt trong từ trường?","opts":["Động cơ điện một chiều trong quạt máy, máy bơm nước và xe đạp điện.","Bình thủy điện giữ nhiệt dùng trong sinh hoạt gia đình.","Ấm đun nước siêu tốc bằng điện trở may-so đốt nóng.","Bóng đèn sợi đốt halogen dùng để chiếu sáng trong nhà."],"ans":0,"exp":"• <b>Ứng dụng của lực từ:</b> Động cơ điện (motor) hoạt động dựa trên tác dụng của lực từ lên các đoạn dây dẫn của khung dây mang dòng điện đặt trong từ trường.<br>• Cặp lực từ tác dụng lên hai cạnh đối diện của khung dây tạo thành một ngẫu lực từ, làm khung dây quay liên tục quanh trục của nó, chuyển hóa điện năng thành cơ năng phục vụ đời sống.","svgGraph":null},{"q":"Nguyên lí phát ra âm thanh của một chiếc loa điện động (loa thùng, tai nghe thông thường) dựa trên hiện tượng vật lí nào sau đây?","opts":["Lực từ tác dụng lên cuộn dây mang dòng âm tần đặt trong từ trường của nam châm, làm cuộn dây và màng loa dao động.","Hiện tượng quang điện giải phóng các hạt electron tự do làm rung chuyển các phân tử không khí.","Lực ma sát cơ học giữa cuộn dây và lõi thép tạo ra âm thanh truyền qua màng loa.","Sự dãn nở vì nhiệt tuần hoàn của màng loa khi có dòng điện chạy qua điện trở."],"ans":0,"exp":"• <b>Nguyên lí loa điện động:</b> Loa điện động gồm một nam châm vĩnh cửu tạo từ trường hướng tâm và một cuộn dây (cuộn âm thanh) gắn liền với màng loa đặt trong khe từ trường.<br>• Khi dòng điện xoay chiều mang tín hiệu âm tần chạy qua cuộn dây, từ trường tác dụng lực từ F<sub>t</sub>ừ lên cuộn dây làm nó dao động dọc theo trục theo phương vuông góc với đường sức từ.<br>• Cuộn dây kéo theo màng loa dao động, nén và dãn các lớp không khí xung quanh, tái tạo sóng âm truyền đến tai người nghe.","svgGraph":null},{"q":"Tàu đệm từ trường (Maglev) có thể di chuyển với vận tốc cực cao (trên 500 km/h) mà vẫn rất êm ái. Đặc điểm vật lí cốt lõi giúp tàu đạt được vận tốc này là:","opts":["Lực từ giữa nam châm siêu dẫn nâng thân tàu lơ lửng trên đường ray, triệt tiêu hoàn toàn ma sát lăn cơ học.","Tàu được trang bị động cơ phản lực đốt cháy nhiên liệu hạt nhân ở đuôi tàu.","Đường ray của tàu được bọc kín và hút chân không tuyệt đối làm giảm lực cản không khí về 0.","Trọng lực của Trái Đất tác dụng lên đoàn tàu bị triệt tiêu hoàn toàn khi tàu đạt tốc độ cao."],"ans":0,"exp":"• <b>Ứng dụng của lực từ trong tàu đệm từ Maglev:</b> Hệ thống nam châm điện siêu dẫn đặt trên thân tàu và đường ray tạo ra lực từ cực mạnh cùng dấu để đẩy tàu nâng bổng lên cách mặt ray khoảng 10 - 15 mm.<br>• Nhờ không có sự tiếp xúc cơ học trực tiếp giữa bánh xe và ray, lực ma sát lăn bị triệt tiêu hoàn toàn, chỉ còn lực cản của không khí.<br>• Điều này giúp tàu Maglev vận hành êm ái, giảm thiểu tiếng ồn và đạt tốc độ siêu cao vượt trội (từ 400 đến trên 600 km/h) mà các đoàn tàu bánh sắt truyền thống khó đạt được.","svgGraph":null}],"16":[{"q":"Từ thông Φ xuyên qua diện tích S của một khung dây phẳng đặt trong từ trường đều B được xác định bởi công thức:","opts":["Φ = B · S · cosα (với α là góc giữa vectơ cảm ứng từ B và vectơ pháp tuyến n của khung dây).","Φ = B · S · sinα.","Φ = <span class=\"fraction\"><span class=\"numerator\">B</span><span class=\"denominator\">S · cosα</span></span>.","Φ = I · B · S."],"ans":0,"exp":"• <b>Định nghĩa từ thông:</b> <span class=\"math-sym\">Φ = B · S · cos α</span>.<br>• Trong đó <span class=\"math-sym\">α = (n, B)</span>. Từ thông có đơn vị là <b>Weber (Wb)</b>.","svgGraph":null},{"q":"Điều kiện cần và đủ để xuất hiện dòng điện cảm ứng trong một mạch kín là:","opts":["Từ thông qua diện tích giới hạn bởi mạch kín phải biến thiên theo thời gian.","Mạch kín phải được đặt trong một từ trường có độ lớn cực đại không đổi.","Khung dây phải được làm bằng chất liệu siêu dẫn.","Từ trường gửi qua mạch kín phải có các đường sức từ hoàn toàn song song."],"ans":0,"exp":"• <b>Hiện tượng cảm ứng điện từ:</b> Dòng điện cảm ứng chỉ xuất hiện trong mạch kín <b>khi và chỉ khi từ thông qua mạch biến thiên</b> theo thời gian.","svgGraph":null},{"q":"Theo <b>Định luật Lenz</b>, dòng điện cảm ứng xuất hiện trong mạch kín có chiều sao cho:","opts":["Từ trường do nó sinh ra có tác dụng chống lại sự biến thiên của từ thông ban đầu gửi qua mạch kín.","Làm cho từ thông qua mạch luôn luôn tăng lên cực đại.","Làm cho khung dây quay theo chiều kim đồng hồ trong mọi trường hợp.","Từ trường cảm ứng luôn luôn cùng chiều với từ trường ban đầu."],"ans":0,"exp":"• <b>Định luật Lenz:</b> Thể hiện tính bảo toàn năng lượng và chống lại nguyên nhân sinh ra nó: Nếu từ thông ban đầu tăng thì từ trường cảm ứng sẽ ngược chiều để chống tăng; nếu từ thông giảm thì từ trường cảm ứng sẽ cùng chiều để chống giảm.","svgGraph":null},{"q":"Một khung dây phẳng có diện tích 20 cm² gồm 100 vòng dây đặt trong từ trường đều có vectơ B vuông góc với mặt phẳng khung. Trong khoảng thời gian 0,02 s, cảm ứng từ giảm đều từ 0,5 T về 0,1 T. Độ lớn của suất điện động cảm ứng xuất hiện trong khung dây là:","opts":["4,0 V.","2,0 V.","8,0 V.","0,4 V."],"ans":0,"exp":"• Vectơ B vuông góc mặt phẳng khung ⇒ cos 0° = 1.<br>• <span class=\"math-sym\">|e</span><sub>c</sub><span class=\"math-sym\">| = N · S ·</span> <span class=\"fraction\"><span class=\"numerator\">|ΔB|</span><span class=\"denominator\">Δt</span></span> = 100 × 20 · 10⁻⁴ × <span class=\"fraction\"><span class=\"numerator\">0,5 - 0,1</span><span class=\"denominator\">0,02</span></span> = 0,2 × 20 = <b>4,0 V</b>.","svgGraph":null},{"q":"Trong hệ thống giao thông hiện đại, phanh điện từ sử dụng dòng điện Fu-cô (Foucault) được trang bị phổ biến trên các đoàn tàu cao tốc (như Shinkansen, TGV). Ưu điểm nổi bật của loại phanh này so với phanh ma sát cơ học là:","opts":["Quá trình hãm phanh êm ái ở tốc độ cao, không mòn đĩa phanh và không phát sinh tia lửa hay bụi ma sát độc hại.","Phanh điện từ có thể dừng đoàn tàu tức thì chỉ trong 0,01 giây mà hoàn toàn không gây gia tốc quán tính.","Phanh điện từ tự động tăng công suất phát điện của động cơ kéo đoàn tàu trong khi hãm.","Phanh điện từ vận hành mà không cần bất kì từ trường nào tác dụng lên đĩa kim loại dẫn điện."],"ans":0,"exp":"• <b>Ứng dụng dòng điện Fu-cô:</b> Khi phanh điện từ hoạt động, một từ trường mạnh được đặt xuyên qua đĩa kim loại gắn với trục bánh xe (hoặc ray dẫn).<br>• Sự quay của đĩa kim loại trong từ trường làm từ thông biến thiên, sinh ra dòng điện xoay tròn Foucault bên trong khối kim loại. Theo định luật Lenz, lực từ tác dụng lên các dòng điện này luôn chống lại nguyên nhân sinh ra nó (chống lại chuyển động quay), tạo ra mômen hãm xe dừng lại mà không hề có sự cọ xát mài mòn cơ học.","svgGraph":null},{"q":"Khi đưa một thanh nam châm dịch chuyển ra xa một cuộn dây dẫn kín, dòng điện cảm ứng xuất hiện trong cuộn dây sẽ có chiều sinh ra từ trường nhằm mục đích:","opts":["Hút thanh nam châm lại gần cuộn dây (chống lại sự dịch chuyển ra xa).","Đẩy thanh nam châm ra xa nhanh hơn nữa.","Triệt tiêu hoàn toàn từ trường của chính thanh nam châm.","Làm nóng cuộn dây đến khi nóng chảy."],"ans":0,"exp":"• <b>Theo định luật Lenz:</b> Dòng điện cảm ứng luôn sinh ra lực từ chống lại chuyển động tương đối. Khi nam châm ra xa, nó sẽ hút lại để ngăn cản sự chuyển động ra xa đó.","svgGraph":null}],"17":[{"q":"Nguyên tắc hoạt động của máy phát điện xoay chiều một pha dựa trên hiện tượng vật lí nào?","opts":["Hiện tượng cảm ứng điện từ.","Hiện tượng tự cảm.","Hiện tượng tỏa nhiệt Joule - Lenz.","Hiện tượng quang điện ngoài."],"ans":0,"exp":"• <b>Nguyên tắc:</b> Máy phát điện xoay chiều hoạt động dựa trên <b>hiện tượng cảm ứng điện từ</b>: khi từ thông qua cuộn dây biến thiên tuần hoàn (do roto quay), trong cuộn dây xuất hiện suất điện động xoay chiều.","svgGraph":null},{"q":"Mối quan hệ giữa giá trị hiệu dụng U và giá trị cực đại (biên độ) U₀ của điện áp xoay chiều hình sin là:","opts":["U = <span class=\"fraction\"><span class=\"numerator\">U₀</span><span class=\"denominator\">√2</span></span>.","U = U₀ · √2.","U = 2 · U₀.","U = <span class=\"fraction\"><span class=\"numerator\">U₀</span><span class=\"denominator\">2</span></span>."],"ans":0,"exp":"• <b>Giá trị hiệu dụng:</b> <span class=\"math-sym\">U</span> = <span class=\"fraction\"><span class=\"numerator\">U₀</span><span class=\"denominator\">√2</span></span> ≈ 0,707 <span class=\"math-sym\">U</span><sub>0</sub>.","svgGraph":null},{"q":"Điện áp xoay chiều của mạng điện sinh hoạt dân dụng tại Việt Nam có giá trị hiệu dụng 220 V và tần số 50 Hz. Giá trị cực đại của điện áp này xấp xỉ bằng:","opts":["311 V.","220 V.","440 V.","155 V."],"ans":0,"exp":"• <span class=\"math-sym\">U</span><sub>0</sub> = <span class=\"math-sym\">U · √2</span> = 220 × 1,414 ≈ <b>311 V</b>.","svgGraph":null},{"q":"Một máy phát điện xoay chiều một pha có roto gồm 4 cặp cực (p = 4). Để máy phát ra dòng điện có tần số chuẩn 50 Hz thì roto phải quay với tốc độ là:","opts":["750 vòng/phút (12,5 vòng/s).","1500 vòng/phút.","3000 vòng/phút.","600 vòng/phút."],"ans":0,"exp":"• <span class=\"math-sym\">f = n · p</span> ⇒ <span class=\"math-sym\">n = <span class=\"fraction\"><span class=\"numerator\">f</span><span class=\"denominator\">p</span></span></span> = <span class=\"fraction\"><span class=\"numerator\">50</span><span class=\"denominator\">4</span></span> = 12,5 vòng/s.<br>• Tính theo vòng/phút: <span class=\"math-sym\">N</span> = 12,5 × 60 = <b>750 vòng/phút</b>.","svgGraph":null},{"q":"Đinamô (dynamo) gắn ở bánh xe đạp dùng để thắp sáng bóng đèn khi đạp xe vào ban đêm. Hoạt động của đinamô xe đạp dựa trên nguyên tắc vật lí nào sau đây?","opts":["Bánh xe quay làm nam châm quay theo trước cuộn dây cố định, làm từ thông qua cuộn dây biến thiên tạo suất điện động cảm ứng.","Bánh xe cọ xát với núm xoay sinh ra hiện tượng nhiễm điện do ma sát truyền điện vào bóng đèn.","Pin hóa học tích hợp bên trong đinamô tự động phát điện khi phát hiện xe chuyển động.","Nhiệt lượng sinh ra do ma sát ở vành bánh xe được chuyển hóa trực tiếp thành quang năng phát sáng."],"ans":0,"exp":"• <b>Cấu tạo và hoạt động của đinamô xe đạp:</b> Đinamô xe đạp là một máy phát điện xoay chiều cỡ nhỏ. Phần cảm là nam châm vĩnh cửu gắn với núm xoay tì vào lốp xe; phần ứng là cuộn dây quấn quanh lõi sắt non cố định trên khung xe.<br>• Khi bánh xe quay, nam châm quay theo làm từ thông Φ(t) qua cuộn dây biến thiên tuần hoàn: Φ(t) = B · S · cos(ωt).<br>• Theo định luật Faraday, trong cuộn dây xuất hiện suất điện động cảm ứng xoay chiều e<sub>c</sub> = -dΦ/dt = ω · B · S · sin(ωt), cung cấp dòng điện làm sáng đèn xe đạp khi đi trong đêm tối.","svgGraph":null},{"q":"Trong hệ thống truyền tải điện lưới quốc gia và các nhà máy công nghiệp, người ta sử dụng phổ biến dòng điện xoay chiều ba pha thay vì dòng một pha chủ yếu là vì:","opts":["Tiết kiệm dây dẫn khi truyền tải điện năng đi xa và dễ dàng tạo ra từ trường quay để vận hành động cơ không đồng bộ 3 pha.","Dòng điện xoay chiều 3 pha có điện áp thấp hơn nên hoàn toàn không gây nguy hiểm điện giật cho con người.","Dòng điện 3 pha không bị tiêu hao năng lượng do tỏa nhiệt Joule trên đường dây truyền tải.","Dòng 3 pha chỉ truyền tải điện theo một chiều duy nhất mà không đổi chiều như dòng 1 pha."],"ans":0,"exp":"• <b>Ưu điểm vượt trội của dòng xoay chiều 3 pha:</b><br>1. <i>Tiết kiệm dây dẫn:</i> Truyền tải điện năng bằng dòng 3 pha tiết kiệm dây dẫn đáng kể so với dòng 1 pha có cùng công suất.<br>2. <i>Tạo từ trường quay:</i> Dòng điện xoay chiều 3 pha chạy vào ba cuộn dây đặt lệch nhau 120° trên stato sẽ tạo ra từ trường quay đồng bộ cực kì mạnh mẽ và ổn định, làm quay rôto của động cơ không đồng bộ 3 pha (loại động cơ chiếm trên 85% tổng công suất động cơ điện trong công nghiệp).","svgGraph":null}],"18":[{"q":"Dòng điện Foucault (dòng điện xoáy) là:","opts":["Dòng điện cảm ứng xuất hiện trong khối vật dẫn kim loại khi khối vật dẫn đó đặt trong từ trường biến thiên hoặc chuyển động cắt đường sức từ.","Dòng điện xoay chiều một pha trong lưới điện quốc gia.","Dòng chuyển dời của các hạt mang điện trong chất bán dẫn tinh khiết.","Dòng điện một chiều phát ra từ các tấm pin Mặt Trời."],"ans":0,"exp":"• <b>Định nghĩa dòng Foucault:</b> Là dòng điện cảm ứng khép kín sinh ra trong <b>khối vật dẫn kim loại</b> khi có sự biến thiên từ thông, gây ra tác dụng nhiệt mạnh hoặc lực cản từ.","svgGraph":null},{"q":"Để giảm thiểu tác hại của dòng điện Foucault làm nóng và gây hao phí năng lượng trong lõi thép của máy biến áp và động cơ điện, người ta thường:","opts":["Ghép lõi thép từ nhiều lá thép kĩ thuật mỏng có phủ sơn cách điện xếp khép kín song song với đường sức từ.","Đúc lõi thép thành một khối kim loại dày nguyên khối bằng đồng nguyên chất.","Tăng cường độ dòng điện đi qua các cuộn dây lên mức tối đa.","Hút chân không hoàn toàn bên trong vỏ máy."],"ans":0,"exp":"• Khi chia lõi thép thành các lá mỏng cách điện, mạch dòng điện xoáy bị chia nhỏ và điện trở tăng lên rất lớn, làm dòng Foucault giảm xuống tối thiểu, giảm hao phí do tỏa nhiệt.","svgGraph":null},{"q":"Một máy biến áp lí tưởng có số vòng dây cuộn sơ cấp là N₁ = 2200 vòng và cuộn thứ cấp là N₂ = 110 vòng. Khi đặt vào hai đầu cuộn sơ cấp điện áp xoay chiều có giá trị hiệu dụng U₁ = 220 V thì điện áp hiệu dụng ở hai đầu cuộn thứ cấp để hở là:","opts":["11 V.","22 V.","44 V.","110 V."],"ans":0,"exp":"• Áp dụng hệ thức biến áp: <span class=\"fraction\"><span class=\"numerator\">U₂</span><span class=\"denominator\">U₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">N₂</span><span class=\"denominator\">N₁</span></span>.<br>• <span class=\"math-sym\">U</span><sub>2</sub> = <span class=\"math-sym\">U</span><sub>1</sub> · <span class=\"fraction\"><span class=\"numerator\">N₂</span><span class=\"denominator\">N₁</span></span> = 220 × <span class=\"fraction\"><span class=\"numerator\">110</span><span class=\"denominator\">2200</span></span> = <b>11 V</b>.","svgGraph":null},{"q":"Một máy biến áp lí tưởng có tỉ số số vòng dây <span class=\"fraction\"><span class=\"numerator\">N₁</span><span class=\"denominator\">N₂</span></span> = 5. Cuộn thứ cấp được nối với một bóng đèn sợi đốt tiêu thụ công suất 44 W ở điện áp 22 V. Cường độ dòng điện hiệu dụng chạy trong cuộn sơ cấp là:","opts":["0,4 A.","2,0 A.","10 A.","0,08 A."],"ans":0,"exp":"• Cường độ dòng thứ cấp: <span class=\"math-sym\">I</span><sub>2</sub> = <span class=\"math-sym\">P / U</span><sub>2</sub> = <span class=\"fraction\"><span class=\"numerator\">44</span><span class=\"denominator\">22</span></span> = 2 A.<br>• Biến áp lí tưởng: <span class=\"fraction\"><span class=\"numerator\">I₁</span><span class=\"denominator\">I₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">N₂</span><span class=\"denominator\">N₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">5</span></span>.<br>• <span class=\"math-sym\">I</span><sub>1</sub> = <span class=\"math-sym\">I</span><sub>2</sub> / 5 = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">5</span></span> = <b>0,4 A</b>.","svgGraph":null},{"q":"Người ta cần truyền tải một công suất điện 1,0 MW từ nhà máy thủy điện đến nơi tiêu thụ bằng đường dây có điện trở tổng cộng R = 20 Ω. Nếu điện áp ở đầu đường dây truyền tải là 50 kV và hệ số công suất cosφ = 1 thì công suất hao phí do tỏa nhiệt trên đường dây là:","opts":["8,0 kW.","4,0 kW.","16 kW.","2,0 kW."],"ans":0,"exp":"• Δ<span class=\"math-sym\">P</span> = <span class=\"fraction\"><span class=\"numerator\">P² · R</span><span class=\"denominator\">U²</span></span> = <span class=\"fraction\"><span class=\"numerator\">(1,0 · 10⁶)² × 20</span><span class=\"denominator\">(50 · 10³)²</span></span> = <span class=\"fraction\"><span class=\"numerator\">2 · 10¹³</span><span class=\"denominator\">2,5 · 10⁹</span></span> = 8000 W = <b>8,0 kW</b>.","svgGraph":null},{"q":"Tại sao các thiết bị phanh điện từ trên xe tải lớn hoặc tàu hỏa chạy đệm từ trường lại không bao giờ bị mòn cơ học như phanh má phanh ma sát truyền thống?","opts":["Vì lực hãm sinh ra hoàn toàn do tương tác từ trường giữa dòng điện Foucault cảm ứng và nam châm mà không cần hai bề mặt tiếp xúc cọ xát trực tiếp.","Vì nhiệt độ làm bốc hơi toàn bộ bề mặt kim loại trước khi chạm vào nhau.","Vì nam châm đẩy xe bay lên không trung.","Vì dòng Foucault làm nguội dầu bôi trơn thành chất siêu rắn."],"ans":0,"exp":"• <b>Ưu điểm vượt trội của phanh điện từ:</b> Lực hãm là lực tương tác từ trường tác dụng từ xa lên dòng xoáy Foucault, không có tiếp xúc cọ xát cơ học nên <b>không bị mòn đĩa phanh và không phát sinh bụi bẩn</b>.","svgGraph":null}],"19":[{"q":"Theo luận điểm nổi tiếng của James Clerk Maxwell, mối quan hệ mật thiết giữa điện trường và từ trường biến thiên là:","opts":["Một từ trường biến thiên theo thời gian sinh ra một điện trường xoáy, và ngược lại một điện trường biến thiên theo thời gian sinh ra một từ trường.","Điện trường biến thiên chỉ sinh ra các hạt electron tự do.","Từ trường biến thiên chỉ xuất hiện khi có dây dẫn kim loại dẫn điện.","Điện trường và từ trường tồn tại hoàn toàn độc lập, không bao giờ có thể tương hỗ sinh ra nhau."],"ans":0,"exp":"• <b>Thuyết điện từ trường Maxwell:</b> Điện trường biến thiên và từ trường biến thiên là hai mặt thống nhất của một thực thể vật lí duy nhất gọi là <b>điện từ trường</b>.","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Axis v (Propagating axis x) -->\n  <line x1=\"40\" y1=\"105\" x2=\"420\" y2=\"105\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n  <polygon points=\"425,105 413,99 413,111\" fill=\"#94a3b8\"/>\n  <text x=\"430\" y=\"110\" fill=\"#94a3b8\" font-size=\"13\" font-weight=\"800\">v</text>\n  <!-- E wave (Vertical, Red/Pink) -->\n  <path d=\"M 60,105 Q 110,25 160,105 Q 210,185 260,105 Q 310,25 360,105\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n  <text x=\"110\" y=\"30\" fill=\"#f43f5e\" font-size=\"14\" font-weight=\"800\">E (Điện trường)</text>\n  <!-- E vectors -->\n  <line x1=\"110\" y1=\"105\" x2=\"110\" y2=\"35\" stroke=\"#f43f5e\" stroke-width=\"1.5\"/><polygon points=\"110,30 106,40 114,40\" fill=\"#f43f5e\"/>\n  <line x1=\"210\" y1=\"105\" x2=\"210\" y2=\"175\" stroke=\"#f43f5e\" stroke-width=\"1.5\"/><polygon points=\"210,180 206,170 214,170\" fill=\"#f43f5e\"/>\n  <!-- B wave (Horizontal perspective, Cyan/Blue) -->\n  <path d=\"M 60,105 Q 110,145 160,105 Q 210,65 260,105 Q 310,145 360,105\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"2.5\" stroke-dasharray=\"4,2\"/>\n  <text x=\"210\" y=\"55\" fill=\"#06b6d4\" font-size=\"14\" font-weight=\"800\">B (Từ trường)</text>\n  <!-- Caption -->\n  <text x=\"230\" y=\"198\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\">Sóng điện từ là sóng ngang: E ⊥ B ⊥ v và cùng pha dao động</text>\n</svg>"},{"q":"Sóng điện từ là:","opts":["Điện từ trường lan truyền trong không gian dưới dạng sóng.","Sóng cơ học lan truyền nhờ sự dao động của các phân tử môi trường.","Chỉ là dòng các hạt proton chuyển động trong chân không.","Dòng các hạt neutron thoát ra từ lò phản ứng hạt nhân."],"ans":0,"exp":"• <b>Định nghĩa sóng điện từ:</b> Là sự lan truyền của điện từ trường trong không gian theo thời gian.","svgGraph":null},{"q":"Đặc điểm nào sau đây là <b>đúng</b> khi nói về sóng điện từ?","opts":["Sóng điện từ là sóng ngang, lan truyền được trong chân không với tốc độ bằng tốc độ ánh sáng c ≈ 3 · 10⁸ m/s.","Sóng điện từ là sóng dọc, không thể lan truyền trong môi trường chân không.","Vectơ cường độ điện trường E và vectơ cảm ứng từ B luôn dao động vuông pha với nhau.","Tốc độ truyền sóng điện từ trong môi trường điện môi luôn lớn hơn tốc độ truyền trong chân không."],"ans":0,"exp":"• <b>Đặc điểm sóng điện từ:</b> Là sóng ngang (<span class=\"math-sym\">E ⊥ B ⊥ v</span>), truyền được trong chân không với tốc độ cực đại <span class=\"math-sym\">c ≈ 3 · 10⁸</span> m/s. Tại mỗi điểm, <span class=\"math-sym\">E</span> và <span class=\"math-sym\">B</span> luôn <b>dao động đồng pha</b>.","svgGraph":null},{"q":"Một sóng điện từ truyền hình phát sóng với tần số f = 100 MHz trong chân không. Biết tốc độ ánh sáng c = 3 · 10⁸ m/s. Bước sóng của sóng điện từ này là:","opts":["3,0 m.","0,3 m.","30 m.","300 m."],"ans":0,"exp":"• <span class=\"math-sym\">λ = <span class=\"fraction\"><span class=\"numerator\">c</span><span class=\"denominator\">f</span></span></span> = <span class=\"fraction\"><span class=\"numerator\">3 · 10⁸</span><span class=\"denominator\">100 · 10⁶</span></span> = <b>3,0 m</b>.","svgGraph":null},{"q":"Lò vi sóng là thiết bị làm nóng và nấu chín thức ăn rất nhanh chóng trong gia đình. Cơ chế vật lí chủ yếu giúp lò vi sóng làm nóng thực phẩm là gì?","opts":["Dùng sóng điện từ tần số khoảng 2,45 GHz làm các phân tử nước phân cực trong thực phẩm dao động mạnh, chuyển năng lượng thành nhiệt.","Dùng dòng điện Fu-cô chạy trực tiếp qua thực phẩm để nung nóng tương tự nguyên lí bếp từ.","Chiếu chùm tia tử ngoại (UV) năng lượng cao làm biến tính nhiệt các protein trong thức ăn.","Dùng nhiệt lượng tỏa ra từ thanh đốt điện trở may-so hồng ngoại gắn trên nóc lò."],"ans":0,"exp":"• <b>Cơ chế vật lí của lò vi sóng:</b> Nước là phân tử phân cực (có cực âm và cực dương). Sóng vi sóng phát ra có tần số 2,45 GHz làm điện trường dao động đảo chiều 2,45 tỉ lần mỗi giây.<br>• Dưới tác dụng của điện trường xoay chiều này, các phân tử nước trong thức ăn liên tục quay đổi hướng với tần số cực cao, cọ xát mãnh liệt vào nhau sinh ra nhiệt lượng lớn từ sâu bên trong khối thức ăn.<br>• Nhờ vậy, thức ăn được làm nóng cực nhanh và chín đều từ trong ra ngoài, tiết kiệm năng lượng hơn nhiều so với việc truyền nhiệt bề mặt của bếp gas hay lò nướng thông thường.","svgGraph":null},{"q":"Sóng wifi gia đình thường hoạt động ở hai dải tần số 2,4 GHz và 5 GHz. Các sóng này thuộc loại bức xạ nào trong thang sóng điện từ?","opts":["Sóng vô tuyến cực ngắn (vi sóng - microwaves).","Bức xạ tia hồng ngoại (infrared).","Bức xạ tia tử ngoại (ultraviolet).","Bức xạ tia X (X-rays)."],"ans":0,"exp":"• <b>Phân loại sóng vô tuyến:</b> Bước sóng của wifi ở tần số f = 2,4 GHz là λ = <span class=\"fraction\"><span class=\"numerator\">c</span><span class=\"denominator\">f</span></span> = <span class=\"fraction\"><span class=\"numerator\">3 · 10⁸</span><span class=\"denominator\">2,4 · 10⁹</span></span> ≈ 0,125 m = 12,5 cm.<br>• Bước sóng này nằm trong dải từ 1 mm đến 1 m, thuộc vùng sóng vi ba (vi sóng) của sóng vô tuyến cực ngắn. Sóng cực ngắn mang lượng thông tin rất lớn, truyền thẳng tốt, thích hợp cho truyền dẫn mạng không dây wifi, thông tin vệ tinh và mạng di động 4G/5G.","svgGraph":null}],"20":[{"q":"Một thanh kim loại chiều dài L chuyển động với vận tốc không đổi v vuông góc với các đường sức từ của một từ trường đều có cảm ứng từ B. Độ lớn của suất điện động cảm ứng xuất hiện giữa hai đầu thanh là:","opts":["ec = B · L · v.","ec = <span class=\"fraction\"><span class=\"numerator\">B · v</span><span class=\"denominator\">L</span></span>.","ec = <span class=\"fraction\"><span class=\"numerator\">B · L</span><span class=\"denominator\">v</span></span>.","ec = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · B · v² · L."],"ans":0,"exp":"• <b>Suất điện động chuyển động:</b> Khi đoạn dây cắt đường sức từ với góc vuông: <span class=\"math-sym\">e</span><sub>c</sub> = <span class=\"math-sym\">B · v · L</span>.","svgGraph":null},{"q":"Một thanh dẫn điện dài 0,5 m chuyển động đều với tốc độ 4,0 m/s trong mặt phẳng vuông góc với từ trường đều B = 0,25 T. Suất điện động cảm ứng xuất hiện giữa hai đầu thanh là:","opts":["0,50 V.","0,25 V.","1,00 V.","0,125 V."],"ans":0,"exp":"• <span class=\"math-sym\">e</span><sub>c</sub> = <span class=\"math-sym\">B · v · L</span> = 0,25 × 4,0 × 0,5 = <b>0,50 V</b>.","svgGraph":null},{"q":"Một khung dây phẳng tròn bán kính r = 10 cm gồm 50 vòng dây quay đều quanh một đường kính nằm trong từ trường đều B = 0,1 T với tốc độ góc ω = 100 rad/s. Trục quay vuông góc với vectơ B. Suất điện động cực đại sinh ra trong khung dây là:","opts":["15,7 V (5π V).","31,4 V (10π V).","7,85 V.","5,0 V."],"ans":0,"exp":"• Diện tích một vòng: <span class=\"math-sym\">S = πr²</span> = π × 0,1² = 0,01π m².<br>• <span class=\"math-sym\">E</span><sub>0</sub> = <span class=\"math-sym\">ω · N · B · S</span> = 100 × 50 × 0,1 × (0,01π) = 5π ≈ <b>15,7 V</b>.","svgGraph":null},{"q":"Một thanh kim loại MN dài 20 cm, khối lượng 40 g đặt trên hai thanh ray nằm ngang nhẵn trong từ trường đều thẳng đứng B = 0,5 T. Nối hai ray với nguồn điện không đổi. Để thanh chuyển động sang phải với gia tốc a = 2,5 m/s² thì cường độ dòng điện chạy qua thanh MN phải là:","opts":["1,0 A.","2,0 A.","0,5 A.","4,0 A."],"ans":0,"exp":"• Lực từ gây gia tốc cho thanh: <span class=\"math-sym\">F = m · a</span> = 0,04 × 2,5 = 0,1 N.<br>• Mà <span class=\"math-sym\">F = I · B · L</span> ⇒ <span class=\"math-sym\">I = F / (B · L)</span> = 0,1 / (0,5 × 0,2) = <b>1,0 A</b>.","svgGraph":null},{"q":"Tại một trạm phát điện, người ta muốn giảm công suất hao phí do tỏa nhiệt trên đường dây truyền tải đi 64 lần mà vẫn giữ nguyên công suất truyền đi và hệ số công suất. Cần phải điều chỉnh tỉ số điện áp ở máy biến áp tăng áp như thế nào?","opts":["Tăng điện áp trước khi truyền tải lên 8 lần.","Tăng điện áp trước khi truyền tải lên 64 lần.","Giảm điện áp trước khi truyền tải đi 8 lần.","Tăng điện áp trước khi truyền tải lên 16 lần."],"ans":0,"exp":"• Vì hao phí tỉ lệ nghịch với <span class=\"math-sym\">U²</span>: <span class=\"fraction\"><span class=\"numerator\">ΔP₁</span><span class=\"denominator\">ΔP₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">U₂²</span><span class=\"denominator\">U₁²</span></span> = 64 ⇒ <span class=\"fraction\"><span class=\"numerator\">U₂</span><span class=\"denominator\">U₁</span></span> = √64 = <b>8 lần</b>.","svgGraph":null},{"q":"Một máy biến áp có số vòng cuộn sơ cấp là 1000 vòng, cuộn thứ cấp là 200 vòng. Cuộn sơ cấp mắc vào điện áp xoay chiều hiệu dụng 220 V. Mạch thứ cấp tiêu thụ dòng điện hiệu dụng 5 A. Hiệu suất của máy biến áp đạt 90%. Cường độ dòng điện hiệu dụng ở cuộn sơ cấp là:","opts":["1,11 A.","1,00 A.","0,90 A.","1,25 A."],"ans":0,"exp":"• Điện áp thứ cấp: <span class=\"math-sym\">U</span><sub>2</sub> = <span class=\"math-sym\">U</span><sub>1</sub> × (<span class=\"fraction\"><span class=\"numerator\">200</span><span class=\"denominator\">1000</span></span>) = 44 V.<br>• Công suất thứ cấp: <span class=\"math-sym\">P</span><sub>2</sub> = <span class=\"math-sym\">U</span><sub>2</sub> · <span class=\"math-sym\">I</span><sub>2</sub> = 44 × 5 = 220 W.<br>• Hiệu suất: <span class=\"math-sym\">H = P₂ / P₁</span> = 0,90 ⇒ <span class=\"math-sym\">P</span><sub>1</sub> = <span class=\"fraction\"><span class=\"numerator\">220</span><span class=\"denominator\">0</span></span>,90 ≈ 244,4 W.<br>• Cường độ dòng sơ cấp: <span class=\"math-sym\">I</span><sub>1</sub> = <span class=\"math-sym\">P</span><sub>1</sub> / <span class=\"math-sym\">U</span><sub>1</sub> = 244,<span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">220</span></span> ≈ <b>1,11 A</b>.","svgGraph":null}],"21":[{"q":"Hạt nhân nguyên tử được cấu tạo từ các hạt cơ bản nào sau đây?","opts":["Các proton mang điện tích dương và các neutron không mang điện (gọi chung là nucleon).","Các electron mang điện tích âm và các proton mang điện tích dương.","Chỉ gồm các hạt neutron liên kết lại với nhau.","Các hạt electron chuyển động với tốc độ ánh sáng xung quanh tâm."],"ans":0,"exp":"• <b>Cấu tạo hạt nhân:</b> Hạt nhân nguyên tử được tạo thành từ <b>proton (mang điện tích +e)</b> và <b>neutron (không mang điện)</b>, gọi chung là các <b>nucleon</b>.","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <radialGradient id=\"pGrad\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#fb7185\"/><stop offset=\"100%\" stop-color=\"#e11d48\"/></radialGradient>\n    <radialGradient id=\"nGrad\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#60a5fa\"/><stop offset=\"100%\" stop-color=\"#2563eb\"/></radialGradient>\n    <radialGradient id=\"eGrad\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#fef08a\"/><stop offset=\"100%\" stop-color=\"#eab308\"/></radialGradient>\n  </defs>\n  <!-- Electron orbits -->\n  <ellipse cx=\"230\" cy=\"105\" rx=\"160\" ry=\"50\" fill=\"none\" stroke=\"rgba(255,255,255,0.15)\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n  <ellipse cx=\"230\" cy=\"105\" rx=\"90\" ry=\"75\" fill=\"none\" stroke=\"rgba(255,255,255,0.15)\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\" transform=\"rotate(45 230 105)\"/>\n  <!-- Electrons -->\n  <circle cx=\"70\" cy=\"105\" r=\"5\" fill=\"url(#eGrad)\"><animate attributeName=\"opacity\" values=\"0.6;1;0.6\" dur=\"2s\" repeatCount=\"indefinite\"/></circle>\n  <circle cx=\"390\" cy=\"105\" r=\"5\" fill=\"url(#eGrad)\"/>\n  <!-- Nucleus Glow Container -->\n  <circle cx=\"230\" cy=\"105\" r=\"45\" fill=\"rgba(147,51,234,0.15)\" stroke=\"#a855f7\" stroke-width=\"1.5\"/>\n  <!-- Nucleons cluster -->\n  <g>\n    <!-- Protons -->\n    <circle cx=\"220\" cy=\"95\" r=\"10\" fill=\"url(#pGrad)\"/><text x=\"220\" y=\"98\" fill=\"#fff\" font-size=\"10\" font-weight=\"800\" text-anchor=\"middle\">+</text>\n    <circle cx=\"238\" cy=\"115\" r=\"10\" fill=\"url(#pGrad)\"/><text x=\"238\" y=\"118\" fill=\"#fff\" font-size=\"10\" font-weight=\"800\" text-anchor=\"middle\">+</text>\n    <circle cx=\"215\" cy=\"118\" r=\"10\" fill=\"url(#pGrad)\"/><text x=\"215\" y=\"121\" fill=\"#fff\" font-size=\"10\" font-weight=\"800\" text-anchor=\"middle\">+</text>\n    <!-- Neutrons -->\n    <circle cx=\"238\" cy=\"92\" r=\"10\" fill=\"url(#nGrad)\"/><text x=\"238\" y=\"95\" fill=\"#fff\" font-size=\"9\" font-weight=\"800\" text-anchor=\"middle\">n</text>\n    <circle cx=\"222\" cy=\"110\" r=\"10\" fill=\"url(#nGrad)\"/><text x=\"222\" y=\"113\" fill=\"#fff\" font-size=\"9\" font-weight=\"800\" text-anchor=\"middle\">n</text>\n    <circle cx=\"245\" cy=\"108\" r=\"10\" fill=\"url(#nGrad)\"/><text x=\"245\" y=\"111\" fill=\"#fff\" font-size=\"9\" font-weight=\"800\" text-anchor=\"middle\">n</text>\n  </g>\n  <!-- Legend -->\n  <rect x=\"25\" y=\"20\" width=\"130\" height=\"75\" rx=\"8\" fill=\"rgba(15,23,42,0.85)\" stroke=\"rgba(255,255,255,0.12)\"/>\n  <circle cx=\"45\" cy=\"40\" r=\"7\" fill=\"url(#pGrad)\"/><text x=\"60\" y=\"44\" fill=\"#fb7185\" font-size=\"11\" font-weight=\"700\">Proton (Z, +e)</text>\n  <circle cx=\"45\" cy=\"60\" r=\"7\" fill=\"url(#nGrad)\"/><text x=\"60\" y=\"64\" fill=\"#60a5fa\" font-size=\"11\" font-weight=\"700\">Neutron (N, 0)</text>\n  <circle cx=\"45\" cy=\"80\" r=\"5\" fill=\"url(#eGrad)\"/><text x=\"60\" y=\"84\" fill=\"#fde047\" font-size=\"11\" font-weight=\"700\">Electron (-e)</text>\n  <!-- Caption -->\n  <text x=\"230\" y=\"198\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\">Mô hình cấu tạo hạt nhân (Số khối A = Z + N)</text>\n</svg>"},{"q":"Hạt nhân nguyên tử nhôm có ký hiệu là ²⁷₁₃Al. Số lượng proton, neutron và số khối A của hạt nhân này lần lượt là:","opts":["13 proton, 14 neutron và số khối A = 27.","13 proton, 27 neutron và số khối A = 14.","14 proton, 13 neutron và số khối A = 27.","27 proton, 13 neutron và số khối A = 14."],"ans":0,"exp":"• Kí hiệu <span class=\"math-sym\"><sup>A</sup><sub>Z</sub>X</span>:<br>• Số proton: <span class=\"math-sym\">Z</span> = 13.<br>• Số khối: <span class=\"math-sym\">A</span> = 27.<br>• Số neutron: <span class=\"math-sym\">N = A - Z</span> = 27 - 13 = 14.","svgGraph":null},{"q":"Các nguyên tử được gọi là <b>đồng vị</b> của nhau khi hạt nhân của chúng có:","opts":["Cùng số proton Z nhưng khác số neutron N (dẫn tới số khối A khác nhau).","Cùng số neutron N nhưng khác số proton Z.","Cùng số khối A nhưng khác số proton Z.","Cùng khối lượng nhưng tính chất hóa học hoàn toàn khác nhau."],"ans":0,"exp":"• <b>Định nghĩa đồng vị:</b> Các nguyên tử có <b>cùng số proton Z</b> (cùng vị trí trong bảng tuần hoàn hóa học) nhưng có <b>số neutron N khác nhau</b>.","svgGraph":null},{"q":"Kĩ thuật chụp cắt lớp phát xạ positron (PET scan) là một công nghệ chẩn đoán y tế tiên tiến giúp phát hiện sớm các tế bào ung thư. Kĩ thuật này sử dụng loại chất nào đưa vào cơ thể bệnh nhân?","opts":["Dược chất phóng xạ chứa đồng vị phóng xạ phát hạt positron (tia β⁺, như ¹⁸₉F).","Nam châm vĩnh cửu siêu nhỏ gắn định vị vào tế bào hồng cầu.","Khối lượng kim loại chì ²⁰⁶₈₂Pb có khả năng cản tia bức xạ ngoài.","Khí hiếm phóng xạ radon hít trực tiếp qua đường hô hấp."],"ans":0,"exp":"• <b>Ứng dụng y học hạt nhân (PET Scan):</b> Bệnh nhân được tiêm một lượng nhỏ dược chất chứa đồng vị phát hạt positron β⁺ (như ¹⁸₉F gắn vào glucose).<br>• Tế bào ung thư phát triển mạnh tiêu thụ nhiều glucose sẽ tập trung nhiều đồng vị này. Hạt positron phát ra khi phân rã gặp ngay electron trong mô sẽ xảy ra hiện tượng hủy cặp (e⁺ + e⁻ → 2γ), tạo ra 2 photon tia gamma bay ngược chiều nhau (180°). Hệ thống máy dò PET ghi lại các tia gamma này để dựng hình ảnh 3D vị trí khối u với độ chính xác cao.","svgGraph":null},{"q":"Bán kính hạt nhân nguyên tử có kích thước cực nhỏ (cỡ 10⁻¹⁵ m) nhưng lại tập trung tới hơn 99,9% khối lượng của toàn bộ nguyên tử. Mật độ khối lượng của vật chất hạt nhân xấp xỉ khoảng bao nhiêu?","opts":["Khoảng 10¹⁷ kg/m³ (một giọt vật chất hạt nhân thể tích 1 cm³ có khối lượng lên tới hàng trăm triệu tấn).","Khoảng 1000 kg/m³ tương đương với khối lượng riêng của nước nguyên chất.","Khoảng 10⁴ kg/m³ tương đương với khối lượng riêng của kim loại chì và vàng.","Khoảng 10⁻¹⁷ kg/m³ vì các hạt vi mô có khối lượng vô cùng nhỏ bé."],"ans":0,"exp":"• <b>Mật độ khối lượng hạt nhân:</b> Thể tích hạt nhân V = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">3</span></span> · π · R³ ≈ 7,2 · 10⁻⁴⁵ · A m³.<br>• Khối lượng hạt nhân m ≈ A · 1,66 · 10⁻²⁷ kg.<br>• Mật độ khối lượng ρ = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">V</span></span> ≈ <span class=\"fraction\"><span class=\"numerator\">1,66 · 10⁻²⁷</span><span class=\"denominator\">7,2 · 10⁻⁴⁵</span></span> ≈ 2,3 · 10¹⁷ kg/m³.<br>• Con số khổng lồ này cho thấy vật chất hạt nhân đặc khít một cách phi thường (tương đương mật độ vật chất bên trong các ngôi sao neutron trong vũ trụ).","svgGraph":null},{"q":"Trong tự nhiên, nguyên tố carbon có các đồng vị bền là ¹²₆C, ¹³₆C và đồng vị phóng xạ ¹⁴₆C (chu kì bán rã 5730 năm). Khẳng định nào sau đây là đúng khi nói về các đồng vị này?","opts":["Chúng có cùng tính chất hóa học vì cùng có 6 electron lớp vỏ, nhưng khác nhau về độ bền vững hạt nhân.","Chúng có tính chất hóa học hoàn toàn khác nhau vì số lượng neutron quyết định khả năng liên kết phân tử.","Cả ba đồng vị đều tự phát phân rã phóng xạ với cùng tốc độ và chu kì bán rã.","Đồng vị ¹⁴₆C có 8 proton và 6 neutron nằm trong hạt nhân nguyên tử."],"ans":0,"exp":"• <b>Đặc điểm của đồng vị:</b> Các đồng vị của cùng một nguyên tố có cùng số hiệu nguyên tử Z = 6 (cùng số proton và cùng số electron lớp ngoài), do đó chúng có cấu hình electron giống hệt nhau và thể hiện các tính chất hóa học hoàn toàn như nhau.<br>• Tuy nhiên, vì có số neutron N khác nhau (N<sub>C12</sub> = 6, N<sub>C13</sub> = 7, N<sub>C14</sub> = 8) nên khối lượng và độ bền vững hạt nhân của chúng khác nhau: ¹²C, ¹³C bền vững vĩnh cửu, trong khi ¹⁴C không bền và phân rã phóng xạ β⁻.","svgGraph":null}],"22":[{"q":"Độ hụt khối Δm của hạt nhân nguyên tử <sup>A</sup><sub>Z</sub>X được xác định bởi công thức nào sau đây?","opts":["Δm = [Z · mp + (A - Z) · mn] - mX.","Δm = mX - [Z · mp + (A - Z) · mn].","Δm = A · mp - mX.","Δm = Z · mp + A · mn."],"ans":0,"exp":"• <b>Định nghĩa độ hụt khối:</b> Khối lượng của hạt nhân luôn nhỏ hơn tổng khối lượng của các nucleon tự do tạo nên nó: <span class=\"math-sym\">Δm = [Z · m<sub>p</sub> + (A - Z) · m<sub>n</sub>] - m<sub>X</sub> > 0</span>.","svgGraph":null},{"q":"Đại lượng vật lí nào sau đây đặc trưng trực tiếp cho <b>mức độ bền vững</b> của hạt nhân nguyên tử?","opts":["Năng lượng liên kết riêng (E<sub>lkr</sub> = <span class=\"fraction\"><span class=\"numerator\">E<sub>lk</sub></span><span class=\"denominator\">A</span></span>).","Năng lượng liên kết toàn phần (Elk).","Độ hụt khối của hạt nhân (Δm).","Số lượng neutron trong hạt nhân."],"ans":0,"exp":"• <b>Quy tắc bền vững:</b> Năng lượng liên kết toàn phần tỉ lệ với số nucleon, nhưng <b>năng lượng liên kết riêng (<span class=\"math-sym\">E</span><sub>lkr</sub> = <span class=\"math-sym\">E</span><sub>lk</sub> / <span class=\"math-sym\">A</span>)</b> mới là đại lượng đặc trưng cho độ bền vững của hạt nhân (càng lớn thì hạt nhân càng bền).","svgGraph":null},{"q":"Nguồn gốc năng lượng khổng lồ giúp Mặt Trời và các vì sao trong vũ trụ tỏa sáng và bức xạ nhiệt liên tục hàng tỉ năm qua đến từ loại phản ứng nào sau đây?","opts":["Phản ứng nhiệt hạch (tổng hợp các hạt nhân hydro nhẹ thành hạt nhân heli ở nhiệt độ và áp suất cực cao).","Phản ứng phân hạch dây chuyền của các đồng vị urani và thori bên trong lòng Mặt Trời.","Quá trình phân rã phóng xạ tự nhiên của các quặng khoáng chất kim loại nặng ở tâm Mặt Trời.","Phản ứng oxy hóa cháy của khí hydro và carbon dưới áp suất khí quyển Mặt Trời."],"ans":0,"exp":"• <b>Năng lượng Mặt Trời từ Phản ứng nhiệt hạch:</b> Ở vùng tâm của Mặt Trời có nhiệt độ khoảng 15 triệu Kelvin và áp suất hàng trăm tỉ atm.<br>• Dưới điều kiện siêu nhiệt này, các hạt nhân hydro (¹₁H) có động năng cực lớn vượt qua lực đẩy Coulomb tĩnh điện, kết hợp với nhau trong chuỗi phản ứng nhiệt hạch tạo thành hạt nhân heli (⁴₂He) và giải phóng nguồn năng lượng bức xạ khổng lồ khoảng 26,7 MeV cho mỗi hạt heli tạo thành.","svgGraph":null},{"q":"Cho khối lượng hạt nhân ⁴₂He là 4,0015 u; mp = 1,00728 u; mn = 1,00866 u. Lấy 1 u = 931,5 MeV/c². Năng lượng liên kết riêng của hạt nhân ⁴₂He là:","opts":["7,07 MeV/nucleon.","28,3 MeV/nucleon.","14,1 MeV/nucleon.","3,53 MeV/nucleon."],"ans":0,"exp":"• Độ hụt khối: <span class=\"math-sym\">Δm</span> = 2 × 1,00728 + 2 × 1,00866 - 4,0015 = 0,03038 u.<br>• Năng lượng liên kết: <span class=\"math-sym\">E</span><sub>lk</sub> = 0,03038 × 931,5 ≈ 28,30 MeV.<br>• Năng lượng liên kết riêng: <span class=\"math-sym\">E</span><sub>lkr</sub> = 28,<span class=\"fraction\"><span class=\"numerator\">30</span><span class=\"denominator\">4</span></span> ≈ <b>7,07 MeV/nucleon</b>.","svgGraph":null},{"q":"Trên đường cong năng lượng liên kết riêng theo số khối A, các hạt nhân có số khối trong khoảng 50 < A < 70 (đặc biệt là sắt ⁵⁶₂₆Fe) có năng lượng liên kết riêng đạt cực đại (khoảng 8,8 MeV/nucleon). Ý nghĩa vật lí của đặc điểm này là gì?","opts":["Hạt nhân ⁵⁶₂₆Fe bền vững nhất trong tự nhiên, khó bị phá vỡ nhất, là 'điểm dừng' của quá trình nhiệt hạch trong các ngôi sao già.","Hạt nhân ⁵⁶₂₆Fe kém bền vững nhất và rất dễ dàng tự phát nổ phân hạch ở điều kiện thường.","Hạt nhân sắt có khả năng tự phát nổ nhiệt hạch để sinh ra các nguyên tố nhẹ hơn như hydro.","Năng lượng liên kết của toàn bộ hạt nhân sắt nhỏ hơn năng lượng liên kết của một hạt proton đơn lẻ."],"ans":0,"exp":"• <b>Độ bền vững của hạt nhân:</b> Năng lượng liên kết riêng E<sub>lkr</sub> = <span class=\"fraction\"><span class=\"numerator\">E<sub>lk</sub></span><span class=\"denominator\">A</span></span> đặc trưng cho mức độ bền vững của hạt nhân: E<sub>lkr</sub> càng lớn thì hạt nhân càng bền chặt.<br>• Với giá trị cực đại ≈ 8,8 MeV/nucleon, hạt nhân sắt ⁵⁶₂₆Fe là một trong những hạt nhân bền vững nhất trong vũ trụ. Các phản ứng nhiệt hạch trong lõi các ngôi sao chỉ có thể sinh năng lượng đến khi tạo ra sắt thì dừng lại; để tạo ra các nguyên tố nặng hơn sắt cần năng lượng từ các vụ nổ siêu tân tinh (supernova).","svgGraph":null},{"q":"Vũ khí hạt nhân bao gồm bom nguyên tử (bom A) và bom nhiệt hạch (bom H hay bom khinh khí). Sự khác biệt cốt lõi về nguyên lí giải phóng năng lượng giữa hai loại vũ khí này là gì?","opts":["Bom A dựa trên phân hạch dây chuyền hạt nhân nặng (²³⁵U), bom H dựa trên nhiệt hạch hạt nhân hydro được kích hoạt bởi bom A.","Bom nguyên tử không phát ra phóng xạ nguy hiểm, còn bom nhiệt hạch chỉ phát ra sóng âm thanh xung kích.","Bom nhiệt hạch chỉ dùng thuốc nổ hóa học TNT thông thường nén khí để tạo ra áp suất cao.","Bom nguyên tử giải phóng năng lượng lớn hơn bom nhiệt hạch hàng nghìn lần với cùng khối lượng."],"ans":0,"exp":"• <b>Cơ chế của bom hạt nhân:</b><br>1. <i>Bom nguyên tử (Bom A):</i> Dựa trên phản ứng phân hạch dây chuyền không điều khiển của các hạt nhân nặng (²³⁵U hoặc ²³⁹Pu) khi đạt khối lượng tới hạn.<br>2. <i>Bom nhiệt hạch (Bom H):</i> Dựa trên phản ứng tổng hợp hạt nhân các đồng vị hydro (²₁H + ³₁H → ⁴₂He + ¹₀n). Để đạt nhiệt độ hàng chục triệu độ kích hoạt phản ứng nhiệt hạch, người ta phải dùng một quả bom phân hạch (bom A) làm ngòi nổ. Bom H có sức tàn phá lớn gấp hàng trăm đến hàng nghìn lần bom A.","svgGraph":null}],"23":[{"q":"Hiện tượng phóng xạ là quá trình biến đổi hạt nhân có đặc điểm bản chất nào sau đây?","opts":["Quá trình tự phát của một hạt nhân không bền vững tự phân rã, giải phóng các tia bức xạ và biến đổi thành hạt nhân khác.","Hiện tượng hạt nhân bị kích thích phát quang khi bị chiếu ánh sáng tử ngoại.","Quá trình hai hạt nhân nhẹ va chạm kết hợp thành hạt nhân nặng hơn ở nhiệt độ cao.","Hiện tượng bắn phá hạt nhân bằng chùm electron năng lượng cao trong máy gia tốc."],"ans":0,"exp":"• <b>Bản chất hiện tượng phóng xạ:</b> Là quá trình <b>tự phát và ngẫu nhiên</b> từ bên trong hạt nhân, hoàn toàn không phụ thuộc vào các điều kiện môi trường bên ngoài như nhiệt độ, áp suất hay liên kết hóa học.","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Radioactive source Lead box -->\n  <rect x=\"30\" y=\"80\" width=\"50\" height=\"50\" fill=\"#475569\" stroke=\"#94a3b8\" stroke-width=\"2\" rx=\"4\"/>\n  <rect x=\"65\" y=\"100\" width=\"20\" height=\"10\" fill=\"#0f172a\"/>\n  <circle cx=\"50\" cy=\"105\" r=\"8\" fill=\"#f59e0b\"/>\n  <text x=\"55\" y=\"145\" fill=\"#cbd5e1\" font-size=\"10\" text-anchor=\"middle\">Nguồn phóng xạ</text>\n  <!-- Capacitor plates -->\n  <!-- Positive plate (top) -->\n  <rect x=\"130\" y=\"25\" width=\"200\" height=\"12\" fill=\"#ef4444\" rx=\"3\"/>\n  <text x=\"230\" y=\"20\" fill=\"#ef4444\" font-size=\"12\" font-weight=\"800\" text-anchor=\"middle\">BẢN CỰC DƯƠNG (+)</text>\n  <!-- Negative plate (bottom) -->\n  <rect x=\"130\" y=\"165\" width=\"200\" height=\"12\" fill=\"#3b82f6\" rx=\"3\"/>\n  <text x=\"230\" y=\"192\" fill=\"#3b82f6\" font-size=\"12\" font-weight=\"800\" text-anchor=\"middle\">BẢN CỰC ÂM (-)</text>\n  <!-- Radiation rays -->\n  <!-- Beta- (curves towards positive plate) -->\n  <path d=\"M 80,105 Q 160,105 240,45\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2.5\"/>\n  <polygon points=\"245,42 233,43 238,51\" fill=\"#f59e0b\"/>\n  <text x=\"255\" y=\"45\" fill=\"#f59e0b\" font-size=\"13\" font-weight=\"800\">Tia β⁻ (lệch nhiều về +)</text>\n  <!-- Gamma (straight line, not deflected) -->\n  <line x1=\"80\" y1=\"105\" x2=\"360\" y2=\"105\" stroke=\"#10b981\" stroke-width=\"2.5\" stroke-dasharray=\"5,2\"/>\n  <polygon points=\"368,105 356,99 356,111\" fill=\"#10b981\"/>\n  <text x=\"375\" y=\"109\" fill=\"#10b981\" font-size=\"13\" font-weight=\"800\">Tia γ (không lệch)</text>\n  <!-- Alpha (curves gently towards negative plate) -->\n  <path d=\"M 80,105 Q 180,105 260,155\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"3\"/>\n  <polygon points=\"266,159 254,153 259,161\" fill=\"#06b6d4\"/>\n  <text x=\"275\" y=\"163\" fill=\"#06b6d4\" font-size=\"13\" font-weight=\"800\">Tia α (lệch ít về -)</text>\n</svg>"},{"q":"Tia phóng xạ nào sau đây có bản chất là sóng điện từ có bước sóng cực ngắn (mang năng lượng photon rất cao và có khả năng đâm xuyên mạnh nhất)?","opts":["Tia gamma (γ).","Tia alpha (α).","Tia bêta trừ (β⁻).","Tia bêta cộng (β⁺)."],"ans":0,"exp":"• <b>Tia gamma (γ)</b> là sóng điện từ có bước sóng cực ngắn (dưới 10⁻¹¹ m), không mang điện tích, đâm xuyên cực kì mạnh (có thể xuyên qua lớp chì dày hàng chục cm).","svgGraph":null},{"q":"Chu kỳ bán rã T của một chất phóng xạ là khoảng thời gian để:","opts":["Một nửa số lượng hạt nhân của chất phóng xạ đó bị phân rã biến đổi thành chất khác.","Toàn bộ khối lượng chất phóng xạ bị tiêu hủy hoàn toàn.","Độ phóng xạ của chất tăng lên gấp đôi.","Khối lượng chất phóng xạ giảm đi <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>."],"ans":0,"exp":"• <b>Định nghĩa chu kỳ bán rã T:</b> Là khoảng thời gian mà sau đó số hạt nhân phóng xạ (hoặc độ phóng xạ) giảm đi <b>một nửa (còn lại 50%)</b>.","svgGraph":null},{"q":"Một chất phóng xạ có chu kỳ bán rã là 14 ngày. Ban đầu có 80 mg chất đó. Khối lượng chất phóng xạ còn lại sau 42 ngày là:","opts":["10 mg.","20 mg.","40 mg.","5 mg."],"ans":0,"exp":"• Số chu kỳ bán rã đã trôi qua: <span class=\"math-sym\">k = <span class=\"fraction\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></span> = <span class=\"fraction\"><span class=\"numerator\">42</span><span class=\"denominator\">14</span></span> = 3 chu kỳ.<br>• Khối lượng còn lại: <span class=\"math-sym\">m = <span class=\"fraction\"><span class=\"numerator\">m₀</span><span class=\"denominator\">2³</span></span></span> = <span class=\"fraction\"><span class=\"numerator\">80</span><span class=\"denominator\">8</span></span> = <b>10 mg</b>.","svgGraph":null},{"q":"Hạt nhân poloni ²¹⁰₈₄Po phóng xạ alpha và biến đổi thành hạt nhân chì Pb bền vững theo phương trình: ²¹⁰₈₄Po → ⁴₂He + <sup>A</sup><sub>Z</sub>Pb. Kí hiệu của hạt nhân chì sinh ra là:","opts":["²⁰⁶₈₂Pb.","²⁰⁸₈₂Pb.","²¹⁴₈₆Pb.","²⁰⁶₈₀Pb."],"ans":0,"exp":"• Bảo toàn số khối: <span class=\"math-sym\">A</span> = 210 - 4 = 206.<br>• Bảo toàn điện tích: <span class=\"math-sym\">Z</span> = 84 - 2 = 82.<br>• Hạt nhân tạo thành là <b>²⁰⁶₈₂Pb</b>.","svgGraph":null},{"q":"Một mẫu gỗ cổ khai quật từ một di chỉ khảo cổ học có độ phóng xạ của đồng vị ¹⁴₆C bằng 25% độ phóng xạ của mẫu gỗ tươi cùng loại cùng khối lượng. Biết chu kỳ bán rã của ¹⁴C là 5730 năm. Tuổi của mẫu gỗ cổ đó là:","opts":["11460 năm.","5730 năm.","17190 năm.","22920 năm."],"ans":0,"exp":"• <span class=\"math-sym\"><span class=\"fraction\"><span class=\"numerator\">H(t)</span><span class=\"denominator\">H₀</span></span></span> = 25% = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span> = <span class=\"math-sym\">2⁻² ⇒ t / T</span> = 2.<br>• Tuổi mẫu gỗ: <span class=\"math-sym\">t = 2T</span> = 2 × 5730 = <b>11460 năm</b>.","svgGraph":null}],"24":[{"q":"Phản ứng phân hạch hạt nhân là quá trình:","opts":["Một hạt nhân nặng hấp thụ một neutron chậm rồi vỡ thành hai hạt nhân nhẹ hơn và giải phóng thêm các neutron thứ cấp kèm năng lượng lớn.","Hai hạt nhân nhẹ kết hợp lại với nhau thành hạt nhân nặng hơn ở nhiệt độ hàng trăm triệu độ.","Hạt nhân tự phát phóng ra các tia alpha để trở nên bền vững hơn.","Hạt nhân hấp thụ photon gamma để biến đổi điện tích."],"ans":0,"exp":"• <b>Định nghĩa phản ứng phân hạch:</b> Là phản ứng trong đó một <b>hạt nhân rất nặng</b> (như ²³⁵U, ²³⁹Pu) hấp thụ một neutron nhiệt (chậm), kích hoạt vỡ thành 2 mảnh nhẹ hơn và kèm theo 2 đến 3 neutron mới.","svgGraph":null},{"q":"Để duy trì phản ứng phân hạch dây chuyền tự kiểm soát được và ổn định trong lò phản ứng của nhà máy điện hạt nhân, hệ số nhân neutron k phải được duy trì ở giá trị:","opts":["k = 1 (trạng thái tới hạn).","k > 1 (trạng thái trên tới hạn).","k < 1 (trạng thái dưới tới hạn).","k = 0."],"ans":0,"exp":"• <b>Các chế độ phản ứng dây chuyền:</b><br>• <span class=\"math-sym\">k = 1</span>: Số neutron sinh ra trung bình bằng số neutron tiêu hao, phản ứng diễn ra <b>ổn định và kiểm soát được</b> trong lò phản ứng điện hạt nhân.<br>• <span class=\"math-sym\">k > 1</span>: Bùng nổ mãnh liệt (bom nguyên tử).<br>• <span class=\"math-sym\">k < 1</span>: Phản ứng tự tắt.","svgGraph":null},{"q":"Phản ứng nhiệt hạch là phản ứng tổng hợp hai hạt nhân rất nhẹ thành hạt nhân nặng hơn. Điều kiện cốt lõi để phản ứng nhiệt hạch có thể xảy ra trong thực tế là:","opts":["Nhiệt độ phải cực kì cao (hàng chục đến hàng trăm triệu độ) để các hạt nhân có động năng đủ lớn thắng được lực đẩy tĩnh điện Coulomb.","Nhiệt độ phải hạ xuống gần độ không tuyệt đối 0 K.","Phải có từ trường ngoài cực mạnh hướng dọc trục lò phản ứng.","Phải dùng tia laser công suất thấp chiếu liên tục nhiều năm."],"ans":0,"exp":"• Để hai hạt nhân tích điện dương thắng được lực đẩy tĩnh điện và tiến vào khoảng cách <span class=\"math-sym\">10⁻¹⁵</span> m (tầm tác dụng của lực hạt nhân), chúng cần động năng nhiệt cực lớn, tương ứng nhiệt độ <b>hàng trăm triệu Kelvin</b>.","svgGraph":null},{"q":"Biết mỗi phân hạch hạt nhân ²³⁵U tỏa ra năng lượng trung bình là 200 MeV. Cho số Avogadro NA = 6,022 · 10²³ mol⁻¹ và 1 eV = 1,6 · 10⁻¹⁹ J. Năng lượng tỏa ra khi phân hạch hoàn toàn 1,0 kg ²³⁵U xấp xỉ bằng:","opts":["8,2 · 10¹³ J (tương đương đốt cháy hàng ngàn tấn than đá).","2,5 · 10⁸ J.","5,1 · 10¹⁰ J.","1,6 · 10¹⁵ J."],"ans":0,"exp":"• Số hạt nhân trong 1 kg: <span class=\"math-sym\">N</span> = (<span class=\"fraction\"><span class=\"numerator\">1000</span><span class=\"denominator\">235</span></span>) × 6,022 · 10²³ ≈ 2,56 · 10²⁴ hạt.<br>• Năng lượng tỏa ra: <span class=\"math-sym\">E</span> = 2,56 · 10²⁴ × 200 × 10⁶ × 1,6 · 10⁻¹⁹ ≈ <b>8,2 · 10¹³ J</b>.","svgGraph":null},{"q":"Ưu thế vượt trội lớn nhất của việc phát triển điện hạt nhân so với các nhà máy nhiệt điện đốt nhiên liệu hóa thạch truyền thống (than đá, dầu khí) là:","opts":["Mật độ năng lượng cực kì cao và không phát thải khí nhà kính (CO₂) gây biến đổi khí hậu trong quá trình vận hành.","Chi phí xây dựng ban đầu của nhà máy điện hạt nhân rẻ hơn rất nhiều.","Không bao giờ sinh ra chất thải sau quá trình sản xuất điện.","Có thể xây dựng ở bất kì vị trí nào mà không cần nguồn nước làm mát."],"ans":0,"exp":"• <b>Ưu điểm cốt lõi của điện hạt nhân:</b> Năng lượng hạt nhân có mật độ năng lượng siêu đậm đặc, vận hành liên tục ổn định (công suất nền) và <b>không phát thải khí CO₂ hay SO₂</b> gây ô nhiễm không khí.","svgGraph":null},{"q":"Đồng vị phóng xạ Co-60 (Coban-60) được ứng dụng rộng rãi trong y tế chủ yếu để:","opts":["Xạ trị tiêu diệt tế bào ung thư bằng chùm tia gamma.","Chụp ảnh cắt lớp phổi bằng sóng siêu âm.","Làm nguồn phát quang cho đèn tín hiệu giao thông.","Khử trùng nguồn nước sinh hoạt bằng nhiệt độ cao."],"ans":0,"exp":"• Đồng vị <b>⁶⁰₂₇Co</b> phát ra tia gamma năng lượng cao dùng trong máy xạ trị điều trị ung thư.","svgGraph":null}],"25":[{"q":"Tỉ số giữa số hạt nhân con tạo thành N<sub>con</sub> và số hạt nhân mẹ còn lại N<sub>m</sub>ẹ tại thời điểm t trong một phân rã phóng xạ tuân theo hệ thức:","opts":["<span class=\"fraction\"><span class=\"numerator\">N<sub>con</sub></span><span class=\"denominator\">N<sub>mẹ</sub></span></span> = 2<sup><span class=\"fraction\" style=\"font-size:0.75em;\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></sup> - 1.","<span class=\"fraction\"><span class=\"numerator\">N<sub>con</sub></span><span class=\"denominator\">N<sub>mẹ</sub></span></span> = 2<sup>-<span class=\"fraction\" style=\"font-size:0.75em;\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></sup>.","<span class=\"fraction\"><span class=\"numerator\">N<sub>con</sub></span><span class=\"denominator\">N<sub>mẹ</sub></span></span> = 1 - 2<sup>-<span class=\"fraction\" style=\"font-size:0.75em;\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></sup>.","<span class=\"fraction\"><span class=\"numerator\">N<sub>con</sub></span><span class=\"denominator\">N<sub>mẹ</sub></span></span> = 2<sup><span class=\"fraction\" style=\"font-size:0.75em;\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></sup> + 1."],"ans":0,"exp":"• Số hạt con tạo thành bằng số hạt mẹ đã phân rã: <span class=\"math-sym\">N</span><sub>con</sub> = <span class=\"math-sym\">ΔN = N</span><sub>0</sub>(1 - <span class=\"math-sym\">2⁻ᵗ/ᵀ</span>).<br>• Số hạt mẹ còn lại: <span class=\"math-sym\">N</span><sub>mẹ</sub> = <span class=\"math-sym\">N</span><sub>0</sub> · <span class=\"math-sym\">2⁻ᵗ/ᵀ</span>.<br>• Tỉ số: <span class=\"fraction\"><span class=\"numerator\">N<sub>con</sub></span><span class=\"denominator\">N<sub>m</sub>ẹ</span></span> = <span class=\"fraction\"><span class=\"numerator\">1 - 2⁻ᵗ/ᵀ</span><span class=\"denominator\">2⁻ᵗ/ᵀ</span></span> = <b>2ᵗ/ᵀ - 1</b>.","svgGraph":null},{"q":"Tại thời điểm t = 2T (sau 2 chu kỳ bán rã), tỉ số giữa số hạt nhân con tạo thành và số hạt nhân mẹ còn lại là:","opts":["3.","2.","4.","<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">3</span></span>."],"ans":0,"exp":"• Áp dụng công thức: <span class=\"math-sym\">N</span><sub>con</sub> / <span class=\"math-sym\">N</span><sub>mẹ</sub> = <span class=\"math-sym\">2² - 1 = 4 - 1</span> = <b>3</b> (số hạt con gấp 3 lần số hạt mẹ).","svgGraph":null},{"q":"Phương pháp 'nguyên tử đánh dấu' (radioactive tracer) ứng dụng phổ biến trong y tế chẩn đoán và khảo sát nông nghiệp dựa trên nguyên lí vật lí nào sau đây?","opts":["Đưa lượng nhỏ đồng vị phóng xạ vào hệ thống và dùng thiết bị dò bức xạ theo dõi đường đi và sự tích tụ của nguyên tố đó.","Chiếu chùm tia gamma cường độ mạnh để biến đổi toàn bộ cấu trúc di truyền của sinh vật.","Kích thích phản ứng nhiệt hạch mini bên trong các cơ quan nội tạng để tiêu diệt mầm bệnh.","Đo vận tốc truyền sóng ánh sáng khả kiến qua tế bào sinh học để xác định nồng độ khoáng chất."],"ans":0,"exp":"• <b>Kĩ thuật nguyên tử đánh dấu:</b> Đồng vị phóng xạ có tính chất hóa học giống hệt đồng vị bền của cùng nguyên tố nên tham gia vào các quá trình sinh hóa tự nhiên của cơ thể hoặc hệ thống ống dẫn.<br>• Trong quá trình di chuyển, chúng liên tục phát ra tia bức xạ (như tia γ). Thiết bị dò bức xạ bên ngoài có thể theo dõi chính xác dòng chảy của máu, phát hiện các vị trí tắc mạch, đánh giá chức năng tuyến giáp (dùng ¹³¹I), hoặc phát hiện các điểm rò rỉ ngầm dưới lòng đất.","svgGraph":null},{"q":"Một hạt nhân ²¹⁰₈₄Po đứng yên phân rã alpha thành hạt nhân chì ²⁰⁶₈₂Pb. Cho khối lượng các hạt xấp xỉ bằng số khối: m_α = 4 u; m<sub>Pb</sub> = 206 u. Phản ứng tỏa ra năng lượng ΔE = 5,4 MeV. Động năng của hạt alpha sinh ra là:","opts":["5,3 MeV.","5,1 MeV.","4,8 MeV.","2,7 MeV."],"ans":0,"exp":"• Bảo toàn động lượng: <span class=\"math-sym\"><span class=\"fraction\"><span class=\"numerator\">K_α</span><span class=\"denominator\">K<sub>Pb</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">m<sub>Pb</sub></span><span class=\"denominator\">m_α</span></span></span> = <span class=\"fraction\"><span class=\"numerator\">206</span><span class=\"denominator\">4</span></span> = 51,5.<br>• <span class=\"math-sym\">K_α = ΔE</span> × <span class=\"fraction\"><span class=\"numerator\">m<sub>Pb</sub></span><span class=\"denominator\">m<sub>Pb</sub> + m_α</span></span> = 5,4 × (<span class=\"fraction\"><span class=\"numerator\">206</span><span class=\"denominator\">210</span></span>) ≈ <b>5,3 MeV</b>.","svgGraph":null},{"q":"Các nhà địa chất và thiên văn học xác định tuổi của các mẫu đất đá trên Mặt Trăng do tàu Apollo mang về là khoảng 4,5 tỉ năm dựa trên phương pháp định tuổi bằng tỉ số phóng xạ nào?","opts":["Tỉ số giữa số hạt chì con ²⁰⁶₈₂Pb tạo thành và số hạt urani mẹ ²³⁸₉₂U còn lại trong mẫu đá.","Tỉ số giữa đồng vị carbon phóng xạ ¹⁴₆C và đồng vị carbon bền ¹²₆C.","Tỉ số giữa lượng khí heli và lượng khí hydrogen thoát ra khi nung chảy mẫu đá.","Tỉ số giữa khối lượng của mẫu đá so với khối lượng toàn bộ vỏ Mặt Trăng."],"ans":0,"exp":"• <b>Định tuổi địa chất U - Pb:</b> Chuỗi phân rã của đồng vị ²³⁸₉₂U chuyển hóa thành đồng vị bền ²⁰⁶₈₂Pb có chu kì bán rã rất lớn T ≈ 4,47 · 10⁹ năm (xấp xỉ tuổi của Trái Đất và hệ Mặt Trời).<br>• Tỉ số số hạt: <span class=\"fraction\"><span class=\"numerator\">N<sub>Pb</sub></span><span class=\"denominator\">N<sub>U</sub></span></span> = 2<sup><span class=\"fraction\" style=\"font-size:0.75em;\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></sup> - 1. Bằng cách đo tỉ số này trong các tinh thể zircon của mẫu đá, các nhà khoa học tính chính xác tuổi t của đá Mặt Trăng là khoảng 4,5 tỉ năm (trong khi phương pháp ¹⁴C chỉ đo được cổ vật dưới 50.000 năm do T<sub>C14</sub> ≈ 5730 năm).","svgGraph":null},{"q":"Trong dây chuyền sản xuất tự động các lá màng nhôm mỏng hoặc giấy công nghiệp, người ta đặt nguồn phát tia phóng xạ β ở một bên tấm màng và đầu dò bức xạ ở bên đối diện. Thiết bị này dùng để:","opts":["Tự động kiểm soát và điều chỉnh độ dày của màng thông qua mức độ suy giảm của chùm tia β khi đâm xuyên qua màng.","Khử trùng và tiệt trùng bề mặt tấm màng để chống nấm mốc và vi khuẩn bám dính.","Đốt nóng làm khô nhanh màng nhôm và giấy trong quá trình cán tốc độ cao.","Tích điện âm cho màng kim loại để các lớp màng tự động dính chặt vào nhau."],"ans":0,"exp":"• <b>Thiết bị đo độ dày bức xạ:</b> Tia β (các electron năng lượng cao) có khả năng đâm xuyên qua các màng vật chất mỏng và bị hấp thụ một phần.<br>• Độ suy giảm cường độ của chùm tia β phụ thuộc chặt chẽ vào độ dày của lớp vật liệu. Nếu màng bị dày hơn tiêu chuẩn, lượng tia β tới đầu dò giảm ⇒ hệ thống tự động điều khiển trục cán ép chặt lại. Ngược lại, nếu màng mỏng hơn, lượng tia tới tăng ⇒ nới lỏng trục cán. Thiết bị hoạt động liên tục không tiếp xúc và tự động hóa 100%.","svgGraph":null}]}};